#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NxFrame<'a> {
    pub flags: u8,
    pub payload: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameError {
    Truncated { needed: usize, actual: usize },
    BadMagic(u16),
    UnsupportedVersion(u8),
    ReservedFlags(u8),
    FrameTooLarge(u32),
    CrcMismatch { expected: u32, actual: u32 },
}

pub const MAGIC: u16 = 0x4E58;
pub const VERSION: u8 = 0x02;
pub const MAX_PAYLOAD: usize = 1_048_576;
pub const HEADER_LEN: usize = 8;
pub const TRAILER_LEN: usize = 4;

fn crc32c(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFF_FFFF;
    for &byte in data {
        crc ^= u32::from(byte);
        for _ in 0..8 {
            let mask = (crc & 1).wrapping_neg();
            crc = (crc >> 1) ^ (0x82F6_3B78 & mask);
        }
    }
    !crc
}

pub fn decode_nx_frame(buf: &[u8]) -> Result<(NxFrame<'_>, &[u8]), FrameError> {
    if buf.len() < HEADER_LEN + TRAILER_LEN {
        return Err(FrameError::Truncated {
            needed: HEADER_LEN + TRAILER_LEN,
            actual: buf.len(),
        });
    }
    let magic = u16::from_be_bytes([buf[0], buf[1]]);
    if magic != MAGIC {
        return Err(FrameError::BadMagic(magic));
    }
    let ver = buf[2];
    if ver != VERSION {
        return Err(FrameError::UnsupportedVersion(ver));
    }
    let flags = buf[3];
    if flags & 0xF0 != 0 {
        return Err(FrameError::ReservedFlags(flags));
    }
    let raw_len = u32::from_be_bytes([buf[4], buf[5], buf[6], buf[7]]);
    let payload_len = raw_len as usize;
    if payload_len > MAX_PAYLOAD {
        return Err(FrameError::FrameTooLarge(raw_len));
    }
    let total_len = HEADER_LEN + payload_len + TRAILER_LEN;
    if buf.len() < total_len {
        return Err(FrameError::Truncated {
            needed: total_len,
            actual: buf.len(),
        });
    }
    let body_end = HEADER_LEN + payload_len;
    let computed_crc = crc32c(&buf[..body_end]);
    let wire_crc = u32::from_be_bytes([
        buf[body_end],
        buf[body_end + 1],
        buf[body_end + 2],
        buf[body_end + 3],
    ]);
    if computed_crc != wire_crc {
        return Err(FrameError::CrcMismatch {
            expected: computed_crc,
            actual: wire_crc,
        });
    }
    Ok((
        NxFrame {
            flags,
            payload: &buf[HEADER_LEN..body_end],
        },
        &buf[total_len..],
    ))
}

pub fn encode_nx_frame(flags: u8, payload: &[u8], out: &mut Vec<u8>) -> Result<(), FrameError> {
    if flags & 0xF0 != 0 {
        return Err(FrameError::ReservedFlags(flags));
    }
    if payload.len() > MAX_PAYLOAD {
        return Err(FrameError::FrameTooLarge(u32::try_from(payload.len()).unwrap_or(u32::MAX)));
    }
    let start = out.len();
    out.reserve(HEADER_LEN + payload.len() + TRAILER_LEN);
    out.extend_from_slice(&MAGIC.to_be_bytes());
    out.push(VERSION);
    out.push(flags);
    out.extend_from_slice(&(payload.len() as u32).to_be_bytes());
    out.extend_from_slice(payload);
    let crc = crc32c(&out[start..]);
    out.extend_from_slice(&crc.to_be_bytes());
    Ok(())
}
