#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    WS_OK = 0,
    WS_ERR_TRUNCATED,
    WS_ERR_RSV_BITS,
    WS_ERR_BAD_OPCODE,
    WS_ERR_UNMASKED_CLIENT,
    WS_ERR_NON_MINIMAL_LEN,
    WS_ERR_MSB_SET,
    WS_ERR_CONTROL_FRAME,
    WS_ERR_TOO_LARGE,
    WS_ERR_DST_SMALL,
} ws_status_t;

typedef struct {
    bool fin;
    uint8_t opcode;
    size_t payload_len;
    size_t frame_wire_len;
} ws_parsed_t;

static inline bool ws_opcode_valid(uint8_t op) {
    return (op <= 0x02U) || (op >= 0x08U && op <= 0x0AU);
}

[[nodiscard]] ws_status_t ws_decode_client_frame(
    const uint8_t *buf,
    size_t buf_len,
    size_t max_payload,
    uint8_t *payload_out,
    size_t payload_cap,
    ws_parsed_t *meta_out
) {
