        return WS_ERR_DST_SMALL;
    }
    if (buf_len < 2U) {
        return WS_ERR_TRUNCATED;
    }
    uint8_t b0 = buf[0];
    uint8_t b1 = buf[1];
    if ((b0 & 0x70U) != 0U) {
        return WS_ERR_RSV_BITS;
    }
    bool fin = (b0 & 0x80U) != 0U;
    uint8_t opcode = b0 & 0x0FU;
    if (!ws_opcode_valid(opcode)) {
        return WS_ERR_BAD_OPCODE;
    }
    if ((b1 & 0x80U) == 0U) {
        return WS_ERR_UNMASKED_CLIENT;
    }

    uint8_t len7 = b1 & 0x7FU;
    size_t pos = 2U;
    uint64_t plen64 = 0U;

    if (len7 < 126U) {
        plen64 = len7;
    } else if (len7 == 126U) {
        if (buf_len < pos + 2U) {
            return WS_ERR_TRUNCATED;
        }
        plen64 = ((uint64_t)buf[pos] << 8) | (uint64_t)buf[pos + 1U];
        if (plen64 < 126U) {
            return WS_ERR_NON_MINIMAL_LEN;
        }
        pos += 2U;
    } else {
        if (buf_len < pos + 8U) {
            return WS_ERR_TRUNCATED;
        }
        if ((buf[pos] & 0x80U) != 0U) {
            return WS_ERR_MSB_SET;
        }
        for (size_t i = 0U; i < 8U; ++i) {
            plen64 = (plen64 << 8) | (uint64_t)buf[pos + i];
        }
        if (plen64 < 65536ULL) {
            return WS_ERR_NON_MINIMAL_LEN;
        }
        pos += 8U;
    }

    if ((opcode & 0x08U) != 0U && (!fin || plen64 > 125ULL)) {
        return WS_ERR_CONTROL_FRAME;
    }
    if (plen64 > (uint64_t)max_payload || plen64 > (uint64_t)(SIZE_MAX - pos - 4U)) {
        return WS_ERR_TOO_LARGE;
    }
    size_t plen = (size_t)plen64;
    if (plen > payload_cap) {
        return WS_ERR_DST_SMALL;
    }
    if (buf_len < pos + 4U + plen) {
        return WS_ERR_TRUNCATED;
    }
    uint8_t mask[4] = { buf[pos], buf[pos + 1U], buf[pos + 2U], buf[pos + 3U] };
    pos += 4U;
    for (size_t i = 0U; i < plen; ++i) {
        payload_out[i] = buf[pos + i] ^ mask[i & 3U];
    }
    *meta_out = (ws_parsed_t){
        .fin = fin,
        .opcode = opcode,
        .payload_len = plen,
        .frame_wire_len = pos + plen,
    };
    return WS_OK;
}

[[nodiscard]] ws_status_t ws_encode_server_frame(
    bool fin,
    uint8_t opcode,
    const uint8_t *payload,
    size_t payload_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (dst == nullptr || written_out == nullptr || (payload_len > 0U && payload == nullptr)) {
        return WS_ERR_DST_SMALL;
    }
    if (!ws_opcode_valid(opcode)) {
        return WS_ERR_BAD_OPCODE;
    }
    if ((opcode & 0x08U) != 0U && (!fin || payload_len > 125U)) {
        return WS_ERR_CONTROL_FRAME;
    }
    if ((uint64_t)payload_len > 0x7FFFFFFFFFFFFFFFULL) {
        return WS_ERR_MSB_SET;
    }
    size_t hdr_len = (payload_len < 126U) ? 2U : ((payload_len <= 65535U) ? 4U : 10U);
    if (payload_len > SIZE_MAX - hdr_len || hdr_len + payload_len > dst_cap) {
        return WS_ERR_DST_SMALL;
    }
    dst[0] = (uint8_t)((fin ? 0x80U : 0x00U) | (opcode & 0x0FU));
    if (payload_len < 126U) {
        dst[1] = (uint8_t)payload_len;
    } else if (payload_len <= 65535U) {
        dst[1] = 126U;
        dst[2] = (uint8_t)((payload_len >> 8) & 0xFFU);
        dst[3] = (uint8_t)(payload_len & 0xFFU);
    } else {
        dst[1] = 127U;
        uint64_t v = (uint64_t)payload_len;
        for (size_t i = 0U; i < 8U; ++i) {
            dst[9U - i] = (uint8_t)(v & 0xFFU);
            v >>= 8;
        }
    }
    if (payload_len > 0U) {
        memcpy(dst + hdr_len, payload, payload_len);
    }
    *written_out = hdr_len + payload_len;
    return WS_OK;
}
