use std::collections::BTreeSet;

pub const QUIC_VARINT_MAX: u64 = (1u64 << 62) - 1;
pub const MAX_PARAM_LEN: usize = 65_535;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum QuicTlvError {
    Truncated,
    VarIntOverflow(u64),
    NonCanonicalVarInt { value: u64, encoded_len: usize },
    ParamTooLarge(u64),
    DuplicateParamId(u64),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TransportParam<'a> {
    pub id: u64,
    pub value: &'a [u8],
}

pub fn min_varint_len(v: u64) -> Result<usize, QuicTlvError> {
    if v <= 63 {
        Ok(1)
    } else if v <= 16_383 {
        Ok(2)
    } else if v <= 1_073_741_823 {
        Ok(4)
    } else if v <= QUIC_VARINT_MAX {
        Ok(8)
    } else {
        Err(QuicTlvError::VarIntOverflow(v))
    }
}

pub fn decode_varint(buf: &[u8], strict_canonical: bool) -> Result<(u64, &[u8]), QuicTlvError> {
    let &first = buf.first().ok_or(QuicTlvError::Truncated)?;
    let tag = first >> 6;
    let len = 1usize << tag;
    let raw = buf.get(..len).ok_or(QuicTlvError::Truncated)?;

    let mut val = u64::from(raw[0] & 0x3F);
    for &b in &raw[1..] {
        val = (val << 8) | u64::from(b);
    }
    if strict_canonical && min_varint_len(val)? != len {
        return Err(QuicTlvError::NonCanonicalVarInt {
            value: val,
            encoded_len: len,
        });
    }
    Ok((val, &buf[len..]))
}

pub fn encode_varint(v: u64, out: &mut Vec<u8>) -> Result<(), QuicTlvError> {
    match min_varint_len(v)? {
        1 => out.push(v as u8),
        2 => {
            let tagged = (v as u16) | 0x4000;
            out.extend_from_slice(&tagged.to_be_bytes());
        }
        4 => {
            let tagged = (v as u32) | 0x8000_0000;
            out.extend_from_slice(&tagged.to_be_bytes());
        }
        8 => {
            let tagged = v | 0xC000_0000_0000_0000;
            out.extend_from_slice(&tagged.to_be_bytes());
        }
        _ => unreachable!(),
    }
    Ok(())
}

pub fn decode_transport_params(mut buf: &[u8]) -> Result<Vec<TransportParam<'_>>, QuicTlvError> {
    let mut seen = BTreeSet::new();
    let mut params = Vec::new();
    while !buf.is_empty() {
        let (id, rest) = decode_varint(buf, true)?;
        if !seen.insert(id) {
            return Err(QuicTlvError::DuplicateParamId(id));
        }
        let (plen, rest) = decode_varint(rest, true)?;
        if plen > MAX_PARAM_LEN as u64 {
            return Err(QuicTlvError::ParamTooLarge(plen));
        }
        let n = plen as usize;
        let value = rest.get(..n).ok_or(QuicTlvError::Truncated)?;
        params.push(TransportParam { id, value });
        buf = &rest[n..];
    }
    Ok(params)
}

pub fn encode_transport_params(params: &[TransportParam<'_>], out: &mut Vec<u8>) -> Result<(), QuicTlvError> {
    let mut seen = BTreeSet::new();
    for p in params {
        if !seen.insert(p.id) {
            return Err(QuicTlvError::DuplicateParamId(p.id));
        }
        if p.value.len() > MAX_PARAM_LEN {
            return Err(QuicTlvError::ParamTooLarge(p.value.len() as u64));
        }
        encode_varint(p.id, out)?;
        encode_varint(p.value.len() as u64, out)?;
        out.extend_from_slice(p.value);
    }
    Ok(())
}
