#include <stddef.h>
#include <stdint.h>

typedef enum : uint8_t {
    LEB_OK = 0,
    LEB_ERR_NULL,
    LEB_ERR_TRUNCATED,
    LEB_ERR_OVERFLOW,
    LEB_ERR_NON_CANONICAL,
    LEB_ERR_DST_SMALL,
} leb_status_t;

static inline uint64_t zigzag_encode_i64(int64_t n) {
    uint64_t u = (uint64_t)n;
    uint64_t sign_mask = (n < 0) ? UINT64_MAX : 0ULL;
    return (u << 1) ^ sign_mask;
}

static inline int64_t zigzag_decode_u64(uint64_t z) {
    uint64_t neg_mask = 0ULL - (z & 1ULL);
    return (int64_t)((z >> 1) ^ neg_mask);
}

[[nodiscard]] leb_status_t uleb128_encode(
    uint64_t val,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (dst == nullptr || written_out == nullptr) {
        return LEB_ERR_NULL;
    }
    size_t i = 0U;
    do {
        if (i >= dst_cap) {
            return LEB_ERR_DST_SMALL;
        }
        uint8_t byte = (uint8_t)(val & 0x7FU);
        val >>= 7;
        if (val != 0ULL) {
            byte |= 0x80U;
        }
        dst[i++] = byte;
    } while (val != 0ULL);
    *written_out = i;
    return LEB_OK;
}

[[nodiscard]] leb_status_t uleb128_decode_canonical(
    const uint8_t *src,
    size_t src_len,
    uint64_t *val_out,
    size_t *consumed_out
) {
    if (src == nullptr || val_out == nullptr || consumed_out == nullptr) {
        return LEB_ERR_NULL;
    }
    uint64_t acc = 0ULL;
    for (size_t i = 0U; i < 10U; ++i) {
        if (i >= src_len) {
            return LEB_ERR_TRUNCATED;
        }
        uint8_t b = src[i];
        if (i == 9U && b > 0x01U) {
            return LEB_ERR_OVERFLOW;
        }
        acc |= ((uint64_t)(b & 0x7FU)) << (i * 7U);
        if ((b & 0x80U) == 0U) {
            if (i > 0U && b == 0x00U) {
                return LEB_ERR_NON_CANONICAL;
            }
            *val_out = acc;
            *consumed_out = i + 1U;
            return LEB_OK;
        }
    }
    return LEB_ERR_OVERFLOW;
}

[[nodiscard]] leb_status_t zigzag_leb128_encode(
    int64_t val,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    return uleb128_encode(zigzag_encode_i64(val), dst, dst_cap, written_out);
}

[[nodiscard]] leb_status_t zigzag_leb128_decode_canonical(
    const uint8_t *src,
    size_t src_len,
    int64_t *val_out,
    size_t *consumed_out
) {
    if (val_out == nullptr) {
        return LEB_ERR_NULL;
    }
    uint64_t raw = 0ULL;
    leb_status_t st = uleb128_decode_canonical(src, src_len, &raw, consumed_out);
    if (st != LEB_OK) {
        return st;
    }
    *val_out = zigzag_decode_u64(raw);
    return LEB_OK;
}
