pub const MAX_LABEL_LEN: usize = 63;
pub const MAX_WIRE_NAME_LEN: usize = 255;
pub const MAX_PTR_HOPS: usize = 16;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DnsNameError {
    OffsetOutOfBounds,
    Truncated,
    ReservedLabelType(u8),
    InvalidPointerTarget { from: usize, target: usize },
    TooManyPointers,
    WireNameTooLong,
    EmptyLabel,
    LabelTooLong(usize),
}

pub fn decode_dns_name(
    packet: &[u8],
    start_offset: usize,
) -> Result<(Vec<Vec<u8>>, usize), DnsNameError> {
    if start_offset >= packet.len() {
        return Err(DnsNameError::OffsetOutOfBounds);
    }
    let mut labels: Vec<Vec<u8>> = Vec::new();
    let mut pos = start_offset;
    let mut next_after_name: Option<usize> = None;
    let mut wire_len: usize = 0;
    let mut hops: usize = 0;

    loop {
        let &tag = packet.get(pos).ok_or(DnsNameError::Truncated)?;
        match tag & 0xC0 {
            0x00 => {
                let len = (tag & 0x3F) as usize;
                wire_len = wire_len
                    .checked_add(1 + len)
                    .ok_or(DnsNameError::WireNameTooLong)?;
                if wire_len > MAX_WIRE_NAME_LEN {
                    return Err(DnsNameError::WireNameTooLong);
                }
                if len == 0 {
                    let end_offset = next_after_name.unwrap_or(pos + 1);
                    return Ok((labels, end_offset));
                }
                let label_start = pos + 1;
                let label_end = label_start + len;
                let slice = packet.get(label_start..label_end).ok_or(DnsNameError::Truncated)?;
                labels.push(slice.to_vec());
                pos = label_end;
            }
            0xC0 => {
                let &low = packet.get(pos + 1).ok_or(DnsNameError::Truncated)?;
                hops += 1;
                if hops > MAX_PTR_HOPS {
                    return Err(DnsNameError::TooManyPointers);
                }
                let target = (((tag & 0x3F) as usize) << 8) | (low as usize);
                if target >= pos {
                    return Err(DnsNameError::InvalidPointerTarget { from: pos, target });
                }
                if next_after_name.is_none() {
                    next_after_name = Some(pos + 2);
                }
                pos = target;
            }
            other => return Err(DnsNameError::ReservedLabelType(other)),
        }
    }
}

pub fn encode_dns_name(labels: &[&[u8]], out: &mut Vec<u8>) -> Result<(), DnsNameError> {
    let mut wire_len = 1usize; // root 0x00
    for label in labels {
        if label.is_empty() {
            return Err(DnsNameError::EmptyLabel);
        }
        if label.len() > MAX_LABEL_LEN {
            return Err(DnsNameError::LabelTooLong(label.len()));
        }
        wire_len += 1 + label.len();
        if wire_len > MAX_WIRE_NAME_LEN {
            return Err(DnsNameError::WireNameTooLong);
        }
    }
    out.reserve(wire_len);
    for label in labels {
        out.push(label.len() as u8);
        out.extend_from_slice(label);
    }
    out.push(0x00);
    Ok(())
}
