static constexpr uint8_t PP2_SIG[12] = {
    0x0D, 0x0A, 0x0D, 0x0A, 0x00, 0x0D, 0x0A, 0x51, 0x55, 0x49, 0x54, 0x0A
};
static constexpr size_t PP2_HDR_FIXED = 16U;
static constexpr size_t PP2_MAX_TOTAL = 536U;

typedef enum : uint8_t {
    PP2_OK = 0,
    PP2_ERR_NULL,
    PP2_ERR_TRUNCATED,
    PP2_ERR_BAD_SIG,
    PP2_ERR_BAD_VER_CMD,
    PP2_ERR_BAD_FAM_PROTO,
    PP2_ERR_BAD_ADDR_LEN,
    PP2_ERR_TOO_LARGE,
    PP2_ERR_DST_SMALL,
} pp2_status_t;

typedef enum : uint8_t {
    PP2_CMD_LOCAL = 0x0U,
    PP2_CMD_PROXY = 0x1U,
} pp2_cmd_t;

typedef struct {
    pp2_cmd_t cmd;
    uint8_t family;    // 0=UNSPEC, 1=INET, 2=INET6
    uint8_t transport; // 0=UNSPEC, 1=STREAM, 2=DGRAM
    uint8_t src_addr[16];
    uint8_t dst_addr[16];
    uint16_t src_port;
    uint16_t dst_port;
    const uint8_t *tlv_slice;
    size_t tlv_len;
    size_t total_header_len;
} pp2_header_t;

[[nodiscard]] pp2_status_t pp2_decode(
    const uint8_t *buf,
    size_t buf_len,
    pp2_header_t *out
) {
    if (buf == nullptr || out == nullptr) {
        return PP2_ERR_NULL;
    }
