        addr_len = (hdr->family == 1U) ? 12U : 36U;
        fam_proto = (uint8_t)((hdr->family << 4) | (hdr->transport & 0x0FU));
    } else {
        return PP2_ERR_BAD_VER_CMD;
    }
    if (hdr->tlv_len > PP2_MAX_TOTAL - PP2_HDR_FIXED - addr_len) {
        return PP2_ERR_TOO_LARGE;
    }
    size_t payload_len = addr_len + hdr->tlv_len;
    size_t total = PP2_HDR_FIXED + payload_len;
    if (total > dst_cap) {
        return PP2_ERR_DST_SMALL;
    }
    memcpy(dst, PP2_SIG, 12U);
    dst[12] = (uint8_t)(0x20U | ((uint8_t)hdr->cmd & 0x0FU));
    dst[13] = fam_proto;
    dst[14] = (uint8_t)((payload_len >> 8) & 0xFFU);
    dst[15] = (uint8_t)(payload_len & 0xFFU);
    uint8_t *p = dst + PP2_HDR_FIXED;
