        memcpy(p + 4U, hdr->dst_addr, 4U);
        p[8] = (uint8_t)(hdr->src_port >> 8);
        p[9] = (uint8_t)(hdr->src_port & 0xFFU);
        p[10] = (uint8_t)(hdr->dst_port >> 8);
        p[11] = (uint8_t)(hdr->dst_port & 0xFFU);
        p += 12U;
    } else if (addr_len == 36U) {
        memcpy(p, hdr->src_addr, 16U);
        memcpy(p + 16U, hdr->dst_addr, 16U);
        p[32] = (uint8_t)(hdr->src_port >> 8);
        p[33] = (uint8_t)(hdr->src_port & 0xFFU);
        p[34] = (uint8_t)(hdr->dst_port >> 8);
        p[35] = (uint8_t)(hdr->dst_port & 0xFFU);
        p += 36U;
    }
    if (hdr->tlv_len > 0U) {
        memcpy(p, hdr->tlv_slice, hdr->tlv_len);
    }
    *written_out = total;
    return PP2_OK;
}
