pub const FERNET_VERSION: u8 = 0x80;
pub const MIN_TOKEN_LEN: usize = 1 + 8 + 16 + 16 + 32; // 73
pub const MAX_TOKEN_LEN: usize = 65_536;
pub const TAG_LEN: usize = 32;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FernetParts<'a> {
    pub timestamp: u64,
    pub iv: [u8; 16],
    pub ciphertext: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FernetWireError {
    InvalidLength(usize),
    BadVersion(u8),
    UnalignedCiphertext(usize),
    BadMac,
    FutureSkew { issued_at: u64, now_sec: u64 },
    Expired { issued_at: u64, now_sec: u64 },
}

fn ct_eq_32(a: &[u8; 32], b: &[u8; 32]) -> bool {
    let mut diff: u8 = 0;
    for i in 0..32 {
        diff |= a[i] ^ b[i];
    }
    diff == 0
}

pub fn parse_fernet_envelope<'a, F>(
    raw: &'a [u8],
    now_sec: u64,
    ttl_sec: u64,
    max_clock_skew_sec: u64,
    compute_hmac: F,
) -> Result<FernetParts<'a>, FernetWireError>
where
    F: FnOnce(&[u8]) -> [u8; 32],
{
    if raw.len() < MIN_TOKEN_LEN || raw.len() > MAX_TOKEN_LEN {
        return Err(FernetWireError::InvalidLength(raw.len()));
    }
    if raw[0] != FERNET_VERSION {
        return Err(FernetWireError::BadVersion(raw[0]));
    }
    let signed_end = raw.len() - TAG_LEN;
    let ct_len = signed_end - 25;
    if ct_len == 0 || ct_len % 16 != 0 {
        return Err(FernetWireError::UnalignedCiphertext(ct_len));
    }

    let expected_tag = compute_hmac(&raw[..signed_end]);
    let mut wire_tag = [0u8; 32];
    wire_tag.copy_from_slice(&raw[signed_end..]);
    if !ct_eq_32(&expected_tag, &wire_tag) {
        return Err(FernetWireError::BadMac);
    }

    let mut ts_bytes = [0u8; 8];
    ts_bytes.copy_from_slice(&raw[1..9]);
    let timestamp = u64::from_be_bytes(ts_bytes);

    if timestamp > now_sec.saturating_add(max_clock_skew_sec) {
        return Err(FernetWireError::FutureSkew {
            issued_at: timestamp,
            now_sec,
        });
    }
    if now_sec > timestamp && (now_sec - timestamp) > ttl_sec {
        return Err(FernetWireError::Expired {
            issued_at: timestamp,
            now_sec,
        });
    }

    let mut iv = [0u8; 16];
    iv.copy_from_slice(&raw[9..25]);
    Ok(FernetParts {
        timestamp,
        iv,
        ciphertext: &raw[25..signed_end],
    })
}

pub fn serialize_fernet_envelope<F>(
    timestamp: u64,
    iv: &[u8; 16],
    ciphertext: &[u8],
    compute_hmac: F,
    out: &mut Vec<u8>,
) -> Result<(), FernetWireError>
where
    F: FnOnce(&[u8]) -> [u8; 32],
{
    if ciphertext.is_empty() || ciphertext.len() % 16 != 0 {
        return Err(FernetWireError::UnalignedCiphertext(ciphertext.len()));
    }
    let total = 25usize
        .checked_add(ciphertext.len())
        .and_then(|n| n.checked_add(TAG_LEN))
        .ok_or(FernetWireError::InvalidLength(usize::MAX))?;
    if total > MAX_TOKEN_LEN {
        return Err(FernetWireError::InvalidLength(total));
    }
    let start = out.len();
    out.reserve(total);
    out.push(FERNET_VERSION);
    out.extend_from_slice(&timestamp.to_be_bytes());
    out.extend_from_slice(iv);
    out.extend_from_slice(ciphertext);
    let tag = compute_hmac(&out[start..]);
    out.extend_from_slice(&tag);
    Ok(())
}
