typedef enum : uint8_t {
    OTP_OK = 0,
    OTP_ERR_NULL,
    OTP_ERR_LENGTH,
    OTP_ERR_VERSION,
    OTP_ERR_ALG,
    OTP_ERR_DIGITS,
    OTP_ERR_RESERVED,
    OTP_ERR_DST_SMALL,
} otp_status_t;

typedef struct {
    uint8_t alg_id;
    uint8_t digits;
    uint64_t step_counter;
    uint32_t otp_code;
} otp_packet_t;

static inline size_t otp_digest_len(uint8_t alg_id) {
    switch (alg_id) {
        case 0x01U: return 20U;
        case 0x02U: return 32U;
        case 0x03U: return 64U;
        default:    return 0U;
    }
}

static inline uint32_t otp_pow10(uint8_t digits) {
    switch (digits) {
        case 6U: return 1000000U;
        case 7U: return 10000000U;
        case 8U: return 100000000U;
        default: return 0U;
    }
}

[[nodiscard]] otp_status_t otp_dynamic_truncate(
    const uint8_t *digest,
    size_t digest_len,
    uint8_t digits,
    uint32_t *code_out
) {
    if (digest == nullptr || code_out == nullptr) {
        return OTP_ERR_NULL;
    }
    if (digest_len != 20U && digest_len != 32U && digest_len != 64U) {
        return OTP_ERR_ALG;
    }
    uint32_t mod = otp_pow10(digits);
    if (mod == 0U) {
        return OTP_ERR_DIGITS;
    }
    size_t offset = (size_t)(digest[digest_len - 1U] & 0x0FU);
    if (offset + 4U > digest_len) {
        return OTP_ERR_LENGTH;
    }
    uint32_t bin_code =
        (((uint32_t)(digest[offset] & 0x7FU)) << 24) |
        (((uint32_t)digest[offset + 1U]) << 16) |
        (((uint32_t)digest[offset + 2U]) << 8) |
        ((uint32_t)digest[offset + 3U]);
    *code_out = bin_code % mod;
    return OTP_OK;
}

[[nodiscard]] otp_status_t otp_decode_packet(
    const uint8_t *buf,
    size_t buf_len,
    otp_packet_t *out
) {
    if (buf == nullptr || out == nullptr) {
        return OTP_ERR_NULL;
    }
    if (buf_len < 12U) {
        return OTP_ERR_LENGTH;
    }
    if (buf[0] != 0x01U) {
        return OTP_ERR_VERSION;
    }
    size_t dlen = otp_digest_len(buf[1]);
    if (dlen == 0U) {
        return OTP_ERR_ALG;
    }
    if (otp_pow10(buf[2]) == 0U) {
        return OTP_ERR_DIGITS;
    }
    if (buf[3] != 0x00U) {
        return OTP_ERR_RESERVED;
    }
    if (buf_len != 12U + dlen) {
        return OTP_ERR_LENGTH;
    }
    uint64_t ctr = 0ULL;
    for (size_t i = 0U; i < 8U; ++i) {
        ctr = (ctr << 8) | (uint64_t)buf[4U + i];
    }
    uint32_t code = 0U;
    otp_status_t st = otp_dynamic_truncate(buf + 12U, dlen, buf[2], &code);
    if (st != OTP_OK) {
        return st;
    }
    *out = (otp_packet_t){
        .alg_id = buf[1],
        .digits = buf[2],
        .step_counter = ctr,
        .otp_code = code,
    };
    return OTP_OK;
}

[[nodiscard]] otp_status_t otp_encode_packet(
    uint8_t alg_id,
    uint8_t digits,
    uint64_t step_counter,
    const uint8_t *digest,
    size_t digest_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (digest == nullptr || dst == nullptr || written_out == nullptr) {
        return OTP_ERR_NULL;
    }
    size_t expected_dlen = otp_digest_len(alg_id);
    if (expected_dlen == 0U || digest_len != expected_dlen) {
        return OTP_ERR_ALG;
    }
    if (otp_pow10(digits) == 0U) {
        return OTP_ERR_DIGITS;
    }
    size_t total = 12U + digest_len;
    if (dst_cap < total) {
        return OTP_ERR_DST_SMALL;
    }
    dst[0] = 0x01U;
    dst[1] = alg_id;
    dst[2] = digits;
    dst[3] = 0x00U;
    for (size_t i = 0U; i < 8U; ++i) {
        dst[11U - i] = (uint8_t)(step_counter & 0xFFU);
        step_counter >>= 8;
    }
    memcpy(dst + 12U, digest, digest_len);
    *written_out = total;
    return OTP_OK;
}
