pub const EPB_BLOCK_TYPE: u32 = 0x0000_0006;
pub const EPB_MIN_LEN: usize = 32;
pub const EPB_MAX_LEN: usize = 16_777_216;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EnhancedPacketBlock<'a> {
    pub interface_id: u32,
    pub ts_high: u32,
    pub ts_low: u32,
    pub orig_len: u32,
    pub packet_data: &'a [u8],
    pub options_raw: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EpbError {
    Truncated,
    WrongBlockType(u32),
    InvalidBlockLength(u32),
    TrailerLengthMismatch { header: u32, trailer: u32 },
    CapturedExceedsOriginal { captured: u32, orig: u32 },
    PacketDataOutOfBlock,
    UnalignedOptions(usize),
}

#[inline]
fn align4(n: usize) -> Option<usize> {
    n.checked_add(3).map(|v| v & !3usize)
}

pub fn decode_epb(buf: &[u8]) -> Result<(EnhancedPacketBlock<'_>, &[u8]), EpbError> {
    if buf.len() < EPB_MIN_LEN {
        return Err(EpbError::Truncated);
    }
    let btype = u32::from_le_bytes([buf[0], buf[1], buf[2], buf[3]]);
    if btype != EPB_BLOCK_TYPE {
        return Err(EpbError::WrongBlockType(btype));
