    let tr_pos = total - 4;
    let trailer_u32 = u32::from_le_bytes([block[tr_pos], block[tr_pos + 1], block[tr_pos + 2], block[tr_pos + 3]]);
    if total_u32 != trailer_u32 {
        return Err(EpbError::TrailerLengthMismatch {
            header: total_u32,
            trailer: trailer_u32,
        });
    }
    let interface_id = u32::from_le_bytes([block[8], block[9], block[10], block[11]]);
    let ts_high = u32::from_le_bytes([block[12], block[13], block[14], block[15]]);
    let ts_low = u32::from_le_bytes([block[16], block[17], block[18], block[19]]);
    let cap_len = u32::from_le_bytes([block[20], block[21], block[22], block[23]]);
    let orig_len = u32::from_le_bytes([block[24], block[25], block[26], block[27]]);
    if cap_len > orig_len {
        return Err(EpbError::CapturedExceedsOriginal {
            captured: cap_len,
            orig: orig_len,
        });
    }
    let cap_usize = cap_len as usize;
    let padded_cap = align4(cap_usize).ok_or(EpbError::PacketDataOutOfBlock)?;
    let opts_start = 28usize
        .checked_add(padded_cap)
        .ok_or(EpbError::PacketDataOutOfBlock)?;
    if opts_start > tr_pos {
        return Err(EpbError::PacketDataOutOfBlock);
    }
    let packet_data = &block[28..28 + cap_usize];
    let options_raw = &block[opts_start..tr_pos];
    Ok((
        EnhancedPacketBlock {
            interface_id,
            ts_high,
            ts_low,
            orig_len,
            packet_data,
            options_raw,
        },
        &buf[total..],
    ))
}

pub fn encode_epb(epb: &EnhancedPacketBlock<'_>, out: &mut Vec<u8>) -> Result<(), EpbError> {
    if epb.options_raw.len() % 4 != 0 {
        return Err(EpbError::UnalignedOptions(epb.options_raw.len()));
    }
    let cap_u32 = u32::try_from(epb.packet_data.len())
        .map_err(|_| EpbError::InvalidBlockLength(u32::MAX))?;
    if cap_u32 > epb.orig_len {
        return Err(EpbError::CapturedExceedsOriginal {
            captured: cap_u32,
            orig: epb.orig_len,
        });
    }
    let padded_cap = align4(epb.packet_data.len()).ok_or(EpbError::PacketDataOutOfBlock)?;
    let total = 28usize
        .checked_add(padded_cap)
        .and_then(|v| v.checked_add(epb.options_raw.len()))
        .and_then(|v| v.checked_add(4))
        .ok_or(EpbError::InvalidBlockLength(u32::MAX))?;
    if total > EPB_MAX_LEN {
        return Err(EpbError::InvalidBlockLength(u32::try_from(total).unwrap_or(u32::MAX)));
    }
    let total_u32 = total as u32;
    out.reserve(total);
    out.extend_from_slice(&EPB_BLOCK_TYPE.to_le_bytes());
    out.extend_from_slice(&total_u32.to_le_bytes());
    out.extend_from_slice(&epb.interface_id.to_le_bytes());
    out.extend_from_slice(&epb.ts_high.to_le_bytes());
    out.extend_from_slice(&epb.ts_low.to_le_bytes());
    out.extend_from_slice(&cap_u32.to_le_bytes());
