const maxPNGUint31 = 0x7FFFFFFF

type Chunk struct {
	Type      [4]byte
	Data      []byte
	CRC       uint32
	Ancillary bool
}

type IHDR struct {
	Width             uint32
	Height            uint32
	BitDepth          uint8
	ColorType         uint8
	CompressionMethod uint8
	FilterMethod      uint8
	InterlaceMethod   uint8
}

type ParsedStream struct {
	Header IHDR
