			if w == 0 || w > maxPNGUint31 || hgt == 0 || hgt > maxPNGUint31 {
				return nil, fmt.Errorf("png: invalid IHDR dimensions %dx%d", w, hgt)
			}
			out.Header = IHDR{
				Width:             w,
				Height:            hgt,
				BitDepth:          dataSlice[8],
				ColorType:         dataSlice[9],
				CompressionMethod: dataSlice[10],
				FilterMethod:      dataSlice[11],
				InterlaceMethod:   dataSlice[12],
			}
		} else if string(ctype[:]) == "IHDR" {
			return nil, errors.New("png: duplicate IHDR chunk")
		}

