export type H2ErrorCode =
  | "PROTOCOL_ERROR"
  | "FLOW_CONTROL_ERROR"
  | "SETTINGS_TIMEOUT"
  | "FRAME_SIZE_ERROR";

export class H2FrameError extends Error {
  constructor(
    public readonly code: H2ErrorCode,
    message: string,
  ) {
    super(message);
    this.name = "H2FrameError";
  }
}

export interface FrameHeader {
  length: number;
  type: number;
  flags: number;
  reservedBit: number;
  streamId: number;
}

export interface SettingEntry {
  id: number;
  value: number;
}

export type ParsedH2Frame =
  | { kind: "SETTINGS"; header: FrameHeader; ack: boolean; entries: SettingEntry[] }
  | { kind: "WINDOW_UPDATE"; header: FrameHeader; windowSizeIncrement: number }
  | { kind: "RAW"; header: FrameHeader; payload: Uint8Array };

export function parseHttp2Frame(
  buf: Uint8Array,
  maxFrameSize = 16_384,
): { frame: ParsedH2Frame; bytesConsumed: number } {
  if (maxFrameSize < 16_384 || maxFrameSize > 16_777_215) {
    throw new RangeError("Invalid maxFrameSize setting bound");
  }
  if (buf.byteLength < 9) {
    throw new H2FrameError("FRAME_SIZE_ERROR", "Truncated 9-byte HTTP/2 frame header");
  }

  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const length = (view.getUint8(0) << 16) | (view.getUint8(1) << 8) | view.getUint8(2);
  if (length > maxFrameSize) {
    throw new H2FrameError(
      "FRAME_SIZE_ERROR",
      `Frame payload length ${length} exceeds maxFrameSize ${maxFrameSize}`,
    );
  }

  const totalBytes = 9 + length;
  if (buf.byteLength < totalBytes) {
    throw new H2FrameError("FRAME_SIZE_ERROR", "Truncated HTTP/2 frame payload");
  }

  const type = view.getUint8(3);
  const flags = view.getUint8(4);
  const rawStreamWord = view.getUint32(5, false);
  const reservedBit = (rawStreamWord >>> 31) & 1;
  const streamId = (rawStreamWord & 0x7fffffff) >>> 0;
  const header: FrameHeader = { length, type, flags, reservedBit, streamId };

  if (type === 0x04) {
    if (streamId !== 0) {
      throw new H2FrameError("PROTOCOL_ERROR", "SETTINGS frame must use streamId 0");
    }
    const ack = (flags & 0x01) !== 0;
    if (ack) {
      if (length !== 0) {
        throw new H2FrameError("FRAME_SIZE_ERROR", "SETTINGS ACK frame must have empty payload");
      }
      return { frame: { kind: "SETTINGS", header, ack: true, entries: [] }, bytesConsumed: totalBytes };
    }
    if (length % 6 !== 0) {
      throw new H2FrameError("FRAME_SIZE_ERROR", "SETTINGS length must be a multiple of 6");
    }
    const entries: SettingEntry[] = [];
    for (let off = 9; off < totalBytes; off += 6) {
      const id = view.getUint16(off, false);
      const value = view.getUint32(off + 2, false);
      if (id === 0x02 && value !== 0 && value !== 1) {
        throw new H2FrameError("PROTOCOL_ERROR", `Invalid SETTINGS_ENABLE_PUSH value: ${value}`);
      }
      if (id === 0x04 && value > 0x7fffffff) {
        throw new H2FrameError("FLOW_CONTROL_ERROR", "SETTINGS_INITIAL_WINDOW_SIZE exceeds 2^31-1");
      }
      if (id === 0x05 && (value < 16_384 || value > 16_777_215)) {
        throw new H2FrameError("PROTOCOL_ERROR", `Invalid SETTINGS_MAX_FRAME_SIZE: ${value}`);
      }
      entries.push({ id, value });
    }
    return { frame: { kind: "SETTINGS", header, ack: false, entries }, bytesConsumed: totalBytes };
  }

  if (type === 0x08) {
    if (length !== 4) {
      throw new H2FrameError("FRAME_SIZE_ERROR", "WINDOW_UPDATE length must be exactly 4 bytes");
    }
    const increment = (view.getUint32(9, false) & 0x7fffffff) >>> 0;
    if (increment === 0) {
      throw new H2FrameError("PROTOCOL_ERROR", "WINDOW_UPDATE increment must be non-zero");
    }
    return {
      frame: { kind: "WINDOW_UPDATE", header, windowSizeIncrement: increment },
      bytesConsumed: totalBytes,
    };
  }

  return {
    frame: { kind: "RAW", header, payload: buf.subarray(9, totalBytes) },
    bytesConsumed: totalBytes,
  };
}
