func parseALPN(ext []byte) ([]string, error) {
	if len(ext) < 4 {
		return nil, errors.New("tls: ALPN extension too short")
	}
	listLen := int(binary.BigEndian.Uint16(ext[0:2]))
	if listLen != len(ext)-2 || listLen < 2 {
		return nil, fmt.Errorf("tls: ALPN list_len %d != ext_len-2 (%d)", listLen, len(ext)-2)
	}
