}

func ParseClientHelloExtensions(buf []byte) (*ClientHelloExtensions, error) {
	if len(buf) < 10 {
		return nil, errors.New("tls: ClientHello extensions block < 8 bytes payload")
	}
	blockLen := int(binary.BigEndian.Uint16(buf[0:2]))
	if blockLen < 8 || blockLen != len(buf)-2 {
		return nil, fmt.Errorf("tls: extensions block length %d mismatches buffer %d", blockLen, len(buf)-2)
	}
	seen := make(map[uint16]struct{})
	var out ClientHelloExtensions
	off := 2
	for off < len(buf) {
		if len(buf)-off < 4 {
			return nil, errors.New("tls: truncated extension header")
		}
		extType := binary.BigEndian.Uint16(buf[off : off+2])
		extLen := int(binary.BigEndian.Uint16(buf[off+2 : off+4]))
		off += 4
		if len(buf)-off < extLen {
			return nil, fmt.Errorf("tls: extension 0x%04x overruns extensions block", extType)
		}
		if _, dup := seen[extType]; dup {
			return nil, fmt.Errorf("tls: duplicate extension 0x%04x", extType)
		}
		seen[extType] = struct{}{}
		out.ExtensionIDs = append(out.ExtensionIDs, extType)

		payload := buf[off : off+extLen]
		off += extLen

		switch extType {
		case ExtServerName:
			sni, err := parseSNI(payload)
			if err != nil {
				return nil, err
			}
			out.ServerName = sni
		case ExtALPN:
			alpn, err := parseALPN(payload)
			if err != nil {
				return nil, err
			}
			out.ALPNProtocols = alpn
		}
	}
	return &out, nil
}
