#include <stddef.h>
#include <stdint.h>
#include <string.h>

static constexpr size_t NETSTR_MAX_LEN = 262144U;

typedef enum : uint8_t {
    NS_OK = 0,
    NS_ERR_NULL,
    NS_ERR_TRUNCATED,
    NS_ERR_LEADING_ZERO,
    NS_ERR_BAD_DIGIT,
    NS_ERR_TOO_LARGE,
    NS_ERR_MISSING_COMMA,
    NS_ERR_DST_SMALL,
} ns_status_t;

typedef struct {
    const uint8_t *data;
    size_t data_len;
    size_t consumed;
} ns_view_t;

[[nodiscard]] ns_status_t netstring_decode(
    const uint8_t *buf,
    size_t buf_len,
    ns_view_t *out
) {
    if (buf == nullptr || out == nullptr) {
        return NS_ERR_NULL;
    }
    if (buf_len < 3U) {
        return NS_ERR_TRUNCATED;
    }
    size_t pos = 0U;
    size_t dlen = 0U;
    if (buf[0] == '0') {
        if (buf[1] != ':') {
            return (buf[1] >= '0' && buf[1] <= '9') ? NS_ERR_LEADING_ZERO : NS_ERR_BAD_DIGIT;
        }
        pos = 2U;
        dlen = 0U;
    } else if (buf[0] >= '1' && buf[0] <= '9') {
        while (pos < buf_len && buf[pos] != ':') {
            uint8_t c = buf[pos];
            if (c < '0' || c > '9') {
                return NS_ERR_BAD_DIGIT;
            }
            dlen = dlen * 10U + (size_t)(c - '0');
            if (dlen > NETSTR_MAX_LEN) {
                return NS_ERR_TOO_LARGE;
            }
            ++pos;
        }
        if (pos >= buf_len) {
            return NS_ERR_TRUNCATED;
        }
        ++pos; // skip ':'
    } else {
        return NS_ERR_BAD_DIGIT;
    }

    if (buf_len - pos < dlen + 1U) {
        return NS_ERR_TRUNCATED;
    }
    if (buf[pos + dlen] != ',') {
        return NS_ERR_MISSING_COMMA;
    }
    *out = (ns_view_t){
        .data = buf + pos,
        .data_len = dlen,
        .consumed = pos + dlen + 1U,
    };
    return NS_OK;
}

[[nodiscard]] ns_status_t netstring_encode(
    const uint8_t *data,
    size_t data_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (dst == nullptr || written_out == nullptr || (data_len > 0U && data == nullptr)) {
        return NS_ERR_NULL;
    }
    if (data_len > NETSTR_MAX_LEN) {
        return NS_ERR_TOO_LARGE;
    }
    uint8_t digits[8];
    size_t ndig = 0U;
    size_t tmp = data_len;
    do {
        digits[ndig++] = (uint8_t)('0' + (tmp % 10U));
        tmp /= 10U;
    } while (tmp > 0U);

    size_t total = ndig + 1U + data_len + 1U;
    if (dst_cap < total) {
        return NS_ERR_DST_SMALL;
    }
    for (size_t i = 0U; i < ndig; ++i) {
        dst[i] = digits[ndig - 1U - i];
    }
    dst[ndig] = ':';
    if (data_len > 0U) {
        memcpy(dst + ndig + 1U, data, data_len);
    }
    dst[ndig + 1U + data_len] = ',';
    *written_out = total;
    return NS_OK;
}
