pub const H2_HEADER_LEN: usize = 9;
pub const H2_MIN_MAX_FRAME: u32 = 16_384;
pub const H2_ABS_MAX_FRAME: u32 = 16_777_215;

pub const TYPE_SETTINGS: u8 = 0x04;
pub const TYPE_PING: u8 = 0x06;
pub const TYPE_WINDOW_UPDATE: u8 = 0x08;
pub const FLAG_ACK: u8 = 0x01;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct H2Frame<'a> {
    pub frame_type: u8,
    pub flags: u8,
    pub stream_id: u32,
    pub payload: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum H2FrameError {
    InvalidMaxFrameSetting(u32),
    Truncated,
    FrameSizeError(u32),
    ReservedBitSet,
    ProtocolError(&'static str),
}

fn validate_semantics(ft: u8, flags: u8, stream_id: u32, payload: &[u8]) -> Result<(), H2FrameError> {
    match ft {
        TYPE_SETTINGS => {
            if stream_id != 0 {
                return Err(H2FrameError::ProtocolError("SETTINGS requires stream_id == 0"));
            }
            if (flags & FLAG_ACK) != 0 {
                if !payload.is_empty() {
                    return Err(H2FrameError::FrameSizeError(payload.len() as u32));
                }
            } else if payload.len() % 6 != 0 {
                return Err(H2FrameError::FrameSizeError(payload.len() as u32));
            }
        }
        TYPE_PING => {
            if stream_id != 0 {
                return Err(H2FrameError::ProtocolError("PING requires stream_id == 0"));
            }
            if payload.len() != 8 {
                return Err(H2FrameError::FrameSizeError(payload.len() as u32));
            }
        }
        TYPE_WINDOW_UPDATE => {
            if payload.len() != 4 {
                return Err(H2FrameError::FrameSizeError(payload.len() as u32));
            }
            let inc = u32::from_be_bytes([payload[0], payload[1], payload[2], payload[3]]) & 0x7FFF_FFFF;
            if inc == 0 {
                return Err(H2FrameError::ProtocolError("WINDOW_UPDATE increment cannot be 0"));
            }
        }
        _ => {}
    }
    Ok(())
}

pub fn decode_h2_frame(buf: &[u8], max_frame_size: u32) -> Result<(H2Frame<'_>, &[u8]), H2FrameError> {
    if !(H2_MIN_MAX_FRAME..=H2_ABS_MAX_FRAME).contains(&max_frame_size) {
        return Err(H2FrameError::InvalidMaxFrameSetting(max_frame_size));
    }
    let hdr = buf.get(..H2_HEADER_LEN).ok_or(H2FrameError::Truncated)?;
    let len = ((hdr[0] as u32) << 16) | ((hdr[1] as u32) << 8) | (hdr[2] as u32);
