    frame: &H2Frame<'_>,
    max_frame_size: u32,
    out: &mut Vec<u8>,
) -> Result<(), H2FrameError> {
    if !(H2_MIN_MAX_FRAME..=H2_ABS_MAX_FRAME).contains(&max_frame_size) {
