pub enum SlebError {
    Truncated,
    Overflow,
    NonCanonical,
}

pub fn encode_sleb128_i64(mut value: i64, out: &mut Vec<u8>) {
    loop {
        let mut byte = (value as u8) & 0x7F;
        value >>= 7;
        let sign_bit_set = (byte & 0x40) != 0;
        let done = (value == 0 && !sign_bit_set) || (value == -1 && sign_bit_set);
        if !done {
            byte |= 0x80;
        }
        out.push(byte);
        if done {
            break;
        }
    }
}

pub fn decode_sleb128_i64_canonical(buf: &[u8]) -> Result<(i64, &[u8]), SlebError> {
    let mut result: u64 = 0;
    let mut shift: u32 = 0;

    for i in 0..10usize {
        let &byte = buf.get(i).ok_or(SlebError::Truncated)?;
        if i == 9 {
            if (byte & 0x80) != 0 {
                return Err(SlebError::Overflow);
            }
            if byte != 0x00 && byte != 0x7F {
                return Err(SlebError::Overflow);
            }
        }

        let low = u64::from(byte & 0x7F);
        if shift < 64 {
            result |= low << shift;
        }
        shift += 7;

        if (byte & 0x80) == 0 {
            if i > 0 {
                let prev = buf[i - 1];
                if byte == 0x00 && (prev & 0x40) == 0 {
                    return Err(SlebError::NonCanonical);
                }
                if byte == 0x7F && (prev & 0x40) != 0 {
                    return Err(SlebError::NonCanonical);
                }
            }
            if shift < 64 && (byte & 0x40) != 0 {
                result |= (!0u64) << shift;
            }
            return Ok((result as i64, &buf[i + 1..]));
        }
    }
    Err(SlebError::Overflow)
}
