#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Socks5Cmd {
    Connect = 0x01,
    Bind = 0x02,
    UdpAssociate = 0x03,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Socks5Addr<'a> {
    V4([u8; 4]),
    Domain(&'a str),
    V6([u8; 16]),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Socks5Request<'a> {
    pub cmd: Socks5Cmd,
    pub dst_addr: Socks5Addr<'a>,
    pub dst_port: u16,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Socks5Error {
    Truncated,
    BadVersion(u8),
    BadCmd(u8),
    NonZeroRsv(u8),
    BadAtyp(u8),
    InvalidDomain,
}

fn validate_domain_bytes(raw: &[u8]) -> Result<&str, Socks5Error> {
    if raw.is_empty() || raw.len() > 253 {
        return Err(Socks5Error::InvalidDomain);
    }
    for &b in raw {
        if b <= 0x20 || b >= 0x7F {
            return Err(Socks5Error::InvalidDomain);
        }
    }
    std::str::from_utf8(raw).map_err(|_| Socks5Error::InvalidDomain)
}

pub fn decode_socks5_request(buf: &[u8]) -> Result<(Socks5Request<'_>, &[u8]), Socks5Error> {
    let hdr = buf.get(..4).ok_or(Socks5Error::Truncated)?;
    if hdr[0] != 0x05 {
        return Err(Socks5Error::BadVersion(hdr[0]));
    }
    let cmd = match hdr[1] {
        0x01 => Socks5Cmd::Connect,
        0x02 => Socks5Cmd::Bind,
        0x03 => Socks5Cmd::UdpAssociate,
        other => return Err(Socks5Error::BadCmd(other)),
    };
    if hdr[2] != 0x00 {
        return Err(Socks5Error::NonZeroRsv(hdr[2]));
    }
    let (dst_addr, pos) = match hdr[3] {
        0x01 => {
            let ip_slice = buf.get(4..8).ok_or(Socks5Error::Truncated)?;
            let mut ip = [0u8; 4];
            ip.copy_from_slice(ip_slice);
            (Socks5Addr::V4(ip), 8usize)
        }
        0x03 => {
            let dlen = (*buf.get(4).ok_or(Socks5Error::Truncated)?) as usize;
            let end = 5 + dlen;
            let raw = buf.get(5..end).ok_or(Socks5Error::Truncated)?;
            let host = validate_domain_bytes(raw)?;
            (Socks5Addr::Domain(host), end)
        }
        0x04 => {
            let ip_slice = buf.get(4..20).ok_or(Socks5Error::Truncated)?;
            let mut ip = [0u8; 16];
            ip.copy_from_slice(ip_slice);
            (Socks5Addr::V6(ip), 20usize)
        }
        other => return Err(Socks5Error::BadAtyp(other)),
    };
    let port_slice = buf.get(pos..pos + 2).ok_or(Socks5Error::Truncated)?;
    let dst_port = u16::from_be_bytes([port_slice[0], port_slice[1]]);
    Ok((
        Socks5Request {
            cmd,
            dst_addr,
            dst_port,
        },
        &buf[pos + 2..],
    ))
}

pub fn encode_socks5_request(req: &Socks5Request<'_>, out: &mut Vec<u8>) -> Result<(), Socks5Error> {
    out.push(0x05);
    out.push(req.cmd as u8);
    out.push(0x00);
    match &req.dst_addr {
        Socks5Addr::V4(ip) => {
            out.push(0x01);
            out.extend_from_slice(ip);
        }
        Socks5Addr::Domain(host) => {
            let _ = validate_domain_bytes(host.as_bytes())?;
            out.push(0x03);
            out.push(host.len() as u8);
            out.extend_from_slice(host.as_bytes());
        }
        Socks5Addr::V6(ip) => {
            out.push(0x04);
            out.extend_from_slice(ip);
        }
    }
    out.extend_from_slice(&req.dst_port.to_be_bytes());
    Ok(())
}
