static constexpr size_t GENEVE_FIXED_LEN = 8U;
static constexpr size_t GENEVE_MAX_OPTS  = 16U;

typedef enum : uint8_t {
    GNV_OK = 0,
    GNV_ERR_NULL,
    GNV_ERR_TRUNCATED,
    GNV_ERR_VERSION,
    GNV_ERR_RESERVED,
    GNV_ERR_OPT_MALFORMED,
    GNV_ERR_TOO_MANY_OPTS,
    GNV_ERR_VNI_RANGE,
    GNV_ERR_DST_SMALL,
} gnv_status_t;

typedef struct {
    uint16_t opt_class;
    uint8_t opt_type;
    const uint8_t *data;
    size_t data_len; // MUST be multiple of 4 and <= 124
} gnv_option_t;

typedef struct {
    bool oam;
    bool critical;
    uint16_t proto_type;
    uint32_t vni; // 24-bit
    gnv_option_t opts[GENEVE_MAX_OPTS];
    size_t opt_count;
    size_t header_total_len;
} gnv_header_t;

[[nodiscard]] gnv_status_t geneve_decode(
    const uint8_t *buf,
    size_t buf_len,
    gnv_header_t *out
) {
