    size_t total = GENEVE_FIXED_LEN + opt_bytes;
    if (buf_len < total) {
        return GNV_ERR_TRUNCATED;
    }

    memset(out, 0, sizeof(*out));
    out->oam = (buf[1] & 0x80U) != 0U;
    out->critical = (buf[1] & 0x40U) != 0U;
    out->proto_type = (uint16_t)(((uint16_t)buf[2] << 8) | (uint16_t)buf[3]);
    out->vni = ((uint32_t)buf[4] << 16) | ((uint32_t)buf[5] << 8) | (uint32_t)buf[6];
    out->header_total_len = total;

    size_t pos = GENEVE_FIXED_LEN;
    while (pos < total) {
        if (total - pos < 4U) {
            return GNV_ERR_OPT_MALFORMED;
        }
        if ((buf[pos + 3U] & 0xE0U) != 0U) {
            return GNV_ERR_RESERVED;
        }
        size_t olen = (size_t)(buf[pos + 3U] & 0x1FU) * 4U;
        if (total - (pos + 4U) < olen) {
            return GNV_ERR_OPT_MALFORMED;
