        if (out->opt_count >= GENEVE_MAX_OPTS) {
            return GNV_ERR_TOO_MANY_OPTS;
        }
        out->opts[out->opt_count++] = (gnv_option_t){
            .opt_class = (uint16_t)(((uint16_t)buf[pos] << 8) | (uint16_t)buf[pos + 1U]),
            .opt_type = buf[pos + 2U],
            .data = buf + pos + 4U,
            .data_len = olen,
        };
        pos += 4U + olen;
    }
    return GNV_OK;
}

[[nodiscard]] gnv_status_t geneve_encode(
    const gnv_header_t *hdr,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
