pub const SSHSIG_MAGIC: &[u8; 6] = b"SSHSIG";
pub const SSHSIG_VERSION: u32 = 1;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SshSigHash {
    Sha256,
    Sha512,
}

impl SshSigHash {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Sha256 => "sha256",
            Self::Sha512 => "sha512",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SshSigBlob<'a> {
    pub public_key: &'a [u8],
    pub namespace: &'a str,
    pub reserved: &'a [u8],
    pub hash_alg: SshSigHash,
    pub signature: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SshSigError {
    Truncated,
    BadMagic,
    UnsupportedVersion(u32),
    FieldBounds(&'static str),
    InvalidNamespace,
    UnsupportedHash,
    TrailingBytes(usize),
}

fn read_ssh_string<'a>(
    buf: &'a [u8],
    min_len: usize,
    max_len: usize,
    field: &'static str,
) -> Result<(&'a [u8], &'a [u8]), SshSigError> {
    let lbytes = buf.get(..4).ok_or(SshSigError::Truncated)?;
    let len = u32::from_be_bytes([lbytes[0], lbytes[1], lbytes[2], lbytes[3]]) as usize;
    if len < min_len || len > max_len {
        return Err(SshSigError::FieldBounds(field));
    }
    let end = 4usize.checked_add(len).ok_or(SshSigError::FieldBounds(field))?;
    let val = buf.get(4..end).ok_or(SshSigError::Truncated)?;
    Ok((val, &buf[end..]))
}

fn write_ssh_string(
    data: &[u8],
    min_len: usize,
    max_len: usize,
    field: &'static str,
    out: &mut Vec<u8>,
) -> Result<(), SshSigError> {
    if data.len() < min_len || data.len() > max_len {
        return Err(SshSigError::FieldBounds(field));
    }
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(data);
    Ok(())
}

pub fn decode_sshsig_blob(buf: &[u8]) -> Result<SshSigBlob<'_>, SshSigError> {
    let pre = buf.get(..10).ok_or(SshSigError::Truncated)?;
    if &pre[..6] != SSHSIG_MAGIC {
        return Err(SshSigError::BadMagic);
    }
    let ver = u32::from_be_bytes([pre[6], pre[7], pre[8], pre[9]]);
    if ver != SSHSIG_VERSION {
        return Err(SshSigError::UnsupportedVersion(ver));
    }
    let rest = &buf[10..];
    let (public_key, rest) = read_ssh_string(rest, 1, 8192, "publickey")?;
    let (ns_raw, rest) = read_ssh_string(rest, 1, 256, "namespace")?;
    if ns_raw.iter().any(|&b| b <= 0x20 || b >= 0x7F) {
        return Err(SshSigError::InvalidNamespace);
    }
    let namespace = std::str::from_utf8(ns_raw).map_err(|_| SshSigError::InvalidNamespace)?;
    let (reserved, rest) = read_ssh_string(rest, 0, 1024, "reserved")?;
    let (hash_raw, rest) = read_ssh_string(rest, 6, 6, "hash_algorithm")?;
    let hash_alg = match hash_raw {
        b"sha256" => SshSigHash::Sha256,
        b"sha512" => SshSigHash::Sha512,
        _ => return Err(SshSigError::UnsupportedHash),
    };
    let (signature, rest) = read_ssh_string(rest, 1, 8192, "signature")?;
    if !rest.is_empty() {
        return Err(SshSigError::TrailingBytes(rest.len()));
    }
    Ok(SshSigBlob {
        public_key,
        namespace,
        reserved,
        hash_alg,
        signature,
    })
}

pub fn encode_sshsig_blob(blob: &SshSigBlob<'_>, out: &mut Vec<u8>) -> Result<(), SshSigError> {
    if blob.namespace.bytes().any(|b| b <= 0x20 || b >= 0x7F) {
        return Err(SshSigError::InvalidNamespace);
    }
    out.extend_from_slice(SSHSIG_MAGIC);
    out.extend_from_slice(&SSHSIG_VERSION.to_be_bytes());
    write_ssh_string(blob.public_key, 1, 8192, "publickey", out)?;
    write_ssh_string(blob.namespace.as_bytes(), 1, 256, "namespace", out)?;
    write_ssh_string(blob.reserved, 0, 1024, "reserved", out)?;
    write_ssh_string(blob.hash_alg.as_str().as_bytes(), 6, 6, "hash_algorithm", out)?;
    write_ssh_string(blob.signature, 1, 8192, "signature", out)?;
    Ok(())
}
