static constexpr size_t PASETO_V4_NONCE_LEN = 32U;
static constexpr size_t PASETO_V4_TAG_LEN   = 32U;
static constexpr size_t PASETO_V4_MAX_CT    = 65536U;

typedef enum : uint8_t {
    PV4_OK = 0,
    PV4_ERR_NULL,
    PV4_ERR_LENGTH,
    PV4_ERR_BAD_TAG,
    PV4_ERR_DST_SMALL,
} pv4_status_t;

typedef struct {
    const uint8_t *ptr;
    size_t len;
} pv4_slice_t;

typedef struct {
    uint8_t nonce[32];
    const uint8_t *ciphertext;
    size_t ciphertext_len;
} pv4_local_parts_t;

static inline void write_le64(uint8_t dst[8], uint64_t v) {
    for (size_t i = 0U; i < 8U; ++i) {
        dst[i] = (uint8_t)(v & 0xFFU);
        v >>= 8;
    }
}

static inline bool ct_eq_32(const uint8_t a[32], const uint8_t b[32]) {
    uint8_t diff = 0U;
    for (size_t i = 0U; i < 32U; ++i) {
        diff |= (uint8_t)(a[i] ^ b[i]);
    }
    return diff == 0U;
}

[[nodiscard]] pv4_status_t paseto_pae_encode(
    const pv4_slice_t *pieces,
    size_t count,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (dst == nullptr || written_out == nullptr || (count > 0U && pieces == nullptr)) {
        return PV4_ERR_NULL;
    }
    if ((uint64_t)count > 0x7FFFFFFFFFFFFFFFULL) {
        return PV4_ERR_LENGTH;
    }
    size_t total = 8U;
    for (size_t i = 0U; i < count; ++i) {
        if (pieces[i].len > 0U && pieces[i].ptr == nullptr) {
            return PV4_ERR_NULL;
        }
        if ((uint64_t)pieces[i].len > 0x7FFFFFFFFFFFFFFFULL) {
            return PV4_ERR_LENGTH;
        }
        if (pieces[i].len > SIZE_MAX - 8U || total > SIZE_MAX - (8U + pieces[i].len)) {
            return PV4_ERR_LENGTH;
        }
        total += 8U + pieces[i].len;
    }
    if (dst_cap < total) {
        return PV4_ERR_DST_SMALL;
    }
    write_le64(dst, (uint64_t)count);
    size_t pos = 8U;
    for (size_t i = 0U; i < count; ++i) {
        write_le64(dst + pos, (uint64_t)pieces[i].len);
        pos += 8U;
        if (pieces[i].len > 0U) {
            memcpy(dst + pos, pieces[i].ptr, pieces[i].len);
            pos += pieces[i].len;
        }
    }
    *written_out = total;
    return PV4_OK;
}

[[nodiscard]] pv4_status_t paseto_v4_local_unpack(
    const uint8_t *raw_body,
    size_t raw_len,
    const uint8_t expected_tag[32],
    pv4_local_parts_t *out
) {
    if (raw_body == nullptr || expected_tag == nullptr || out == nullptr) {
        return PV4_ERR_NULL;
    }
    size_t overhead = PASETO_V4_NONCE_LEN + PASETO_V4_TAG_LEN;
    if (raw_len < overhead || raw_len - overhead > PASETO_V4_MAX_CT) {
        return PV4_ERR_LENGTH;
    }
    size_t tag_offset = raw_len - PASETO_V4_TAG_LEN;
    if (!ct_eq_32(raw_body + tag_offset, expected_tag)) {
        return PV4_ERR_BAD_TAG;
    }
    memcpy(out->nonce, raw_body, PASETO_V4_NONCE_LEN);
    out->ciphertext = raw_body + PASETO_V4_NONCE_LEN;
    out->ciphertext_len = tag_offset - PASETO_V4_NONCE_LEN;
    return PV4_OK;
}

[[nodiscard]] pv4_status_t paseto_v4_local_pack(
    const uint8_t nonce[32],
    const uint8_t *ciphertext,
    size_t ciphertext_len,
    const uint8_t tag[32],
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (nonce == nullptr || tag == nullptr || dst == nullptr || written_out == nullptr) {
        return PV4_ERR_NULL;
    }
    if (ciphertext_len > 0U && ciphertext == nullptr) {
        return PV4_ERR_NULL;
    }
    if (ciphertext_len > PASETO_V4_MAX_CT) {
        return PV4_ERR_LENGTH;
    }
    size_t total = PASETO_V4_NONCE_LEN + ciphertext_len + PASETO_V4_TAG_LEN;
    if (dst_cap < total) {
        return PV4_ERR_DST_SMALL;
    }
    memcpy(dst, nonce, PASETO_V4_NONCE_LEN);
    if (ciphertext_len > 0U) {
        memcpy(dst + PASETO_V4_NONCE_LEN, ciphertext, ciphertext_len);
    }
    memcpy(dst + PASETO_V4_NONCE_LEN + ciphertext_len, tag, PASETO_V4_TAG_LEN);
    *written_out = total;
    return PV4_OK;
}
