pub const MAX_FIELD_NAME: usize = 64;
pub const MAX_FIELD_VALUE: usize = 1_048_576;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JournalField<'a> {
    pub name: &'a str,
    pub value: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum JournalExportError {
    Truncated,
    InvalidFieldName,
    ValueTooLarge(u64),
    MissingTrailingNewline,
}

fn validate_field_name(raw: &[u8]) -> Result<&str, JournalExportError> {
    if raw.is_empty() || raw.len() > MAX_FIELD_NAME {
        return Err(JournalExportError::InvalidFieldName);
    }
    let first = raw[0];
    if !(first.is_ascii_uppercase() || first == b'_') {
        return Err(JournalExportError::InvalidFieldName);
    }
    for &b in &raw[1..] {
        if !(b.is_ascii_uppercase() || b.is_ascii_digit() || b == b'_') {
            return Err(JournalExportError::InvalidFieldName);
        }
    }
    std::str::from_utf8(raw).map_err(|_| JournalExportError::InvalidFieldName)
}

pub fn decode_journal_field(buf: &[u8]) -> Result<(JournalField<'_>, &[u8]), JournalExportError> {
    let sep_pos = buf
        .iter()
        .take(MAX_FIELD_NAME + 1)
        .position(|&b| b == b'=' || b == b'\n')
        .ok_or_else(|| {
            if buf.len() <= MAX_FIELD_NAME {
                JournalExportError::Truncated
            } else {
                JournalExportError::InvalidFieldName
            }
        })?;

    let name = validate_field_name(&buf[..sep_pos])?;
    let sep = buf[sep_pos];
    let after_sep = &buf[sep_pos + 1..];

    if sep == b'=' {
        let nl_rel = after_sep
            .iter()
            .take(MAX_FIELD_VALUE + 1)
            .position(|&b| b == b'\n')
            .ok_or_else(|| {
                if after_sep.len() > MAX_FIELD_VALUE {
                    JournalExportError::ValueTooLarge(after_sep.len() as u64)
                } else {
                    JournalExportError::Truncated
                }
            })?;
        let value = &after_sep[..nl_rel];
        Ok((JournalField { name, value }, &after_sep[nl_rel + 1..]))
    } else {
        let len_bytes = after_sep.get(..8).ok_or(JournalExportError::Truncated)?;
        let mut arr = [0u8; 8];
        arr.copy_from_slice(len_bytes);
        let raw_len = u64::from_le_bytes(arr);
        if raw_len > MAX_FIELD_VALUE as u64 {
            return Err(JournalExportError::ValueTooLarge(raw_len));
        }
        let vlen = raw_len as usize;
        let val_end = 8 + vlen;
        let value = after_sep.get(8..val_end).ok_or(JournalExportError::Truncated)?;
        let &tr_nl = after_sep.get(val_end).ok_or(JournalExportError::Truncated)?;
        if tr_nl != b'\n' {
            return Err(JournalExportError::MissingTrailingNewline);
        }
        Ok((JournalField { name, value }, &after_sep[val_end + 1..]))
    }
}

pub fn encode_journal_field(field: &JournalField<'_>, out: &mut Vec<u8>) -> Result<(), JournalExportError> {
    let _ = validate_field_name(field.name.as_bytes())?;
    if field.value.len() > MAX_FIELD_VALUE {
        return Err(JournalExportError::ValueTooLarge(field.value.len() as u64));
    }
    let safe_text = std::str::from_utf8(field.value).is_ok()
        && field.value.iter().all(|&b| b >= 0x20 && b != 0x7F);

    out.extend_from_slice(field.name.as_bytes());
    if safe_text {
        out.push(b'=');
        out.extend_from_slice(field.value);
        out.push(b'\n');
    } else {
        out.push(b'\n');
        out.extend_from_slice(&(field.value.len() as u64).to_le_bytes());
        out.extend_from_slice(field.value);
        out.push(b'\n');
    }
    Ok(())
}
