#include <stddef.h>
#include <stdint.h>
#include <string.h>

static constexpr size_t SYSLOG_MAX_MSG = 65536U;

typedef enum : uint8_t {
    SL_OK = 0,
    SL_ERR_NULL,
    SL_ERR_TRUNCATED,
    SL_ERR_BAD_MSGLEN,
    SL_ERR_TOO_LARGE,
    SL_ERR_BAD_PRI,
    SL_ERR_BAD_VERSION,
    SL_ERR_DST_SMALL,
} sl_status_t;

typedef struct {
    uint8_t prival;          // 0..=191
    const uint8_t *msg;      // entire SYSLOG-MSG starting at '<'
    size_t msg_len;
    const uint8_t *rest_body;// after "<PRI>1 "
    size_t rest_body_len;
    size_t frame_consumed;
} sl_frame_t;

[[nodiscard]] sl_status_t syslog_octet_decode(
    const uint8_t *buf,
    size_t buf_len,
    sl_frame_t *out
) {
    if (buf == nullptr || out == nullptr) {
        return SL_ERR_NULL;
    }
    if (buf_len < 7U) {
        return SL_ERR_TRUNCATED;
    }
    if (buf[0] < '1' || buf[0] > '9') {
        return SL_ERR_BAD_MSGLEN;
    }
    size_t pos = 0U;
    size_t mlen = 0U;
    while (pos < buf_len && buf[pos] != ' ') {
        if (buf[pos] < '0' || buf[pos] > '9') {
            return SL_ERR_BAD_MSGLEN;
        }
        mlen = mlen * 10U + (size_t)(buf[pos] - '0');
        if (mlen > SYSLOG_MAX_MSG) {
            return SL_ERR_TOO_LARGE;
        }
        ++pos;
    }
    if (pos >= buf_len) {
        return SL_ERR_TRUNCATED;
    }
    ++pos; // skip SP
    if (buf_len - pos < mlen) {
        return SL_ERR_TRUNCATED;
    }

    const uint8_t *m = buf + pos;
    if (mlen < 5U || m[0] != '<') {
        return SL_ERR_BAD_PRI;
    }
    size_t p = 1U;
    uint32_t pri = 0U;
    if (m[p] == '0') {
        ++p;
        if (p >= mlen || m[p] != '>') {
            return SL_ERR_BAD_PRI;
        }
    } else if (m[p] >= '1' && m[p] <= '9') {
        size_t digits = 0U;
        while (p < mlen && m[p] != '>' && digits < 3U) {
            if (m[p] < '0' || m[p] > '9') {
                return SL_ERR_BAD_PRI;
            }
            pri = pri * 10U + (uint32_t)(m[p] - '0');
            ++p;
            ++digits;
        }
        if (p >= mlen || m[p] != '>' || pri > 191U) {
            return SL_ERR_BAD_PRI;
        }
    } else {
        return SL_ERR_BAD_PRI;
    }
    ++p; // skip '>'
    if (mlen - p < 2U || m[p] != '1' || m[p + 1U] != ' ') {
        return SL_ERR_BAD_VERSION;
    }
    p += 2U;

    *out = (sl_frame_t){
        .prival = (uint8_t)pri,
        .msg = m,
        .msg_len = mlen,
        .rest_body = m + p,
        .rest_body_len = mlen - p,
        .frame_consumed = pos + mlen,
    };
    return SL_OK;
}

static size_t fmt_u32_dec(uint32_t v, uint8_t out[10]) {
    uint8_t rev[10];
    size_t n = 0U;
    do {
        rev[n++] = (uint8_t)('0' + (v % 10U));
        v /= 10U;
    } while (v > 0U);
    for (size_t i = 0U; i < n; ++i) {
        out[i] = rev[n - 1U - i];
    }
    return n;
}

[[nodiscard]] sl_status_t syslog_octet_encode(
    uint8_t prival,
    const uint8_t *rest_body,
    size_t rest_body_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *written_out
) {
    if (dst == nullptr || written_out == nullptr || (rest_body_len > 0U && rest_body == nullptr)) {
        return SL_ERR_NULL;
    }
    if (prival > 191U) {
        return SL_ERR_BAD_PRI;
    }
    uint8_t pri_dec[10];
    size_t pri_n = fmt_u32_dec(prival, pri_dec);
    size_t hdr_in_msg = 1U + pri_n + 3U; // '<' + PRI + ">1 "
    if (rest_body_len > SYSLOG_MAX_MSG - hdr_in_msg) {
        return SL_ERR_TOO_LARGE;
    }
    size_t mlen = hdr_in_msg + rest_body_len;
    uint8_t mlen_dec[10];
    size_t mlen_n = fmt_u32_dec((uint32_t)mlen, mlen_dec);

    size_t total = mlen_n + 1U + mlen;
    if (dst_cap < total) {
        return SL_ERR_DST_SMALL;
    }
    size_t pos = 0U;
    memcpy(dst + pos, mlen_dec, mlen_n); pos += mlen_n;
    dst[pos++] = ' ';
    dst[pos++] = '<';
    memcpy(dst + pos, pri_dec, pri_n); pos += pri_n;
    dst[pos++] = '>';
    dst[pos++] = '1';
    dst[pos++] = ' ';
    if (rest_body_len > 0U) {
        memcpy(dst + pos, rest_body, rest_body_len);
    }
    *written_out = total;
    return SL_OK;
}
