package pgwire

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"unicode/utf8"
)

const (
	ProtoVersion30    uint32 = 0x00030000 // 196608
	SSLRequestCode    uint32 = 80877103   // 0x04d2162f
	GSSENCRequestCode uint32 = 80877104   // 0x04d21630
	MaxStartupLength  int    = 10000
)

type FrontendInitKind uint8

const (
	InitStartup FrontendInitKind = iota + 1
	InitSSLRequest
	InitGSSENCRequest
)

type FrontendInitPacket struct {
	Kind    FrontendInitKind
	Version uint32
	Params  map[string]string
}

func readCString(buf []byte, off int) (string, int, error) {
	idx := bytes.IndexByte(buf[off:], 0x00)
	if idx < 0 {
		return "", 0, errors.New("pgwire: unterminated C-string in StartupMessage")
	}
	raw := buf[off : off+idx]
	if !utf8.Valid(raw) {
		return "", 0, errors.New("pgwire: invalid UTF-8 in StartupMessage parameter")
	}
	return string(raw), off + idx + 1, nil
}

func ParseFrontendInit(buf []byte) (*FrontendInitPacket, error) {
	if len(buf) < 8 {
		return nil, fmt.Errorf("pgwire: init packet shorter than 8 bytes (%d)", len(buf))
	}
	frameLen := int(int32(binary.BigEndian.Uint32(buf[0:4])))
	if frameLen < 8 || frameLen > MaxStartupLength {
		return nil, fmt.Errorf("pgwire: invalid startup length %d (must be 8..%d)", frameLen, MaxStartupLength)
	}
	if frameLen != len(buf) {
		return nil, fmt.Errorf("pgwire: header length %d != buffer length %d", frameLen, len(buf))
	}

	code := binary.BigEndian.Uint32(buf[4:8])
	switch code {
	case SSLRequestCode:
		if frameLen != 8 {
			return nil, errors.New("pgwire: SSLRequest must be exactly 8 bytes")
		}
		return &FrontendInitPacket{Kind: InitSSLRequest, Version: code}, nil
	case GSSENCRequestCode:
		if frameLen != 8 {
			return nil, errors.New("pgwire: GSSENCRequest must be exactly 8 bytes")
		}
		return &FrontendInitPacket{Kind: InitGSSENCRequest, Version: code}, nil
	}

	if code != ProtoVersion30 {
		return nil, fmt.Errorf("pgwire: unsupported protocol version 0x%08x", code)
	}
	if frameLen < 9 || buf[frameLen-1] != 0x00 {
		return nil, errors.New("pgwire: StartupMessage missing terminal NUL byte")
	}

	params := make(map[string]string)
	off := 8
	for off < frameLen-1 {
		key, nextOff, err := readCString(buf, off)
		if err != nil {
			return nil, err
		}
		if key == "" {
			return nil, errors.New("pgwire: empty parameter key before end of StartupMessage")
		}
		if nextOff >= frameLen {
			return nil, fmt.Errorf("pgwire: missing value for StartupMessage key %q", key)
		}
		val, afterVal, err := readCString(buf, nextOff)
		if err != nil {
			return nil, err
		}
		if _, exists := params[key]; exists {
			return nil, fmt.Errorf("pgwire: duplicate StartupMessage parameter %q", key)
		}
		params[key] = val
		off = afterVal
	}

	if off != frameLen-1 {
		return nil, errors.New("pgwire: StartupMessage parameter list misaligned with final NUL")
	}
	if params["user"] == "" {
		return nil, errors.New("pgwire: mandatory non-empty 'user' parameter missing")
	}

	return &FrontendInitPacket{
		Kind:    InitStartup,
		Version: code,
		Params:  params,
	}, nil
}
