export type BerTagClass = "universal" | "application" | "context" | "private";

export interface BerTlvNode {
  tagHex: string;
  tagNumber: number;
  tagClass: BerTagClass;
  constructed: boolean;
  value: Uint8Array;
  children?: BerTlvNode[];
}

const TAG_CLASSES: readonly BerTagClass[] = [
  "universal",
  "application",
  "context",
  "private",
];

function readCanonicalTag(
  view: DataView,
  buf: Uint8Array,
  off: number,
  end: number,
): { tagHex: string; tagNumber: number; tagClass: BerTagClass; constructed: boolean; nextOff: number } {
  if (off >= end) {
    throw new Error(`Truncated BER-TLV tag at offset ${off}`);
  }
  const b0 = view.getUint8(off);
  const tagClass = TAG_CLASSES[(b0 >>> 6) & 0x03]!;
  const constructed = (b0 & 0x20) !== 0;
  const low5 = b0 & 0x1f;

  if (low5 !== 0x1f) {
    return {
      tagHex: b0.toString(16).toUpperCase().padStart(2, "0"),
      tagNumber: low5,
      tagClass,
      constructed,
      nextOff: off + 1,
    };
  }

  let cur = off + 1;
  let tagNum = 0;
  let count = 0;
  while (true) {
    if (cur >= end) {
      throw new Error("Truncated multi-byte BER-TLV tag");
    }
    count++;
    if (count > 3) {
      throw new Error("BER-TLV tag exceeds 4 total bytes");
    }
    const b = view.getUint8(cur++);
    if (count === 1 && (b & 0x7f) === 0) {
      throw new Error("Non-canonical multi-byte BER-TLV tag with leading zero bits");
    }
    tagNum = (tagNum << 7) | (b & 0x7f);
    if ((b & 0x80) === 0) {
      break;
    }
  }
  if (tagNum < 31) {
    throw new Error(`Non-canonical multi-byte encoding for tag number ${tagNum} < 31`);
  }

  let hex = "";
  for (let i = off; i < cur; i++) {
    hex += buf[i]!.toString(16).toUpperCase().padStart(2, "0");
  }
  return { tagHex: hex, tagNumber: tagNum, tagClass, constructed, nextOff: cur };
}

function readCanonicalDefiniteLength(
  view: DataView,
  off: number,
  end: number,
): { length: number; nextOff: number } {
  if (off >= end) {
    throw new Error(`Truncated BER-TLV length at offset ${off}`);
  }
  const first = view.getUint8(off);
  if (first < 0x80) {
    return { length: first, nextOff: off + 1 };
  }
  if (first === 0x80) {
    throw new Error("Indefinite BER-TLV length 0x80 is forbidden in EMV/ISO-7816");
  }
  const numOctets = first & 0x7f;
  if (numOctets > 4) {
    throw new Error(`BER-TLV length width ${numOctets} exceeds 4 bytes`);
  }
  if (off + 1 + numOctets > end) {
    throw new Error("Truncated long-form BER-TLV length bytes");
  }
  if (view.getUint8(off + 1) === 0x00) {
    throw new Error("Non-canonical leading 0x00 in long-form BER-TLV length");
  }

  let length = 0;
  for (let i = 0; i < numOctets; i++) {
    length = length * 256 + view.getUint8(off + 1 + i);
  }
  if (length < 0x80) {
    throw new Error(`Non-canonical long-form length ${length} < 128`);
  }
  return { length, nextOff: off + 1 + numOctets };
}

function decodeRange(
  view: DataView,
  buf: Uint8Array,
  start: number,
  end: number,
  depth: number,
  maxDepth: number,
): BerTlvNode[] {
  if (depth > maxDepth) {
    throw new Error(`BER-TLV nesting depth ${depth} exceeds maxDepth ${maxDepth}`);
  }
  const nodes: BerTlvNode[] = [];
  let off = start;

  while (off < end) {
    const tag = readCanonicalTag(view, buf, off, end);
    const lenInfo = readCanonicalDefiniteLength(view, tag.nextOff, end);
    const valEnd = lenInfo.nextOff + lenInfo.length;
    if (valEnd > end) {
      throw new Error(`Tag ${tag.tagHex} length ${lenInfo.length} overruns container boundary`);
    }
    const value = buf.subarray(lenInfo.nextOff, valEnd);
    const node: BerTlvNode = {
      tagHex: tag.tagHex,
      tagNumber: tag.tagNumber,
      tagClass: tag.tagClass,
      constructed: tag.constructed,
      value,
    };
    if (tag.constructed) {
      node.children = decodeRange(view, buf, lenInfo.nextOff, valEnd, depth + 1, maxDepth);
    }
    nodes.push(node);
    off = valEnd;
  }
  return nodes;
}

export function parseEmvBerTlv(buf: Uint8Array, maxDepth = 8): BerTlvNode[] {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  return decodeRange(view, buf, 0, buf.byteLength, 0, maxDepth);
}
