```go
package mqttv5

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"strings"
	"unicode/utf8"
)

var (
	ErrMalformedPacket = errors.New("mqttv5: malformed packet (0x81)")
	ErrProtocolError   = errors.New("mqttv5: protocol error (0x82)")
)

var minVarintForWidth = [5]uint32{0, 0, 128, 16_384, 2_097_152}

type UserProperty struct {
	Key   string
	Value string
}

type PublishProperties struct {
	PayloadFormat        *uint8
	MessageExpirySeconds *uint32
	ContentType          *string
	ResponseTopic        *string
	CorrelationData      []byte
	hasCorrelationData   bool
	SubscriptionIDs      []uint32
	TopicAlias           *uint16
	UserProperties       []UserProperty
}

func ReadVarByteInt(buf []byte) (val uint32, n int, err error) {
	var multiplier uint32 = 1
	for i := 0; i < 4; i++ {
		if i >= len(buf) {
			return 0, 0, ErrMalformedPacket
		}
		b := buf[i]
		val += uint32(b&0x7F) * multiplier
		if (b & 0x80) == 0 {
			width := i + 1
			if val < minVarintForWidth[width] {
				return 0, 0, fmt.Errorf("%w: non-canonical overlong varint", ErrMalformedPacket)
			}
			return val, width, nil
		}
		multiplier *= 128
	}
	return 0, 0, fmt.Errorf("%w: varint exceeds 4 bytes", ErrMalformedPacket)
}

func readMQTTUTF8(buf []byte) (string, int, error) {
	if len(buf) < 2 {
		return "", 0, ErrMalformedPacket
	}
	sLen := int(binary.BigEndian.Uint16(buf[0:2]))
	if len(buf)-2 < sLen {
		return "", 0, ErrMalformedPacket
	}
	raw := buf[2 : 2+sLen]
	if bytes.IndexByte(raw, 0x00) >= 0 || !utf8.Valid(raw) {
		return "", 0, fmt.Errorf("%w: invalid UTF-8 or NUL character", ErrMalformedPacket)
	}
	return string(raw), 2 + sLen, nil
}

func ParsePublishProperties(buf []byte) (*PublishProperties, int, error) {
	propLen, hdrBytes, err := ReadVarByteInt(buf)
	if err != nil {
		return nil, 0, err
	}
	totalConsumed := hdrBytes + int(propLen)
	if len(buf) < totalConsumed {
		return nil, 0, ErrMalformedPacket
	}

	block := buf[hdrBytes:totalConsumed]
	var out PublishProperties
	off := 0

	for off < len(block) {
		propID := block[off]
		off++

		switch propID {
		case 0x01:
			if out.PayloadFormat != nil {
				return nil, 0, fmt.Errorf("%w: duplicate Payload Format Indicator", ErrProtocolError)
			}
			if off >= len(block) {
				return nil, 0, ErrMalformedPacket
			}
			v := block[off]
			off++
			if v > 1 {
				return nil, 0, fmt.Errorf("%w: Payload Format Indicator %d not in {0,1}", ErrProtocolError, v)
			}
			out.PayloadFormat = &v

		case 0x02:
			if out.MessageExpirySeconds != nil {
				return nil, 0, fmt.Errorf("%w: duplicate Message Expiry Interval", ErrProtocolError)
			}
			if len(block)-off < 4 {
				return nil, 0, ErrMalformedPacket
			}
			v := binary.BigEndian.Uint32(block[off : off+4])
			off += 4
			out.MessageExpirySeconds = &v

		case 0x03:
			if out.ContentType != nil {
				return nil, 0, fmt.Errorf("%w: duplicate Content Type", ErrProtocolError)
			}
			s, n, err := readMQTTUTF8(block[off:])
			if err != nil {
				return nil, 0, err
			}
			off += n
			out.ContentType = &s

		case 0x08:
			if out.ResponseTopic != nil {
				return nil, 0, fmt.Errorf("%w: duplicate Response Topic", ErrProtocolError)
			}
			s, n, err := readMQTTUTF8(block[off:])
			if err != nil {
				return nil, 0, err
			}
			if strings.ContainsAny(s, "+#") {
				return nil, 0, fmt.Errorf("%w: wildcard forbidden in Response Topic", ErrProtocolError)
			}
			off += n
			out.ResponseTopic = &s

		case 0x09:
			if out.hasCorrelationData {
				return nil, 0, fmt.Errorf("%w: duplicate Correlation Data", ErrProtocolError)
			}
			if len(block)-off < 2 {
				return nil, 0, ErrMalformedPacket
			}
			bLen := int(binary.BigEndian.Uint16(block[off : off+2]))
			off += 2
			if len(block)-off < bLen {
				return nil, 0, ErrMalformedPacket
			}
			out.CorrelationData = bytes.Clone(block[off : off+bLen])
			out.hasCorrelationData = true
			off += bLen

		case 0x0B:
			subID, n, err := ReadVarByteInt(block[off:])
			if err != nil {
				return nil, 0, err
			}
			if subID == 0 {
				return nil, 0, fmt.Errorf("%w: Subscription Identifier cannot be 0", ErrProtocolError)
			}
			off += n
			out.SubscriptionIDs = append(out.SubscriptionIDs, subID)

		case 0x23:
			if out.TopicAlias != nil {
				return nil, 0, fmt.Errorf("%w: duplicate Topic Alias", ErrProtocolError)
			}
			if len(block)-off < 2 {
				return nil, 0, ErrMalformedPacket
			}
			alias := binary.BigEndian.Uint16(block[off : off+2])
			off += 2
			if alias == 0 {
				return nil, 0, fmt.Errorf("%w: Topic Alias cannot be 0", ErrProtocolError)
			}
			out.TopicAlias = &alias

		case 0x26:
			k, nk, err := readMQTTUTF8(block[off:])
			if err != nil {
				return nil, 0, err
			}
			off += nk
			v, nv, err := readMQTTUTF8(block[off:])
			if err != nil {
				return nil, 0, err
			}
			off += nv
			out.UserProperties = append(out.UserProperties, UserProperty{Key: k, Value: v})

		default:
			return nil, 0, fmt.Errorf("%w: property ID 0x%02x invalid in PUBLISH", ErrProtocolError, propID)
		}
	}

	return &out, totalConsumed, nil
}
