```ts
export const WG_HANDSHAKE_INIT_SIZE = 148;

export interface WireGuardHandshakeInitiation {
  messageType: 1;
  senderIndex: number;
  unencryptedEphemeral: Uint8Array;
  encryptedStatic: {
    ciphertext: Uint8Array;
    authTag: Uint8Array;
  };
  encryptedTimestamp: {
    ciphertext: Uint8Array;
    authTag: Uint8Array;
  };
  mac1: Uint8Array;
  mac2: Uint8Array;
  hasMac2Cookie: boolean;
  mac1Input: Uint8Array;
  mac2Input: Uint8Array;
}

function isAllZeroConstantTime(slice: Uint8Array): boolean {
  let acc = 0;
  for (let i = 0; i < slice.byteLength; i++) {
    acc |= slice[i]!;
  }
  return acc === 0;
}

export function parseWireGuardInitiation(pkt: Uint8Array): WireGuardHandshakeInitiation {
  if (pkt.byteLength !== WG_HANDSHAKE_INIT_SIZE) {
    throw new Error(
      `Invalid WireGuard Initiation length: expected ${WG_HANDSHAKE_INIT_SIZE}, got ${pkt.byteLength}`,
    );
  }

  const view = new DataView(pkt.buffer, pkt.byteOffset, pkt.byteLength);
  const messageType = view.getUint8(0);
  if (messageType !== 1) {
    throw new Error(`Invalid WireGuard message_type ${messageType} (expected 1)`);
  }

  if (
    (view.getUint8(1) | view.getUint8(2) | view.getUint8(3)) !== 0
  ) {
    throw new Error("Non-zero reserved bytes in WireGuard Handshake Initiation header");
  }

  const senderIndex = view.getUint32(4, true);
  const unencryptedEphemeral = pkt.subarray(8, 40);
  if (isAllZeroConstantTime(unencryptedEphemeral)) {
    throw new Error("Rejected low-order all-zero Curve25519 ephemeral public key");
  }

  const encryptedStatic = {
    ciphertext: pkt.subarray(40, 72),
    authTag: pkt.subarray(72, 88),
  };
  const encryptedTimestamp = {
    ciphertext: pkt.subarray(88, 100),
    authTag: pkt.subarray(100, 116),
  };

  const mac1 = pkt.subarray(116, 132);
  if (isAllZeroConstantTime(mac1)) {
    throw new Error("Rejected all-zero mac1 in WireGuard Initiation");
  }

  const mac2 = pkt.subarray(132, 148);
  const hasMac2Cookie = !isAllZeroConstantTime(mac2);

  return {
    messageType: 1,
    senderIndex,
    unencryptedEphemeral,
    encryptedStatic,
    encryptedTimestamp,
    mac1,
    mac2,
    hasMac2Cookie,
    mac1Input: pkt.subarray(0, 116),
    mac2Input: pkt.subarray(0, 132),
  };
}
