package bgpwire

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

var bgpMarker = bytes.Repeat([]byte{0xFF}, 16)

type MultiprotocolCap struct {
	AFI  uint16
	SAFI uint8
}

type Capability struct {
	Code uint8
	Raw  []byte
}

type OpenMessage struct {
	MyAS            uint16
	FourOctetASN    *uint32
	HoldTime        uint16
	BGPIdentifier   netip.Addr
	Multiprotocol   []MultiprotocolCap
	RouteRefresh    bool
	AllCapabilities []Capability
}

func ParseBGPOpen(buf []byte) (*OpenMessage, error) {
	if len(buf) < 29 || len(buf) > 4096 {
		return nil, fmt.Errorf("bgp: OPEN length %d outside [29, 4096]", len(buf))
	}
	if !bytes.Equal(buf[0:16], bgpMarker) {
		return nil, errors.New("bgp: invalid 16-byte marker (must be all 0xFF)")
	}

	msgLen := int(binary.BigEndian.Uint16(buf[16:18]))
	if msgLen != len(buf) {
		return nil, fmt.Errorf("bgp: header length %d != buffer length %d", msgLen, len(buf))
	}
	if buf[18] != 1 {
		return nil, fmt.Errorf("bgp: expected OPEN type 1, got %d", buf[18])
	}
	if buf[19] != 4 {
		return nil, fmt.Errorf("bgp: unsupported BGP version %d", buf[19])
	}

	myAS := binary.BigEndian.Uint16(buf[20:22])
	holdTime := binary.BigEndian.Uint16(buf[22:24])
	if holdTime == 1 || holdTime == 2 {
		return nil, fmt.Errorf("bgp: unacceptable Hold Time %d (must be 0 or >= 3)", holdTime)
	}

	var idBytes [4]byte
	copy(idBytes[:], buf[24:28])
	bgpID := netip.AddrFrom4(idBytes)
	if idBytes == [4]byte{0, 0, 0, 0} || idBytes[0] >= 224 {
		return nil, fmt.Errorf("bgp: invalid BGP Identifier %s", bgpID)
	}

	optLen := int(buf[28])
	if optLen != msgLen-29 {
		return nil, fmt.Errorf("bgp: Opt Parm Len %d != %d", optLen, msgLen-29)
	}

	out := &OpenMessage{
		MyAS:          myAS,
		HoldTime:      holdTime,
		BGPIdentifier: bgpID,
	}

	off := 29
	for off < msgLen {
		if msgLen-off < 2 {
			return nil, errors.New("bgp: truncated Optional Parameter TLV header")
		}
		paramType := buf[off]
		paramLen := int(buf[off+1])
		off += 2
		if msgLen-off < paramLen {
			return nil, fmt.Errorf("bgp: Optional Parameter type %d overruns OPEN", paramType)
		}
		paramSlice := buf[off : off+paramLen]
		off += paramLen

		if paramType != 2 {
			return nil, fmt.Errorf("bgp: unsupported Optional Parameter type %d", paramType)
		}
		if paramLen == 0 {
			return nil, errors.New("bgp: empty Capabilities Optional Parameter")
		}

		cOff := 0
		for cOff < len(paramSlice) {
			if len(paramSlice)-cOff < 2 {
				return nil, errors.New("bgp: truncated Capability TLV header")
			}
			capCode := paramSlice[cOff]
			capLen := int(paramSlice[cOff+1])
			cOff += 2
			if len(paramSlice)-cOff < capLen {
				return nil, fmt.Errorf("bgp: Capability %d length %d overruns parameter", capCode, capLen)
			}
			capVal := bytes.Clone(paramSlice[cOff : cOff+capLen])
			cOff += capLen
			out.AllCapabilities = append(out.AllCapabilities, Capability{Code: capCode, Raw: capVal})

			switch capCode {
			case 1:
				if capLen != 4 || capVal[2] != 0x00 {
					return nil, errors.New("bgp: malformed Multiprotocol Capability (Code 1)")
				}
				out.Multiprotocol = append(out.Multiprotocol, MultiprotocolCap{
					AFI:  binary.BigEndian.Uint16(capVal[0:2]),
					SAFI: capVal[3],
				})
			case 2:
				if capLen != 0 {
					return nil, errors.New("bgp: Route Refresh Capability (Code 2) must have length 0")
				}
				out.RouteRefresh = true
			case 65:
				if capLen != 4 {
					return nil, errors.New("bgp: 4-octet ASN Capability (Code 65) must have length 4")
				}
				asn := binary.BigEndian.Uint32(capVal[0:4])
				out.FourOctetASN = &asn
			}
		}
	}

	return out, nil
}
