```go
package jwsdetached

import (
	"bytes"
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

var rawURLStrict = base64.RawURLEncoding.Strict()

type ProtectedHeader struct {
	Alg  string   `json:"alg"`
	Kid  string   `json:"kid,omitempty"`
	Typ  string   `json:"typ,omitempty"`
	B64  *bool    `json:"b64,omitempty"`
	Crit []string `json:"crit,omitempty"`
}

func decodeStrictB64URL(seg string) ([]byte, error) {
	if seg == "" {
		return nil, errors.New("jws: empty base64url segment")
	}
	for i := 0; i < len(seg); i++ {
		c := seg[i]
		ok := (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
			(c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return nil, fmt.Errorf("jws: illegal base64url character %q", c)
		}
	}
	out, err := rawURLStrict.DecodeString(seg)
	if err != nil {
		return nil, fmt.Errorf("jws: non-canonical base64url encoding: %w", err)
	}
	return out, nil
}

func validateHeaderInvariants(rawJSON []byte) (*ProtectedHeader, bool, error) {
	dec := json.NewDecoder(bytes.NewReader(rawJSON))
	dec.DisallowUnknownFields()
	var hdr ProtectedHeader
	if err := dec.Decode(&hdr); err != nil {
		return nil, false, fmt.Errorf("jws: invalid protected header JSON: %w", err)
	}
	if dec.More() {
		return nil, false, errors.New("jws: trailing tokens in protected header JSON")
	}
	if hdr.Alg != "EdDSA" {
		return nil, false, fmt.Errorf("jws: unsupported or unpinned alg %q", hdr.Alg)
	}

	b64Enabled := true
	critHasB64 := false
	if hdr.Crit != nil {
		if len(hdr.Crit) == 0 {
			return nil, false, errors.New("jws: empty 'crit' array is forbidden by RFC 7515")
		}
		seen := make(map[string]struct{}, len(hdr.Crit))
		for _, ext := range hdr.Crit {
			if _, dup := seen[ext]; dup {
				return nil, false, fmt.Errorf("jws: duplicate 'crit' entry %q", ext)
			}
			seen[ext] = struct{}{}
			if ext != "b64" {
				return nil, false, fmt.Errorf("jws: unsupported critical header parameter %q", ext)
			}
			critHasB64 = true
		}
	}

	if critHasB64 && hdr.B64 == nil {
		return nil, false, errors.New("jws: 'b64' listed in 'crit' but omitted from header")
	}
	if hdr.B64 != nil {
		if !*hdr.B64 && !critHasB64 {
			return nil, false, errors.New("jws: RFC 7797 requires 'b64':false to be listed in 'crit'")
		}
		b64Enabled = *hdr.B64
	}

	return &hdr, b64Enabled, nil
}

func VerifyDetachedEdDSA(compactJWS string, detachedPayload []byte, pubKey ed25519.PublicKey) (*ProtectedHeader, error) {
	if len(pubKey) != ed25519.PublicKeySize {
		return nil, errors.New("jws: invalid Ed25519 public key length")
	}
	parts := strings.Split(compactJWS, ".")
	if len(parts) != 3 || parts[1] != "" {
		return nil, errors.New("jws: detached JWS must match '<protected>..<signature>'")
	}

	hdrBytes, err := decodeStrictB64URL(parts[0])
	if err != nil {
		return nil, err
	}
	sigBytes, err := decodeStrictB64URL(parts[2])
	if err != nil {
		return nil, err
	}
	if len(sigBytes) != ed25519.SignatureSize {
		return nil, fmt.Errorf("jws: Ed25519 signature must be 64 bytes, got %d", len(sigBytes))
	}

	hdr, b64Enabled, err := validateHeaderInvariants(hdrBytes)
	if err != nil {
		return nil, err
	}

	var signingInput []byte
	if b64Enabled {
		encPayload := base64.RawURLEncoding.EncodeToString(detachedPayload)
		signingInput = make([]byte, len(parts[0])+1+len(encPayload))
		n := copy(signingInput, parts[0])
		signingInput[n] = '.'
		copy(signingInput[n+1:], encPayload)
	} else {
		signingInput = make([]byte, len(parts[0])+1+len(detachedPayload))
		n := copy(signingInput, parts[0])
		signingInput[n] = '.'
		copy(signingInput[n+1:], detachedPayload)
	}

	if !ed25519.Verify(pubKey, signingInput, sigBytes) {
		return nil, errors.New("jws: Ed25519 detached signature verification failed")
	}
	return hdr, nil
}
