```python
from __future__ import annotations

from enum import Enum

CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
CHARSET_REV = {ch: idx for idx, ch in enumerate(CHARSET)}
GEN = (0x3B6A57B2, 0x26508E6D, 0x1EA119FA, 0x3D4233DD, 0x2A1462B3)


class Bech32Variant(Enum):
    BECH32 = 1
    BECH32M = 0x2BC830A3


class Bech32Error(ValueError):
    pass


def _polymod(values: list[int]) -> int:
    chk = 1
    for val in values:
        top = chk >> 25
        chk = ((chk & 0x1FFFFFF) << 5) ^ val
        for i in range(5):
            if (top >> i) & 1:
                chk ^= GEN[i]
    return chk


def _hrp_expand(hrp: str) -> list[int]:
    return [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]


def convert_bits(data: bytes | list[int], from_bits: int, to_bits: int, pad: bool) -> list[int]:
    acc = 0
    bits = 0
    ret: list[int] = []
    maxv = (1 << to_bits) - 1
    max_acc = (1 << (from_bits + to_bits - 1)) - 1

    for value in data:
        if value < 0 or (value >> from_bits) != 0:
            raise Bech32Error(f"invalid bit-group value {value}")
        acc = ((acc << from_bits) | value) & max_acc
        bits += from_bits
        while bits >= to_bits:
            bits -= to_bits
            ret.append((acc >> bits) & maxv)

    if pad:
        if bits > 0:
            ret.append((acc << (to_bits - bits)) & maxv)
    else:
        if bits >= from_bits:
            raise Bech32Error("excess trailing padding bits in 5-to-8 conversion")
        if ((acc << (to_bits - bits)) & maxv) != 0:
            raise Bech32Error("non-zero trailing padding bits in 5-to-8 conversion")

    return ret


def encode_bech32_bytes(
    hrp: str,
    payload: bytes,
    variant: Bech32Variant = Bech32Variant.BECH32M,
    max_len: int = 90,
) -> str:
    if not (1 <= len(hrp) <= 83) or hrp != hrp.lower():
        raise Bech32Error("HRP must be 1..83 lowercase ASCII characters")
    if any(not (33 <= ord(c) <= 126) for c in hrp):
        raise Bech32Error("HRP contains out-of-range ASCII characters")

    data5 = convert_bits(payload, 8, 5, pad=True)
    values = _hrp_expand(hrp) + data5
    pmod = _polymod(values + [0, 0, 0, 0, 0, 0]) ^ variant.value
    checksum = [(pmod >> (5 * (5 - i))) & 31 for i in range(6)]
    encoded = hrp + "1" + "".join(CHARSET[d] for d in data5 + checksum)
    if len(encoded) > max_len:
        raise Bech32Error(f"encoded Bech32 length {len(encoded)} > {max_len}")
    return encoded


def decode_bech32_bytes(token: str, max_len: int = 90) -> tuple[str, bytes, Bech32Variant]:
    if len(token) < 8 or len(token) > max_len:
        raise Bech32Error(f"Bech32 token length {len(token)} outside [8, {max_len}]")
    if token.lower() != token and token.upper() != token:
        raise Bech32Error("mixed-case Bech32 string is forbidden")

    norm = token.lower()
    pos = norm.rfind("1")
    if pos < 1 or pos + 7 > len(norm) or pos > 83:
        raise Bech32Error("invalid or missing '1' HRP separator")

    hrp = norm[:pos]
