        raise Bech32Error("invalid ASCII character in HRP")

    try:
        data_part = [CHARSET_REV[ch] for ch in norm[pos + 1 :]]
    except KeyError as exc:
        raise Bech32Error(f"invalid Base32 character {exc}") from exc

    rem = _polymod(_hrp_expand(hrp) + data_part)
    if rem == Bech32Variant.BECH32.value:
