package cefwire

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type CEFEvent struct {
	SyslogPrefix       string
	Version            int
	DeviceVendor       string
	DeviceProduct      string
	DeviceVersion      string
	DeviceEventClassID string
	Name               string
	Severity           string
	Extensions         map[string]string
}

var allowedSeverityWords = map[string]struct{}{
	"Unknown":   {},
	"Low":       {},
	"Medium":    {},
	"High":      {},
	"Very-High": {},
}

func isValidSeverity(s string) bool {
	if _, ok := allowedSeverityWords[s]; ok {
		return true
	}
	n, err := strconv.Atoi(s)
	return err == nil && n >= 0 && n <= 10 && strconv.Itoa(n) == s
}

func isKeyChar(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') ||
		(b >= '0' && b <= '9') || b == '_' || b == '.' || b == '-'
}

func unescapeExtensionValue(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case '\\':
				b.WriteByte('\\')
				i++
				continue
			case '=':
				b.WriteByte('=')
				i++
				continue
			case 'n':
				b.WriteByte('\n')
				i++
				continue
			case 'r':
				b.WriteByte('\r')
				i++
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

type keyAnchor struct {
	keyStart int
	eqIdx    int
}

func parseExtensions(ext string) (map[string]string, error) {
	out := make(map[string]string)
	ext = strings.TrimLeft(ext, " ")
	if ext == "" {
		return out, nil
	}

	var anchors []keyAnchor
	i := 0
	for i < len(ext) {
		if i == 0 || ext[i-1] == ' ' {
			kStart := i
			for i < len(ext) && isKeyChar(ext[i]) {
				i++
			}
			if i > kStart && i < len(ext) && ext[i] == '=' {
				anchors = append(anchors, keyAnchor{keyStart: kStart, eqIdx: i})
				i++
				continue
			}
			if i == kStart {
				i++
			}
		} else {
			if ext[i] == '\\' && i+1 < len(ext) {
				i += 2
			} else {
				i++
			}
		}
	}

	if len(anchors) == 0 || anchors[0].keyStart != 0 {
		return nil, errors.New("cef: malformed extension tail (must begin with key=value)")
	}

	for idx, a := range anchors {
		key := ext[a.keyStart:a.eqIdx]
		valStart := a.eqIdx + 1
		valEnd := len(ext)
		if idx+1 < len(anchors) {
			valEnd = anchors[idx+1].keyStart - 1
			for valEnd > valStart && ext[valEnd-1] == ' ' {
				if valEnd-2 >= valStart && ext[valEnd-2] == '\\' {
					break
				}
				valEnd--
			}
		}
		if _, dup := out[key]; dup {
			return nil, fmt.Errorf("cef: duplicate extension key %q", key)
		}
		out[key] = unescapeExtensionValue(ext[valStart:valEnd])
	}
	return out, nil
}

func ParseCEF(line string) (*CEFEvent, error) {
	if strings.ContainsAny(line, "\r\n") {
		return nil, errors.New("cef: raw CR/LF forbidden inside single CEF frame")
	}
	cefIdx := strings.Index(line, "CEF:")
	if cefIdx < 0 || (cefIdx > 0 && line[cefIdx-1] != ' ') {
		return nil, errors.New("cef: missing valid 'CEF:' header marker")
	}

	prefix := strings.TrimRight(line[:cefIdx], " ")
	body := line[cefIdx+4:]

	fields := make([]string, 0, 7)
	var cur strings.Builder
	extStart := -1

	for i := 0; i < len(body); i++ {
		ch := body[i]
		if ch == '\\' && i+1 < len(body) {
			next := body[i+1]
			if next == '|' || next == '\\' {
				cur.WriteByte(next)
				i++
				continue
			}
		}
		if ch == '|' {
			fields = append(fields, cur.String())
			cur.Reset()
			if len(fields) == 7 {
				extStart = i + 1
				break
			}
			continue
		}
		cur.WriteByte(ch)
	}

	if len(fields) < 7 || extStart < 0 {
		return nil, fmt.Errorf("cef: expected 7 pipe-terminated header fields, got %d", len(fields))
	}

	ver, err := strconv.Atoi(fields[0])
	if err != nil || (ver != 0 && ver != 1) {
		return nil, fmt.Errorf("cef: unsupported CEF version %q", fields[0])
	}
	if !isValidSeverity(fields[6]) {
		return nil, fmt.Errorf("cef: invalid severity %q", fields[6])
	}

	exts, err := parseExtensions(body[extStart:])
	if err != nil {
		return nil, err
	}

	return &CEFEvent{
		SyslogPrefix:       prefix,
		Version:            ver,
		DeviceVendor:       fields[1],
		DeviceProduct:      fields[2],
		DeviceVersion:      fields[3],
		DeviceEventClassID: fields[4],
		Name:               fields[5],
		Severity:           fields[6],
		Extensions:         exts,
	}, nil
}
