    def _parse_data_flowset(
        self,
        source_id: int,
        flowset_id: int,
        payload: memoryview,
    ) -> list[tuple[int, dict[int, bytes]]]:
        tdef = self._templates.get((source_id, flowset_id))
        if tdef is None:
            raise NetFlowV9Error(f"unknown template {flowset_id} for source_id {source_id}")

        records: list[tuple[int, dict[int, bytes]]] = []
