```ts
export class Resp3ProtocolError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "Resp3ProtocolError";
  }
}

export type Resp3Node =
  | { kind: "null"; attributes?: Map<string, Resp3Node> }
  | { kind: "boolean"; value: boolean; attributes?: Map<string, Resp3Node> }
  | { kind: "bignum"; value: bigint; attributes?: Map<string, Resp3Node> }
  | { kind: "blob"; value: Uint8Array; attributes?: Map<string, Resp3Node> }
  | { kind: "verbatim"; encoding: string; value: Uint8Array; attributes?: Map<string, Resp3Node> }
  | { kind: "array"; items: Resp3Node[]; attributes?: Map<string, Resp3Node> }
  | { kind: "map"; entries: Array<[Resp3Node, Resp3Node]>; attributes?: Map<string, Resp3Node> };

export type Resp3StreamResult =
  | { status: "incomplete" }
  | { status: "ok"; node: Resp3Node; bytesConsumed: number };

export interface Resp3Limits {
  maxBulkLength?: number;
  maxCollectionLength?: number;
  maxDepth?: number;
}

const asciiDecoder = new TextDecoder("utf-8", { fatal: true });

function readCRLFLine(
  view: DataView,
  buf: Uint8Array,
  start: number,
): { line: Uint8Array; nextOff: number } | null {
  for (let i = start; i < buf.byteLength; i++) {
    const b = view.getUint8(i);
    if (b === 0x0a) {
      throw new Resp3ProtocolError(`Bare LF without preceding CR at offset ${i}`);
    }
    if (b === 0x0d) {
      if (i + 1 >= buf.byteLength) {
        return null;
      }
      if (view.getUint8(i + 1) !== 0x0a) {
        throw new Resp3ProtocolError(`CR not followed by LF at offset ${i}`);
      }
      return { line: buf.subarray(start, i), nextOff: i + 2 };
    }
  }
  return null;
}

function parseCanonicalCount(line: Uint8Array, maxVal: number): number {
  if (line.byteLength === 0) {
    throw new Resp3ProtocolError("Empty RESP3 length header");
  }
  if (line.byteLength > 1 && line[0] === 0x30) {
    throw new Resp3ProtocolError("Non-canonical leading zero in RESP3 length");
  }
  let acc = 0;
  for (let i = 0; i < line.byteLength; i++) {
    const c = line[i]!;
    if (c < 0x30 || c > 0x39) {
      throw new Resp3ProtocolError("Invalid non-digit in RESP3 unsigned length");
    }
    acc = acc * 10 + (c - 0x30);
    if (acc > maxVal) {
      throw new Resp3ProtocolError(`RESP3 length ${acc} exceeds limit ${maxVal}`);
    }
  }
  return acc;
}

function parseItem(
  view: DataView,
  buf: Uint8Array,
  off: number,
  depth: number,
  limits: Required<Resp3Limits>,
): { node: Resp3Node; nextOff: number } | null {
  if (depth > limits.maxDepth) {
    throw new Resp3ProtocolError(`RESP3 nesting depth exceeds ${limits.maxDepth}`);
  }
  if (off >= buf.byteLength) {
    return null;
  }

  let attachedAttrs: Map<string, Resp3Node> | undefined;
  let cur = off;

  if (view.getUint8(cur) === 0x7c) {
    const hdr = readCRLFLine(view, buf, cur + 1);
    if (!hdr) return null;
    const count = parseCanonicalCount(hdr.line, limits.maxCollectionLength);
    cur = hdr.nextOff;
    attachedAttrs = new Map<string, Resp3Node>();
    for (let i = 0; i < count; i++) {
      const kRes = parseItem(view, buf, cur, depth + 1, limits);
      if (!kRes) return null;
      const vRes = parseItem(view, buf, kRes.nextOff, depth + 1, limits);
      if (!vRes) return null;
      if (kRes.node.kind !== "blob") {
        throw new Resp3ProtocolError("Attribute keys in parser profile must be blob strings");
      }
      attachedAttrs.set(asciiDecoder.decode(kRes.node.value), vRes.node);
      cur = vRes.nextOff;
    }
    if (cur >= buf.byteLength) return null;
  }

  const prefix = view.getUint8(cur);
  const hdr = readCRLFLine(view, buf, cur + 1);
  if (!hdr) return null;

  const withAttrs = <T extends Resp3Node>(n: T): T => {
    if (attachedAttrs) n.attributes = attachedAttrs;
    return n;
  };

  switch (prefix) {
    case 0x5f: {
      if (hdr.line.byteLength !== 0) {
        throw new Resp3ProtocolError("RESP3 null frame must have empty body");
      }
      return { node: withAttrs({ kind: "null" }), nextOff: hdr.nextOff };
    }
    case 0x23: {
      if (hdr.line.byteLength !== 1 || (hdr.line[0] !== 0x74 && hdr.line[0] !== 0x66)) {
        throw new Resp3ProtocolError("RESP3 boolean must be #t or #f");
      }
      return {
        node: withAttrs({ kind: "boolean", value: hdr.line[0] === 0x74 }),
        nextOff: hdr.nextOff,
      };
    }
    case 0x28: {
      const text = asciiDecoder.decode(hdr.line);
      if (!/^[+-]?(?:0|[1-9][0-9]*)$/.test(text) || text === "-0" || text === "+0") {
        throw new Resp3ProtocolError(`Invalid canonical RESP3 BigNumber: ${text}`);
      }
      return {
        node: withAttrs({ kind: "bignum", value: BigInt(text) }),
        nextOff: hdr.nextOff,
      };
    }
    case 0x24:
    case 0x3d: {
      const byteLen = parseCanonicalCount(hdr.line, limits.maxBulkLength);
      const endPayload = hdr.nextOff + byteLen;
      if (endPayload + 2 > buf.byteLength) {
        return null;
      }
      if (view.getUint8(endPayload) !== 0x0d || view.getUint8(endPayload + 1) !== 0x0a) {
        throw new Resp3ProtocolError("Missing trailing CRLF after RESP3 bulk payload");
      }
      const raw = buf.subarray(hdr.nextOff, endPayload);
      if (prefix === 0x24) {
        return { node: withAttrs({ kind: "blob", value: raw }), nextOff: endPayload + 2 };
      }
      if (byteLen < 4 || raw[3] !== 0x3a) {
        throw new Resp3ProtocolError("RESP3 verbatim string requires '<3-char-enc>:' prefix");
      }
      for (let i = 0; i < 3; i++) {
        const c = raw[i]!;
        if (c < 0x61 || c > 0x7a) {
          throw new Resp3ProtocolError("RESP3 verbatim encoding tag must be 3 lowercase ASCII letters");
        }
      }
      return {
        node: withAttrs({
          kind: "verbatim",
          encoding: asciiDecoder.decode(raw.subarray(0, 3)),
          value: raw.subarray(4),
        }),
        nextOff: endPayload + 2,
      };
    }
    case 0x2a: {
      const count = parseCanonicalCount(hdr.line, limits.maxCollectionLength);
      const items: Resp3Node[] = [];
      let p = hdr.nextOff;
      for (let i = 0; i < count; i++) {
        const elem = parseItem(view, buf, p, depth + 1, limits);
        if (!elem) return null;
        items.push(elem.node);
        p = elem.nextOff;
      }
      return { node: withAttrs({ kind: "array", items }), nextOff: p };
    }
    case 0x25: {
      const count = parseCanonicalCount(hdr.line, limits.maxCollectionLength);
      const entries: Array<[Resp3Node, Resp3Node]> = [];
      let p = hdr.nextOff;
      for (let i = 0; i < count; i++) {
        const k = parseItem(view, buf, p, depth + 1, limits);
        if (!k) return null;
        const v = parseItem(view, buf, k.nextOff, depth + 1, limits);
        if (!v) return null;
        entries.push([k.node, v.node]);
        p = v.nextOff;
      }
      return { node: withAttrs({ kind: "map", entries }), nextOff: p };
    }
    default:
      throw new Resp3ProtocolError(`Unsupported RESP3 prefix byte 0x${prefix.toString(16)}`);
  }
}

export function parseResp3Stream(buf: Uint8Array, opts: Resp3Limits = {}): Resp3StreamResult {
  const limits: Required<Resp3Limits> = {
    maxBulkLength: opts.maxBulkLength ?? 8 * 1024 * 1024,
    maxCollectionLength: opts.maxCollectionLength ?? 65_536,
    maxDepth: opts.maxDepth ?? 32,
  };
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const res = parseItem(view, buf, 0, 0, limits);
  if (!res) {
    return { status: "incomplete" };
  }
  return { status: "ok", node: res.node, bytesConsumed: res.nextOff };
}
