import re
import struct
from dataclasses import dataclass
from typing import Literal

SASL_MECH_RE = re.compile(r"^[A-Z0-9_-]{1,20}$")


class PgSASLFrameError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class AuthSASLMechanisms:
    kind: Literal["SASLInit"]
    mechanisms: tuple[str, ...]


@dataclass(frozen=True, slots=True)
class AuthSASLStep:
    kind: Literal["SASLContinue", "SASLFinal"]
    scram_data: str


PgSASLFrame = AuthSASLMechanisms | AuthSASLStep


def _decode_scram_ascii(raw: memoryview, label: str) -> str:
    if len(raw) == 0:
        raise PgSASLFrameError(f"{label} payload cannot be empty")
    for b in raw:
        if b < 0x20 or b > 0x7E:
            raise PgSASLFrameError(f"{label} contains non-printable ASCII byte 0x{b:02x}")
    return bytes(raw).decode("ascii")


def parse_pg_backend_sasl(buf: bytes | bytearray | memoryview) -> PgSASLFrame:
    mv = memoryview(buf)
    if len(mv) < 9:
        raise PgSASLFrameError(f"truncated PostgreSQL 'R' frame ({len(mv)} < 9 bytes)")
    if mv[0] != 0x52:
        raise PgSASLFrameError(f"expected message tag 'R' (0x52), got 0x{mv[0]:02x}")

    (frame_len, auth_type) = struct.unpack_from(">ii", mv, 1)
    if frame_len < 8 or frame_len > 65536:
        raise PgSASLFrameError(f"invalid SASL frame length {frame_len}")
