        raise PgSASLFrameError(f"frame length {1 + frame_len} != buffer size {len(mv)}")

    body = mv[9:]

    if auth_type == 10:
        if len(body) < 3 or body[-1] != 0x00 or body[-2] != 0x00:
            raise PgSASLFrameError("AuthenticationSASL must end with double-NUL terminator")
        raw_items = bytes(body[:-1]).split(b"\x00")
        if raw_items[-1] != b"":
            raise PgSASLFrameError("AuthenticationSASL mechanism list improperly terminated")

        mechs: list[str] = []
        seen: set[str] = set()
        for raw_mech in raw_items[:-1]:
            try:
                name = raw_mech.decode("ascii")
            except UnicodeDecodeError as exc:
                raise PgSASLFrameError("non-ASCII SASL mechanism name") from exc
            if not SASL_MECH_RE.fullmatch(name):
                raise PgSASLFrameError(f"invalid RFC 4422 SASL mechanism identifier {name!r}")
