from __future__ import annotations

from dataclasses import dataclass, field


class ProtoCanonicalError(ValueError):
    pass


def read_varint(buf: memoryview, off: int, max_bytes: int = 10) -> tuple[int, int]:
    val = 0
    for i in range(max_bytes):
        if off + i >= len(buf):
            raise ProtoCanonicalError(f"truncated varint at offset {off}")
        b = buf[off + i]
        if max_bytes == 10 and i == 9 and b > 0x01:
            raise ProtoCanonicalError("uint64 varint overflow in 10th byte")
        if max_bytes == 5 and i == 4 and b > 0x0F:
            raise ProtoCanonicalError("uint32 varint overflow in 5th byte")
        val |= (b & 0x7F) << (7 * i)
        if b < 0x80:
            if i > 0 and b == 0x00:
                raise ProtoCanonicalError("non-canonical overlong varint trailing 0x00")
            return val, off + i + 1
    raise ProtoCanonicalError(f"varint exceeds {max_bytes} bytes at offset {off}")


def zigzag_decode(u: int) -> int:
    return (u >> 1) ^ -(u & 1)


@dataclass(slots=True)
class DecodedMetricsProto:
    scalar_sint32: int = 0
    packed_deltas: list[int] = field(default_factory=list)
    labels_to_counters: dict[str, int] = field(default_factory=dict)


def _decode_map_entry(entry_mv: memoryview, depth: int, max_depth: int) -> tuple[str, int]:
    if depth > max_depth:
        raise ProtoCanonicalError(f"recursion depth {depth} > {max_depth}")
    key = ""
    val = 0
    off = 0
    while off < len(entry_mv):
        tag, off = read_varint(entry_mv, off, max_bytes=5)
        fnum, wtype = tag >> 3, tag & 0x07
        if fnum == 1 and wtype == 2:
            slen, off = read_varint(entry_mv, off, max_bytes=5)
            if off + slen > len(entry_mv):
                raise ProtoCanonicalError("map key string overruns entry")
            try:
                key = bytes(entry_mv[off : off + slen]).decode("utf-8", errors="strict")
            except UnicodeDecodeError as exc:
                raise ProtoCanonicalError("invalid UTF-8 in map key") from exc
            off += slen
        elif fnum == 2 and wtype == 0:
            raw_v, off = read_varint(entry_mv, off, max_bytes=10)
            val = zigzag_decode(raw_v)
        else:
            raise ProtoCanonicalError(f"unexpected map entry field {fnum} wire_type {wtype}")
    return key, val


def decode_metrics_message(
    data: bytes | bytearray | memoryview,
    max_depth: int = 8,
) -> DecodedMetricsProto:
    # Field 1: sint32 scalar_sint32 (wire_type 0)
    # Field 2: repeated sint64 packed_deltas [packed=true] (wire_type 2)
    # Field 3: map<string, sint64> labels_to_counters (wire_type 2)
    mv = memoryview(data)
    out = DecodedMetricsProto()
    off = 0

    while off < len(mv):
        tag, off = read_varint(mv, off, max_bytes=5)
        fnum, wtype = tag >> 3, tag & 0x07
        if fnum == 0 or fnum > (1 << 29) - 1 or (19000 <= fnum <= 19999):
            raise ProtoCanonicalError(f"invalid or reserved field number {fnum}")

        if fnum == 1:
            if wtype != 0:
                raise ProtoCanonicalError(f"field 1 expected wire_type 0, got {wtype}")
            raw32, off = read_varint(mv, off, max_bytes=5)
            out.scalar_sint32 = zigzag_decode(raw32)

        elif fnum == 2:
            if wtype != 2:
                raise ProtoCanonicalError("field 2 must use proto3 packed wire_type 2")
            plen, off = read_varint(mv, off, max_bytes=5)
            if plen == 0:
                raise ProtoCanonicalError("empty packed repeated field is non-canonical")
            if off + plen > len(mv):
                raise ProtoCanonicalError("packed repeated field overruns buffer")
            p_end = off + plen
            while off < p_end:
                u64, off = read_varint(mv[:p_end], off, max_bytes=10)
                out.packed_deltas.append(zigzag_decode(u64))

        elif fnum == 3:
            if wtype != 2:
                raise ProtoCanonicalError("map field 3 must have wire_type 2")
            elen, off = read_varint(mv, off, max_bytes=5)
            if off + elen > len(mv):
                raise ProtoCanonicalError("map entry overruns buffer")
            k, v = _decode_map_entry(mv[off : off + elen], 1, max_depth)
            out.labels_to_counters[k] = v
            off += elen

        else:
            raise ProtoCanonicalError(f"unknown field {fnum} rejected in strict canonical mode")

    return out
