export type CborDeterministicValue =
  | number
  | bigint
  | Uint8Array
  | string
  | CborDeterministicValue[]
  | Map<CborDeterministicValue, CborDeterministicValue>
  | { tag: number | bigint; value: CborDeterministicValue };

const utf8Fatal = new TextDecoder("utf-8", { fatal: true });

function compareBytesLex(a: Uint8Array, b: Uint8Array): number {
  const minLen = Math.min(a.byteLength, b.byteLength);
  for (let i = 0; i < minLen; i++) {
    const diff = a[i]! - b[i]!;
    if (diff !== 0) return diff;
  }
  return a.byteLength - b.byteLength;
}

function readCanonicalArg(
  view: DataView,
  off: number,
): { arg: bigint; nextOff: number } {
  if (off >= view.byteLength) {
    throw new Error(`Truncated CBOR initial byte at offset ${off}`);
  }
  const ai = view.getUint8(off) & 0x1f;
  const bodyOff = off + 1;

  if (ai < 24) {
    return { arg: BigInt(ai), nextOff: bodyOff };
  }
  if (ai === 24) {
    if (bodyOff + 1 > view.byteLength) throw new Error("Truncated 1-byte CBOR arg");
    const v = view.getUint8(bodyOff);
    if (v < 24) throw new Error(`Non-canonical 1-byte CBOR arg ${v}`);
    return { arg: BigInt(v), nextOff: bodyOff + 1 };
  }
  if (ai === 25) {
    if (bodyOff + 2 > view.byteLength) throw new Error("Truncated 2-byte CBOR arg");
    const v = view.getUint16(bodyOff, false);
    if (v < 256) throw new Error(`Non-canonical 2-byte CBOR arg ${v}`);
    return { arg: BigInt(v), nextOff: bodyOff + 2 };
  }
  if (ai === 26) {
    if (bodyOff + 4 > view.byteLength) throw new Error("Truncated 4-byte CBOR arg");
    const v = view.getUint32(bodyOff, false);
    if (v < 65536) throw new Error(`Non-canonical 4-byte CBOR arg ${v}`);
    return { arg: BigInt(v), nextOff: bodyOff + 4 };
  }
  if (ai === 27) {
    if (bodyOff + 8 > view.byteLength) throw new Error("Truncated 8-byte CBOR arg");
    const v = view.getBigUint64(bodyOff, false);
    if (v < 4294967296n) throw new Error(`Non-canonical 8-byte CBOR arg ${v}`);
    return { arg: v, nextOff: bodyOff + 8 };
  }
  if (ai === 31) {
    throw new Error("Indefinite-length CBOR forbidden in Core Deterministic profile");
  }
  throw new Error(`Reserved CBOR additional info ${ai}`);
}

function toSafeLen(n: bigint, maxRemaining: number): number {
  if (n > BigInt(maxRemaining)) {
    throw new Error(`CBOR length ${n} exceeds remaining ${maxRemaining} bytes`);
  }
  return Number(n);
}

function decodeNode(
  view: DataView,
  buf: Uint8Array,
  off: number,
  depth: number,
  maxDepth: number,
): { value: CborDeterministicValue; nextOff: number } {
  if (depth > maxDepth) {
    throw new Error(`CBOR recursion depth ${depth} exceeds maxDepth ${maxDepth}`);
  }
  if (off >= view.byteLength) {
    throw new Error("Unexpected EOF in CBOR stream");
  }

  const major = view.getUint8(off) >>> 5;
  if (major === 7) {
    throw new Error("Major type 7 outside Major 0..6 profile");
  }

  const { arg, nextOff } = readCanonicalArg(view, off);

  if (major === 0) {
    const val = arg <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(arg) : arg;
    return { value: val, nextOff };
  }
  if (major === 1) {
    const neg = -1n - arg;
    const val = neg >= BigInt(Number.MIN_SAFE_INTEGER) ? Number(neg) : neg;
    return { value: val, nextOff };
  }
  if (major === 2 || major === 3) {
    const byteLen = toSafeLen(arg, view.byteLength - nextOff);
    const slice = buf.subarray(nextOff, nextOff + byteLen);
    if (major === 2) {
      return { value: slice, nextOff: nextOff + byteLen };
    }
    return { value: utf8Fatal.decode(slice), nextOff: nextOff + byteLen };
  }
  if (major === 4) {
    const count = toSafeLen(arg, view.byteLength - nextOff);
    const arr: CborDeterministicValue[] = [];
    let cur = nextOff;
    for (let i = 0; i < count; i++) {
      const child = decodeNode(view, buf, cur, depth + 1, maxDepth);
      arr.push(child.value);
      cur = child.nextOff;
    }
    return { value: arr, nextOff: cur };
  }
  if (major === 5) {
    const count = toSafeLen(arg, Math.floor((view.byteLength - nextOff) / 2));
    const map = new Map<CborDeterministicValue, CborDeterministicValue>();
    let cur = nextOff;
    let prevKeyBytes: Uint8Array | null = null;

    for (let i = 0; i < count; i++) {
      const keyStart = cur;
      const k = decodeNode(view, buf, cur, depth + 1, maxDepth);
      const keyBytes = buf.subarray(keyStart, k.nextOff);
      if (prevKeyBytes !== null) {
        const cmp = compareBytesLex(prevKeyBytes, keyBytes);
        if (cmp === 0) throw new Error("Duplicate map key in deterministic CBOR");
        if (cmp > 0) throw new Error("Map keys out of canonical bytewise lexicographic order");
