      map.set(k.value, v.value);
      cur = v.nextOff;
    }
    return { value: map, nextOff: cur };
  }

  const tagNum = arg <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(arg) : arg;
  const inner = decodeNode(view, buf, nextOff, depth + 1, maxDepth);
  return { value: { tag: tagNum, value: inner.value }, nextOff: inner.nextOff };
}

export function decodeDeterministicCbor(buf: Uint8Array, maxDepth = 32): CborDeterministicValue {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const res = decodeNode(view, buf, 0, 0, maxDepth);
  if (res.nextOff !== buf.byteLength) {
    throw new Error(`Unconsumed ${buf.byteLength - res.nextOff} trailing bytes after CBOR root`);
  }
  return res.value;
}
