export interface GracefulRestartTuple {
  afi: number;
  safi: number;
  forwardingStatePreserved: boolean;
}

export interface GracefulRestartCapability {
  restartStateBit: boolean;
  restartTimeSeconds: number;
  tuples: GracefulRestartTuple[];
}

export interface AddPathTuple {
  afi: number;
  safi: number;
  sendReceive: 1 | 2 | 3;
}

export interface ParsedBgpExtendedOpen {
  extendedEncoding: boolean;
  myAs: number;
  holdTime: number;
  bgpId: string;
  gracefulRestart?: GracefulRestartCapability;
  addPath: AddPathTuple[];
}

function parseGracefulRestart(view: DataView, off: number, len: number): GracefulRestartCapability {
  if (len < 2 || (len - 2) % 4 !== 0) {
    throw new Error(`Invalid Graceful Restart (Cap 64) length ${len}`);
  }
  const headerWord = view.getUint16(off, false);
  const restartStateBit = ((headerWord >>> 15) & 1) === 1;
  const restartTimeSeconds = headerWord & 0x0fff;
  const tuples: GracefulRestartTuple[] = [];

  for (let p = off + 2; p < off + len; p += 4) {
    const afi = view.getUint16(p, false);
    const safi = view.getUint8(p + 2);
    const flags = view.getUint8(p + 3);
    tuples.push({
      afi,
      safi,
      forwardingStatePreserved: (flags & 0x80) !== 0,
    });
  }
  return { restartStateBit, restartTimeSeconds, tuples };
}

function parseAddPath(view: DataView, off: number, len: number): AddPathTuple[] {
  if (len < 4 || len % 4 !== 0) {
    throw new Error(`Invalid ADD-PATH (Cap 69) length ${len}`);
  }
  const tuples: AddPathTuple[] = [];
  for (let p = off; p < off + len; p += 4) {
    const afi = view.getUint16(p, false);
    const safi = view.getUint8(p + 2);
    const sr = view.getUint8(p + 3);
    if (sr !== 1 && sr !== 2 && sr !== 3) {
      throw new Error(`Invalid ADD-PATH Send/Receive value ${sr} (expected 1, 2, or 3)`);
    }
    tuples.push({ afi, safi, sendReceive: sr });
  }
  return tuples;
}

export function parseBgpOpenRfc9072(buf: Uint8Array): ParsedBgpExtendedOpen {
  if (buf.byteLength < 29 || buf.byteLength > 4096) {
    throw new Error(`BGP OPEN length ${buf.byteLength} outside [29, 4096]`);
