type CredentialPublicKey struct {
	Alg   int
	ECDSA *ecdsa.PublicKey
	EdDSA ed25519.PublicKey
}

func ParseCanonicalCOSEKey(cborBuf []byte) (*CredentialPublicKey, int, error) {
	if len(cborBuf) < 1 {
		return nil, 0, errors.New("cose: empty COSE_Key buffer")
	}
	switch cborBuf[0] {
	case 0xA4: // 4-pair map -> OKP Ed25519: {1:1, 3:-8, -1:6, -2:bstr(32)} = 42 bytes
		const wantLen = 42
		if len(cborBuf) < wantLen {
			return nil, 0, errors.New("cose: truncated OKP Ed25519 COSE_Key")
		}
		prefix := [10]byte{0xA4, 0x01, 0x01, 0x03, 0x27, 0x20, 0x06, 0x21, 0x58, 0x20}
		if subtle.ConstantTimeCompare(cborBuf[:10], prefix[:]) != 1 {
			return nil, 0, errors.New("cose: non-canonical OKP Ed25519 COSE_Key header/order")
		}
		pub := make(ed25519.PublicKey, 32)
		copy(pub, cborBuf[10:42])
		return &CredentialPublicKey{Alg: -8, EdDSA: pub}, wantLen, nil

	case 0xA5: // 5-pair map -> EC2 P-256: {1:2, 3:-7, -1:1, -2:bstr(32), -3:bstr(32)} = 77 bytes
		const wantLen = 77
		if len(cborBuf) < wantLen {
			return nil, 0, errors.New("cose: truncated EC2 P-256 COSE_Key")
		}
		prefix := [10]byte{0xA5, 0x01, 0x02, 0x03, 0x26, 0x20, 0x01, 0x21, 0x58, 0x20}
		mid := [3]byte{0x22, 0x58, 0x20}
		if subtle.ConstantTimeCompare(cborBuf[:10], prefix[:]) != 1 ||
			subtle.ConstantTimeCompare(cborBuf[42:45], mid[:]) != 1 {
			return nil, 0, errors.New("cose: non-canonical EC2 P-256 COSE_Key header/order")
		}
		uncompressed := make([]byte, 65)
		uncompressed[0] = 0x04
		copy(uncompressed[1:33], cborBuf[10:42])
		copy(uncompressed[33:65], cborBuf[45:77])
		if _, err := ecdh.P256().NewPublicKey(uncompressed); err != nil {
			return nil, 0, fmt.Errorf("cose: P-256 point not on curve: %w", err)
		}
		pub := &ecdsa.PublicKey{
			Curve: elliptic.P256(),
			X:     new(big.Int).SetBytes(cborBuf[10:42]),
			Y:     new(big.Int).SetBytes(cborBuf[45:77]),
		}
		return &CredentialPublicKey{Alg: -7, ECDSA: pub}, wantLen, nil

	default:
		return nil, 0, fmt.Errorf("cose: unsupported COSE_Key CBOR map head 0x%02x", cborBuf[0])
	}
}

func VerifyAssertion(
	authData []byte,
	clientDataJSON []byte,
	signature []byte,
	rpID string,
	credKey *CredentialPublicKey,
	prevSignCount uint32,
	requireUV bool,
) (uint32, error) {
	if len(authData) < 37 {
		return 0, errors.New("webauthn: authenticatorData < 37 bytes")
	}
	wantRP := sha256.Sum256([]byte(rpID))
	if subtle.ConstantTimeCompare(authData[0:32], wantRP[:]) != 1 {
		return 0, errors.New("webauthn: rpIdHash mismatch")
	}

	flags := authData[32]
	if (flags & 0x01) == 0 {
		return 0, errors.New("webauthn: UP flag missing")
	}
	if requireUV && (flags&0x04) == 0 {
		return 0, errors.New("webauthn: UV flag required")
	}
	if (flags&0x10) != 0 && (flags&0x08) == 0 {
		return 0, errors.New("webauthn: illegal BS=1 with BE=0")
	}
	if (flags & 0x40) != 0 {
		return 0, errors.New("webauthn: AT flag forbidden in assertion authData")
	}
	if (flags&0x80) == 0 && len(authData) != 37 {
		return 0, errors.New("webauthn: trailing bytes in 37-byte assertion authData")
	}

	newSignCount := binary.BigEndian.Uint32(authData[33:37])
	if (prevSignCount != 0 || newSignCount != 0) && newSignCount <= prevSignCount {
		return 0, fmt.Errorf("webauthn: cloned/rolled-back signCount %d <= %d", newSignCount, prevSignCount)
	}

	clientHash := sha256.Sum256(clientDataJSON)
	signedPayload := make([]byte, len(authData)+32)
	copy(signedPayload, authData)
	copy(signedPayload[len(authData):], clientHash[:])

	switch credKey.Alg {
	case -8:
		if len(signature) != ed25519.SignatureSize || !ed25519.Verify(credKey.EdDSA, signedPayload, signature) {
			return 0, errors.New("webauthn: Ed25519 assertion signature invalid")
		}
	case -7:
		digest := sha256.Sum256(signedPayload)
		if !ecdsa.VerifyASN1(credKey.ECDSA, digest[:], signature) {
			return 0, errors.New("webauthn: ES256 assertion signature invalid")
		}
	default:
		return 0, fmt.Errorf("webauthn: unsupported credential alg %d", credKey.Alg)
	}

	return newSignCount, nil
}
