const B32HEX_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUV";
const B32HEX_LOOKUP = new Int8Array(128).fill(-1);
for (let i = 0; i < B32HEX_ALPHABET.length; i++) {
  B32HEX_LOOKUP[B32HEX_ALPHABET.charCodeAt(i)] = i;
}

export interface ResourceToken {
  prefix: string;
  version: 1;
  tenantId: number;
  resourceId: bigint;
}

export function crc16Xmodem(chunks: readonly Uint8Array[]): number {
  let crc = 0x0000;
  for (const chunk of chunks) {
    for (let i = 0; i < chunk.byteLength; i++) {
      crc ^= chunk[i]! << 8;
      for (let bit = 0; bit < 8; bit++) {
        crc = (crc & 0x8000) !== 0 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
      }
    }
  }
  return crc;
}

export function encodeBase32HexCanonical(bytes: Uint8Array): string {
  let out = "";
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < bytes.byteLength; i++) {
    buffer = (buffer << 8) | bytes[i]!;
    bits += 8;
    while (bits >= 5) {
      bits -= 5;
      out += B32HEX_ALPHABET[(buffer >>> bits) & 0x1f]!;
    }
  }
  if (bits > 0) {
    out += B32HEX_ALPHABET[(buffer << (5 - bits)) & 0x1f]!;
  }
  return out;
}

export function decodeBase32HexCanonical(str: string): Uint8Array {
  const rem = str.length % 8;
  if (rem === 1 || rem === 3 || rem === 6) {
    throw new Error(`Invalid unpadded Base32hex length ${str.length}`);
  }
  const out = new Uint8Array(Math.floor((str.length * 5) / 8));
  let buffer = 0;
  let bits = 0;
  let idx = 0;

  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    const val = code < 128 ? B32HEX_LOOKUP[code]! : -1;
    if (val < 0) {
      throw new Error(`Invalid uppercase Base32hex character at index ${i}`);
    }
    buffer = (buffer << 5) | val;
    bits += 5;
    if (bits >= 8) {
      bits -= 8;
      out[idx++] = (buffer >>> bits) & 0xff;
    }
  }

  if (bits > 0 && (buffer & ((1 << bits) - 1)) !== 0) {
    throw new Error("Non-canonical Base32hex: non-zero trailing padding bits");
  }
  return out;
}

export function encodeResourceToken(tok: ResourceToken): string {
  if (!/^[a-z]{3}$/.test(tok.prefix)) {
    throw new Error("Prefix must be 3 lowercase ASCII letters");
  }
  if (tok.tenantId <= 0 || tok.tenantId > 0xffffffff || !Number.isInteger(tok.tenantId)) {
    throw new Error("Invalid uint32 tenantId");
  }
  if (tok.resourceId <= 0n || tok.resourceId > 0xffffffffffffffffn) {
    throw new Error("Invalid uint64 resourceId");
  }

