  view.setUint16(13, crc, false);

  return `${tok.prefix}_${encodeBase32HexCanonical(raw)}`;
}

export function decodeResourceToken(token: string, expectedPrefix?: string): ResourceToken {
  if (token.length !== 28 || token[3] !== "_") {
    throw new Error("Invalid token length or missing '_' separator");
  }
  const prefix = token.slice(0, 3);
  if (!/^[a-z]{3}$/.test(prefix)) {
    throw new Error("Invalid 3-letter lowercase prefix");
