	ErrInvalidDelimiter = errors.New("traceparent: invalid '-' delimiter position")
	ErrNonLowerHex      = errors.New("traceparent: uppercase or non-hex character")
	ErrForbiddenVersion = errors.New("traceparent: version 0xff is forbidden")
	ErrZeroTraceID      = errors.New("traceparent: all-zero trace-id is forbidden")
	ErrZeroParentID     = errors.New("traceparent: all-zero parent-id is forbidden")
)

const (
	FlagSampled       uint8 = 0x01
	FlagRandomTraceID uint8 = 0x02
)

type SpanContextWire struct {
	Version   uint8
	TraceID   [16]byte
	ParentID  [8]byte
	Flags     uint8
}

func (s SpanContextWire) Sampled() bool {
	return (s.Flags & FlagSampled) != 0
}

func (s SpanContextWire) RandomTraceID() bool {
	return (s.Flags & FlagRandomTraceID) != 0
}

func decodeLowerHexByte(hi, lo byte) (byte, bool) {
	var h, l byte
	switch {
	case hi >= '0' && hi <= '9':
		h = hi - '0'
	case hi >= 'a' && hi <= 'f':
		h = hi - 'a' + 10
	default:
		return 0, false
	}
	switch {
	case lo >= '0' && lo <= '9':
		l = lo - '0'
	case lo >= 'a' && lo <= 'f':
		l = lo - 'a' + 10
	default:
		return 0, false
	}
	return (h << 4) | l, true
}

func trimOWS(b []byte) []byte {
	start := 0
	for start < len(b) && (b[start] == ' ' || b[start] == '\t') {
		start++
	}
	end := len(b)
	for end > start && (b[end-1] == ' ' || b[end-1] == '\t') {
		end--
	}
	return b[start:end]
}

func ParseTraceparentBytes(raw []byte) (SpanContextWire, error) {
	var out SpanContextWire
	b := trimOWS(raw)
	if len(b) < 55 {
		return out, ErrInvalidLength
	}
	if b[2] != '-' || b[35] != '-' || b[52] != '-' {
		return out, ErrInvalidDelimiter
	}

	ver, ok := decodeLowerHexByte(b[0], b[1])
	if !ok {
		return out, ErrNonLowerHex
	}
	if ver == 0xff {
		return out, ErrForbiddenVersion
	}
	if ver == 0x00 {
		if len(b) != 55 {
			return out, ErrInvalidLength
		}
	} else if len(b) > 55 && b[55] != '-' {
		return out, ErrInvalidDelimiter
	}

	var traceNonZero byte
	for i := range 16 {
		v, ok := decodeLowerHexByte(b[3+i*2], b[4+i*2])
		if !ok {
			return out, ErrNonLowerHex
		}
		out.TraceID[i] = v
		traceNonZero |= v
	}
	if traceNonZero == 0 {
		return out, ErrZeroTraceID
	}

	var spanNonZero byte
	for i := range 8 {
		v, ok := decodeLowerHexByte(b[36+i*2], b[37+i*2])
		if !ok {
			return out, ErrNonLowerHex
		}
		out.ParentID[i] = v
		spanNonZero |= v
	}
	if spanNonZero == 0 {
		return out, ErrZeroParentID
	}

	flags, ok := decodeLowerHexByte(b[53], b[54])
	if !ok {
		return out, ErrNonLowerHex
	}

	out.Version = ver
	out.Flags = flags
	return out, nil
}
