    }
    if (scopeBytes < 4 || scopeBytes % 4 !== 0) {
      throw new Error(`Invalid option_scope_length ${scopeBytes}`);
    }
    if (optBytes < 4 || optBytes % 4 !== 0) {
      throw new Error(`Invalid option_length ${optBytes}`);
