import (
	"encoding/binary"
	"errors"
	"fmt"
)

const (
	FrameData    uint8 = 0x00
	FrameHeaders uint8 = 0x01

	FlagEndStream  uint8 = 0x01
	FlagEndHeaders uint8 = 0x04
	FlagPadded     uint8 = 0x08
	FlagPriority   uint8 = 0x20
)

var (
	ErrFrameSize = errors.New("h2: FRAME_SIZE_ERROR")
	ErrProtocol  = errors.New("h2: PROTOCOL_ERROR")
)

type PrioritySpec struct {
	Exclusive        bool
	StreamDependency uint32
	Weight           uint16 // 1..256 per RFC 9113
}

type UnwrappedFrame struct {
	Type          uint8
	Flags         uint8
	StreamID      uint32
	EndStream     bool
	EndHeaders    bool
	Priority      *PrioritySpec
	CleanPayload  []byte
	PaddingLength uint8
}

func UnwrapDataOrHeadersFrame(buf []byte, maxFrameSize uint32) (*UnwrappedFrame, int, error) {
	if len(buf) < 9 {
		return nil, 0, fmt.Errorf("%w: need 9-byte header, got %d", ErrFrameSize, len(buf))
	}
	payloadLen := (uint32(buf[0]) << 16) | (uint32(buf[1]) << 8) | uint32(buf[2])
	if payloadLen > maxFrameSize {
		return nil, 0, fmt.Errorf("%w: length %d > maxFrameSize %d", ErrFrameSize, payloadLen, maxFrameSize)
	}
	totalLen := 9 + int(payloadLen)
	if len(buf) < totalLen {
		return nil, 0, fmt.Errorf("%w: truncated frame payload", ErrFrameSize)
	}

	fType := buf[3]
	if fType != FrameData && fType != FrameHeaders {
		return nil, 0, fmt.Errorf("%w: unsupported frame type 0x%02x", ErrProtocol, fType)
	}
	flags := buf[4]
	streamID := binary.BigEndian.Uint32(buf[5:9]) & 0x7FFFFFFF
	if streamID == 0 {
		return nil, 0, fmt.Errorf("%w: frame type 0x%02x forbidden on stream 0", ErrProtocol, fType)
	}

	payload := buf[9:totalLen]
	cur := 0
	var padLen uint8

	if (flags & FlagPadded) != 0 {
		if len(payload) < 1 {
			return nil, 0, fmt.Errorf("%w: PADDED set on 0-byte payload", ErrProtocol)
		}
		padLen = payload[0]
		cur = 1
		if int(padLen) >= len(payload) {
			return nil, 0, fmt.Errorf("%w: pad_length %d >= frame length %d", ErrProtocol, padLen, len(payload))
		}
	}

	var prio *PrioritySpec
	if fType == FrameHeaders && (flags&FlagPriority) != 0 {
		if len(payload)-cur < 5 {
			return nil, 0, fmt.Errorf("%w: truncated 5-byte PRIORITY fields in HEADERS", ErrFrameSize)
		}
		depRaw := binary.BigEndian.Uint32(payload[cur : cur+4])
		depStream := depRaw & 0x7FFFFFFF
		if depStream == streamID {
			return nil, 0, fmt.Errorf("%w: stream %d cannot depend on itself", ErrProtocol, streamID)
		}
		prio = &PrioritySpec{
			Exclusive:        (depRaw >> 31) == 1,
			StreamDependency: depStream,
			Weight:           uint16(payload[cur+4]) + 1,
		}
		cur += 5
	}

