		Type:          fType,
		Flags:         flags,
		StreamID:      streamID,
		EndStream:     (flags & FlagEndStream) != 0,
		EndHeaders:    fType == FrameHeaders && (flags&FlagEndHeaders) != 0,
		Priority:      prio,
