const PNG_MAGIC = new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

const CRC32_TABLE = (() => {
  const tbl = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) !== 0 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    tbl[i] = c >>> 0;
  }
  return tbl;
})();

function crc32IEEE(buf: Uint8Array, start: number, end: number): number {
  let c = 0xffffffff;
  for (let i = start; i < end; i++) {
    c = CRC32_TABLE[(c ^ buf[i]!) & 0xff]! ^ (c >>> 8);
  }
  return (c ^ 0xffffffff) >>> 0;
}

const VALID_DEPTHS: Record<number, ReadonlySet<number>> = {
  0: new Set([1, 2, 4, 8, 16]),
  2: new Set([8, 16]),
  3: new Set([1, 2, 4, 8]),
  4: new Set([8, 16]),
  6: new Set([8, 16]),
};

export interface ValidatedPngMetadata {
  width: number;
  height: number;
  bitDepth: number;
  colorType: 0 | 2 | 3 | 4 | 6;
  interlaceMethod: 0 | 1;
  paletteEntries: number;
  hasTransparencyChunk: boolean;
  idatChunkCount: number;
  totalIdatBytes: number;
}

export function validatePngCriticalStream(buf: Uint8Array): ValidatedPngMetadata {
  if (buf.byteLength < 8) {
    throw new Error("Truncated PNG signature");
  }
  for (let i = 0; i < 8; i++) {
    if (buf[i] !== PNG_MAGIC[i]) {
      throw new Error("Invalid 8-byte PNG signature");
    }
  }

  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  let off = 8;
  let chunkIndex = 0;

  let ihdr: {
    width: number;
    height: number;
    bitDepth: number;
    colorType: 0 | 2 | 3 | 4 | 6;
    interlaceMethod: 0 | 1;
  } | null = null;

  let paletteEntries = 0;
  let sawPLTE = false;
  let sawTRNS = false;
  let idatCount = 0;
  let totalIdatBytes = 0;
  let inIdatRun = false;
  let finishedIdatRun = false;
  let sawIEND = false;

  while (off < buf.byteLength) {
    if (buf.byteLength - off < 12) {
      throw new Error(`Truncated PNG chunk header at offset ${off}`);
    }
    const len = view.getUint32(off, false);
    if (len > 0x7fffffff || off + 12 + len > buf.byteLength) {
      throw new Error(`Invalid or truncated PNG chunk length ${len} at offset ${off}`);
    }

    const typeStr = String.fromCharCode(
      buf[off + 4]!,
      buf[off + 5]!,
      buf[off + 6]!,
      buf[off + 7]!,
    );
    if (!/^[A-Za-z]{4}$/.test(typeStr) || (buf[off + 6]! & 0x20) !== 0) {
      throw new Error(`Invalid PNG chunk type '${typeStr}'`);
    }

    const dataStart = off + 8;
    const dataEnd = dataStart + len;
    const wantCrc = view.getUint32(dataEnd, false);
    const gotCrc = crc32IEEE(buf, off + 4, dataEnd);
    if (gotCrc !== wantCrc) {
      throw new Error(`CRC-32 mismatch in chunk '${typeStr}'`);
    }

    if (chunkIndex === 0) {
      if (typeStr !== "IHDR" || len !== 13) {
        throw new Error("First PNG chunk must be 13-byte IHDR");
      }
      const width = view.getUint32(dataStart, false);
      const height = view.getUint32(dataStart + 4, false);
      const bitDepth = view.getUint8(dataStart + 8);
      const colorType = view.getUint8(dataStart + 9);
      const comp = view.getUint8(dataStart + 10);
      const filter = view.getUint8(dataStart + 11);
      const interlace = view.getUint8(dataStart + 12);

      if (width === 0 || width > 0x7fffffff || height === 0 || height > 0x7fffffff) {
        throw new Error(`Invalid PNG dimensions ${width}x${height}`);
      }
      const allowedDepths = VALID_DEPTHS[colorType];
      if (!allowedDepths || !allowedDepths.has(bitDepth)) {
        throw new Error(`Illegal PNG (colorType=${colorType}, bitDepth=${bitDepth}) combination`);
      }
      if (comp !== 0 || filter !== 0 || (interlace !== 0 && interlace !== 1)) {
        throw new Error("Invalid PNG compression, filter, or interlace method in IHDR");
      }
      ihdr = {
        width,
        height,
        bitDepth,
        colorType: colorType as 0 | 2 | 3 | 4 | 6,
        interlaceMethod: interlace,
      };
    } else {
      if (!ihdr) throw new Error("Missing IHDR state");
      if (typeStr === "IHDR") {
        throw new Error("Duplicate IHDR chunk");
      }

      if (typeStr === "IDAT") {
        if (finishedIdatRun) {
          throw new Error("Non-consecutive IDAT chunks are forbidden by PNG spec");
        }
        if (ihdr.colorType === 3 && !sawPLTE) {
          throw new Error("Indexed-color PNG (colorType=3) missing PLTE before IDAT");
        }
        inIdatRun = true;
        idatCount++;
        totalIdatBytes += len;
      } else if (inIdatRun) {
        inIdatRun = false;
        finishedIdatRun = true;
      }

      if (typeStr === "PLTE") {
        if (sawPLTE || idatCount > 0) {
          throw new Error("Duplicate PLTE or PLTE after IDAT");
        }
        if (ihdr.colorType === 0 || ihdr.colorType === 4) {
          throw new Error(`PLTE forbidden for grayscale colorType ${ihdr.colorType}`);
        }
        if (len === 0 || len % 3 !== 0 || len > 768) {
          throw new Error(`Invalid PLTE byte length ${len}`);
        }
        paletteEntries = len / 3;
        if (ihdr.colorType === 3 && paletteEntries > (1 << ihdr.bitDepth)) {
          throw new Error(`PLTE entries ${paletteEntries} exceed 2^bitDepth`);
        }
        sawPLTE = true;
      } else if (typeStr === "tRNS") {
        if (sawTRNS || idatCount > 0) {
          throw new Error("Duplicate tRNS or tRNS after IDAT");
        }
        if (ihdr.colorType === 4 || ihdr.colorType === 6) {
          throw new Error(`tRNS forbidden when alpha channel already present (colorType=${ihdr.colorType})`);
        }
        if (ihdr.colorType === 0 && len !== 2) {
          throw new Error("tRNS for colorType=0 must be 2 bytes");
        }
        if (ihdr.colorType === 2 && len !== 6) {
          throw new Error("tRNS for colorType=2 must be 6 bytes");
        }
        if (ihdr.colorType === 3) {
          if (!sawPLTE) {
            throw new Error("tRNS must appear after PLTE for colorType=3");
          }
          if (len === 0 || len > paletteEntries) {
            throw new Error(`tRNS length ${len} invalid for ${paletteEntries} PLTE entries`);
          }
        }
        sawTRNS = true;
      } else if (typeStr === "IEND") {
        if (len !== 0) {
          throw new Error("IEND chunk must have length 0");
        }
        if (idatCount === 0) {
          throw new Error("PNG missing IDAT chunk before IEND");
        }
        if (dataEnd + 4 !== buf.byteLength) {
          throw new Error("Trailing bytes after IEND chunk");
        }
        sawIEND = true;
        break;
      }
    }

    off = dataEnd + 4;
    chunkIndex++;
  }

  if (!sawIEND || !ihdr) {
    throw new Error("Incomplete PNG stream: missing IEND");
  }

  return {
    width: ihdr.width,
    height: ihdr.height,
    bitDepth: ihdr.bitDepth,
    colorType: ihdr.colorType,
    interlaceMethod: ihdr.interlaceMethod,
    paletteEntries,
    hasTransparencyChunk: sawTRNS,
    idatChunkCount: idatCount,
    totalIdatBytes,
  };
}
