package emvdol

import (
	"bytes"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
)

type DOLEntry struct {
	TagHex string
	Length int
}

type GenerateACFormat2 struct {
	CryptogramInfoData byte     // 9F27 (1B)
	AppTransactionCtr  uint16   // 9F36 (2B)
	AppCryptogram      [8]byte  // 9F26 (8B)
	IssuerAppData      []byte   // 9F10 (optional, 1..32B)
	OtherTags          map[string][]byte
}

func readCanonicalEMVTag(buf []byte, off int) (tagHex string, constructed bool, nextOff int, err error) {
	if off >= len(buf) {
		return "", false, 0, errors.New("emv: truncated tag")
	}
	b0 := buf[off]
	constructed = (b0 & 0x20) != 0
	if (b0 & 0x1F) != 0x1F {
		return strings.ToUpper(hex.EncodeToString(buf[off : off+1])), constructed, off + 1, nil
	}

	cur := off + 1
	tagNum := 0
	for count := 1; ; count++ {
		if cur >= len(buf) {
			return "", false, 0, errors.New("emv: truncated multi-byte tag")
		}
		if count > 2 {
			return "", false, 0, errors.New("emv: EMV tag exceeds 3 bytes")
		}
		b := buf[cur]
		cur++
		if count == 1 && (b&0x7F) == 0 {
			return "", false, 0, errors.New("emv: non-canonical leading zero in multi-byte tag")
		}
		tagNum = (tagNum << 7) | int(b&0x7F)
		if (b & 0x80) == 0 {
			break
		}
	}
	if tagNum < 31 {
		return "", false, 0, errors.New("emv: non-canonical multi-byte tag < 31")
	}
	return strings.ToUpper(hex.EncodeToString(buf[off:cur])), constructed, cur, nil
}

func readCanonicalBERLength(buf []byte, off int) (int, int, error) {
	if off >= len(buf) {
		return 0, 0, errors.New("emv: truncated BER length")
	}
	b0 := buf[off]
	if b0 < 0x80 {
		return int(b0), off + 1, nil
	}
	switch b0 {
	case 0x81:
		if off+2 > len(buf) {
			return 0, 0, errors.New("emv: truncated 0x81 length")
		}
		v := int(buf[off+1])
		if v < 128 {
			return 0, 0, fmt.Errorf("emv: non-canonical 0x81 length %d < 128", v)
		}
		return v, off + 2, nil
	case 0x82:
		if off+3 > len(buf) {
			return 0, 0, errors.New("emv: truncated 0x82 length")
		}
		v := int(binary.BigEndian.Uint16(buf[off+1 : off+3]))
		if v < 256 {
			return 0, 0, fmt.Errorf("emv: non-canonical 0x82 length %d < 256", v)
		}
		return v, off + 3, nil
	default:
		return 0, 0, fmt.Errorf("emv: unsupported or indefinite BER length prefix 0x%02x", b0)
	}
}

func ParseDOLDescriptors(dolBytes []byte) ([]DOLEntry, int, error) {
	if len(dolBytes) == 0 {
		return nil, 0, errors.New("emv: empty DOL descriptor list")
	}
	var entries []DOLEntry
	seen := make(map[string]struct{})
	totalExpected := 0
	off := 0

	for off < len(dolBytes) {
		tagHex, constructed, afterTag, err := readCanonicalEMVTag(dolBytes, off)
		if err != nil {
			return nil, 0, err
		}
		if constructed {
			return nil, 0, fmt.Errorf("emv: constructed tag %s forbidden in DOL request", tagHex)
		}
		reqLen, afterLen, err := readCanonicalBERLength(dolBytes, afterTag)
		if err != nil {
			return nil, 0, err
		}
		if reqLen == 0 {
			return nil, 0, fmt.Errorf("emv: zero requested length for DOL tag %s", tagHex)
		}
		if _, dup := seen[tagHex]; dup {
			return nil, 0, fmt.Errorf("emv: duplicate tag %s in DOL", tagHex)
		}
		seen[tagHex] = struct{}{}
		entries = append(entries, DOLEntry{TagHex: tagHex, Length: reqLen})
		totalExpected += reqLen
		off = afterLen
	}
	return entries, totalExpected, nil
}

func ParseGenerateACFormat2(buf []byte) (*GenerateACFormat2, error) {
	tagHex, constructed, afterTag, err := readCanonicalEMVTag(buf, 0)
	if err != nil {
		return nil, err
	}
	if tagHex != "77" || !constructed {
		return nil, fmt.Errorf("emv: expected constructed template 77, got %s", tagHex)
	}
	bodyLen, off, err := readCanonicalBERLength(buf, afterTag)
	if err != nil {
		return nil, err
	}
	if off+bodyLen != len(buf) {
		return nil, errors.New("emv: template 77 length mismatches buffer size")
	}

	var out GenerateACFormat2
	out.OtherTags = make(map[string][]byte)
	var hasCID, hasATC, hasAC bool
	seen := make(map[string]struct{})

	for off < len(buf) {
		cTag, _, cAfterTag, err := readCanonicalEMVTag(buf, off)
		if err != nil {
			return nil, err
		}
		cLen, cValStart, err := readCanonicalBERLength(buf, cAfterTag)
		if err != nil {
			return nil, err
		}
		if cValStart+cLen > len(buf) {
			return nil, fmt.Errorf("emv: child tag %s overruns template 77", cTag)
		}
		if _, dup := seen[cTag]; dup {
			return nil, fmt.Errorf("emv: duplicate tag %s inside template 77", cTag)
		}
		seen[cTag] = struct{}{}
		val := buf[cValStart : cValStart+cLen]
		off = cValStart + cLen

		switch cTag {
		case "9F27":
			if cLen != 1 {
				return nil, errors.New("emv: 9F27 (CID) must be 1 byte")
			}
			out.CryptogramInfoData = val[0]
			hasCID = true
		case "9F36":
			if cLen != 2 {
				return nil, errors.New("emv: 9F36 (ATC) must be 2 bytes")
			}
			out.AppTransactionCtr = binary.BigEndian.Uint16(val)
			hasATC = true
		case "9F26":
			if cLen != 8 {
				return nil, errors.New("emv: 9F26 (AC) must be 8 bytes")
			}
			copy(out.AppCryptogram[:], val)
			hasAC = true
		case "9F10":
			if cLen < 1 || cLen > 32 {
				return nil, fmt.Errorf("emv: 9F10 (IAD) length %d outside 1..32", cLen)
			}
			out.IssuerAppData = bytes.Clone(val)
		default:
			out.OtherTags[cTag] = bytes.Clone(val)
		}
	}

	if !hasCID || !hasATC || !hasAC {
		return nil, errors.New("emv: template 77 missing mandatory 9F27, 9F36, or 9F26")
	}
	return &out, nil
}
