from __future__ import annotations

import struct
from dataclasses import dataclass, field

MIN_VARINT = (0, 0, 128, 16_384, 2_097_152)

CONNACK_ALLOWED = frozenset({0x11, 0x12, 0x13, 0x1F, 0x21, 0x22, 0x24, 0x25, 0x26, 0x27})
PUBACK_ALLOWED = frozenset({0x1F, 0x26})
DISCONNECT_ALLOWED = frozenset({0x11, 0x1C, 0x1F, 0x26})


class MQTTv5ProtocolError(ValueError):
    pass


def read_varint(mv: memoryview, off: int) -> tuple[int, int]:
    val = 0
    mul = 1
    for i in range(4):
        if off + i >= len(mv):
            raise MQTTv5ProtocolError("truncated MQTT v5 Variable Byte Integer")
        b = mv[off + i]
        val += (b & 0x7F) * mul
        if (b & 0x80) == 0:
            width = i + 1
            if val < MIN_VARINT[width]:
                raise MQTTv5ProtocolError("non-canonical overlong MQTT v5 varint")
            return val, off + width
        mul *= 128
    raise MQTTv5ProtocolError("MQTT v5 varint exceeds 4 bytes")


def read_utf8_str(mv: memoryview, off: int) -> tuple[str, int]:
    if off + 2 > len(mv):
        raise MQTTv5ProtocolError("truncated UTF-8 length")
    (slen,) = struct.unpack_from(">H", mv, off)
    end = off + 2 + slen
    if end > len(mv):
        raise MQTTv5ProtocolError("truncated UTF-8 string bytes")
    raw = bytes(mv[off + 2 : end])
    if b"\x00" in raw:
        raise MQTTv5ProtocolError("U+0000 NUL forbidden in MQTT UTF-8 string")
    try:
        text = raw.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise MQTTv5ProtocolError("invalid UTF-8 sequence in MQTT string") from exc
    return text, end


@dataclass(slots=True)
class DecodedControlPacket:
    packet_type: str
    reason_code: int
    session_present: bool | None = None
    packet_id: int | None = None
    scalars: dict[int, int | str] = field(default_factory=dict)
    user_properties: list[tuple[str, str]] = field(default_factory=list)


def _parse_properties(
    mv: memoryview,
    off: int,
    allowed: frozenset[int],
) -> tuple[dict[int, int | str], list[tuple[str, str]], int]:
    prop_len, cur = read_varint(mv, off)
    end = cur + prop_len
    if end > len(mv):
        raise MQTTv5ProtocolError("property block overruns packet")

    scalars: dict[int, int | str] = {}
    user_props: list[tuple[str, str]] = []

    while cur < end:
        pid = mv[cur]
        cur += 1
        if pid not in allowed:
            raise MQTTv5ProtocolError(f"property 0x{pid:02x} not allowed in this packet")

        if pid == 0x26:
            k, cur = read_utf8_str(mv[:end], cur)
            v, cur = read_utf8_str(mv[:end], cur)
            user_props.append((k, v))
            continue

        if pid in scalars:
            raise MQTTv5ProtocolError(f"duplicate single-occurrence property 0x{pid:02x}")

        if pid in (0x24, 0x25):
            if cur >= end:
                raise MQTTv5ProtocolError(f"truncated 1-byte property 0x{pid:02x}")
            bval = mv[cur]
            cur += 1
            if bval not in (0, 1):
                raise MQTTv5ProtocolError(f"property 0x{pid:02x} value {bval} must be 0 or 1")
            scalars[pid] = bval
        elif pid in (0x13, 0x21, 0x22):
            if cur + 2 > end:
                raise MQTTv5ProtocolError(f"truncated uint16 property 0x{pid:02x}")
            (u16,) = struct.unpack_from(">H", mv, cur)
            cur += 2
            if pid == 0x21 and u16 == 0:
                raise MQTTv5ProtocolError("Receive Maximum (0x21) cannot be 0")
            scalars[pid] = u16
        elif pid in (0x11, 0x27):
            if cur + 4 > end:
                raise MQTTv5ProtocolError(f"truncated uint32 property 0x{pid:02x}")
            (u32,) = struct.unpack_from(">I", mv, cur)
            cur += 4
            if pid == 0x27 and u32 == 0:
                raise MQTTv5ProtocolError("Maximum Packet Size (0x27) cannot be 0")
            scalars[pid] = u32
        elif pid in (0x12, 0x1C, 0x1F):
            sval, cur = read_utf8_str(mv[:end], cur)
            scalars[pid] = sval

    return scalars, user_props, end


def parse_mqttv5_ack_or_disconnect(pkt: bytes | bytearray | memoryview) -> DecodedControlPacket:
    mv = memoryview(pkt)
    if len(mv) < 2:
        raise MQTTv5ProtocolError("MQTT v5 packet < 2 bytes")

    b0 = mv[0]
    if (b0 & 0x0F) != 0x00:
        raise MQTTv5ProtocolError(f"non-zero reserved fixed header flags in 0x{b0:02x}")

    rem_len, vh_start = read_varint(mv, 1)
    if vh_start + rem_len != len(mv):
        raise MQTTv5ProtocolError("Remaining Length does not match packet buffer")

    body = mv[vh_start:]

    if b0 == 0x20:  # CONNACK
        if len(body) < 3:
            raise MQTTv5ProtocolError("CONNACK variable header < 3 bytes")
        ack_flags = body[0]
        if (ack_flags & 0xFE) != 0:
            raise MQTTv5ProtocolError("non-zero reserved CONNACK flags")
        session_present = (ack_flags & 0x01) == 1
        reason = body[1]
        if reason >= 0x80 and session_present:
            raise MQTTv5ProtocolError("CONNACK failure reason >= 0x80 must have SessionPresent=0")
        scalars, uprops, end = _parse_properties(body, 2, CONNACK_ALLOWED)
        if end != len(body):
            raise MQTTv5ProtocolError("CONNACK has unexpected payload bytes")
        return DecodedControlPacket(
            packet_type="CONNACK",
            reason_code=reason,
            session_present=session_present,
            scalars=scalars,
            user_properties=uprops,
        )

    if b0 == 0x40:  # PUBACK
        if len(body) < 2:
            raise MQTTv5ProtocolError("PUBACK missing 2-byte Packet Identifier")
        (packet_id,) = struct.unpack_from(">H", body, 0)
        if packet_id == 0:
            raise MQTTv5ProtocolError("PUBACK Packet Identifier cannot be 0")
        if len(body) == 2:
            return DecodedControlPacket("PUBACK", reason_code=0x00, packet_id=packet_id)
        reason = body[2]
        if len(body) == 3:
            return DecodedControlPacket("PUBACK", reason_code=reason, packet_id=packet_id)
        scalars, uprops, end = _parse_properties(body, 3, PUBACK_ALLOWED)
        if end != len(body):
            raise MQTTv5ProtocolError("PUBACK has trailing bytes after properties")
        return DecodedControlPacket(
            packet_type="PUBACK",
            reason_code=reason,
            packet_id=packet_id,
            scalars=scalars,
            user_properties=uprops,
        )

    if b0 == 0xE0:  # DISCONNECT
        if len(body) == 0:
            return DecodedControlPacket("DISCONNECT", reason_code=0x00)
        reason = body[0]
        if len(body) == 1:
            return DecodedControlPacket("DISCONNECT", reason_code=reason)
        scalars, uprops, end = _parse_properties(body, 1, DISCONNECT_ALLOWED)
        if end != len(body):
            raise MQTTv5ProtocolError("DISCONNECT has trailing bytes after properties")
        return DecodedControlPacket(
            packet_type="DISCONNECT",
            reason_code=reason,
            scalars=scalars,
            user_properties=uprops,
        )

    raise MQTTv5ProtocolError(f"unsupported MQTT v5 control packet header 0x{b0:02x}")
