package wgwire

import (
	"encoding/binary"
	"errors"
	"fmt"
	"math"
)

const (
	MsgInitiation  uint8  = 1
	MsgResponse    uint8  = 2
	MsgCookieReply uint8  = 3
	MsgTransport   uint8  = 4

	RejectAfterMessages uint64 = math.MaxUint64 - (1 << 13)
)

type Packet struct {
	Type           uint8
	SenderIndex    uint32
	ReceiverIndex  uint32
	Counter        uint64
	Ephemeral      []byte
	Nonce24        []byte
	CiphertextBody []byte
	Poly1305Tag    []byte
	MAC1           []byte
	MAC2           []byte
}

func isAllZeroCT(b []byte) bool {
	var acc byte
	for _, x := range b {
		acc |= x
	}
	return acc == 0
}

func ParseWireGuardDatagram(pkt []byte) (*Packet, error) {
	if len(pkt) < 32 {
		return nil, fmt.Errorf("wg: datagram shorter than 32-byte minimum (%d bytes)", len(pkt))
	}
	if (pkt[1] | pkt[2] | pkt[3]) != 0 {
		return nil, errors.New("wg: non-zero reserved header bytes [1..3]")
	}

	msgType := pkt[0]
	switch msgType {
	case MsgInitiation:
		if len(pkt) != 148 {
			return nil, fmt.Errorf("wg: Initiation must be 148 bytes, got %d", len(pkt))
		}
		ephem := pkt[8:40]
		mac1 := pkt[116:132]
		if isAllZeroCT(ephem) || isAllZeroCT(mac1) {
			return nil, errors.New("wg: all-zero ephemeral or mac1 in Initiation")
		}
		return &Packet{
			Type:           MsgInitiation,
			SenderIndex:    binary.LittleEndian.Uint32(pkt[4:8]),
			Ephemeral:      ephem,
			CiphertextBody: pkt[40:116],
			MAC1:           mac1,
			MAC2:           pkt[132:148],
		}, nil

	case MsgResponse:
		if len(pkt) != 92 {
			return nil, fmt.Errorf("wg: Response must be 92 bytes, got %d", len(pkt))
		}
		ephem := pkt[12:44]
		mac1 := pkt[60:76]
		if isAllZeroCT(ephem) || isAllZeroCT(mac1) {
			return nil, errors.New("wg: all-zero ephemeral or mac1 in Response")
		}
		return &Packet{
			Type:           MsgResponse,
			SenderIndex:    binary.LittleEndian.Uint32(pkt[4:8]),
			ReceiverIndex:  binary.LittleEndian.Uint32(pkt[8:12]),
			Ephemeral:      ephem,
			CiphertextBody: pkt[44:60],
			MAC1:           mac1,
			MAC2:           pkt[76:92],
		}, nil

	case MsgCookieReply:
		if len(pkt) != 64 {
			return nil, fmt.Errorf("wg: CookieReply must be 64 bytes, got %d", len(pkt))
		}
		return &Packet{
			Type:           MsgCookieReply,
			ReceiverIndex:  binary.LittleEndian.Uint32(pkt[4:8]),
			Nonce24:        pkt[8:32],
			CiphertextBody: pkt[32:48],
			Poly1305Tag:    pkt[48:64],
		}, nil

	case MsgTransport:
		counter := binary.LittleEndian.Uint64(pkt[8:16])
		if counter >= RejectAfterMessages {
			return nil, fmt.Errorf("wg: transport counter %d >= RejectAfterMessages", counter)
		}
		tagStart := len(pkt) - 16
		return &Packet{
			Type:           MsgTransport,
			ReceiverIndex:  binary.LittleEndian.Uint32(pkt[4:8]),
			Counter:        counter,
			CiphertextBody: pkt[16:tagStart],
			Poly1305Tag:    pkt[tagStart:],
		}, nil

	default:
		return nil, fmt.Errorf("wg: unknown message type %d", msgType)
	}
}
