import hmac
import struct
from dataclasses import dataclass

HRR_RANDOM = bytes.fromhex(
    "cf21ad74e59a6111be1d8c021e65b891c2a211167abb8c5e079e09e2c8a8339c"
)
TLS13_CIPHER_SUITES = frozenset({0x1301, 0x1302, 0x1303, 0x1304, 0x1305})

EXT_COOKIE = 0x002C
EXT_SUPPORTED_VERSIONS = 0x002B
EXT_KEY_SHARE = 0x0033


class TLS13ServerHelloError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class ParsedServerHello13:
    is_hello_retry_request: bool
    server_random: bytes
    cipher_suite: int
    selected_group: int | None
    server_key_exchange: bytes | None
    hrr_cookie: bytes | None


def parse_tls13_server_hello(
    hs_msg: bytes | bytearray | memoryview,
    expected_client_session_id: bytes,
) -> ParsedServerHello13:
    mv = memoryview(hs_msg)
    if len(expected_client_session_id) > 32:
        raise TLS13ServerHelloError("expected_client_session_id > 32 bytes")
    if len(mv) < 4 + 38:
        raise TLS13ServerHelloError("truncated TLS 1.3 ServerHello handshake message")

    msg_type = mv[0]
    hs_len = (mv[1] << 16) | (mv[2] << 8) | mv[3]
    if msg_type != 0x02 or 4 + hs_len != len(mv):
        raise TLS13ServerHelloError("invalid ServerHello handshake header or length")

