    if legacy_ver != 0x0303:
        raise TLS13ServerHelloError(f"ServerHello legacy_version 0x{legacy_ver:04x} != 0x0303")

    srv_random = bytes(body[2:34])
    is_hrr = hmac.compare_digest(srv_random, HRR_RANDOM)

    sid_len = body[34]
    off = 35
    if sid_len > 32 or off + sid_len + 5 > len(body):
        raise TLS13ServerHelloError("truncated session_id_echo or fixed fields")
    sid_echo = bytes(body[off : off + sid_len])
    if len(sid_echo) != len(expected_client_session_id) or not hmac.compare_digest(
        sid_echo, expected_client_session_id
    ):
        raise TLS13ServerHelloError("legacy_session_id_echo mismatch")
    off += sid_len

    cipher_suite, comp_method, ext_block_len = struct.unpack_from(">HBH", body, off)
    off += 5
    if cipher_suite not in TLS13_CIPHER_SUITES:
        raise TLS13ServerHelloError(f"illegal TLS 1.3 cipher_suite 0x{cipher_suite:04x}")
    if comp_method != 0x00:
        raise TLS13ServerHelloError("TLS 1.3 legacy_compression_method must be 0x00")
    if ext_block_len < 6 or off + ext_block_len != len(body):
        raise TLS13ServerHelloError("ServerHello extensions length mismatch")

    seen_exts: set[int] = set()
    saw_tls13_ver = False
    selected_group: int | None = None
    server_kex: bytes | None = None
    hrr_cookie: bytes | None = None

    while off < len(body):
        if len(body) - off < 4:
            raise TLS13ServerHelloError("truncated ServerHello extension header")
        ext_type, ext_len = struct.unpack_from(">HH", body, off)
        off += 4
        if off + ext_len > len(body):
            raise TLS13ServerHelloError(f"extension 0x{ext_type:04x} overruns ServerHello")
        if ext_type in seen_exts:
            raise TLS13ServerHelloError(f"duplicate extension 0x{ext_type:04x}")
        seen_exts.add(ext_type)

        ext = body[off : off + ext_len]
        off += ext_len

        if ext_type == EXT_SUPPORTED_VERSIONS:
            if ext_len != 2 or struct.unpack_from(">H", ext, 0)[0] != 0x0304:
                raise TLS13ServerHelloError("ServerHello supported_versions must be exact 0x0304")
            saw_tls13_ver = True

        elif ext_type == EXT_KEY_SHARE:
            if is_hrr:
                if ext_len != 2:
                    raise TLS13ServerHelloError("HRR key_share must be 2-byte NamedGroup")
                (selected_group,) = struct.unpack_from(">H", ext, 0)
            else:
                if ext_len < 5:
                    raise TLS13ServerHelloError("ServerHello key_share entry too short")
                grp, kex_len = struct.unpack_from(">HH", ext, 0)
                if kex_len == 0 or 4 + kex_len != ext_len:
                    raise TLS13ServerHelloError("ServerHello KeyShareEntry length mismatch")
                selected_group = grp
                server_kex = bytes(ext[4:])

        elif ext_type == EXT_COOKIE:
            if not is_hrr:
                raise TLS13ServerHelloError("cookie extension forbidden in non-HRR ServerHello")
            if ext_len < 3:
                raise TLS13ServerHelloError("HRR cookie extension too short")
            (c_len,) = struct.unpack_from(">H", ext, 0)
            if c_len == 0 or 2 + c_len != ext_len:
                raise TLS13ServerHelloError("HRR cookie nested length mismatch")
            hrr_cookie = bytes(ext[2:])
        else:
            raise TLS13ServerHelloError(
                f"forbidden extension 0x{ext_type:04x} in ServerHello/HelloRetryRequest"
            )

    if not saw_tls13_ver:
        raise TLS13ServerHelloError("missing mandatory supported_versions (0x0304)")
    if is_hrr and selected_group is None and hrr_cookie is None:
        raise TLS13ServerHelloError("HelloRetryRequest made no state-changing modification")
    if not is_hrr and server_kex is None:
        raise TLS13ServerHelloError("ServerHello missing key_share entry")

    return ParsedServerHello13(
        is_hello_retry_request=is_hrr,
        server_random=srv_random,
        cipher_suite=cipher_suite,
        selected_group=selected_group,
        server_key_exchange=server_kex,
        hrr_cookie=hrr_cookie,
    )
