from __future__ import annotations

import base64
import json
import re
from typing import Any

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import encode_dss_signature

SECP256R1_ORDER = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
B64URL_RE = re.compile(r"^[A-Za-z0-9_-]+$")


class JWSVerifyError(ValueError):
    pass


def b64url_encode(raw: bytes) -> bytes:
    return base64.urlsafe_b64encode(raw).rstrip(b"=")


def b64url_decode_canonical(seg: str) -> bytes:
    if not seg or not B64URL_RE.fullmatch(seg) or (len(seg) % 4) == 1:
        raise JWSVerifyError("invalid unpadded Base64url segment")
    padded = seg + ("=" * ((4 - (len(seg) % 4)) % 4))
    raw = base64.urlsafe_b64decode(padded)
    if b64url_encode(raw).decode("ascii") != seg:
        raise JWSVerifyError("non-canonical Base64url trailing bits")
    return raw


def _no_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    obj: dict[str, Any] = {}
    for k, v in pairs:
        if k in obj:
            raise JWSVerifyError(f"duplicate JSON key {k!r} in JWS protected header")
        obj[k] = v
    return obj


def verify_jws_detached_es256(
    compact_jws: str,
    detached_payload: bytes,
    public_key: ec.EllipticCurvePublicKey,
) -> dict[str, Any]:
    if not isinstance(public_key.curve, ec.SECP256R1):
        raise JWSVerifyError("public_key must use secp256r1 (P-256)")

    parts = compact_jws.split(".")
    if len(parts) != 3 or parts[1] != "":
        raise JWSVerifyError("detached JWS must have format '<protected>..<signature>'")

    hdr_raw = b64url_decode_canonical(parts[0])
    sig_raw = b64url_decode_canonical(parts[2])
    if len(sig_raw) != 64:
        raise JWSVerifyError(f"ES256 JWS signature must be 64 bytes (R||S), got {len(sig_raw)}")

    try:
        header = json.loads(hdr_raw.decode("utf-8", errors="strict"), object_pairs_hook=_no_duplicate_keys)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise JWSVerifyError("malformed JWS protected header JSON") from exc

    if not isinstance(header, dict) or header.get("alg") != "ES256":
        raise JWSVerifyError("JWS protected header must pin 'alg' == 'ES256'")
    if "crit" in header:
        raise JWSVerifyError("unsupported critical extension in 'crit'")
    if header.get("b64", True) is not True:
        raise JWSVerifyError("unencoded b64=false requires explicit RFC 7797 profile")

    r = int.from_bytes(sig_raw[:32], "big")
    s = int.from_bytes(sig_raw[32:], "big")
    if not (1 <= r < SECP256R1_ORDER and 1 <= s < SECP256R1_ORDER):
        raise JWSVerifyError("ES256 signature scalar (r or s) out of range [1, n-1]")

    der_sig = encode_dss_signature(r, s)
    signing_input = parts[0].encode("ascii") + b"." + b64url_encode(detached_payload)

    try:
        public_key.verify(der_sig, signing_input, ec.ECDSA(hashes.SHA256()))
    except InvalidSignature as exc:
        raise JWSVerifyError("ES256 detached JWS signature verification failed") from exc

    return header
