func Extract(hashFn func() hash.Hash, salt, ikm []byte) []byte {
	hLen := hashFn().Size()
	if len(salt) == 0 {
		salt = make([]byte, hLen)
	}
	mac := hmac.New(hashFn, salt)
	_, _ = mac.Write(ikm)
	return mac.Sum(nil)
}

func Expand(hashFn func() hash.Hash, prk, info []byte, length int) ([]byte, error) {
	hLen := hashFn().Size()
	if len(prk) < hLen {
		return nil, fmt.Errorf("hkdf: PRK length %d < HashLen %d", len(prk), hLen)
	}
	if length < 0 || length > 255*hLen {
		return nil, fmt.Errorf("hkdf: requested length %d outside 0..%d", length, 255*hLen)
	}
	if length == 0 {
		return []byte{}, nil
	}

	blocks := (length + hLen - 1) / hLen
	out := make([]byte, 0, blocks*hLen)
	var prev []byte
	mac := hmac.New(hashFn, prk)

	for i := 1; i <= blocks; i++ {
		mac.Reset()
		_, _ = mac.Write(prev)
		_, _ = mac.Write(info)
		_, _ = mac.Write([]byte{byte(i)})
		prev = mac.Sum(prev[:0])
		out = append(out, prev...)
	}
	return out[:length], nil
}

func EncodeContextInfo(domain, purpose string, keyLen uint32) ([]byte, error) {
	if len(domain) == 0 || len(domain) > 0xFFFF {
		return nil, errors.New("hkdf: domain must be 1..65535 bytes")
	}
	if len(purpose) == 0 || len(purpose) > 0xFFFF {
		return nil, errors.New("hkdf: purpose must be 1..65535 bytes")
	}
	buf := make([]byte, 2+len(domain)+2+len(purpose)+4)
	off := 0
	binary.BigEndian.PutUint16(buf[off:off+2], uint16(len(domain)))
	off += 2
	off += copy(buf[off:], domain)
	binary.BigEndian.PutUint16(buf[off:off+2], uint16(len(purpose)))
	off += 2
	off += copy(buf[off:], purpose)
	binary.BigEndian.PutUint32(buf[off:off+4], keyLen)
	return buf, nil
}

func DeriveLabeledKey(hashFn func() hash.Hash, prk []byte, domain, purpose string, length int) ([]byte, error) {
	if length <= 0 || length > 0xFFFF {
		return nil, errors.New("hkdf: invalid derived key length")
	}
	info, err := EncodeContextInfo(domain, purpose, uint32(length))
	if err != nil {
