from dataclasses import dataclass

ALLOWED_SEVERITIES = frozenset(
    {*(str(i) for i in range(11)), "Unknown", "Low", "Medium", "High", "Very-High"}
)
KEY_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-")


class CEFParseError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class CEFRecord:
    syslog_prefix: str
    version: int
    device_vendor: str
    device_product: str
    device_version: str
    event_class_id: str
    name: str
    severity: str
