def _unescape_ext_value(raw: str) -> str:
    out: list[str] = []
    i = 0
    n = len(raw)
    while i < n:
        ch = raw[i]
        if ch == "\\" and i + 1 < n:
            nxt = raw[i + 1]
            if nxt == "\\":
                out.append("\\")
                i += 2
                continue
            if nxt == "=":
                out.append("=")
                i += 2
                continue
            if nxt == "n":
                out.append("\n")
                i += 2
                continue
            if nxt == "r":
                out.append("\r")
                i += 2
                continue
        out.append(ch)
        i += 1
    return "".join(out)


def _parse_extensions(ext_str: str) -> dict[str, str]:
    s = ext_str.lstrip(" ")
    if not s:
        return {}

    anchors: list[tuple[int, int]] = []
    i = 0
    n = len(s)
    while i < n:
        if i == 0 or s[i - 1] == " ":
            k_start = i
            while i < n and s[i] in KEY_CHARS:
                i += 1
            if i > k_start and i < n and s[i] == "=":
                anchors.append((k_start, i))
                i += 1
                continue
            if i == k_start:
                i += 1
        else:
            i += 2 if (s[i] == "\\" and i + 1 < n) else 1

    if not anchors or anchors[0][0] != 0:
        raise CEFParseError("CEF extension block does not begin with a valid key=value pair")

    result: dict[str, str] = {}
    for idx, (k_start, eq_pos) in enumerate(anchors):
        key = s[k_start:eq_pos]
        if key in result:
            raise CEFParseError(f"duplicate CEF extension key {key!r}")
