        if idx + 1 < len(anchors):
            v_end = anchors[idx + 1][0] - 1
            while v_end > v_start and s[v_end - 1] == " ":
                if v_end - 2 >= v_start and s[v_end - 2] == "\\":
                    break
                v_end -= 1
        else:
            v_end = n
        result[key] = _unescape_ext_value(s[v_start:v_end])

