def parse_cef_line(line: str) -> CEFRecord:
    if "\r" in line or "\n" in line or "\x00" in line:
        raise CEFParseError("raw CR, LF, or NUL byte forbidden inside CEF record")

    marker = line.find("CEF:")
    if marker < 0 or (marker > 0 and line[marker - 1] != " "):
        raise CEFParseError("missing valid 'CEF:' boundary")

    syslog_prefix = line[:marker].rstrip(" ")
    rest = line[marker + 4 :]

    header_fields: list[str] = []
    buf: list[str] = []
    i = 0
    n = len(rest)
    ext_offset = -1

    while i < n:
        ch = rest[i]
        if ch == "\\" and i + 1 < n and rest[i + 1] in ("|", "\\"):
            buf.append(rest[i + 1])
            i += 2
            continue
        if ch == "|":
            header_fields.append("".join(buf))
            buf.clear()
            if len(header_fields) == 7:
                ext_offset = i + 1
                break
            i += 1
            continue
        buf.append(ch)
        i += 1

    if len(header_fields) != 7 or ext_offset < 0:
        raise CEFParseError(f"expected 7 pipe-terminated CEF header fields, got {len(header_fields)}")

    ver_str = header_fields[0]
    if ver_str not in ("0", "1"):
        raise CEFParseError(f"unsupported CEF version {ver_str!r}")
    severity = header_fields[6]
    if severity not in ALLOWED_SEVERITIES:
        raise CEFParseError(f"invalid CEF severity {severity!r}")

    extensions = _parse_extensions(rest[ext_offset:])
    return CEFRecord(
        syslog_prefix=syslog_prefix,
        version=int(ver_str),
        device_vendor=header_fields[1],
        device_product=header_fields[2],
        device_version=header_fields[3],
        event_class_id=header_fields[4],
        name=header_fields[5],
        severity=severity,
        extensions=extensions,
    )
