	}
	switch ai {
	case 24:
		if len(buf) < 2 || buf[1] < 24 {
			return 0, 0, errors.New("cbor: non-canonical 1-byte bstr length")
		}
		return int(buf[1]), 2, nil
	case 25:
		if len(buf) < 3 {
			return 0, 0, errors.New("cbor: truncated 2-byte bstr length")
		}
		n := int(binary.BigEndian.Uint16(buf[1:3]))
		if n < 256 {
			return 0, 0, errors.New("cbor: non-canonical 2-byte bstr length")
		}
		return n, 3, nil
	default:
		return 0, 0, fmt.Errorf("cbor: unsupported or non-canonical bstr ai=%d", ai)
	}
}

func DecodeCanonicalFloatOrBignum(buf []byte) (*DecodedNumber, error) {
	if len(buf) == 0 {
		return nil, errors.New("cbor: empty input")
	}

	switch buf[0] {
	case 0xF9:
		if len(buf) != 3 {
			return nil, errors.New("cbor: float16 item must be exact 3 bytes")
		}
		h := binary.BigEndian.Uint16(buf[1:3])
		if (h&0x7C00) == 0x7C00 && (h&0x03FF) != 0 {
			if h != 0x7E00 {
				return nil, fmt.Errorf("cbor: non-canonical float16 NaN 0x%04x (must be 0x7e00)", h)
			}
			return &DecodedNumber{IsFloat: true, Float64: math.NaN()}, nil
		}
		return &DecodedNumber{IsFloat: true, Float64: float16ToFloat64(h)}, nil

	case 0xFA:
		if len(buf) != 5 {
			return nil, errors.New("cbor: float32 item must be exact 5 bytes")
		}
		u32 := binary.BigEndian.Uint32(buf[1:5])
		f := float64(math.Float32frombits(u32))
		if math.IsNaN(f) {
			return nil, errors.New("cbor: NaN must use canonical float16 0xf97e00, not float32")
		}
		if fitsLosslesslyInFloat16(f) {
			return nil, fmt.Errorf("cbor: float32 %g fits losslessly in float16", f)
		}
		return &DecodedNumber{IsFloat: true, Float64: f}, nil

	case 0xFB:
		if len(buf) != 9 {
			return nil, errors.New("cbor: float64 item must be exact 9 bytes")
		}
		u64 := binary.BigEndian.Uint64(buf[1:9])
		f := math.Float64frombits(u64)
		if math.IsNaN(f) {
			return nil, errors.New("cbor: NaN must use canonical float16 0xf97e00, not float64")
		}
		if fitsLosslesslyInFloat32(f) {
			return nil, fmt.Errorf("cbor: float64 %g fits losslessly in narrower float width", f)
		}
		return &DecodedNumber{IsFloat: true, Float64: f}, nil

	case 0xC2, 0xC3:
		bLen, hdrLen, err := readCanonicalBstrLen(buf[1:])
		if err != nil {
			return nil, err
		}
		if 1+hdrLen+bLen != len(buf) {
			return nil, errors.New("cbor: bignum byte string length mismatch")
		}
		payload := buf[1+hdrLen:]
		if len(payload) == 0 || payload[0] == 0x00 {
			return nil, errors.New("cbor: bignum has empty or leading-zero byte string")
		}
		if len(payload) <= 8 {
			return nil, errors.New("cbor: integer <= 64 bits must use major type 0/1, not Tag 2/3")
		}
		mag := new(big.Int).SetBytes(payload)
		if buf[0] == 0xC3 {
			mag.Add(mag, big.NewInt(1))
			mag.Neg(mag)
		}
		return &DecodedNumber{IsFloat: false, BigInt: mag}, nil

	default:
		return nil, fmt.Errorf("cbor: unsupported head byte 0x%02x", buf[0])
	}
}
