export interface StunAuthenticatedMessage {
  messageType: number;
  transactionId: Uint8Array;
  xorPeerAddress?: { family: "IPv4" | "IPv6"; address: string; port: number };
  errorCode?: { code: number; reason: string };
  messageIntegrityVerified: boolean;
  fingerprintVerified: boolean;
}

function decodeXorAddress(
  view: DataView,
  buf: Uint8Array,
  valOff: number,
  valLen: number,
): { family: "IPv4" | "IPv6"; address: string; port: number } {
  if (valLen < 4 || view.getUint8(valOff) !== 0x00) {
    throw new Error("Malformed XOR-PEER-ADDRESS header");
  }
  const fam = view.getUint8(valOff + 1);
  const port = view.getUint16(valOff + 2, false) ^ 0x2112;

  if (fam === 0x01) {
    if (valLen !== 8) throw new Error("IPv4 XOR-PEER-ADDRESS must be 8 bytes");
    const ipWord = (view.getUint32(valOff + 4, false) ^ STUN_COOKIE) >>> 0;
    const address = `${(ipWord >>> 24) & 0xff}.${(ipWord >>> 16) & 0xff}.${(ipWord >>> 8) & 0xff}.${ipWord & 0xff}`;
    return { family: "IPv4", address, port };
  }
  if (fam === 0x02) {
    if (valLen !== 20) throw new Error("IPv6 XOR-PEER-ADDRESS must be 20 bytes");
    const groups: string[] = [];
    for (let i = 0; i < 16; i += 2) {
      const maskHi = buf[4 + i]!;
      const maskLo = buf[4 + i + 1]!;
      const word = ((buf[valOff + 4 + i]! ^ maskHi) << 8) | (buf[valOff + 4 + i + 1]! ^ maskLo);
      groups.push(word.toString(16));
    }
    return { family: "IPv6", address: groups.join(":"), port };
  }
  throw new Error(`Unsupported XOR address family 0x${fam.toString(16)}`);
}

function decodeErrorCode(
  view: DataView,
  buf: Uint8Array,
  valOff: number,
  valLen: number,
): { code: number; reason: string } {
  if (valLen < 4) {
    throw new Error("STUN ERROR-CODE attribute < 4 bytes");
  }
  const topWord = view.getUint32(valOff, false);
  if ((topWord >>> 11) !== 0) {
    throw new Error("Non-zero reserved bits in STUN ERROR-CODE");
  }
  const cls = (topWord >>> 8) & 0x07;
  const num = topWord & 0xff;
  if (cls < 3 || cls > 6 || num > 99) {
    throw new Error(`Out-of-range STUN ERROR-CODE class=${cls}, number=${num}`);
  }
  const reason = utf8Strict.decode(buf.subarray(valOff + 4, valOff + valLen));
  return { code: cls * 100 + num, reason };
}

export async function parseAndVerifyStunTurnMessage(
  pkt: Uint8Array,
  hmacKeyBytes: Uint8Array,
): Promise<StunAuthenticatedMessage> {
  if (pkt.byteLength < 20) {
    throw new Error("Truncated 20-byte STUN header");
  }
  const view = new DataView(pkt.buffer, pkt.byteOffset, pkt.byteLength);
  const messageType = view.getUint16(0, false);
  const msgLen = view.getUint16(2, false);
  const cookie = view.getUint32(4, false);

  if ((messageType & 0xc000) !== 0 || cookie !== STUN_COOKIE) {
    throw new Error("Invalid STUN header bits or magic cookie");
  }
  if (msgLen % 4 !== 0 || 20 + msgLen !== pkt.byteLength) {
    throw new Error("STUN Message Length misalignment");
  }

  let off = 20;
  let sawMI = false;
  let miVerified = false;
  let fpVerified = false;
  let xorPeerAddress: { family: "IPv4" | "IPv6"; address: string; port: number } | undefined;
  let errorCode: { code: number; reason: string } | undefined;

  while (off < pkt.byteLength) {
    if (pkt.byteLength - off < 4) {
      throw new Error("Truncated STUN attribute header");
    }
    const attrType = view.getUint16(off, false);
    const attrLen = view.getUint16(off + 2, false);
    const valOff = off + 4;
    const padded = (attrLen + 3) & ~3;
    const nextOff = valOff + padded;
    if (nextOff > pkt.byteLength) {
      throw new Error(`Attribute 0x${attrType.toString(16)} overruns packet`);
    }

    if (sawMI && attrType !== 0x8028) {
      throw new Error("Illegal attribute following STUN MESSAGE-INTEGRITY");
    }

    if (attrType === 0x0012) {
      xorPeerAddress = decodeXorAddress(view, pkt, valOff, attrLen);
    } else if (attrType === 0x0009) {
      errorCode = decodeErrorCode(view, pkt, valOff, attrLen);
    } else if (attrType === 0x0008) {
      if (attrLen !== 20) {
        throw new Error("STUN MESSAGE-INTEGRITY must be 20 bytes");
      }
      const adjusted = new Uint8Array(off);
      adjusted.set(pkt.subarray(0, off));
      const adjView = new DataView(adjusted.buffer);
      adjView.setUint16(2, off + 24 - 20, false);

      const cryptoKey = await crypto.subtle.importKey(
        "raw",
        hmacKeyBytes,
        { name: "HMAC", hash: "SHA-1" },
        false,
        ["verify"],
      );
      const macSlice = pkt.subarray(valOff, valOff + 20);
      const ok = await crypto.subtle.verify("HMAC", cryptoKey, macSlice, adjusted);
      if (!ok) {
        throw new Error("STUN MESSAGE-INTEGRITY HMAC-SHA1 verification failed");
      }
      sawMI = true;
      miVerified = true;
    } else if (attrType === 0x8028) {
      if (attrLen !== 4 || nextOff !== pkt.byteLength) {
        throw new Error("Malformed or non-final STUN FINGERPRINT");
      }
      const wantFp = (crc32(pkt, off) ^ 0x5354554e) >>> 0;
      const gotFp = view.getUint32(valOff, false);
      if (gotFp !== wantFp) {
        throw new Error("STUN FINGERPRINT CRC-32 mismatch");
      }
      fpVerified = true;
    }

    off = nextOff;
  }

  if (!miVerified) {
    throw new Error("Missing required STUN MESSAGE-INTEGRITY attribute");
  }

  return {
    messageType,
    transactionId: pkt.subarray(8, 20),
    ...(xorPeerAddress ? { xorPeerAddress } : {}),
    ...(errorCode ? { errorCode } : {}),
    messageIntegrityVerified: miVerified,
    fingerprintVerified: fpVerified,
  };
}
