const (
	tai64EpochBias uint64 = 0x4000000000000000
	tai64MaxValid  uint64 = 0x5000000000000000
	taiMinusUnix   int64  = 10 // TAI base offset before leap seconds
)

var labelMAC1 = []byte("mac1----")

type TAI64N struct {
	Raw         [12]byte
	TAISeconds  uint64
	Nanoseconds uint32
}

func DeriveMAC1Key(responderStaticPub [32]byte) [32]byte {
	h, _ := blake2s.New256(nil)
	_, _ = h.Write(labelMAC1)
	_, _ = h.Write(responderStaticPub[:])
	var key [32]byte
	copy(key[:], h.Sum(nil))
	return key
}

func VerifyInitiationMAC1(pkt []byte, responderStaticPub [32]byte) error {
