		return errors.New("wg: invalid 148-byte Initiation packet header")
	}
	key := DeriveMAC1Key(responderStaticPub)
	mac, err := blake2s.New128(key[:])
	if err != nil {
		return err
	}
	_, _ = mac.Write(pkt[0:116])
	want := mac.Sum(nil)
	if subtle.ConstantTimeCompare(want, pkt[116:132]) != 1 {
		return errors.New("wg: Initiation mac1 verification failed")
	}
	return nil
