func ParseAndCheckTAI64N(raw []byte, lastAccepted *[12]byte) (TAI64N, error) {
	var out TAI64N
	if len(raw) != 12 {
		return out, fmt.Errorf("wg: TAI64N must be 12 bytes, got %d", len(raw))
	}

	sec := binary.BigEndian.Uint64(raw[0:8])
	nsec := binary.BigEndian.Uint32(raw[8:12])
	if sec < tai64EpochBias || sec >= tai64MaxValid {
		return out, fmt.Errorf("wg: TAI64N seconds 0x%016x outside canonical epoch range", sec)
	}
	if nsec > 999_999_999 {
		return out, fmt.Errorf("wg: TAI64N nanoseconds %d > 999999999", nsec)
	}

	copy(out.Raw[:], raw)
	out.TAISeconds = sec
	out.Nanoseconds = nsec

	if lastAccepted != nil {
		if bytes.Compare(out.Raw[:], lastAccepted[:]) <= 0 {
			return out, errors.New("wg: replayed or non-monotonic TAI64N timestamp rejected")
		}
	}
	return out, nil
}

func (t TAI64N) ApproxUTC(leapSeconds int64) time.Time {
	unixSec := int64(t.TAISeconds-tai64EpochBias) - (taiMinusUnix + leapSeconds)
	return time.Unix(unixSec, int64(t.Nanoseconds)).UTC()
}
