const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const REV = new Int8Array(128).fill(-1);
for (let i = 0; i < CHARSET.length; i++) {
  REV[CHARSET.charCodeAt(i)] = i;
}

const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3] as const;
const CONST_BECH32 = 1;
const CONST_BECH32M = 0x2bc830a3;
const ALLOWED_HRPS = new Set(["bc", "tb", "bcrt"]);

export interface DecodedSegwitAddress {
  hrp: "bc" | "tb" | "bcrt";
  witnessVersion: number;
  encoding: "bech32" | "bech32m";
  witnessProgram: Uint8Array;
  programView: DataView;
}

function polymod(values: readonly number[]): number {
  let chk = 1;
  for (const v of values) {
    const top = chk >>> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if (((top >>> i) & 1) !== 0) {
        chk ^= GEN[i]!;
      }
    }
  }
  return chk;
}

function hrpExpand(hrp: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < hrp.length; i++) out.push(hrp.charCodeAt(i) >>> 5);
  out.push(0);
  for (let i = 0; i < hrp.length; i++) out.push(hrp.charCodeAt(i) & 31);
  return out;
}

function unpack5To8(words: readonly number[]): Uint8Array {
  let acc = 0;
  let bits = 0;
  const bytes: number[] = [];

  for (const w of words) {
    acc = (acc << 5) | w;
    bits += 5;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((acc >>> bits) & 0xff);
    }
  }
  if (bits >= 5 || ((acc << (8 - bits)) & 0xff) !== 0) {
    throw new Error("Invalid non-zero or >=5 trailing padding bits in witness program");
  }
  return new Uint8Array(bytes);
}

export function parseSegwitAddress(addr: string): DecodedSegwitAddress {
  if (addr.length < 14 || addr.length > 90) {
    throw new Error(`SegWit address length ${addr.length} outside [14, 90]`);
  }
  const hasLower = /[a-z]/.test(addr);
  const hasUpper = /[A-Z]/.test(addr);
  if (hasLower && hasUpper) {
    throw new Error("Mixed-case Bech32/Bech32m address is forbidden");
  }

  const norm = addr.toLowerCase();
  const sep = norm.lastIndexOf("1");
  if (sep < 1 || sep + 7 > norm.length) {
    throw new Error("Invalid '1' separator position in SegWit address");
  }

  const hrp = norm.slice(0, sep);
  if (!ALLOWED_HRPS.has(hrp)) {
    throw new Error(`Unsupported SegWit HRP '${hrp}'`);
  }

  const dataWords: number[] = [];
  for (let i = sep + 1; i < norm.length; i++) {
    const code = norm.charCodeAt(i);
    const val = code < 128 ? REV[code]! : -1;
    if (val < 0) {
      throw new Error(`Invalid Base32 character at index ${i}`);
    }
    dataWords.push(val);
  }

  if (dataWords.length < 7) {
    throw new Error("Missing witness version or checksum symbols");
  }

  const witnessVersion = dataWords[0]!;
  if (witnessVersion > 16) {
    throw new Error(`Invalid SegWit witness version ${witnessVersion} (> 16)`);
  }

  const rem = polymod([...hrpExpand(hrp), ...dataWords]);
  if (witnessVersion === 0 && rem !== CONST_BECH32) {
    throw new Error("Witness v0 address must carry valid BIP-173 Bech32 checksum");
  }
  if (witnessVersion >= 1 && rem !== CONST_BECH32M) {
    throw new Error(`Witness v${witnessVersion} address must carry valid BIP-350 Bech32m checksum`);
  }

  const witnessProgram = unpack5To8(dataWords.slice(1, -6));
  if (witnessProgram.byteLength < 2 || witnessProgram.byteLength > 40) {
    throw new Error(`Witness program length ${witnessProgram.byteLength} outside [2, 40]`);
  }
  if (
    witnessVersion === 0 &&
    witnessProgram.byteLength !== 20 &&
    witnessProgram.byteLength !== 32
  ) {
    throw new Error(`Witness v0 program must be 20 or 32 bytes, got ${witnessProgram.byteLength}`);
  }

  return {
    hrp: hrp as "bc" | "tb" | "bcrt",
    witnessVersion,
    encoding: witnessVersion === 0 ? "bech32" : "bech32m",
    witnessProgram,
    programView: new DataView(
      witnessProgram.buffer,
      witnessProgram.byteOffset,
      witnessProgram.byteLength,
    ),
  };
}
