import struct
from dataclasses import dataclass

ALLOWED_SEMANTICS: dict[int, str] = {
    0x00: "noneOf",
    0x01: "exactlyOneOf",
    0x02: "oneOrMoreOf",
    0x03: "allOf",
    0x04: "ordered",
    0xFF: "undefined",
