class IpfixBasicListError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class DecodedBasicList:
    semantic_code: int
    semantic_name: str
    element_ie_id: int
    enterprise_number: int | None
    element_length_spec: int
    elements: tuple[bytes, ...]


def read_ipfix_varlen_header(mv: memoryview, off: int, end: int) -> tuple[int, int]:
    if off >= end:
        raise IpfixBasicListError(f"truncated IPFIX varlen prefix at offset {off}")
    b0 = mv[off]
    if b0 < 255:
        return b0, off + 1
    if off + 3 > end:
        raise IpfixBasicListError("truncated 3-byte 0xFF IPFIX varlen header")
    (length,) = struct.unpack_from(">H", mv, off + 1)
    return length, off + 3


def decode_ipfix_basic_list(
    buf: bytes | bytearray | memoryview,
    offset: int = 0,
) -> tuple[DecodedBasicList, int]:
    mv = memoryview(buf)
    list_len, body_start = read_ipfix_varlen_header(mv, offset, len(mv))
    list_end = body_start + list_len
    if list_end > len(mv):
        raise IpfixBasicListError("basicList length overruns buffer")
    if list_len < 5:
        raise IpfixBasicListError(f"basicList body shorter than 5-byte minimum ({list_len} B)")

    semantic, raw_field_id, elem_len = struct.unpack_from(">BHH", mv, body_start)
    if semantic not in ALLOWED_SEMANTICS:
        raise IpfixBasicListError(f"invalid RFC 6313 basicList semantic 0x{semantic:02x}")
    if elem_len == 0:
        raise IpfixBasicListError("zero element_length forbidden in IPFIX basicList")

    cur = body_start + 5
    ie_id = raw_field_id & 0x7FFF
    pen: int | None = None
    if (raw_field_id & 0x8000) != 0:
        if cur + 4 > list_end:
            raise IpfixBasicListError("truncated enterprise_number in basicList header")
        (pen,) = struct.unpack_from(">I", mv, cur)
        cur += 4

    elements: list[bytes] = []
    if elem_len == 0xFFFF:
        while cur < list_end:
            item_len, val_start = read_ipfix_varlen_header(mv, cur, list_end)
            val_end = val_start + item_len
            if val_end > list_end:
                raise IpfixBasicListError("variable-length element overruns basicList")
            elements.append(bytes(mv[val_start:val_end]))
            cur = val_end
    else:
        rem = list_end - cur
        if rem % elem_len != 0:
            raise IpfixBasicListError(
                f"remaining {rem} bytes in basicList not divisible by fixed element_length {elem_len}"
            )
        while cur < list_end:
            elements.append(bytes(mv[cur : cur + elem_len]))
            cur += elem_len

    return (
        DecodedBasicList(
            semantic_code=semantic,
            semantic_name=ALLOWED_SEMANTICS[semantic],
            element_ie_id=ie_id,
            enterprise_number=pen,
            element_length_spec=elem_len,
            elements=tuple(elements),
        ),
        list_end,
    )
