```ts
const asciiStrict = new TextDecoder("utf-8", { fatal: true });
const MECH_RE = /^[A-Z0-9_-]{1,20}$/;

export type PgFrontendSASLMessage =
  | {
      kind: "SASLInitialResponse";
      mechanism: string;
      initialResponse: string | null;
    }
  | {
      kind: "SASLResponse";
      response: string;
    };

function decodePrintableScram(slice: Uint8Array, allowEmpty: boolean): string {
  if (!allowEmpty && slice.byteLength === 0) {
    throw new Error("PostgreSQL SCRAM response payload cannot be empty");
  }
  for (let i = 0; i < slice.byteLength; i++) {
    const b = slice[i]!;
    if (b < 0x20 || b > 0x7e) {
      throw new Error(`Non-printable or NUL byte 0x${b.toString(16)} in SCRAM payload`);
    }
  }
  return asciiStrict.decode(slice);
}

export function parsePgFrontendSASL(
  buf: Uint8Array,
  expectInitial: boolean,
): PgFrontendSASLMessage {
  if (buf.byteLength < 5) {
    throw new Error(`Truncated PostgreSQL 'p' frame (${buf.byteLength} < 5 bytes)`);
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  if (view.getUint8(0) !== 0x70) {
    throw new Error(`Expected PostgreSQL 'p' (0x70) tag, got 0x${view.getUint8(0).toString(16)}`);
  }

  const frameLen = view.getInt32(1, false);
  if (frameLen < 4 || frameLen > 131_072 || 1 + frameLen !== buf.byteLength) {
    throw new Error(`PostgreSQL 'p' length ${frameLen} mismatches buffer ${buf.byteLength}`);
  }

  if (!expectInitial) {
    const response = decodePrintableScram(buf.subarray(5), false);
    return { kind: "SASLResponse", response };
  }

  let nulPos = -1;
  for (let i = 5; i < buf.byteLength; i++) {
    if (buf[i] === 0x00) {
      nulPos = i;
      break;
    }
  }
  if (nulPos < 0 || nulPos + 5 > buf.byteLength) {
    throw new Error("SASLInitialResponse missing NUL-terminated mechanism or int32 resp_len");
  }

  const mechanism = asciiStrict.decode(buf.subarray(5, nulPos));
  if (!MECH_RE.test(mechanism)) {
    throw new Error(`Invalid RFC 4422 SASL mechanism name '${mechanism}'`);
  }

  const respLenOff = nulPos + 1;
  const respLen = view.getInt32(respLenOff, false);
  const payloadOff = respLenOff + 4;

  if (respLen === -1) {
    if (payloadOff !== buf.byteLength) {
      throw new Error("SASLInitialResponse with resp_len=-1 has unexpected trailing bytes");
    }
    return { kind: "SASLInitialResponse", mechanism, initialResponse: null };
  }

  if (respLen < 0 || respLen > 65_536) {
    throw new Error(`Invalid SASLInitialResponse resp_len ${respLen}`);
  }
  if (payloadOff + respLen !== buf.byteLength) {
    throw new Error(
      `SASLInitialResponse resp_len ${respLen} != remaining ${buf.byteLength - payloadOff} bytes`,
    );
  }

  const initialResponse = decodePrintableScram(buf.subarray(payloadOff), true);
  return { kind: "SASLInitialResponse", mechanism, initialResponse };
}
