from __future__ import annotations

import struct
from dataclasses import dataclass


class EMVFCIError(ValueError):
    pass


class APDUStatusError(EMVFCIError):
    def __init__(self, sw: int) -> None:
        super().__init__(f"non-9000 APDU status word 0x{sw:04X}")
        self.sw = sw


@dataclass(frozen=True, slots=True)
class SelectFCIResponse:
    df_name_aid: bytes
    application_label: str | None
    priority_rank: int | None
    requires_cardholder_confirmation: bool | None
    issuer_discretionary_tags: dict[str, bytes]
    other_proprietary_tags: dict[str, bytes]


def _read_tag(mv: memoryview, off: int, end: int) -> tuple[str, bool, int]:
    if off >= end:
        raise EMVFCIError("truncated BER-TLV tag")
    b0 = mv[off]
    constructed = (b0 & 0x20) != 0
    if (b0 & 0x1F) != 0x1F:
        return f"{b0:02X}", constructed, off + 1

    cur = off + 1
    tag_num = 0
    count = 0
    while True:
        if cur >= end or count >= 2:
            raise EMVFCIError("truncated or >3-byte EMV BER-TLV tag")
        b = mv[cur]
        cur += 1
        count += 1
        if count == 1 and (b & 0x7F) == 0:
            raise EMVFCIError("non-canonical leading zero in multi-byte EMV tag")
        tag_num = (tag_num << 7) | (b & 0x7F)
        if (b & 0x80) == 0:
            break
    if tag_num < 31:
        raise EMVFCIError("non-canonical multi-byte EMV tag < 31")
    return bytes(mv[off:cur]).hex().upper(), constructed, cur


def _read_len(mv: memoryview, off: int, end: int) -> tuple[int, int]:
    if off >= end:
        raise EMVFCIError("truncated BER-TLV length")
    b0 = mv[off]
    if b0 < 0x80:
        return b0, off + 1
    if b0 == 0x81:
        if off + 2 > end or mv[off + 1] < 128:
            raise EMVFCIError("invalid or non-canonical 0x81 BER length")
        return mv[off + 1], off + 2
    if b0 == 0x82:
        if off + 3 > end:
            raise EMVFCIError("truncated 0x82 BER length")
        (val,) = struct.unpack_from(">H", mv, off + 1)
        if val < 256:
            raise EMVFCIError("non-canonical 0x82 BER length < 256")
        return val, off + 3
    raise EMVFCIError(f"unsupported BER length byte 0x{b0:02X}")


def _parse_flat_children(mv: memoryview, start: int, end: int) -> dict[str, tuple[bool, memoryview]]:
    children: dict[str, tuple[bool, memoryview]] = {}
    cur = start
    while cur < end:
        tag, constructed, after_tag = _read_tag(mv, cur, end)
        vlen, val_start = _read_len(mv, after_tag, end)
        val_end = val_start + vlen
        if val_end > end:
            raise EMVFCIError(f"tag {tag} overruns parent template")
        if tag in children:
            raise EMVFCIError(f"duplicate tag {tag} in FCI template")
        children[tag] = (constructed, mv[val_start:val_end])
        cur = val_end
    return children


def parse_emv_select_fci_apdu(apdu_resp: bytes | bytearray | memoryview) -> SelectFCIResponse:
    mv = memoryview(apdu_resp)
    if len(mv) < 4:
        raise EMVFCIError("APDU response shorter than FCI + SW1SW2")

    (sw,) = struct.unpack_from(">H", mv, len(mv) - 2)
    if sw != 0x9000:
        raise APDUStatusError(sw)

    fci_mv = mv[:-2]
    root_tag, root_cons, after_tag = _read_tag(fci_mv, 0, len(fci_mv))
    if root_tag != "6F" or not root_cons:
        raise EMVFCIError(f"expected constructed root FCI tag 6F, got {root_tag}")
    root_len, root_val_start = _read_len(fci_mv, after_tag, len(fci_mv))
    if root_val_start + root_len != len(fci_mv):
        raise EMVFCIError("root 6F length does not span exact APDU body")

    top = _parse_flat_children(fci_mv, root_val_start, len(fci_mv))
    if "84" not in top or "A5" not in top:
        raise EMVFCIError("6F FCI template missing mandatory tag 84 (DF Name) or A5")

    aid_cons, aid_mv = top["84"]
    if aid_cons or not (5 <= len(aid_mv) <= 16):
        raise EMVFCIError("tag 84 (DF Name) must be primitive and 5..16 bytes")

    a5_cons, a5_mv = top["A5"]
    if not a5_cons:
        raise EMVFCIError("tag A5 (FCI Proprietary Template) must be constructed")

    prop = _parse_flat_children(a5_mv, 0, len(a5_mv))
    app_label: str | None = None
    prio_rank: int | None = None
    req_confirm: bool | None = None
    discretionary: dict[str, bytes] = {}
    others: dict[str, bytes] = {}

    for ptag, (pcons, pval) in prop.items():
        if ptag == "50":
            if pcons or not (1 <= len(pval) <= 16) or any(b < 0x20 or b > 0x7E for b in pval):
                raise EMVFCIError("invalid tag 50 Application Label")
