            others[ptag] = bytes(pval)

    return SelectFCIResponse(
        df_name_aid=bytes(aid_mv),
        application_label=app_label,
        priority_rank=prio_rank,
        requires_cardholder_confirmation=req_confirm,
        issuer_discretionary_tags=discretionary,
        other_proprietary_tags=others,
    )
