```ts
const utf8Fatal = new TextDecoder("utf-8", { fatal: true });
const MIN_VARINT = [0, 0, 128, 16_384, 2_097_152] as const;

export interface SubscriptionOptions {
  qos: 0 | 1 | 2;
  noLocal: boolean;
  retainAsPublished: boolean;
  retainHandling: 0 | 1 | 2;
}

export type ParsedMqttSubPacket =
  | {
      kind: "SUBSCRIBE";
      packetId: number;
      subscriptionId?: number;
      userProperties: Array<[string, string]>;
      subscriptions: Array<{ topicFilter: string; options: SubscriptionOptions }>;
    }
  | {
      kind: "UNSUBSCRIBE";
      packetId: number;
      userProperties: Array<[string, string]>;
      topicFilters: string[];
    };

function readCanonicalVarint(
  view: DataView,
  off: number,
  end: number,
): { value: number; nextOff: number } {
  let val = 0;
  let mul = 1;
  for (let i = 0; i < 4; i++) {
    const pos = off + i;
    if (pos >= end) {
      throw new Error("Truncated MQTT v5 Variable Byte Integer");
    }
    const b = view.getUint8(pos);
    val += (b & 0x7f) * mul;
    if ((b & 0x80) === 0) {
      const width = i + 1;
      if (val < MIN_VARINT[width]!) {
        throw new Error("Non-canonical overlong MQTT v5 varint");
      }
      return { value: val, nextOff: pos + 1 };
    }
    mul *= 128;
  }
  throw new Error("MQTT v5 varint exceeds 4 bytes");
}

function readMqttUtf8(
  view: DataView,
  buf: Uint8Array,
  off: number,
  end: number,
  requireNonEmpty: boolean,
): { text: string; nextOff: number } {
  if (off + 2 > end) {
    throw new Error("Truncated MQTT UTF-8 string length");
  }
  const slen = view.getUint16(off, false);
  if (requireNonEmpty && slen === 0) {
    throw new Error("Empty Topic Filter forbidden in SUBSCRIBE/UNSUBSCRIBE");
  }
  const strEnd = off + 2 + slen;
  if (strEnd > end) {
    throw new Error("Truncated MQTT UTF-8 string payload");
  }
  const raw = buf.subarray(off + 2, strEnd);
  for (let i = 0; i < raw.byteLength; i++) {
    if (raw[i] === 0x00) {
      throw new Error("U+0000 NUL forbidden in MQTT UTF-8 string");
    }
  }
  return { text: utf8Fatal.decode(raw), nextOff: strEnd };
}

export function parseMqttV5SubOrUnsub(buf: Uint8Array): ParsedMqttSubPacket {
  if (buf.byteLength < 5) {
    throw new Error("MQTT SUBSCRIBE/UNSUBSCRIBE packet too short");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const b0 = view.getUint8(0);
  if ((b0 & 0x0f) !== 0x02 || (b0 !== 0x82 && b0 !== 0xa2)) {
    throw new Error(`Malformed MQTT fixed header 0x${b0.toString(16)} (flags must be 0010b)`);
  }
  const isSubscribe = b0 === 0x82;

  const rem = readCanonicalVarint(view, 1, buf.byteLength);
  if (rem.nextOff + rem.value !== buf.byteLength) {
    throw new Error("MQTT Remaining Length mismatches buffer length");
  }

  let off = rem.nextOff;
  if (off + 2 > buf.byteLength) {
    throw new Error("Missing 2-byte Packet Identifier");
  }
  const packetId = view.getUint16(off, false);
  if (packetId === 0) {
    throw new Error("Packet Identifier 0 is forbidden");
  }
  off += 2;

  const propLen = readCanonicalVarint(view, off, buf.byteLength);
  off = propLen.nextOff;
  const propEnd = off + propLen.value;
  if (propEnd > buf.byteLength) {
    throw new Error("MQTT Properties block overruns packet");
  }

  let subscriptionId: number | undefined;
  const userProperties: Array<[string, string]> = [];

  while (off < propEnd) {
    const propId = view.getUint8(off++);
    if (propId === 0x0b) {
      if (!isSubscribe) {
        throw new Error("Protocol Error: Subscription Identifier (0x0B) forbidden in UNSUBSCRIBE");
      }
      if (subscriptionId !== undefined) {
        throw new Error("Protocol Error: duplicate Subscription Identifier in SUBSCRIBE");
      }
      const subVar = readCanonicalVarint(view, off, propEnd);
      if (subVar.value === 0) {
        throw new Error("Protocol Error: Subscription Identifier cannot be 0");
      }
      subscriptionId = subVar.value;
      off = subVar.nextOff;
    } else if (propId === 0x26) {
      const k = readMqttUtf8(view, buf, off, propEnd, false);
      const v = readMqttUtf8(view, buf, k.nextOff, propEnd, false);
      userProperties.push([k.text, v.text]);
      off = v.nextOff;
    } else {
      throw new Error(`Protocol Error: illegal property 0x${propId.toString(16)}`);
    }
  }

  if (off >= buf.byteLength) {
    throw new Error("Protocol Error: SUBSCRIBE/UNSUBSCRIBE payload must contain >= 1 Topic Filter");
  }

  if (!isSubscribe) {
    const topicFilters: string[] = [];
    while (off < buf.byteLength) {
      const tf = readMqttUtf8(view, buf, off, buf.byteLength, true);
      topicFilters.push(tf.text);
      off = tf.nextOff;
    }
    return { kind: "UNSUBSCRIBE", packetId, userProperties, topicFilters };
  }

  const subscriptions: Array<{ topicFilter: string; options: SubscriptionOptions }> = [];
  while (off < buf.byteLength) {
    const tf = readMqttUtf8(view, buf, off, buf.byteLength, true);
    off = tf.nextOff;
    if (off >= buf.byteLength) {
      throw new Error("Truncated Subscription Options byte in SUBSCRIBE");
    }
    const optByte = view.getUint8(off++);
    if ((optByte & 0xc0) !== 0) {
      throw new Error("Malformed Packet: non-zero reserved bits 6..7 in Subscription Options");
    }
    const qos = optByte & 0x03;
    const retainHandling = (optByte >>> 4) & 0x03;
    if (qos === 3 || retainHandling === 3) {
      throw new Error(`Malformed Subscription Options (qos=${qos}, retainHandling=${retainHandling})`);
    }
    subscriptions.push({
      topicFilter: tf.text,
      options: {
        qos: qos as 0 | 1 | 2,
        noLocal: ((optByte >>> 2) & 1) === 1,
        retainAsPublished: ((optByte >>> 3) & 1) === 1,
        retainHandling: retainHandling as 0 | 1 | 2,
      },
    });
  }

  return {
    kind: "SUBSCRIBE",
    packetId,
    ...(subscriptionId !== undefined ? { subscriptionId } : {}),
    userProperties,
    subscriptions,
  };
}
