        raise BGPOpenCapError("invalid BGP Identifier IPv4")
    bgp_id = ".".join(str(b) for b in id_bytes)

    opt_len = mv[28]
    if 29 + opt_len != msg_len:
        raise BGPOpenCapError(f"Opt Parm Len {opt_len} != {msg_len - 29}")

    role_code: int | None = None
    ext_nhs: list[ExtendedNextHopTuple] = []
    fqdn: tuple[str, str] | None = None

    off = 29
    while off < msg_len:
        if msg_len - off < 2:
            raise BGPOpenCapError("truncated Optional Parameter TLV")
        p_type, p_len = mv[off], mv[off + 1]
        off += 2
        if off + p_len > msg_len or p_type != 2 or p_len == 0:
            raise BGPOpenCapError(f"invalid Optional Parameter type={p_type} len={p_len}")

        c_off = off
        c_end = off + p_len
        while c_off < c_end:
            if c_end - c_off < 2:
                raise BGPOpenCapError("truncated Capability TLV header")
            cap_code, cap_len = mv[c_off], mv[c_off + 1]
            c_off += 2
            if c_off + cap_len > c_end:
                raise BGPOpenCapError(f"Capability {cap_code} overruns parameter")
