            c_off += cap_len

            if cap_code == 5:
                if cap_len < 6 or (cap_len % 6) != 0:
                    raise BGPOpenCapError(f"RFC 8950 Cap 5 invalid length {cap_len}")
                for t_off in range(0, cap_len, 6):
                    n_afi, n_safi_w, nh_afi = struct.unpack_from(">HHH", cap_slice, t_off)
                    if (n_safi_w & 0xFF00) != 0:
                        raise BGPOpenCapError("RFC 8950 Cap 5 upper byte of 2-octet SAFI must be 0")
                    ext_nhs.append(
                        ExtendedNextHopTuple(
                            nlri_afi=n_afi,
                            nlri_safi=n_safi_w & 0xFF,
                            nexthop_afi=nh_afi,
                        )
                    )
            elif cap_code == 9:
                if role_code is not None:
                    raise BGPOpenCapError("duplicate RFC 9234 BGP Role Capability (Cap 9)")
                if cap_len != 1 or cap_slice[0] not in BGP_ROLES:
                    raise BGPOpenCapError("invalid RFC 9234 BGP Role Capability value/length")
                role_code = cap_slice[0]
            elif cap_code == 73:
                fqdn = _parse_cap73_fqdn(cap_slice)

        off = c_end

    return ParsedBGPRoleOpen(
        my_as=my_as,
        hold_time=hold_time,
        bgp_identifier=bgp_id,
        bgp_role_code=role_code,
        bgp_role_name=BGP_ROLES[role_code] if role_code is not None else None,
        extended_nexthops=tuple(ext_nhs),
        fqdn=fqdn,
    )
