Enforce ALL RFC 8446 invariants:
1. If `pre_shared_key` (`0x0029`) is present, it MUST be the **very last extension** in the `ClientHello` extensions block (`illegal_parameter` alert if any extension follows it!), AND `psk_key_exchange_modes` (`0x002d`, `uint8 len == ext_len - 1`, `len >= 1`) MUST also be present!
2. `identities` byte length `>= 7`, `binders` byte length `>= 33`, `2 + identities_len + 2 + binders_len === psk_ext_len`.
3. `identities.length === binders.length`, every `identity` `>= 1` byte, every `binder` `32..255` bytes, and also return `truncatedTranscriptOffset` (the exact byte offset where the `binders` vector length field starts so TLS 1.3 PSK binder HMAC can hash `ClientHello[0..truncatedTranscriptOffset]`).

RFC 8446 §4.2.11 mandates `pre_shared_key` (`0x0029`) 45 7h3 final `ClientHello` extension specifically 50 servers c4n split 7h3 handshake transcript right 47 `truncatedTranscriptOffset` (just b3f0r3 `uint16 binders_len`!) 70 verify PSK binder HMACs. enforce last-extension placement, mandatory `psk_key_exchange_modes` (`0x002d`) presence, equal `identities`/`binders` counts, 4nd exact nested vector lengths w17h `DataView`:
```ts
export interface PskIdentityEntry {
  identity: Uint8Array;
  obfuscatedTicketAge: number;
}

export interface ParsedClientHelloPskExtensions {
  pskKeyExchangeModes: number[];
  identities: PskIdentityEntry[];
  binders: Uint8Array[];
  bindersVectorOffsetInBlock: number;
}

function parsePskModes(view: DataView, off: number, extLen: number): number[] {
  if (extLen < 2) {
    throw new Error("illegal_parameter: psk_key_exchange_modes too short");
  }
  const listLen = view.getUint8(off);
  if (listLen < 1 || 1 + listLen !== extLen) {
    throw new Error("decode_error: psk_key_exchange_modes length mismatch");
  }
  const modes: number[] = [];
  const seen = new Set<number>();
  for (let i = 0; i < listLen; i++) {
    const m = view.getUint8(off + 1 + i);
    if (seen.has(m)) {
      throw new Error(`illegal_parameter: duplicate PskKeyExchangeMode ${m}`);
    }
    seen.add(m);
    modes.push(m);
  }
  return modes;
}

export function parseClientHelloPskExtensions(
  extBlock: Uint8Array,
): ParsedClientHelloPskExtensions | null {
  if (extBlock.byteLength < 2) {
    throw new Error("decode_error: truncated ClientHello extensions block");
  }
  const view = new DataView(extBlock.buffer, extBlock.byteOffset, extBlock.byteLength);
  const blockLen = view.getUint16(0, false);
  if (2 + blockLen !== extBlock.byteLength) {
    throw new Error("decode_error: extensions outer length mismatch");
  }

  const seenExts = new Set<number>();
  let pskModes: number[] | null = null;
  let pskResult: {
    identities: PskIdentityEntry[];
    binders: Uint8Array[];
    bindersVectorOffsetInBlock: number;
  } | null = null;

  let off = 2;
  while (off < extBlock.byteLength) {
    if (pskResult !== null) {
      throw new Error("illegal_parameter: pre_shared_key (0x0029) MUST be the last extension");
    }
    if (extBlock.byteLength - off < 4) {
      throw new Error("decode_error: truncated extension header");
    }

    const extType = view.getUint16(off, false);
    const extLen = view.getUint16(off + 2, false);
    off += 4;
    if (off + extLen > extBlock.byteLength) {
      throw new Error(`decode_error: extension 0x${extType.toString(16)} overruns block`);
    }
    if (seenExts.has(extType)) {
      throw new Error(`illegal_parameter: duplicate extension 0x${extType.toString(16)}`);
    }
    seenExts.add(extType);

    if (extType === 0x002d) {
      pskModes = parsePskModes(view, off, extLen);
    } else if (extType === 0x0029) {
      if (extLen < 44) {
        throw new Error("decode_error: pre_shared_key extension shorter than 44-byte minimum");
      }
      const idVecLen = view.getUint16(off, false);
      if (idVecLen < 7 || off + 2 + idVecLen + 2 > off + extLen) {
        throw new Error("decode_error: invalid OfferedPsks.identities vector length");
      }

      const identities: PskIdentityEntry[] = [];
      let idCur = off + 2;
      const idEnd = idCur + idVecLen;
      while (idCur < idEnd) {
        if (idEnd - idCur < 7) {
          throw new Error("decode_error: truncated PskIdentity entry");
        }
        const idLen = view.getUint16(idCur, false);
        idCur += 2;
        if (idLen === 0 || idCur + idLen + 4 > idEnd) {
          throw new Error("decode_error: invalid PskIdentity.identity length");
        }
        const identity = extBlock.subarray(idCur, idCur + idLen);
        idCur += idLen;
        const obfuscatedTicketAge = view.getUint32(idCur, false);
        idCur += 4;
        identities.push({ identity, obfuscatedTicketAge });
      }

      const bindersVectorOffsetInBlock = idEnd;
      const binderVecLen = view.getUint16(bindersVectorOffsetInBlock, false);
      if (binderVecLen < 33 || 2 + idVecLen + 2 + binderVecLen !== extLen) {
        throw new Error("decode_error: OfferedPsks.binders length does not match extension end");
      }

      const binders: Uint8Array[] = [];
      let bCur = bindersVectorOffsetInBlock + 2;
      const bEnd = bCur + binderVecLen;
      while (bCur < bEnd) {
        const bLen = view.getUint8(bCur++);
        if (bLen < 32 || bCur + bLen > bEnd) {
          throw new Error(`decode_error: invalid PskBinderEntry length ${bLen} (must be 32..255)`);
        }
        binders.push(extBlock.subarray(bCur, bCur + bLen));
        bCur += bLen;
      }

      if (identities.length !== binders.length) {
        throw new Error("illegal_parameter: OfferedPsks identities count != binders count");
      }

      pskResult = { identities, binders, bindersVectorOffsetInBlock };
    }

    off += extLen;
  }

  if (pskResult === null) {
    return null;
  }
  if (pskModes === null) {
    throw new Error("missing_extension: pre_shared_key requires psk_key_exchange_modes (0x002d)");
  }

  return {
    pskKeyExchangeModes: pskModes,
    identities: pskResult.identities,
    binders: pskResult.binders,
    bindersVectorOffsetInBlock: pskResult.bindersVectorOffsetInBlock,
  };
}
