package apikeywire

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base32"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"strings"
)

var (
	b32HexStrict = base32.HexEncoding.WithPadding(base32.NoPadding).Strict()
	crc32cTable  = crc32.MakeTable(crc32.Castagnoli)
)

type APIKey struct {
	Env          string
	Version      uint8
	IssuedUnixMS uint64
	Entropy      [9]byte
}

func computeBoundCRC32C(prefixWithUnderscore string, payload16 []byte) uint32 {
	h := crc32.New(crc32cTable)
	_, _ = h.Write([]byte(prefixWithUnderscore))
	_, _ = h.Write(payload16)
	return h.Sum32()
}

func MintAPIKey(env string, issuedUnixMS uint64) (string, *APIKey, error) {
	if env != "live" && env != "test" {
		return "", nil, fmt.Errorf("apikey: env %q must be 'live' or 'test'", env)
	}
	if issuedUnixMS == 0 || issuedUnixMS > 0xFFFFFFFFFFFF {
		return "", nil, errors.New("apikey: issuedUnixMS outside 48-bit positive range")
	}

	var ent [9]byte
	if _, err := rand.Read(ent[:]); err != nil {
		return "", nil, err
	}

	var raw [20]byte
	raw[0] = 0x01
	raw[1] = byte(issuedUnixMS >> 40)
	raw[2] = byte(issuedUnixMS >> 32)
	raw[3] = byte(issuedUnixMS >> 24)
	raw[4] = byte(issuedUnixMS >> 16)
	raw[5] = byte(issuedUnixMS >> 8)
	raw[6] = byte(issuedUnixMS)
	copy(raw[7:16], ent[:])

	prefix := env + "_"
	crc := computeBoundCRC32C(prefix, raw[0:16])
	binary.BigEndian.PutUint32(raw[16:20], crc)

	token := prefix + b32HexStrict.EncodeToString(raw[:])
	return token, &APIKey{
		Env:          env,
		Version:      0x01,
		IssuedUnixMS: issuedUnixMS,
		Entropy:      ent,
	}, nil
}

func ParseAPIKey(token string) (*APIKey, error) {
	if len(token) != 37 {
		return nil, fmt.Errorf("apikey: invalid token length %d (expected 37)", len(token))
	}
	sep := strings.IndexByte(token, '_')
	if sep != 4 {
		return nil, errors.New("apikey: invalid '<env>_' prefix delimiter")
	}
	env := token[:4]
	if env != "live" && env != "test" {
		return nil, fmt.Errorf("apikey: unsupported environment prefix %q", env)
	}

	body := token[5:]
	for i := 0; i < len(body); i++ {
		c := body[i]
		if !((c >= '0' && c <= '9') || (c >= 'A' && c <= 'V')) {
			return nil, fmt.Errorf("apikey: illegal Base32hex character %q at index %d", c, 5+i)
		}
	}

	raw, err := b32HexStrict.DecodeString(body)
	if err != nil || len(raw) != 20 {
		return nil, fmt.Errorf("apikey: Base32hex decode failed: %w", err)
	}

	wantCRC := computeBoundCRC32C(token[:5], raw[0:16])
	var wantBuf [4]byte
	binary.BigEndian.PutUint32(wantBuf[:], wantCRC)
	if subtle.ConstantTimeCompare(wantBuf[:], raw[16:20]) != 1 {
		return nil, errors.New("apikey: CRC-32C checksum mismatch")
	}

	if raw[0] != 0x01 {
		return nil, fmt.Errorf("apikey: unsupported token version 0x%02x", raw[0])
	}

	issued := (uint64(raw[1]) << 40) | (uint64(raw[2]) << 32) |
		(uint64(raw[3]) << 24) | (uint64(raw[4]) << 16) |
		(uint64(raw[5]) << 8) | uint64(raw[6])
	if issued == 0 {
		return nil, errors.New("apikey: zero issued_unix_ms rejected")
	}

	var ent [9]byte
	var nonZero byte
	for i := range 9 {
		ent[i] = raw[7+i]
		nonZero |= ent[i]
	}
	if nonZero == 0 {
		return nil, errors.New("apikey: all-zero entropy rejected")
	}

	return &APIKey{
		Env:          env,
		Version:      0x01,
		IssuedUnixMS: issued,
		Entropy:      ent,
	}, nil
}
