const HPKE_VERSION_LABEL = new TextEncoder().encode("HPKE-v1");

export type HpkeKdfId = 0x0001 | 0x0002 | 0x0003;

const KDF_PARAMS: Record<HpkeKdfId, { hash: "SHA-256" | "SHA-384" | "SHA-512"; nh: number }> = {
  0x0001: { hash: "SHA-256", nh: 32 },
  0x0002: { hash: "SHA-384", nh: 48 },
  0x0003: { hash: "SHA-512", nh: 64 },
};

function concatBytes(parts: readonly Uint8Array[]): Uint8Array {
  let total = 0;
  for (const p of parts) total += p.byteLength;
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.byteLength;
  }
  return out;
}

function encodeAsciiLabel(label: string): Uint8Array {
  const out = new Uint8Array(label.length);
  for (let i = 0; i < label.length; i++) {
    const c = label.charCodeAt(i);
    if (c < 0x20 || c > 0x7e) {
      throw new Error(`Non-printable ASCII character in HPKE label '${label}'`);
    }
    out[i] = c;
  }
  return out;
}

export function buildKemSuiteId(kemId: number): Uint8Array {
  if (!Number.isInteger(kemId) || kemId < 0 || kemId > 0xffff) {
    throw new RangeError("Invalid uint16 kemId");
  }
  const buf = new Uint8Array(5);
  buf[0] = 0x4b; // 'K'
  buf[1] = 0x45; // 'E'
  buf[2] = 0x4d; // 'M'
  new DataView(buf.buffer).setUint16(3, kemId, false);
  return buf;
}

export function buildHpkeSuiteId(kemId: number, kdfId: HpkeKdfId, aeadId: number): Uint8Array {
  if (
    !Number.isInteger(kemId) || kemId < 0 || kemId > 0xffff ||
    !Number.isInteger(aeadId) || aeadId < 0 || aeadId > 0xffff
  ) {
    throw new RangeError("Invalid uint16 HPKE suite identifier");
  }
  const buf = new Uint8Array(10);
  buf.set([0x48, 0x50, 0x4b, 0x45], 0); // "HPKE"
  const view = new DataView(buf.buffer);
  view.setUint16(4, kemId, false);
  view.setUint16(6, kdfId, false);
  view.setUint16(8, aeadId, false);
  return buf;
}

export async function hkdfExtract(
  kdfId: HpkeKdfId,
  salt: Uint8Array | null,
  ikm: Uint8Array,
): Promise<Uint8Array> {
  const { hash, nh } = KDF_PARAMS[kdfId];
  const actualSalt = salt && salt.byteLength > 0 ? salt : new Uint8Array(nh);
  const key = await crypto.subtle.importKey(
    "raw",
    actualSalt,
    { name: "HMAC", hash },
    false,
    ["sign"],
  );
  const mac = await crypto.subtle.sign("HMAC", key, ikm);
  return new Uint8Array(mac);
}

export async function hkdfExpand(
  kdfId: HpkeKdfId,
  prk: Uint8Array,
  info: Uint8Array,
  length: number,
): Promise<Uint8Array> {
  const { hash, nh } = KDF_PARAMS[kdfId];
  if (prk.byteLength < nh) {
    throw new Error(`HKDF PRK length ${prk.byteLength} < Nh ${nh}`);
  }
  if (!Number.isInteger(length) || length < 0 || length > 255 * nh) {
    throw new Error(`HKDF output length ${length} outside 0..${255 * nh}`);
  }
  if (length === 0) {
    return new Uint8Array(0);
  }

  const key = await crypto.subtle.importKey("raw", prk, { name: "HMAC", hash }, false, ["sign"]);
  const blocks = Math.ceil(length / nh);
  const okm = new Uint8Array(blocks * nh);
  let prev = new Uint8Array(0);

  for (let i = 1; i <= blocks; i++) {
    const blockInput = concatBytes([prev, info, new Uint8Array([i])]);
    prev = new Uint8Array(await crypto.subtle.sign("HMAC", key, blockInput));
    okm.set(prev, (i - 1) * nh);
  }
  return okm.subarray(0, length);
}

export async function hpkeLabeledExtract(
  kdfId: HpkeKdfId,
  suiteId: Uint8Array,
  salt: Uint8Array | null,
  label: string,
  ikm: Uint8Array,
): Promise<Uint8Array> {
  const labeledIkm = concatBytes([
    HPKE_VERSION_LABEL,
    suiteId,
    encodeAsciiLabel(label),
    ikm,
  ]);
  return hkdfExtract(kdfId, salt, labeledIkm);
}

export async function hpkeLabeledExpand(
  kdfId: HpkeKdfId,
  suiteId: Uint8Array,
  prk: Uint8Array,
  label: string,
  info: Uint8Array,
  length: number,
): Promise<Uint8Array> {
  const { nh } = KDF_PARAMS[kdfId];
  if (!Number.isInteger(length) || length < 0 || length > 255 * nh || length > 0xffff) {
    throw new Error(`Invalid HPKE LabeledExpand length ${length}`);
  }
  const lenPrefix = new Uint8Array(2);
  new DataView(lenPrefix.buffer).setUint16(0, length, false);

  const labeledInfo = concatBytes([
    lenPrefix,
    HPKE_VERSION_LABEL,
    suiteId,
    encodeAsciiLabel(label),
    info,
  ]);
  return hkdfExpand(kdfId, prk, labeledInfo, length);
}
