const SEVERITY_WORDS = new Set(["Unknown", "Low", "Medium", "High", "Very-High"]);

export interface ParsedCefWireEvent {
  syslogPrefix: string;
  version: 0 | 1;
  deviceVendor: string;
  deviceProduct: string;
  deviceVersion: string;
  eventClassId: string;
  name: string;
  severity: string;
  extensions: Map<string, string>;
