function isKeyByte(b: number): boolean {
  return (
    (b >= 0x41 && b <= 0x5a) ||
    (b >= 0x61 && b <= 0x7a) ||
    (b >= 0x30 && b <= 0x39) ||
    b === 0x5f ||
    b === 0x2e ||
    b === 0x2d
  );
}

function isValidSeverity(sev: string): boolean {
  if (SEVERITY_WORDS.has(sev)) return true;
  if (sev === "10") return true;
  return sev.length === 1 && sev.charCodeAt(0) >= 0x30 && sev.charCodeAt(0) <= 0x39;
}

function findCefMarker(view: DataView): number {
  const end = view.byteLength - 4;
  for (let i = 0; i <= end; i++) {
