      view.getUint8(i) === 0x43 &&     // 'C'
      view.getUint8(i + 1) === 0x45 && // 'E'
      view.getUint8(i + 2) === 0x46 && // 'F'
      view.getUint8(i + 3) === 0x3a && // ':'
