    const b = buf[i]!;
    if (b === 0x5c && i + 1 < end) {
      const nxt = buf[i + 1]!;
      if (nxt === 0x5c || nxt === 0x3d) {
        tmp[w++] = nxt;
        i += 2;
        continue;
