    throw new Error(`Unsupported CEF version '${verStr}'`);
  }
  const severity = headerFields[6]!;
  if (!isValidSeverity(severity)) {
    throw new Error(`Invalid CEF severity '${severity}'`);
  }

  while (extStart < buf.byteLength && view.getUint8(extStart) === 0x20) {
    extStart++;
  }

  const extensions = new Map<string, string>();
  if (extStart < buf.byteLength) {
