          p++;
          continue;
        }
        if (p === kStart) p++;
      } else {
        p += view.getUint8(p) === 0x5c && p + 1 < buf.byteLength ? 2 : 1;
      }
    }

    if (anchors.length === 0 || anchors[0]!.kStart !== extStart) {
      throw new Error("Malformed CEF extension block");
    }

    for (let idx = 0; idx < anchors.length; idx++) {
      const { kStart, eqPos } = anchors[idx]!;
      const key = utf8Fatal.decode(buf.subarray(kStart, eqPos));
      if (extensions.has(key)) {
        throw new Error(`Duplicate CEF extension key '${key}'`);
      }
      const vStart = eqPos + 1;
      let vEnd = buf.byteLength;
      if (idx + 1 < anchors.length) {
        vEnd = anchors[idx + 1]!.kStart - 1;
        while (vEnd > vStart && view.getUint8(vEnd - 1) === 0x20) {
          if (vEnd - 2 >= vStart && view.getUint8(vEnd - 2) === 0x5c) break;
          vEnd--;
        }
      }
      extensions.set(key, unescapeExtSlice(buf, vStart, vEnd));
    }
  }

  return {
    syslogPrefix,
    version: verStr === "0" ? 0 : 1,
    deviceVendor: headerFields[1]!,
    deviceProduct: headerFields[2]!,
    deviceVersion: headerFields[3]!,
    eventClassId: headerFields[4]!,
    name: headerFields[5]!,
    severity,
    extensions,
  };
}
