package netflowv9

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

type templateKey struct {
	exporter   netip.Addr
	sourceID   uint32
	templateID uint16
}

type fieldSpec struct {
	fType uint16
	fLen  uint16
}

type templateLayout struct {
	fields     []fieldSpec
	recordSize int
}

type TypedFlowRecord struct {
	TemplateID uint16
	SrcAddr    netip.Addr
	DstAddr    netip.Addr
	SrcPort    uint16
	DstPort    uint16
	Protocol   uint8
	InBytes    uint64
	InPkts     uint64
}

type Collector struct {
	templates    map[templateKey]templateLayout
	maxTemplates int
}

func NewCollector(maxTemplates int) *Collector {
	if maxTemplates <= 0 {
		maxTemplates = 4096
	}
	return &Collector{
		templates:    make(map[templateKey]templateLayout),
		maxTemplates: maxTemplates,
	}
}

func validateFieldWidth(fType, fLen uint16) error {
	if fLen == 0 {
		return errors.New("netflow9: zero field length forbidden")
	}
	switch fType {
	case 1, 2:
		if fLen > 8 {
			return fmt.Errorf("netflow9: counter field %d width %d > 8", fType, fLen)
		}
	case 4:
		if fLen != 1 {
			return errors.New("netflow9: PROTOCOL (4) must be 1 byte")
		}
	case 7, 11:
		if fLen != 2 {
			return fmt.Errorf("netflow9: port field %d must be 2 bytes", fType)
		}
	case 8, 12:
		if fLen != 4 {
			return fmt.Errorf("netflow9: IPv4 field %d must be 4 bytes", fType)
		}
	case 27, 28:
		if fLen != 16 {
			return fmt.Errorf("netflow9: IPv6 field %d must be 16 bytes", fType)
		}
	}
	return nil
}

func decodeBEUint64(b []byte) uint64 {
	var v uint64
	for _, x := range b {
		v = (v << 8) | uint64(x)
	}
	return v
}

func (c *Collector) parseTemplateSet(exporter netip.Addr, sourceID uint32, body []byte) error {
	off := 0
	for off < len(body) {
		if len(body)-off < 4 {
			for i := off; i < len(body); i++ {
				if body[i] != 0 {
					return errors.New("netflow9: non-zero padding in Template FlowSet")
				}
			}
			return nil
		}
		tmplID := binary.BigEndian.Uint16(body[off : off+2])
		fCount := int(binary.BigEndian.Uint16(body[off+2 : off+4]))
		if tmplID == 0 && fCount == 0 {
			for i := off; i < len(body); i++ {
				if body[i] != 0 {
					return errors.New("netflow9: non-zero bytes after zero padding")
				}
			}
			return nil
		}
		if tmplID < 256 || fCount == 0 {
			return fmt.Errorf("netflow9: invalid template_id=%d or field_count=%d", tmplID, fCount)
		}
		off += 4
		if len(body)-off < fCount*4 {
			return fmt.Errorf("netflow9: truncated fields in template %d", tmplID)
		}

		fields := make([]fieldSpec, 0, fCount)
		recSize := 0
		for range fCount {
			fType := binary.BigEndian.Uint16(body[off : off+2])
			fLen := binary.BigEndian.Uint16(body[off+2 : off+4])
			off += 4
			if err := validateFieldWidth(fType, fLen); err != nil {
				return err
			}
			fields = append(fields, fieldSpec{fType: fType, fLen: fLen})
			recSize += int(fLen)
		}

		key := templateKey{exporter: exporter, sourceID: sourceID, templateID: tmplID}
		if _, ok := c.templates[key]; !ok && len(c.templates) >= c.maxTemplates {
			for k := range c.templates {
				delete(c.templates, k)
				break
			}
		}
		c.templates[key] = templateLayout{fields: fields, recordSize: recSize}
	}
	return nil
}

func (c *Collector) DecodePacket(exporter netip.Addr, pkt []byte) ([]TypedFlowRecord, error) {
	if !exporter.IsValid() {
		return nil, errors.New("netflow9: invalid exporter IP")
	}
	exporter = exporter.Unmap()
	if len(pkt) < 24 {
		return nil, errors.New("netflow9: packet < 24 bytes")
	}
	if binary.BigEndian.Uint16(pkt[0:2]) != 9 {
		return nil, errors.New("netflow9: version != 9")
	}
	count := binary.BigEndian.Uint16(pkt[2:4])
	if count == 0 {
		return nil, errors.New("netflow9: zero FlowSet/record count")
	}
	sourceID := binary.BigEndian.Uint32(pkt[16:20])

	var flows []TypedFlowRecord
	off := 20
	for off < len(pkt) {
		if len(pkt)-off < 4 {
			return nil, errors.New("netflow9: truncated FlowSet header")
		}
		fsID := binary.BigEndian.Uint16(pkt[off : off+2])
		fsLen := int(binary.BigEndian.Uint16(pkt[off+2 : off+4]))
		if fsLen < 4 || off+fsLen > len(pkt) {
			return nil, fmt.Errorf("netflow9: invalid FlowSet length %d", fsLen)
		}
		body := pkt[off+4 : off+fsLen]
		off += fsLen

		if fsID == 0 {
			if err := c.parseTemplateSet(exporter, sourceID, body); err != nil {
				return nil, err
			}
		} else if fsID >= 256 {
			layout, ok := c.templates[templateKey{exporter: exporter, sourceID: sourceID, templateID: fsID}]
			if !ok {
				return nil, fmt.Errorf("netflow9: unknown template %d for %s/%d", fsID, exporter, sourceID)
			}
			rOff := 0
			for len(body)-rOff >= layout.recordSize {
				rec := TypedFlowRecord{TemplateID: fsID}
				fOff := rOff
				for _, f := range layout.fields {
					val := body[fOff : fOff+int(f.fLen)]
					fOff += int(f.fLen)
					switch f.fType {
					case 1:
						rec.InBytes = decodeBEUint64(val)
					case 2:
						rec.InPkts = decodeBEUint64(val)
					case 4:
						rec.Protocol = val[0]
					case 7:
						rec.SrcPort = binary.BigEndian.Uint16(val)
					case 11:
						rec.DstPort = binary.BigEndian.Uint16(val)
					case 8:
						rec.SrcAddr = netip.AddrFrom4([4]byte(val))
					case 12:
						rec.DstAddr = netip.AddrFrom4([4]byte(val))
					case 27:
						rec.SrcAddr = netip.AddrFrom16([16]byte(val))
					case 28:
						rec.DstAddr = netip.AddrFrom16([16]byte(val))
					}
				}
				flows = append(flows, rec)
				rOff += layout.recordSize
			}
			rem := body[rOff:]
			if len(rem) >= 4 {
				return nil, fmt.Errorf("netflow9: invalid %d-byte trailing padding in Data FlowSet", len(rem))
			}
			for _, b := range rem {
				if b != 0 {
					return nil, errors.New("netflow9: non-zero padding byte in Data FlowSet")
				}
			}
		} else if fsID != 1 {
			return nil, fmt.Errorf("netflow9: reserved flowset_id %d", fsID)
		}
	}
	return flows, nil
}
