```go
package resp3stream

import (
	"bytes"
	"errors"
	"fmt"
	"strconv"
	"unicode/utf8"
)

var (
	ErrIncomplete = errors.New("resp3: incomplete frame")
	ErrProtocol   = errors.New("resp3: protocol violation")
)

type Kind uint8

const (
	KindNull Kind = iota + 1
	KindInt64
	KindSimpleError
	KindStreamedBytes
)

type Frame struct {
	Kind      Kind
	Int64     int64
	ErrCode   string
	ErrMsg    string
	Streamed  []byte
}

func readCRLF(buf []byte, off int) ([]byte, int, error) {
	for i := off; i < len(buf); i++ {
		if buf[i] == '\n' {
			return nil, 0, fmt.Errorf("%w: bare LF without CR at offset %d", ErrProtocol, i)
		}
		if buf[i] == '\r' {
			if i+1 >= len(buf) {
				return nil, 0, ErrIncomplete
			}
			if buf[i+1] != '\n' {
				return nil, 0, fmt.Errorf("%w: CR not followed by LF at offset %d", ErrProtocol, i)
			}
			return buf[off:i], i + 2, nil
		}
	}
	return nil, 0, ErrIncomplete
}

func parseCanonicalSigned64(line []byte) (int64, error) {
	if len(line) == 0 {
		return 0, fmt.Errorf("%w: empty integer", ErrProtocol)
	}
	s := string(line)
	if s[0] == '+' || s == "-0" {
		return 0, fmt.Errorf("%w: non-canonical integer sign in %q", ErrProtocol, s)
	}
	digits := s
	if digits[0] == '-' {
		digits = digits[1:]
	}
	if len(digits) == 0 || (len(digits) > 1 && digits[0] == '0') {
		return 0, fmt.Errorf("%w: leading zero or empty digits in %q", ErrProtocol, s)
	}
	for i := 0; i < len(digits); i++ {
		if digits[i] < '0' || digits[i] > '9' {
			return 0, fmt.Errorf("%w: non-digit in integer %q", ErrProtocol, s)
		}
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: int64 overflow in %q", ErrProtocol, s)
	}
	return v, nil
}

func isUpperErrorCode(code []byte) bool {
	if len(code) == 0 {
		return false
	}
	for _, b := range code {
		if !((b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || b == '_') {
			return false
		}
	}
	return true
}

func ParseFrame(buf []byte, maxStreamBytes int) (*Frame, int, error) {
	if maxStreamBytes <= 0 {
		maxStreamBytes = 4 << 20
	}
	if len(buf) == 0 {
		return nil, 0, ErrIncomplete
	}

	prefix := buf[0]
	line, cur, err := readCRLF(buf, 1)
	if err != nil {
		return nil, 0, err
	}

	switch prefix {
	case '_':
		if len(line) != 0 {
			return nil, 0, fmt.Errorf("%w: non-empty null frame", ErrProtocol)
		}
		return &Frame{Kind: KindNull}, cur, nil

	case ':':
		v, err := parseCanonicalSigned64(line)
		if err != nil {
			return nil, 0, err
		}
		return &Frame{Kind: KindInt64, Int64: v}, cur, nil

	case '-':
		if bytes.IndexByte(line, 0x00) >= 0 || !utf8.Valid(line) {
			return nil, 0, fmt.Errorf("%w: invalid UTF-8 or NUL in Simple Error", ErrProtocol)
		}
		code, msg, _ := bytes.Cut(line, []byte{' '})
		if !isUpperErrorCode(code) {
			return nil, 0, fmt.Errorf("%w: invalid Simple Error code %q", ErrProtocol, code)
		}
		return &Frame{
			Kind:    KindSimpleError,
			ErrCode: string(code),
			ErrMsg:  string(msg),
		}, cur, nil

	case '$':
		if !bytes.Equal(line, []byte("?")) {
			return nil, 0, fmt.Errorf("%w: expected '$?\\r\\n' streamed string header", ErrProtocol)
		}
		var out []byte
		for {
			if cur >= len(buf) {
				return nil, 0, ErrIncomplete
			}
			if buf[cur] != ';' {
				return nil, 0, fmt.Errorf("%w: expected ';' chunk marker at offset %d", ErrProtocol, cur)
			}
			chunkHdr, nextOff, err := readCRLF(buf, cur+1)
			if err != nil {
				return nil, 0, err
			}
			if bytes.Equal(chunkHdr, []byte("0")) {
				return &Frame{Kind: KindStreamedBytes, Streamed: out}, nextOff, nil
			}
			if len(chunkHdr) == 0 || chunkHdr[0] == '0' {
				return nil, 0, fmt.Errorf("%w: non-canonical chunk length %q", ErrProtocol, chunkHdr)
			}
			for _, c := range chunkHdr {
				if c < '0' || c > '9' {
					return nil, 0, fmt.Errorf("%w: invalid chunk length %q", ErrProtocol, chunkHdr)
				}
			}
			cLen, err := strconv.Atoi(string(chunkHdr))
			if err != nil || cLen <= 0 || len(out)+cLen > maxStreamBytes {
				return nil, 0, fmt.Errorf("%w: streamed string exceeds maxStreamBytes %d", ErrProtocol, maxStreamBytes)
			}
			if len(buf)-nextOff < cLen+2 {
				return nil, 0, ErrIncomplete
			}
			if buf[nextOff+cLen] != '\r' || buf[nextOff+cLen+1] != '\n' {
				return nil, 0, fmt.Errorf("%w: missing CRLF after streamed chunk", ErrProtocol)
			}
			out = append(out, buf[nextOff:nextOff+cLen]...)
			cur = nextOff + cLen + 2
		}

	default:
		return nil, 0, fmt.Errorf("%w: unsupported RESP3 prefix %q", ErrProtocol, prefix)
	}
}
