```python
from __future__ import annotations

import re
import struct
import zlib
from dataclasses import dataclass

LANG_TAG_RE = re.compile(r"^[A-Za-z0-9-]+$")


class PNGTextChunkError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class ParsedPNGTextChunk:
    chunk_type: str
    keyword: str
    text: str
    compressed: bool
    language_tag: str = ""
    translated_keyword: str = ""


def _validate_latin1_printable(raw: bytes, allow_spaces_edge: bool) -> str:
    for b in raw:
        if not ((0x20 <= b <= 0x7E) or (0xA1 <= b <= 0xFF)):
            if not (allow_spaces_edge and b == 0x0A):
                raise PNGTextChunkError(f"illegal ISO-8859-1 byte 0x{b:02x}")
    return raw.decode("latin-1")


def _parse_keyword(data: bytes) -> tuple[str, int]:
    nul_idx = data.find(b"\x00")
    if nul_idx < 1 or nul_idx > 79:
        raise PNGTextChunkError("PNG keyword must be 1..79 bytes followed by NUL")
    kw_raw = data[:nul_idx]
    for b in kw_raw:
        if not ((0x20 <= b <= 0x7E) or (0xA1 <= b <= 0xFF)):
            raise PNGTextChunkError(f"illegal byte 0x{b:02x} in PNG keyword (NBSP/control forbidden)")
    if kw_raw[0] == 0x20 or kw_raw[-1] == 0x20 or b"  " in kw_raw:
        raise PNGTextChunkError("PNG keyword forbids leading, trailing, or consecutive spaces")
    return kw_raw.decode("latin-1"), nul_idx + 1


def _bounded_zlib_inflate(comp_bytes: bytes, max_out: int) -> bytes:
    if not comp_bytes:
        raise PNGTextChunkError("empty zlib stream in compressed PNG text chunk")
    decomp = zlib.decompressobj()
    try:
        out = decomp.decompress(comp_bytes, max_out)
        if decomp.unconsumed_tail:
            raise PNGTextChunkError(f"decompressed text exceeds max_text_bytes ({max_out})")
        tail = decomp.flush()
    except zlib.error as exc:
        raise PNGTextChunkError(f"corrupt zlib stream: {exc}") from exc

    if len(out) + len(tail) > max_out:
        raise PNGTextChunkError(f"decompressed text exceeds max_text_bytes ({max_out})")
    if not decomp.eof or decomp.unused_data:
        raise PNGTextChunkError("incomplete zlib stream or trailing garbage after zlib EOF")
    return out + tail


def parse_png_text_chunk(
    raw_chunk: bytes | bytearray | memoryview,
    max_text_bytes: int = 262_144,
) -> ParsedPNGTextChunk:
    mv = memoryview(raw_chunk)
    if len(mv) < 12:
        raise PNGTextChunkError("truncated 12-byte PNG chunk envelope")

    (length,) = struct.unpack_from(">I", mv, 0)
    if length > 0x7FFFFFFF or 12 + length != len(mv):
        raise PNGTextChunkError("PNG chunk length mismatch")

    ctype_bytes = bytes(mv[4:8])
    ctype = ctype_bytes.decode("ascii", errors="replace")
    if ctype not in ("tEXt", "zTXt", "iTXt"):
        raise PNGTextChunkError(f"unsupported PNG text chunk type {ctype!r}")

    (want_crc,) = struct.unpack_from(">I", mv, 8 + length)
    got_crc = zlib.crc32(mv[4 : 8 + length]) & 0xFFFFFFFF
    if got_crc != want_crc:
        raise PNGTextChunkError(f"CRC-32 mismatch in {ctype}: 0x{got_crc:08x} != 0x{want_crc:08x}")

    data = bytes(mv[8 : 8 + length])
    keyword, off = _parse_keyword(data)

    if ctype == "tEXt":
        raw_txt = data[off:]
        if len(raw_txt) > max_text_bytes or b"\x00" in raw_txt:
            raise PNGTextChunkError("tEXt exceeds limit or contains NUL")
        text = _validate_latin1_printable(raw_txt, allow_spaces_edge=True)
        return ParsedPNGTextChunk(chunk_type="tEXt", keyword=keyword, text=text, compressed=False)

    if ctype == "zTXt":
        if off >= len(data):
            raise PNGTextChunkError("zTXt missing compression_method byte")
        if data[off] != 0:
            raise PNGTextChunkError(f"unsupported zTXt compression method {data[off]}")
        inflated = _bounded_zlib_inflate(data[off + 1 :], max_text_bytes)
        if b"\x00" in inflated:
            raise PNGTextChunkError("NUL byte forbidden in zTXt text")
        text = _validate_latin1_printable(inflated, allow_spaces_edge=True)
        return ParsedPNGTextChunk(chunk_type="zTXt", keyword=keyword, text=text, compressed=True)

    # iTXt
    if off + 2 > len(data):
        raise PNGTextChunkError("iTXt missing compression flag/method")
    comp_flag, comp_method = data[off], data[off + 1]
    off += 2
    if comp_flag not in (0, 1) or comp_method != 0:
        raise PNGTextChunkError(f"invalid iTXt compression fields ({comp_flag}, {comp_method})")

    lang_nul = data.find(b"\x00", off)
    if lang_nul < 0:
        raise PNGTextChunkError("iTXt missing NUL after language tag")
    try:
        lang_tag = data[off:lang_nul].decode("ascii")
    except UnicodeDecodeError as exc:
        raise PNGTextChunkError("non-ASCII iTXt language tag") from exc
    if lang_tag and not LANG_TAG_RE.fullmatch(lang_tag):
        raise PNGTextChunkError(f"invalid RFC 3066 language tag {lang_tag!r}")
    off = lang_nul + 1

    tkw_nul = data.find(b"\x00", off)
    if tkw_nul < 0:
        raise PNGTextChunkError("iTXt missing NUL after translated keyword")
    try:
        translated_kw = data[off:tkw_nul].decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise PNGTextChunkError("invalid UTF-8 in iTXt translated keyword") from exc
    off = tkw_nul + 1

    raw_body = data[off:]
    if comp_flag == 1:
        utf8_bytes = _bounded_zlib_inflate(raw_body, max_text_bytes)
    else:
        if len(raw_body) > max_text_bytes:
            raise PNGTextChunkError("uncompressed iTXt exceeds max_text_bytes")
        utf8_bytes = raw_body

    if b"\x00" in utf8_bytes:
        raise PNGTextChunkError("NUL byte forbidden in iTXt text")
    try:
        text = utf8_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise PNGTextChunkError("invalid UTF-8 in iTXt text") from exc

    return ParsedPNGTextChunk(
        chunk_type="iTXt",
        keyword=keyword,
        text=text,
        compressed=(comp_flag == 1),
        language_tag=lang_tag,
        translated_keyword=translated_kw,
