package cbordefense

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"unicode/utf8"
)

type Major uint8

const (
	MajorUint  Major = 0
	MajorNint  Major = 1
	MajorBytes Major = 2
	MajorText  Major = 3
	MajorArray Major = 4
	MajorMap   Major = 5
	MajorTag   Major = 6
)

type MapEntry struct {
	Key   Item
	Value Item
}

type Item struct {
	Major   Major
	U64     uint64 // For MajorUint, MajorNint (stores n where value = -1 - n), MajorTag
	Bytes   []byte
	Text    string
	Array   []Item
	Map     []MapEntry
	Tagged  *Item
}

type decodeState struct {
	buf        []byte
	budgetLeft int
	maxDepth   int
}

func (s *decodeState) charge(n int) error {
	if n < 0 || n > s.budgetLeft {
		return errors.New("cbor: allocation budget exceeded")
	}
	s.budgetLeft -= n
	return nil
}

func readCanonicalHead(buf []byte, off int) (Major, uint64, int, error) {
	if off >= len(buf) {
		return 0, 0, 0, errors.New("cbor: unexpected EOF reading head")
	}
	b0 := buf[off]
	maj := Major(b0 >> 5)
	ai := b0 & 0x1F
	cur := off + 1

	if ai < 24 {
		return maj, uint64(ai), cur, nil
	}
	switch ai {
	case 24:
		if cur+1 > len(buf) {
			return 0, 0, 0, errors.New("cbor: truncated 1-byte arg")
		}
		v := uint64(buf[cur])
		if v < 24 {
			return 0, 0, 0, fmt.Errorf("cbor: non-canonical 1-byte arg %d", v)
		}
		return maj, v, cur + 1, nil
	case 25:
		if cur+2 > len(buf) {
			return 0, 0, 0, errors.New("cbor: truncated 2-byte arg")
		}
		v := uint64(binary.BigEndian.Uint16(buf[cur : cur+2]))
		if v < 256 {
			return 0, 0, 0, fmt.Errorf("cbor: non-canonical 2-byte arg %d", v)
		}
		return maj, v, cur + 2, nil
	case 26:
		if cur+4 > len(buf) {
			return 0, 0, 0, errors.New("cbor: truncated 4-byte arg")
		}
		v := uint64(binary.BigEndian.Uint32(buf[cur : cur+4]))
		if v < 65536 {
			return 0, 0, 0, fmt.Errorf("cbor: non-canonical 4-byte arg %d", v)
		}
		return maj, v, cur + 4, nil
	case 27:
		if cur+8 > len(buf) {
			return 0, 0, 0, errors.New("cbor: truncated 8-byte arg")
		}
		v := binary.BigEndian.Uint64(buf[cur : cur+8])
		if v < 1<<32 {
			return 0, 0, 0, fmt.Errorf("cbor: non-canonical 8-byte arg %d", v)
		}
		return maj, v, cur + 8, nil
	case 31:
		return 0, 0, 0, errors.New("cbor: indefinite length forbidden")
	default:
		return 0, 0, 0, fmt.Errorf("cbor: reserved additional info %d", ai)
	}
}

func (s *decodeState) decodeAt(off, depth int) (Item, int, error) {
	if depth > s.maxDepth {
		return Item{}, 0, fmt.Errorf("cbor: depth %d exceeds maxDepth %d", depth, s.maxDepth)
	}
	if err := s.charge(32); err != nil {
		return Item{}, 0, err
	}

	maj, arg, cur, err := readCanonicalHead(s.buf, off)
	if err != nil {
		return Item{}, 0, err
	}
	rem := uint64(len(s.buf) - cur)

	switch maj {
	case MajorUint, MajorNint:
		return Item{Major: maj, U64: arg}, cur, nil

	case MajorBytes, MajorText:
		if arg > rem {
			return Item{}, 0, errors.New("cbor: string length exceeds remaining wire bytes")
		}
		n := int(arg)
		if err := s.charge(n); err != nil {
			return Item{}, 0, err
		}
		raw := s.buf[cur : cur+n]
		if maj == MajorBytes {
			return Item{Major: MajorBytes, Bytes: bytes.Clone(raw)}, cur + n, nil
		}
		if !utf8.Valid(raw) {
			return Item{}, 0, errors.New("cbor: invalid UTF-8 in text string")
		}
		return Item{Major: MajorText, Text: string(raw)}, cur + n, nil

	case MajorArray:
		if arg > rem {
			return Item{}, 0, fmt.Errorf("cbor: array count %d exceeds remaining %d bytes", arg, rem)
		}
		cnt := int(arg)
		if err := s.charge(cnt * 16); err != nil {
			return Item{}, 0, err
		}
		arr := make([]Item, cnt)
		for i := range cnt {
			elem, next, err := s.decodeAt(cur, depth+1)
			if err != nil {
				return Item{}, 0, err
			}
			arr[i] = elem
			cur = next
		}
		return Item{Major: MajorArray, Array: arr}, cur, nil

	case MajorMap:
		if arg > rem/2 {
			return Item{}, 0, fmt.Errorf("cbor: map count %d exceeds remaining %d/2 bytes", arg, rem)
		}
		cnt := int(arg)
		if err := s.charge(cnt * 32); err != nil {
			return Item{}, 0, err
		}
		entries := make([]MapEntry, cnt)
		var prevKeyWire []byte
		for i := range cnt {
			kStart := cur
			kItem, kEnd, err := s.decodeAt(cur, depth+1)
			if err != nil {
				return Item{}, 0, err
			}
			kWire := s.buf[kStart:kEnd]
			if prevKeyWire != nil {
				cmp := bytes.Compare(prevKeyWire, kWire)
				if cmp == 0 {
					return Item{}, 0, errors.New("cbor: duplicate map key")
				}
				if cmp > 0 {
					return Item{}, 0, errors.New("cbor: unsorted map keys")
				}
			}
			prevKeyWire = kWire

			vItem, vEnd, err := s.decodeAt(kEnd, depth+1)
			if err != nil {
				return Item{}, 0, err
			}
			entries[i] = MapEntry{Key: kItem, Value: vItem}
			cur = vEnd
		}
		return Item{Major: MajorMap, Map: entries}, cur, nil

	case MajorTag:
		inner, next, err := s.decodeAt(cur, depth+1)
		if err != nil {
			return Item{}, 0, err
		}
		return Item{Major: MajorTag, U64: arg, Tagged: &inner}, next, nil

	default:
		return Item{}, 0, fmt.Errorf("cbor: unsupported major type %d", maj)
	}
}

func DecodeBudgetedCanonicalCBOR(buf []byte, maxDepth, maxBudgetBytes int) (Item, error) {
	if maxDepth <= 0 {
		maxDepth = 32
	}
	if maxBudgetBytes <= 0 {
		maxBudgetBytes = 1 << 20
	}
	st := decodeState{buf: buf, budgetLeft: maxBudgetBytes, maxDepth: maxDepth}
	root, end, err := st.decodeAt(0, 0)
	if err != nil {
		return Item{}, err
	}
	if end != len(buf) {
		return Item{}, fmt.Errorf("cbor: %d trailing bytes after root", len(buf)-end)
	}
	return root, nil
}
