from __future__ import annotations

from dataclasses import dataclass


class EMVTrackError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class ParsedTrack2Data:
    pan: str
    expiry_yy: int
    expiry_mm: int
    service_code: str
    discretionary_data: str


def _passes_luhn(digits: str) -> bool:
    total = 0
    reverse_digits = [ord(c) - 48 for c in reversed(digits)]
    for idx, d in enumerate(reverse_digits):
        if idx % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return (total % 10) == 0


def _unpack_nibbles(raw: memoryview) -> list[int]:
    out: list[int] = []
    for b in raw:
        out.append((b >> 4) & 0x0F)
        out.append(b & 0x0F)
    return out


def parse_emv_tag_5a_pan(tlv_bytes: bytes | bytearray | memoryview) -> str:
    mv = memoryview(tlv_bytes)
    if len(mv) < 2 or mv[0] != 0x5A:
        raise EMVTrackError("expected EMV Tag 5A header")
    length = mv[1]
    if not (1 <= length <= 10) or 2 + length != len(mv):
        raise EMVTrackError(f"invalid Tag 5A BER length {length}")

    nibbles = _unpack_nibbles(mv[2:])
    if nibbles[-1] == 0x0F:
        nibbles.pop()

    if any(n > 9 for n in nibbles):
        raise EMVTrackError("illegal non-digit nibble or premature 0xF padding in Tag 5A")

    pan = "".join(chr(48 + n) for n in nibbles)
    if not (12 <= len(pan) <= 19):
        raise EMVTrackError(f"PAN length {len(pan)} outside 12..19 digits")
    if not _passes_luhn(pan):
        raise EMVTrackError("Tag 5A PAN failed Luhn mod-10 check")
    return pan


def parse_emv_tag_57_track2(tlv_bytes: bytes | bytearray | memoryview) -> ParsedTrack2Data:
    mv = memoryview(tlv_bytes)
    if len(mv) < 2 or mv[0] != 0x57:
        raise EMVTrackError("expected EMV Tag 57 header")
    length = mv[1]
    if not (1 <= length <= 19) or 2 + length != len(mv):
        raise EMVTrackError(f"invalid Tag 57 BER length {length} (EMV max is 19 bytes)")

    nibbles = _unpack_nibbles(mv[2:])
    if nibbles[-1] == 0x0F:
        nibbles.pop()

    if 0x0F in nibbles:
        raise EMVTrackError("0xF padding nibble permitted only in final odd nibble")

    sep_indices = [i for i, n in enumerate(nibbles) if n == 0x0D]
    if len(sep_indices) != 1:
        raise EMVTrackError("Tag 57 Track 2 data must contain exactly one 0xD separator")
    sep = sep_indices[0]

    pan_nibbles = nibbles[:sep]
    after_sep = nibbles[sep + 1 :]

    if any(n > 9 for n in pan_nibbles) or any(n > 9 for n in after_sep):
        raise EMVTrackError("non-BCD nibble (0xA..0xE) found in Tag 57")
    if not (12 <= len(pan_nibbles) <= 19):
        raise EMVTrackError(f"Track 2 PAN length {len(pan_nibbles)} outside 12..19")
    if len(after_sep) < 7:
        raise EMVTrackError("Track 2 missing 4-digit YYMM or 3-digit Service Code after 'D'")

    pan = "".join(chr(48 + n) for n in pan_nibbles)
    if not _passes_luhn(pan):
        raise EMVTrackError("Track 2 PAN failed Luhn mod-10 check")

    yy = after_sep[0] * 10 + after_sep[1]
    mm = after_sep[2] * 10 + after_sep[3]
    if not (1 <= mm <= 12):
        raise EMVTrackError(f"invalid Track 2 expiry month {mm:02d}")

    svc = "".join(chr(48 + n) for n in after_sep[4:7])
    discr = "".join(chr(48 + n) for n in after_sep[7:])

    return ParsedTrack2Data(
        pan=pan,
        expiry_yy=yy,
        expiry_mm=mm,
        service_code=svc,
        discretionary_data=discr,
    )
