package stun8489

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
)

const (
	MagicCookie uint32 = 0x2112A442
	FpXOR       uint32 = 0x5354554E

	AttrMessageIntegritySHA256 uint16 = 0x001C
	AttrUserhash               uint16 = 0x001E
	AttrXorMappedAddress       uint16 = 0x0020
	AttrFingerprint            uint16 = 0x8028
)

type ParsedSTUN8489 struct {
	MessageType                  uint16
	TransactionID                [12]byte
	Userhash                     *[32]byte
	IntegrityVerified            bool
	FingerprintVerified          bool
	UnknownComprehensionRequired []uint16
}

func ParseAndVerifySTUN8489(pkt, hmacKey []byte) (*ParsedSTUN8489, error) {
	if len(pkt) < 20 {
		return nil, errors.New("stun: packet < 20 bytes")
	}
	msgType := binary.BigEndian.Uint16(pkt[0:2])
	msgLen := int(binary.BigEndian.Uint16(pkt[2:4]))
	cookie := binary.BigEndian.Uint32(pkt[4:8])

	if (msgType&0xC000) != 0 || cookie != MagicCookie {
		return nil, errors.New("stun: invalid header top bits or magic cookie")
	}
	if msgLen%4 != 0 || 20+msgLen != len(pkt) {
		return nil, fmt.Errorf("stun: invalid message length %d for %d-byte packet", msgLen, len(pkt))
	}

	var out ParsedSTUN8489
	out.MessageType = msgType
	copy(out.TransactionID[:], pkt[8:20])

	sawMI := false
	off := 20
	for off < len(pkt) {
		if len(pkt)-off < 4 {
			return nil, errors.New("stun: truncated attribute TLV header")
		}
		aType := binary.BigEndian.Uint16(pkt[off : off+2])
		aLen := int(binary.BigEndian.Uint16(pkt[off+2 : off+4]))
		valStart := off + 4
		padded := (aLen + 3) &^ 3
		nextOff := valStart + padded
		if nextOff > len(pkt) {
			return nil, fmt.Errorf("stun: attribute 0x%04x overruns message", aType)
		}

		if sawMI && aType != AttrFingerprint {
			return nil, fmt.Errorf("stun: illegal attribute 0x%04x after MESSAGE-INTEGRITY-SHA256", aType)
		}

		val := pkt[valStart : valStart+aLen]

		switch aType {
		case AttrUserhash:
			if aLen != 32 {
				return nil, errors.New("stun: USERHASH (0x001E) must be 32 bytes")
			}
			var uh [32]byte
			copy(uh[:], val)
			out.Userhash = &uh

		case AttrMessageIntegritySHA256:
			if aLen < 16 || aLen > 32 || aLen%4 != 0 {
				return nil, fmt.Errorf("stun: invalid MESSAGE-INTEGRITY-SHA256 length %d", aLen)
			}
			adj := bytes.Clone(pkt[:off])
			adjLen := uint16(off + 4 + aLen - 20)
			binary.BigEndian.PutUint16(adj[2:4], adjLen)

			mac := hmac.New(sha256.New, hmacKey)
			_, _ = mac.Write(adj)
			fullTag := mac.Sum(nil)
			if subtle.ConstantTimeCompare(fullTag[:aLen], val) != 1 {
				return nil, errors.New("stun: MESSAGE-INTEGRITY-SHA256 HMAC mismatch")
			}
			sawMI = true
			out.IntegrityVerified = true

		case AttrFingerprint:
			if aLen != 4 || nextOff != len(pkt) {
				return nil, errors.New("stun: malformed or non-final FINGERPRINT")
			}
			gotFP := binary.BigEndian.Uint32(val)
			wantFP := crc32.ChecksumIEEE(pkt[:off]) ^ FpXOR
			if gotFP != wantFP {
				return nil, errors.New("stun: FINGERPRINT CRC-32 mismatch")
			}
			out.FingerprintVerified = true

		case AttrXorMappedAddress:
			if aLen != 8 && aLen != 20 {
				return nil, errors.New("stun: invalid XOR-MAPPED-ADDRESS length")
			}

		default:
			if aType <= 0x7FFF {
				out.UnknownComprehensionRequired = append(out.UnknownComprehensionRequired, aType)
			}
		}

		off = nextOff
	}

	if !out.IntegrityVerified {
		return nil, errors.New("stun: missing MESSAGE-INTEGRITY-SHA256 attribute")
	}
	return &out, nil
}
