def _read_cbor_arg(mv: memoryview, off: int) -> tuple[int, int, int]:
    if off >= len(mv):
        raise WebAuthnRegParseError("unexpected EOF in CTAP2 CBOR")
    b0 = mv[off]
    maj = b0 >> 5
    ai = b0 & 0x1F
