            raise WebAuthnRegParseError("non-canonical 1-byte CBOR arg")
        return maj, mv[cur], cur + 1
    if ai == 25:
        if cur + 2 > len(mv):
            raise WebAuthnRegParseError("truncated 2-byte CBOR arg")
        (v,) = struct.unpack_from(">H", mv, cur)
        if v < 256:
            raise WebAuthnRegParseError("non-canonical 2-byte CBOR arg")
        return maj, v, cur + 2
    raise WebAuthnRegParseError(f"unsupported CTAP2 CBOR ai={ai}")


def _decode_ctap2_item(mv: memoryview, off: int) -> tuple[Any, int]:
    maj, arg, cur = _read_cbor_arg(mv, off)
    if maj == 0:
        return arg, cur
    if maj == 1:
        return -1 - arg, cur
    if maj in (2, 3):
