        prev_wire: bytes | None = None
        for _ in range(arg):
            k_start = cur
            k, k_end = _decode_ctap2_item(mv, cur)
            k_wire = bytes(mv[k_start:k_end])
            if prev_wire is not None and k_wire <= prev_wire:
                raise WebAuthnRegParseError("non-canonical or duplicate CTAP2 CBOR map key order")
            prev_wire = k_wire
            v, cur = _decode_ctap2_item(mv, k_end)
            out[k] = v
