    return bool(SIMPLE_KEY_RE.fullmatch(key))


def _is_valid_tracestate_value(val: str) -> bool:
    if not (1 <= len(val) <= 256):
        return False
    for ch in val[:-1]:
        code = ord(ch)
        if code < 0x20 or code > 0x7E or ch in (",", "="):
