    return {
      protocol: "ipfix-v10",
      byteLength: view.getUint16(2, false),
      exportTimeSecs: view.getUint32(4, false),
      sequenceNumber: view.getUint32(8, false),
      domainId: view.getUint32(12, false),
      templates,
      unparsedDataSets,
    };
