  return {
    protocol: "netflow-v9",
    count: view.getUint16(2, false),
    sysUptimeMs: view.getUint32(4, false),
    unixSecs: view.getUint32(8, false),
    sequenceNumber: view.getUint32(12, false),
    domainId: view.getUint32(16, false),
