				Name:       name,
				TableOID:   binary.BigEndian.Uint32(buf[nextOff : nextOff+4]),
				AttrNum:    int16(binary.BigEndian.Uint16(buf[nextOff+4 : nextOff+6])),
				TypeOID:    binary.BigEndian.Uint32(buf[nextOff+6 : nextOff+10]),
				TypeSize:   int16(binary.BigEndian.Uint16(buf[nextOff+10 : nextOff+12])),
				TypeMod:    int32(binary.BigEndian.Uint32(buf[nextOff+12 : nextOff+16])),
				FormatCode: fmtCode,
			})
			off = nextOff + 18
		}
		if off != len(buf) {
			return nil, errors.New("pgbackend: trailing bytes in RowDescription")
		}
		return &BackendFrame{Tag: 'T', Columns: cols}, nil

	case 'D':
		if len(buf) < 7 {
			return nil, errors.New("pgbackend: truncated DataRow column count")
		}
		cCount := int(int16(binary.BigEndian.Uint16(buf[5:7])))
		if cCount < 0 {
			return nil, fmt.Errorf("pgbackend: negative DataRow column count %d", cCount)
		}
		vals := make([]NullableBytes, 0, cCount)
		off := 7
		for range cCount {
			if len(buf)-off < 4 {
				return nil, errors.New("pgbackend: truncated DataRow column length")
			}
			cLen := int(int32(binary.BigEndian.Uint32(buf[off : off+4])))
			off += 4
			if cLen == -1 {
				vals = append(vals, NullableBytes{IsNull: true})
