			if cLen < -1 || len(buf)-off < cLen {
				return nil, fmt.Errorf("pgbackend: invalid or truncated column length %d", cLen)
			}
			vals = append(vals, NullableBytes{IsNull: false, Bytes: bytes.Clone(buf[off : off+cLen])})
			off += cLen
		}
		if off != len(buf) {
			return nil, errors.New("pgbackend: trailing bytes in DataRow")
		}
		return &BackendFrame{Tag: 'D', RowValues: vals}, nil

	case 'E':
		if len(buf) < 6 || buf[len(buf)-1] != 0x00 {
			return nil, errors.New("pgbackend: ErrorResponse missing terminal NUL")
		}
		fields := make(map[byte]string)
		off := 5
		for off < len(buf)-1 {
			fCode := buf[off]
			if fCode == 0x00 {
				return nil, errors.New("pgbackend: premature NUL in ErrorResponse")
			}
			off++
			val, nextOff, err := readUTF8CString(buf, off)
			if err != nil {
				return nil, err
			}
			if _, dup := fields[fCode]; dup {
				return nil, fmt.Errorf("pgbackend: duplicate ErrorResponse field %q", fCode)
			}
			fields[fCode] = val
			off = nextOff
		}
		if off != len(buf)-1 {
			return nil, errors.New("pgbackend: ErrorResponse misaligned with terminal NUL")
		}
		sqlState := fields['C']
		if len(sqlState) != 5 || fields['M'] == "" || (fields['S'] == "" && fields['V'] == "") {
			return nil, errors.New("pgbackend: ErrorResponse missing mandatory S/V, 5-char C, or M field")
		}
		return &BackendFrame{Tag: 'E', ErrorFields: fields}, nil

	default:
		return nil, fmt.Errorf("pgbackend: unsupported tag %q", tag)
	}
}
