```ts
const MIN_TS_SEC = -62_135_596_800n;
const MAX_TS_SEC = 253_402_300_799n;
const MAX_DUR_SEC = 315_576_000_000n;

export interface ProtoTimestamp {
  seconds: bigint;
  nanos: number;
}

export interface ProtoDuration {
  seconds: bigint;
  nanos: number;
}

function readCanonicalU64Varint(
  view: DataView,
  off: number,
): { raw: bigint; nextOff: number } {
  let acc = 0n;
  for (let i = 0; i < 10; i++) {
    const pos = off + i;
    if (pos >= view.byteLength) {
      throw new Error(`Truncated Protobuf varint at offset ${off}`);
    }
    const b = view.getUint8(pos);
    if (i === 9 && b > 0x01) {
      throw new Error("Protobuf 64-bit varint overflow in 10th byte");
    }
    acc |= BigInt(b & 0x7f) << BigInt(7 * i);
    if ((b & 0x80) === 0) {
      if (i > 0 && b === 0x00) {
        throw new Error(`Non-canonical overlong varint trailing 0x00 at offset ${off}`);
      }
      return { raw: acc, nextOff: pos + 1 };
    }
  }
  throw new Error(`Varint exceeds 10 bytes at offset ${off}`);
}

function decodeTwosComplementInt32(rawU64: bigint): number {
  const signed64 = BigInt.asIntN(64, rawU64);
  if (signed64 < -2_147_483_648n || signed64 > 2_147_483_647n) {
    throw new Error(`Protobuf int32 varint out of 32-bit signed range: ${signed64}`);
  }
  return Number(signed64);
}

function parseSecondsAndNanos(buf: Uint8Array): { seconds: bigint; nanos: number } {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  let seconds = 0n;
  let nanos = 0;
  let off = 0;

  while (off < view.byteLength) {
    const tagRes = readCanonicalU64Varint(view, off);
    if (tagRes.raw > 0xffffffffn) {
      throw new Error("Protobuf tag exceeds uint32");
    }
    const tag = Number(tagRes.raw);
    off = tagRes.nextOff;

    if (tag === 0x08) {
      const valRes = readCanonicalU64Varint(view, off);
      seconds = BigInt.asIntN(64, valRes.raw);
      off = valRes.nextOff;
    } else if (tag === 0x10) {
      const valRes = readCanonicalU64Varint(view, off);
      nanos = decodeTwosComplementInt32(valRes.raw);
      off = valRes.nextOff;
    } else {
      throw new Error(`Unexpected wire tag 0x${tag.toString(16)} in Timestamp/Duration`);
    }
  }

  return { seconds, nanos };
}

export function parseProtoTimestamp(buf: Uint8Array): ProtoTimestamp {
  const { seconds, nanos } = parseSecondsAndNanos(buf);
  if (seconds < MIN_TS_SEC || seconds > MAX_TS_SEC) {
    throw new Error(`Timestamp.seconds ${seconds} outside [0001-01-01, 9999-12-31]`);
  }
  if (nanos < 0 || nanos > 999_999_999) {
    throw new Error(`Timestamp.nanos ${nanos} outside [0, 999999999]`);
  }
  return { seconds, nanos };
}

export function parseProtoDuration(buf: Uint8Array): ProtoDuration {
  const { seconds, nanos } = parseSecondsAndNanos(buf);
  if (seconds < -MAX_DUR_SEC || seconds > MAX_DUR_SEC) {
    throw new Error(`Duration.seconds ${seconds} outside +-10000 years`);
  }
  if (nanos < -999_999_999 || nanos > 999_999_999) {
    throw new Error(`Duration.nanos ${nanos} outside [-999999999, 999999999]`);
  }
  if ((seconds > 0n && nanos < 0) || (seconds < 0n && nanos > 0)) {
    throw new Error(`Duration sign mismatch: seconds=${seconds}, nanos=${nanos}`);
  }
  return { seconds, nanos };
}
