```go
package mqttv5pub

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"strings"
	"unicode/utf8"
)

var minVarint = [5]uint32{0, 0, 128, 16_384, 2_097_152}

type PublishPacket struct {
	DUP             bool
	QoS             uint8
	Retain          bool
	TopicName       string
	PacketID        uint16
	PayloadFormat   *uint8
	MessageExpiry   *uint32
	TopicAlias      *uint16
	ResponseTopic   string
	CorrelationData []byte
	SubscriptionIDs []uint32
	UserProperties  [][2]string
	Payload         []byte
}

func readVarint(buf []byte) (uint32, int, error) {
	var val uint32
	var mul uint32 = 1
	for i := 0; i < 4; i++ {
		if i >= len(buf) {
			return 0, 0, errors.New("mqttv5: truncated varint")
		}
		b := buf[i]
		val += uint32(b&0x7F) * mul
		if (b & 0x80) == 0 {
			w := i + 1
			if val < minVarint[w] {
				return 0, 0, errors.New("mqttv5: overlong non-canonical varint")
			}
			return val, w, nil
		}
		mul *= 128
	}
	return 0, 0, errors.New("mqttv5: varint > 4 bytes")
}

func validateMQTTStringRunes(raw []byte) (string, error) {
	if !utf8.Valid(raw) {
		return "", errors.New("mqttv5: invalid UTF-8 byte sequence")
	}
	s := string(raw)
	for _, r := range s {
		if r <= 0x001F || (r >= 0x007F && r <= 0x009F) {
			return "", fmt.Errorf("mqttv5: forbidden control codepoint U+%04X", r)
		}
		if (r >= 0xFDD0 && r <= 0xFDEF) || (r&0xFFFE) == 0xFFFE {
			return "", fmt.Errorf("mqttv5: forbidden Unicode noncharacter U+%04X", r)
		}
	}
	return s, nil
}

func readStrictUTF8Field(buf []byte) (string, int, error) {
	if len(buf) < 2 {
		return "", 0, errors.New("mqttv5: truncated string length")
	}
	n := int(binary.BigEndian.Uint16(buf[0:2]))
	if len(buf)-2 < n {
		return "", 0, errors.New("mqttv5: truncated string payload")
	}
	s, err := validateMQTTStringRunes(buf[2 : 2+n])
	if err != nil {
		return "", 0, err
	}
	return s, 2 + n, nil
}

func ParsePublishPacket(pkt []byte) (*PublishPacket, error) {
	if len(pkt) < 4 {
		return nil, errors.New("mqttv5: packet < 4 bytes")
	}
	b0 := pkt[0]
	if (b0 >> 4) != 3 {
		return nil, fmt.Errorf("mqttv5: expected PUBLISH type 3, got %d", b0>>4)
	}
	dup := (b0 & 0x08) != 0
	qos := (b0 >> 1) & 0x03
	retain := (b0 & 0x01) != 0
	if qos == 3 {
		return nil, errors.New("mqttv5: Malformed Packet (QoS 3 forbidden)")
	}
	if qos == 0 && dup {
		return nil, errors.New("mqttv5: Protocol Error (DUP=1 with QoS=0)")
	}

	remLen, nRem, err := readVarint(pkt[1:])
	if err != nil {
		return nil, err
	}
	off := 1 + nRem
	if off+int(remLen) != len(pkt) {
		return nil, errors.New("mqttv5: Remaining Length mismatch")
	}

	topic, nTop, err := readStrictUTF8Field(pkt[off:])
	if err != nil {
		return nil, err
	}
	if strings.ContainsAny(topic, "+#") {
		return nil, errors.New("mqttv5: Protocol Error (wildcards in PUBLISH Topic Name)")
	}
	off += nTop

	var pktID uint16
	if qos > 0 {
		if len(pkt)-off < 2 {
			return nil, errors.New("mqttv5: missing Packet Identifier for QoS > 0")
		}
		pktID = binary.BigEndian.Uint16(pkt[off : off+2])
		if pktID == 0 {
			return nil, errors.New("mqttv5: Packet Identifier 0 forbidden")
		}
		off += 2
	}

	propLen, nProp, err := readVarint(pkt[off:])
	if err != nil {
		return nil, err
	}
	off += nProp
	propEnd := off + int(propLen)
	if propEnd > len(pkt) {
		return nil, errors.New("mqttv5: PUBLISH properties overrun packet")
	}

	out := &PublishPacket{
		DUP:       dup,
		QoS:       qos,
		Retain:    retain,
		TopicName: topic,
		PacketID:  pktID,
	}
	hasRespTopic, hasCorr := false, false

	for off < propEnd {
		pid := pkt[off]
		off++
		switch pid {
		case 0x01:
			if out.PayloadFormat != nil || off >= propEnd || pkt[off] > 1 {
				return nil, errors.New("mqttv5: invalid or duplicate Payload Format Indicator")
			}
			v := pkt[off]
			off++
			out.PayloadFormat = &v
		case 0x02:
			if out.MessageExpiry != nil || propEnd-off < 4 {
				return nil, errors.New("mqttv5: invalid or duplicate Message Expiry Interval")
			}
			v := binary.BigEndian.Uint32(pkt[off : off+4])
			off += 4
			out.MessageExpiry = &v
		case 0x08:
			if hasRespTopic {
				return nil, errors.New("mqttv5: duplicate Response Topic")
			}
			rt, n, err := readStrictUTF8Field(pkt[off:propEnd])
			if err != nil || strings.ContainsAny(rt, "+#") {
				return nil, errors.New("mqttv5: invalid Response Topic")
			}
			out.ResponseTopic = rt
			hasRespTopic = true
			off += n
		case 0x09:
			if hasCorr || propEnd-off < 2 {
				return nil, errors.New("mqttv5: duplicate or truncated Correlation Data")
			}
			cLen := int(binary.BigEndian.Uint16(pkt[off : off+2]))
			off += 2
			if propEnd-off < cLen {
				return nil, errors.New("mqttv5: Correlation Data overruns properties")
			}
			out.CorrelationData = bytes.Clone(pkt[off : off+cLen])
			hasCorr = true
			off += cLen
		case 0x0B:
			subID, n, err := readVarint(pkt[off:propEnd])
			if err != nil || subID == 0 {
				return nil, errors.New("mqttv5: invalid Subscription Identifier")
			}
			out.SubscriptionIDs = append(out.SubscriptionIDs, subID)
			off += n
		case 0x23:
			if out.TopicAlias != nil || propEnd-off < 2 {
				return nil, errors.New("mqttv5: duplicate or truncated Topic Alias")
			}
			alias := binary.BigEndian.Uint16(pkt[off : off+2])
			if alias == 0 {
				return nil, errors.New("mqttv5: Topic Alias 0 forbidden")
			}
			out.TopicAlias = &alias
			off += 2
		case 0x26:
			k, nk, err := readStrictUTF8Field(pkt[off:propEnd])
			if err != nil {
				return nil, err
			}
			v, nv, err := readStrictUTF8Field(pkt[off+nk : propEnd])
			if err != nil {
				return nil, err
			}
			out.UserProperties = append(out.UserProperties, [2]string{k, v})
			off += nk + nv
		default:
			return nil, fmt.Errorf("mqttv5: illegal PUBLISH property 0x%02x", pid)
		}
	}

	if out.TopicName == "" && out.TopicAlias == nil {
		return nil, errors.New("mqttv5: Protocol Error (empty Topic Name without Topic Alias)")
	}

	payload := pkt[propEnd:]
	if out.PayloadFormat != nil && *out.PayloadFormat == 1 {
		if !utf8.Valid(payload) {
			return nil, errors.New("mqttv5: Payload Format Indicator=1 but payload is invalid UTF-8")
		}
	}
	out.Payload = bytes.Clone(payload)
	return out, nil
}
