```ts
const asciiDecoder = new TextDecoder("utf-8", { fatal: true });

export interface OcspStatusRequest {
  responderIds: Uint8Array[];
  requestExtensionsDer: Uint8Array;
}

export interface ParsedTlsDiscoveryExts {
  serverName?: string;
  alpnProtocols?: string[];
  ocspStatusRequest?: OcspStatusRequest;
}

function isValidSniHostname(host: string): boolean {
  if (host.length === 0 || host.length > 253 || host.endsWith(".")) {
    return false;
  }
  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host) || host.includes(":")) {
    return false;
  }
  const labels = host.split(".");
  for (const lbl of labels) {
    if (lbl.length === 0 || lbl.length > 63 || lbl.startsWith("-") || lbl.endsWith("-")) {
      return false;
    }
    if (!/^[A-Za-z0-9-]+$/.test(lbl)) {
      return false;
    }
  }
  return true;
}

function parseSniExt(view: DataView, buf: Uint8Array, off: number, extLen: number): string {
  if (extLen < 5) {
    throw new Error("decode_error: SNI extension < 5 bytes");
  }
  const listLen = view.getUint16(off, false);
  if (2 + listLen !== extLen) {
    throw new Error("decode_error: SNI ServerNameList length != ext_len - 2");
  }

  let cur = off + 2;
  const end = off + extLen;
  let host: string | null = null;

  while (cur < end) {
    if (end - cur < 3) {
      throw new Error("decode_error: truncated ServerName entry");
    }
    const nameType = view.getUint8(cur);
    const nameLen = view.getUint16(cur + 1, false);
    cur += 3;
    if (nameType !== 0x00) {
      throw new Error(`illegal_parameter: unsupported SNI NameType 0x${nameType.toString(16)}`);
    }
    if (host !== null) {
      throw new Error("illegal_parameter: duplicate host_name in SNI");
    }
    if (nameLen === 0 || cur + nameLen > end) {
      throw new Error("decode_error: invalid SNI host_name length");
    }
    const candidate = asciiDecoder.decode(buf.subarray(cur, cur + nameLen));
    if (!isValidSniHostname(candidate)) {
      throw new Error(`illegal_parameter: invalid RFC 6066 SNI hostname '${candidate}'`);
    }
    host = candidate;
    cur += nameLen;
  }

  if (host === null) {
    throw new Error("decode_error: empty SNI ServerNameList");
  }
  return host;
}

function parseAlpnExt(view: DataView, buf: Uint8Array, off: number, extLen: number): string[] {
  if (extLen < 4) {
    throw new Error("decode_error: ALPN extension < 4 bytes");
  }
  const listLen = view.getUint16(off, false);
  if (2 + listLen !== extLen) {
    throw new Error("decode_error: ALPN ProtocolNameList length != ext_len - 2");
  }

  const protos: string[] = [];
  let cur = off + 2;
  const end = off + extLen;
  while (cur < end) {
    const pLen = view.getUint8(cur++);
    if (pLen === 0 || cur + pLen > end) {
      throw new Error("decode_error: empty or truncated ALPN ProtocolName");
    }
    protos.push(asciiDecoder.decode(buf.subarray(cur, cur + pLen)));
    cur += pLen;
  }
  return protos;
}

function parseOcspStatusRequest(
  view: DataView,
  buf: Uint8Array,
  off: number,
  extLen: number,
): OcspStatusRequest {
  if (extLen < 5) {
    throw new Error("decode_error: status_request extension < 5 bytes");
  }
  const statusType = view.getUint8(off);
  if (statusType !== 0x01) {
    throw new Error(`illegal_parameter: unsupported CertificateStatusType ${statusType}`);
  }

  const respListLen = view.getUint16(off + 1, false);
  const reqExtLenOff = off + 3 + respListLen;
  if (reqExtLenOff + 2 > off + extLen) {
    throw new Error("decode_error: responder_id_list overruns status_request");
  }

  const responderIds: Uint8Array[] = [];
  let rCur = off + 3;
  while (rCur < reqExtLenOff) {
    if (reqExtLenOff - rCur < 2) {
      throw new Error("decode_error: truncated ResponderID length");
    }
    const idLen = view.getUint16(rCur, false);
    rCur += 2;
    if (idLen === 0 || rCur + idLen > reqExtLenOff) {
      throw new Error("decode_error: empty or truncated OCSP ResponderID");
    }
    responderIds.push(buf.subarray(rCur, rCur + idLen));
    rCur += idLen;
  }

  const reqExtLen = view.getUint16(reqExtLenOff, false);
  if (1 + 2 + respListLen + 2 + reqExtLen !== extLen) {
    throw new Error("decode_error: status_request nested vector lengths != ext_len");
  }
  const reqExtStart = reqExtLenOff + 2;
  const requestExtensionsDer = buf.subarray(reqExtStart, reqExtStart + reqExtLen);
  return { responderIds, requestExtensionsDer };
}

export function parseClientHelloDiscoveryExtensions(
  extBlock: Uint8Array,
): ParsedTlsDiscoveryExts {
  if (extBlock.byteLength < 2) {
    throw new Error("decode_error: truncated extensions block");
  }
  const view = new DataView(extBlock.buffer, extBlock.byteOffset, extBlock.byteLength);
  const blockLen = view.getUint16(0, false);
  if (2 + blockLen !== extBlock.byteLength) {
    throw new Error("decode_error: outer extensions length mismatch");
  }

  const seen = new Set<number>();
  const out: ParsedTlsDiscoveryExts = {};
  let off = 2;

  while (off < extBlock.byteLength) {
    if (extBlock.byteLength - off < 4) {
      throw new Error("decode_error: truncated extension header");
    }
    const extType = view.getUint16(off, false);
    const extLen = view.getUint16(off + 2, false);
    off += 4;
    if (off + extLen > extBlock.byteLength) {
      throw new Error(`decode_error: extension 0x${extType.toString(16)} overruns block`);
    }
    if (seen.has(extType)) {
      throw new Error(`illegal_parameter: duplicate extension 0x${extType.toString(16)}`);
    }
    seen.add(extType);

    if (extType === 0x0000) {
      out.serverName = parseSniExt(view, extBlock, off, extLen);
    } else if (extType === 0x0005) {
      out.ocspStatusRequest = parseOcspStatusRequest(view, extBlock, off, extLen);
    } else if (extType === 0x0010) {
      out.alpnProtocols = parseAlpnExt(view, extBlock, off, extLen);
    }
    off += extLen;
  }

  return out;
}
