```go
package stunwire

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

const StunMagicCookie uint32 = 0x2112A442

type MessageClass uint8

const (
	ClassRequest         MessageClass = 0b00
	ClassIndication      MessageClass = 0b01
	ClassSuccessResponse MessageClass = 0b10
	ClassErrorResponse   MessageClass = 0b11
)

type DecodedSTUNBinding struct {
	RawType          uint16
	Class            MessageClass
	Method           uint16
	TransactionID    [12]byte
	MappedAddress    *netip.AddrPort
	XorMappedAddress *netip.AddrPort
}

func DeinterleaveType(mtype uint16) (MessageClass, uint16, error) {
	if (mtype & 0xC000) != 0 {
		return 0, 0, errors.New("stun: top two bits of Message Type must be 0b00")
	}
	cls := MessageClass(((mtype & 0x0010) >> 4) | ((mtype & 0x0100) >> 7))
	method := (mtype & 0x000F) | ((mtype & 0x00E0) >> 1) | ((mtype & 0x3E00) >> 2)
	return cls, method, nil
}

func decodeAddrAttr(val []byte, xorMask *[16]byte) (netip.AddrPort, error) {
	var zero netip.AddrPort
	if len(val) < 4 || val[0] != 0x00 {
		return zero, errors.New("stun: malformed address attribute header or non-zero byte 0")
	}
	family := val[1]
	port := binary.BigEndian.Uint16(val[2:4])
	if xorMask != nil {
		port ^= uint16(StunMagicCookie >> 16)
	}

	switch family {
	case 0x01:
		if len(val) != 8 {
			return zero, fmt.Errorf("stun: IPv4 address attribute length %d != 8", len(val))
		}
		var ip4 [4]byte
		copy(ip4[:], val[4:8])
		if xorMask != nil {
			for i := range 4 {
				ip4[i] ^= xorMask[i]
			}
		}
		return netip.AddrPortFrom(netip.AddrFrom4(ip4), port), nil

	case 0x02:
		if len(val) != 20 {
			return zero, fmt.Errorf("stun: IPv6 address attribute length %d != 20", len(val))
		}
		var ip16 [16]byte
		copy(ip16[:], val[4:20])
		if xorMask != nil {
			for i := range 16 {
				ip16[i] ^= xorMask[i]
			}
		}
		return netip.AddrPortFrom(netip.AddrFrom16(ip16), port), nil

	default:
		return zero, fmt.Errorf("stun: unsupported address family 0x%02x", family)
	}
}

func ParseSTUNBindingMessage(pkt []byte) (*DecodedSTUNBinding, error) {
	if len(pkt) < 20 {
		return nil, errors.New("stun: packet < 20-byte header")
	}
	rawType := binary.BigEndian.Uint16(pkt[0:2])
	cls, method, err := DeinterleaveType(rawType)
	if err != nil {
		return nil, err
	}

	msgLen := int(binary.BigEndian.Uint16(pkt[2:4]))
	cookie := binary.BigEndian.Uint32(pkt[4:8])
	if cookie != StunMagicCookie {
		return nil, fmt.Errorf("stun: bad magic cookie 0x%08x", cookie)
	}
	if msgLen%4 != 0 || 20+msgLen != len(pkt) {
		return nil, errors.New("stun: invalid or unaligned Message Length")
	}

	var out DecodedSTUNBinding
	out.RawType = rawType
	out.Class = cls
	out.Method = method
	copy(out.TransactionID[:], pkt[8:20])

	var xorMask [16]byte
	copy(xorMask[:], pkt[4:20]) // cookie[4] || txID[12]

	off := 20
	for off < len(pkt) {
		if len(pkt)-off < 4 {
			return nil, errors.New("stun: truncated attribute TLV")
		}
		aType := binary.BigEndian.Uint16(pkt[off : off+2])
		aLen := int(binary.BigEndian.Uint16(pkt[off+2 : off+4]))
		vStart := off + 4
		vEnd := vStart + aLen
		paddedEnd := vStart + ((aLen + 3) &^ 3)
		if paddedEnd > len(pkt) {
			return nil, fmt.Errorf("stun: attribute 0x%04x overruns packet", aType)
		}
		for p := vEnd; p < paddedEnd; p++ {
			if pkt[p] != 0x00 {
				return nil, fmt.Errorf("stun: non-zero padding in attribute 0x%04x", aType)
			}
		}

		val := pkt[vStart:vEnd]
		switch aType {
		case 0x0001:
			ap, err := decodeAddrAttr(val, nil)
			if err != nil {
				return nil, err
			}
			out.MappedAddress = &ap
		case 0x0020:
			ap, err := decodeAddrAttr(val, &xorMask)
			if err != nil {
				return nil, err
			}
			out.XorMappedAddress = &ap
		}
		off = paddedEnd
	}
	return &out, nil
}
