```ts
const P256_ORDER = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;
const B64U_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
const B64U_LUT = new Int8Array(128).fill(-1);
for (let i = 0; i < B64U_ALPHABET.length; i++) {
  B64U_LUT[B64U_ALPHABET.charCodeAt(i)] = i;
}

const STANDARD_JWS_HEADERS = new Set([
  "alg", "jku", "jwk", "kid", "x5u", "x5c", "x5t", "x5t#S256", "typ", "cty", "crit",
]);

const utf8Strict = new TextDecoder("utf-8", { fatal: true });
const asciiEncoder = new TextEncoder();

export interface VerifiedRfc7797Header {
  alg: "ES256";
  b64: false;
  crit: ["b64"];
  kid?: string;
}

function decodeCanonicalBase64Url(seg: string): Uint8Array {
  if (seg.length === 0 || seg.length % 4 === 1) {
    throw new Error("Invalid unpadded Base64url length");
  }
  const out = new Uint8Array(Math.floor((seg.length * 6) / 8));
  let buf = 0;
  let bits = 0;
  let w = 0;

  for (let i = 0; i < seg.length; i++) {
    const c = seg.charCodeAt(i);
    const v = c < 128 ? B64U_LUT[c]! : -1;
    if (v < 0) {
      throw new Error(`Illegal Base64url character at index ${i}`);
    }
    buf = (buf << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[w++] = (buf >>> bits) & 0xff;
    }
  }
  if (bits > 0 && (buf & ((1 << bits) - 1)) !== 0) {
    throw new Error("Non-canonical Base64url: non-zero trailing padding bits");
  }
  return out;
}

function assertNoDuplicateTopLevelJsonKeys(jsonText: string): void {
  const keyRegex = /"((?:\\.|[^"\\])*)"\s*:/g;
  const seen = new Set<string>();
  let m: RegExpExecArray | null;
  while ((m = keyRegex.exec(jsonText)) !== null) {
    const key = JSON.parse(`"${m[1]}"`) as string;
    if (seen.has(key)) {
      throw new Error(`Duplicate JSON key '${key}' in JWS protected header`);
    }
    seen.add(key);
  }
}

function readBigUint256(view: DataView, off: number): bigint {
  return (
    (view.getBigUint64(off, false) << 192n) |
    (view.getBigUint64(off + 8, false) << 128n) |
    (view.getBigUint64(off + 16, false) << 64n) |
    view.getBigUint64(off + 24, false)
  );
}

export async function verifyRfc7797WebhookSignature(
  compactDetachedJws: string,
  rawWebhookBody: Uint8Array,
  publicKey: CryptoKey,
): Promise<VerifiedRfc7797Header> {
  const parts = compactDetachedJws.split(".");
  if (parts.length !== 3 || parts[1] !== "") {
    throw new Error("Detached JWS must follow '<protected>..<signature>' format");
  }

  const hdrBytes = decodeCanonicalBase64Url(parts[0]!);
  const sigBytes = decodeCanonicalBase64Url(parts[2]!);
  if (sigBytes.byteLength !== 64) {
    throw new Error(`ES256 signature must be 64 bytes (R||S), got ${sigBytes.byteLength}`);
  }

  const sigView = new DataView(sigBytes.buffer, sigBytes.byteOffset, 64);
  const r = readBigUint256(sigView, 0);
  const s = readBigUint256(sigView, 32);
  if (r < 1n || r >= P256_ORDER || s < 1n || s >= P256_ORDER) {
    throw new Error("ES256 signature scalar R or S outside [1, n-1]");
  }

  const hdrText = utf8Strict.decode(hdrBytes);
  assertNoDuplicateTopLevelJsonKeys(hdrText);
  const parsed = JSON.parse(hdrText) as Record<string, unknown>;
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("JWS protected header must be a JSON object");
  }
  if (parsed["alg"] !== "ES256") {
    throw new Error("JWS alg must equal 'ES256'");
  }
  if (parsed["b64"] !== false) {
    throw new Error("RFC 7797 unencoded webhook profile requires 'b64': false");
  }

  const crit = parsed["crit"];
  if (!Array.isArray(crit) || crit.length === 0) {
    throw new Error("RFC 7797 requires non-empty 'crit' array containing 'b64'");
  }
  const critSeen = new Set<string>();
  for (const item of crit) {
    if (typeof item !== "string" || item.length === 0) {
      throw new Error("Invalid non-string entry in 'crit'");
    }
    if (STANDARD_JWS_HEADERS.has(item)) {
      throw new Error(`RFC 7515 forbids standard header '${item}' inside 'crit'`);
    }
    if (critSeen.has(item)) {
      throw new Error(`Duplicate entry '${item}' in 'crit'`);
    }
    if (item !== "b64") {
      throw new Error(`Unsupported critical JWS extension '${item}'`);
    }
    critSeen.add(item);
  }

  const hdrAscii = asciiEncoder.encode(parts[0]!);
  const signingInput = new Uint8Array(hdrAscii.byteLength + 1 + rawWebhookBody.byteLength);
  signingInput.set(hdrAscii, 0);
  signingInput[hdrAscii.byteLength] = 0x2e; // '.'
  signingInput.set(rawWebhookBody, hdrAscii.byteLength + 1);

  const valid = await crypto.subtle.verify(
    { name: "ECDSA", hash: "SHA-256" },
    publicKey,
    sigBytes,
    signingInput,
  );
  if (!valid) {
    throw new Error("ES256 RFC 7797 detached signature verification failed");
  }

  return {
    alg: "ES256",
    b64: false,
    crit: ["b64"],
    ...(typeof parsed["kid"] === "string" ? { kid: parsed["kid"] } : {}),
  };
}
