```ts
const PGCOPY_MAGIC = new Uint8Array([
  0x50, 0x47, 0x43, 0x4f, 0x50, 0x59, 0x0a, 0xff, 0x0d, 0x0a, 0x00,
]);

export interface PgCopyTuple {
  oid?: number;
  columns: Array<Uint8Array | null>;
}

export interface ParsedPgCopyBinary {
  hasOids: boolean;
  lowFlags: number;
  headerExtension: Uint8Array;
  columnCount: number;
  tuples: PgCopyTuple[];
}

export function parsePgCopyBinaryStream(buf: Uint8Array): ParsedPgCopyBinary {
  if (buf.byteLength < 21) {
    throw new Error(`PGCOPY binary stream too short (${buf.byteLength} < 21 bytes)`);
  }
  for (let i = 0; i < 11; i++) {
    if (buf[i] !== PGCOPY_MAGIC[i]) {
      throw new Error(`Invalid PGCOPY binary signature byte at index ${i}`);
    }
  }

  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const flags = view.getUint32(11, false);
  if ((flags & 0xfffe0000) !== 0) {
    throw new Error(`Unrecognized critical PGCOPY header flags: 0x${flags.toString(16)}`);
  }
  const hasOids = (flags & 0x00010000) !== 0;
  const lowFlags = flags & 0xffff;

  const extLen = view.getUint32(15, false);
  if (extLen > 65_536 || 19 + extLen + 2 > buf.byteLength) {
    throw new Error(`Invalid or truncated PGCOPY header extension length ${extLen}`);
  }
  const headerExtension = buf.subarray(19, 19 + extLen);

  let off = 19 + extLen;
  let expectedCols: number | null = null;
  const tuples: PgCopyTuple[] = [];
  let sawTrailer = false;

  while (off < buf.byteLength) {
    if (buf.byteLength - off < 2) {
      throw new Error("Truncated PGCOPY tuple field_count");
    }
    const fieldCount = view.getInt16(off, false);
    off += 2;

    if (fieldCount === -1) {
      if (off !== buf.byteLength) {
        throw new Error(`Unexpected ${buf.byteLength - off} trailing bytes after PGCOPY -1 trailer`);
      }
      sawTrailer = true;
      break;
    }
    if (fieldCount < -1) {
      throw new Error(`Illegal negative PGCOPY field_count ${fieldCount}`);
    }
    if (expectedCols === null) {
      expectedCols = fieldCount;
    } else if (fieldCount !== expectedCols) {
      throw new Error(`Inconsistent PGCOPY tuple column count ${fieldCount} != ${expectedCols}`);
    }

    let rowOid: number | undefined;
    if (hasOids) {
      if (buf.byteLength - off < 4) {
        throw new Error("Truncated PGCOPY tuple OID");
      }
      rowOid = view.getUint32(off, false);
      off += 4;
    }

    const columns: Array<Uint8Array | null> = [];
    for (let c = 0; c < fieldCount; c++) {
      if (buf.byteLength - off < 4) {
        throw new Error("Truncated PGCOPY column length");
      }
      const colLen = view.getInt32(off, false);
      off += 4;
      if (colLen === -1) {
        columns.push(null);
        continue;
      }
      if (colLen < -1 || off + colLen > buf.byteLength) {
        throw new Error(`Invalid or truncated PGCOPY column length ${colLen}`);
      }
      columns.push(buf.subarray(off, off + colLen));
      off += colLen;
    }

    tuples.push({
      ...(rowOid !== undefined ? { oid: rowOid } : {}),
      columns,
    });
  }

  if (!sawTrailer) {
    throw new Error("PGCOPY binary stream missing mandatory 0xFFFF (-1) trailer");
  }

  return {
    hasOids,
    lowFlags,
    headerExtension,
    columnCount: expectedCols ?? 0,
    tuples,
  };
}
```

