export interface PivX509DataObject {
  certificateBytes: Uint8Array;
  gzipCompressed: boolean;
  mscuid?: Uint8Array;
}

function readCanonicalBerLength(
  view: DataView,
  off: number,
  end: number,
): { length: number; nextOff: number } {
  if (off >= end) {
    throw new Error("Truncated PIV BER-TLV length");
  }
  const b0 = view.getUint8(off);
  if (b0 < 0x80) {
    return { length: b0, nextOff: off + 1 };
  }
  if (b0 === 0x81) {
    if (off + 2 > end) throw new Error("Truncated 0x81 BER length");
    const v = view.getUint8(off + 1);
    if (v < 0x80) throw new Error(`Non-canonical 0x81 BER length ${v} < 128`);
    return { length: v, nextOff: off + 2 };
  }
  if (b0 === 0x82) {
    if (off + 3 > end) throw new Error("Truncated 0x82 BER length");
    const v = view.getUint16(off + 1, false);
    if (v < 0x0100) throw new Error(`Non-canonical 0x82 BER length ${v} < 256`);
    return { length: v, nextOff: off + 3 };
  }
  throw new Error(`Unsupported or indefinite PIV BER length prefix 0x${b0.toString(16)}`);
}

export function parsePivX509Container(buf: Uint8Array): PivX509DataObject {
  if (buf.byteLength < 8) {
    throw new Error("Truncated PIV Tag 53 X.509 container");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  if (view.getUint8(0) !== 0x53) {
    throw new Error(`Expected PIV outer Tag 0x53, got 0x${view.getUint8(0).toString(16)}`);
  }

  const outerLen = readCanonicalBerLength(view, 1, buf.byteLength);
  if (outerLen.nextOff + outerLen.length !== buf.byteLength) {
    throw new Error("PIV Tag 53 length does not match buffer byteLength");
  }

  let off = outerLen.nextOff;
  const end = buf.byteLength;
  const seen = new Set<number>();

  let certBytes: Uint8Array | null = null;
  let gzipCompressed: boolean | null = null;
  let sawEdc = false;
  let mscuid: Uint8Array | undefined;

  while (off < end) {
    const tag = view.getUint8(off++);
    if (seen.has(tag)) {
      throw new Error(`Duplicate PIV inner tag 0x${tag.toString(16)}`);
    }
    seen.add(tag);

    const lenInfo = readCanonicalBerLength(view, off, end);
    const valStart = lenInfo.nextOff;
    const valEnd = valStart + lenInfo.length;
    if (valEnd > end) {
      throw new Error(`PIV inner tag 0x${tag.toString(16)} overruns Tag 53 container`);
    }
    const slice = buf.subarray(valStart, valEnd);
    off = valEnd;

    if (tag === 0x70) {
      if (slice.byteLength < 2) {
        throw new Error("PIV Tag 70 Certificate payload too short");
      }
      certBytes = slice;
    } else if (tag === 0x71) {
      if (slice.byteLength !== 1) {
        throw new Error("PIV Tag 71 CertInfo must be exact 1 byte");
      }
      const infoByte = slice[0]!;
      if ((infoByte & 0xfe) !== 0) {
        throw new Error(`Non-zero reserved bits in PIV CertInfo: 0x${infoByte.toString(16)}`);
      }
      gzipCompressed = (infoByte & 0x01) === 1;
    } else if (tag === 0x72) {
      if (slice.byteLength < 1 || slice.byteLength > 255) {
        throw new Error("Invalid PIV Tag 72 MSCUID length");
      }
      mscuid = slice;
    } else if (tag === 0xfe) {
      if (slice.byteLength !== 0) {
        throw new Error("PIV Tag FE ErrorDetectionCode must have length 0");
      }
      sawEdc = true;
    } else {
      throw new Error(`Unexpected tag 0x${tag.toString(16)} in PIV X.509 container`);
    }
  }

  if (certBytes === null || gzipCompressed === null || !sawEdc) {
    throw new Error("PIV X.509 container missing mandatory Tag 70, 71, or FE");
  }

  if (gzipCompressed) {
    if (certBytes[0] !== 0x1f || certBytes[1] !== 0x8b) {
      throw new Error("CertInfo indicates GZIP=1, but Tag 70 lacks 0x1f8b GZIP magic");
    }
  } else if (certBytes[0] !== 0x30) {
    throw new Error("CertInfo indicates uncompressed DER, but Tag 70 lacks 0x30 ASN.1 SEQUENCE");
  }

  return {
    certificateBytes: certBytes,
    gzipCompressed,
    ...(mscuid ? { mscuid } : {}),
  };
}
