import struct
from dataclasses import dataclass
from typing import Literal

BGP_MARKER = b"\xff" * 16
AS_TRANS = 23456


class BGPWireValidationError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class ValidatedBGPOpenASN:
    kind: Literal["OPEN"]
    effective_asn: int
    header_my_as: int
    four_octet_capable: bool
    hold_time: int
    bgp_id: str


@dataclass(frozen=True, slots=True)
class ValidatedBGPNotification:
    kind: Literal["NOTIFICATION"]
    error_code: int
    error_subcode: int
    raw_data: bytes
    shutdown_communication: str | None


def parse_bgp_open_or_notification(
    pkt: bytes | bytearray | memoryview,
) -> ValidatedBGPOpenASN | ValidatedBGPNotification:
    mv = memoryview(pkt)
    if len(mv) < 19 or len(mv) > 4096:
        raise BGPWireValidationError(f"BGP packet length {len(mv)} outside [19, 4096]")
    if bytes(mv[:16]) != BGP_MARKER:
        raise BGPWireValidationError("invalid 16-byte BGP 0xFF Marker")

    msg_len, msg_type = struct.unpack_from(">HB", mv, 16)
    if msg_len != len(mv):
        raise BGPWireValidationError(f"BGP header length {msg_len} != buffer {len(mv)}")

    if msg_type == 3:  # NOTIFICATION
        if msg_len < 21:
            raise BGPWireValidationError("BGP NOTIFICATION shorter than 21 bytes")
        err_code, err_subcode = mv[19], mv[20]
        if not (1 <= err_code <= 6):
            raise BGPWireValidationError(f"invalid BGP NOTIFICATION error_code {err_code}")
        data = bytes(mv[21:])
        shutdown_msg: str | None = None

        if err_code == 6 and err_subcode in (2, 4) and len(data) > 0:
            comm_len = data[0]
            if 1 + comm_len != len(data):
                raise BGPWireValidationError("RFC 9003 Shutdown Communication length mismatch")
            try:
                shutdown_msg = data[1:].decode("utf-8", errors="strict")
            except UnicodeDecodeError as exc:
                raise BGPWireValidationError("invalid UTF-8 in RFC 9003 Shutdown Communication") from exc

        return ValidatedBGPNotification(
            kind="NOTIFICATION",
            error_code=err_code,
            error_subcode=err_subcode,
            raw_data=data,
            shutdown_communication=shutdown_msg,
        )

    if msg_type != 1:
        raise BGPWireValidationError(f"expected OPEN (1) or NOTIFICATION (3), got {msg_type}")

    if msg_len < 29:
        raise BGPWireValidationError("BGP OPEN shorter than 29 bytes")
    ver, my_as, hold_time = struct.unpack_from(">BHH", mv, 19)
    if ver != 4 or hold_time in (1, 2):
        raise BGPWireValidationError(f"invalid BGP OPEN version={ver} or hold_time={hold_time}")
    if my_as == 0:
        raise BGPWireValidationError("RFC 7607 forbids AS 0 in BGP OPEN")

    id_b = mv[24:28]
    if bytes(id_b) == b"\x00\x00\x00\x00" or id_b[0] >= 224:
        raise BGPWireValidationError("invalid BGP Identifier")
    bgp_id = ".".join(str(x) for x in id_b)

    opt_len = mv[28]
    if 29 + opt_len != msg_len:
        raise BGPWireValidationError("BGP OPEN Opt Parm Len mismatch")

    asn4: int | None = None
    off = 29
    while off < msg_len:
        if msg_len - off < 2:
            raise BGPWireValidationError("truncated Optional Parameter")
        p_type, p_len = mv[off], mv[off + 1]
        off += 2
        if p_type != 2 or p_len == 0 or off + p_len > msg_len:
            raise BGPWireValidationError("invalid Capabilities Optional Parameter")

        c_off, c_end = off, off + p_len
        while c_off < c_end:
            if c_end - c_off < 2:
                raise BGPWireValidationError("truncated Capability TLV")
            cap_code, cap_len = mv[c_off], mv[c_off + 1]
            c_off += 2
            if c_off + cap_len > c_end:
                raise BGPWireValidationError("Capability TLV overruns parameter")
