            c_off += cap_len
        off = c_end

    if asn4 is not None:
        if asn4 == 0:
            raise BGPWireValidationError("RFC 7607 forbids AS 0 in Cap 65")
        if asn4 > 65535 and my_as != AS_TRANS:
            raise BGPWireValidationError(
                f"RFC 6793 violation: 4-octet ASN {asn4} > 65535 requires my_as=23456, got {my_as}"
