        if asn4 <= 65535 and my_as != asn4:
            raise BGPWireValidationError(
                f"RFC 6793 violation: 2-octet-mappable Cap 65 ({asn4}) != my_as ({my_as})"
            )
        effective = asn4
    else:
        if my_as == AS_TRANS:
            raise BGPWireValidationError("my_as=23456 (AS_TRANS) without 4-octet ASN Capability 65")
        effective = my_as

    return ValidatedBGPOpenASN(
        kind="OPEN",
        effective_asn=effective,
        header_my_as=my_as,
        four_octet_capable=(asn4 is not None),
        hold_time=hold_time,
        bgp_id=bgp_id,
    )
