        throw new Error("decode_error: early_data (0x002a) in EncryptedExtensions must be empty");
      }
      earlyDataAccepted = true;
    }

    off += extLen;
  }

  return {
    sniAcknowledged,
    ...(selectedAlpn !== undefined ? { selectedAlpn } : {}),
    ...(recordSizeLimit !== undefined ? { recordSizeLimit } : {}),
    earlyDataAccepted,
  };
}
