		extBuilder.WriteString(evVal)
	}

	return fmt.Sprintf(
		"CEF:%d|%s|%s|%s|%s|%s|%s|%s",
		ev.Version,
		escHdrs[0], escHdrs[1], escHdrs[2], escHdrs[3], escHdrs[4],
		ev.Severity,
		extBuilder.String(),
	), nil
}

func isEscapedAt(s string, pos int) bool {
	slashes := 0
	for i := pos - 1; i >= 0 && s[i] == '\\'; i-- {
		slashes++
	}
	return (slashes % 2) == 1
}

func unescapeExtVal(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case '\\':
				b.WriteByte('\\')
				i++
				continue
			case '=':
				b.WriteByte('=')
				i++
				continue
			case 'n':
				b.WriteByte('\n')
				i++
				continue
			case 'r':
				b.WriteByte('\r')
				i++
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func ParseCEF(line string) (*Event, error) {
	if !utf8.ValidString(line) || strings.ContainsAny(line, "\r\n\x00") {
		return nil, errors.New("cef: invalid UTF-8 or raw CR/LF/NUL in wire frame")
	}
	idx := strings.Index(line, "CEF:")
	if idx < 0 || (idx > 0 && line[idx-1] != ' ') {
		return nil, errors.New("cef: missing 'CEF:' header")
	}

	rest := line[idx+4:]
	hdrs := make([]string, 0, 7)
	var cur strings.Builder
	extOff := -1

	for i := 0; i < len(rest); i++ {
		if rest[i] == '\\' && i+1 < len(rest) && (rest[i+1] == '|' || rest[i+1] == '\\') {
			cur.WriteByte(rest[i+1])
			i++
			continue
		}
		if rest[i] == '|' {
			hdrs = append(hdrs, cur.String())
			cur.Reset()
			if len(hdrs) == 7 {
				extOff = i + 1
				break
			}
			continue
		}
		cur.WriteByte(rest[i])
	}
	if len(hdrs) != 7 || extOff < 0 {
		return nil, errors.New("cef: expected 7 header pipes")
	}
	ver, err := strconv.Atoi(hdrs[0])
	if err != nil || (ver != 0 && ver != 1) || !checkSeverity(hdrs[6]) {
		return nil, errors.New("cef: invalid version or severity")
	}

	extStr := strings.TrimLeft(rest[extOff:], " ")
	exts := make(map[string]string)
	if extStr != "" {
		type anchor struct{ ks, eq int }
		var anchors []anchor
		for i := 0; i < len(extStr); {
			if i == 0 || (extStr[i-1] == ' ' && !isEscapedAt(extStr, i-1)) {
				ks := i
				for i < len(extStr) && isValidKey(extStr[i:i+1]) {
					i++
				}
				if i > ks && i < len(extStr) && extStr[i] == '=' {
					anchors = append(anchors, anchor{ks: ks, eq: i})
					i++
					continue
				}
				if i == ks {
					i++
				}
			} else {
				i++
			}
		}
		if len(anchors) == 0 || anchors[0].ks != 0 {
			return nil, errors.New("cef: malformed extension tail")
		}
		for aIdx, a := range anchors {
			key := extStr[a.ks:a.eq]
			if _, dup := exts[key]; dup {
				return nil, fmt.Errorf("cef: duplicate extension key %q", key)
			}
			vs := a.eq + 1
			ve := len(extStr)
			if aIdx+1 < len(anchors) {
				ve = anchors[aIdx+1].ks - 1
				for ve > vs && extStr[ve-1] == ' ' && !isEscapedAt(extStr, ve-1) {
					ve--
				}
			}
			exts[key] = unescapeExtVal(extStr[vs:ve])
		}
	}

	return &Event{
		Version:       ver,
		Vendor:        hdrs[1],
		Product:       hdrs[2],
		DeviceVersion: hdrs[3],
		EventClassID:  hdrs[4],
		Name:          hdrs[5],
		Severity:      hdrs[6],
		Extensions:    exts,
	}, nil
}
