package apngwire

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
)

var pngMagic = [8]byte{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}

type FrameControl struct {
	SeqNumber uint32
	Width     uint32
	Height    uint32
	XOffset   uint32
	YOffset   uint32
	DelayNum  uint16
	DelayDen  uint16
	DisposeOp uint8
	BlendOp   uint8
	DataBytes int
}

type ParsedAPNG struct {
	CanvasWidth  uint32
	CanvasHeight uint32
	NumFrames    uint32
	NumPlays     uint32
	Frames       []FrameControl
}

func ParseAPNGStream(buf []byte) (*ParsedAPNG, error) {
	if len(buf) < 8 || !bytes.Equal(buf[:8], pngMagic[:]) {
		return nil, errors.New("apng: invalid PNG signature")
	}

	var out ParsedAPNG
	off := 8
	sawIHDR, sawACTL, sawIDAT, sawIEND := false, false, false, false
	defaultImgInAnim := false
	var expectedSeq uint32 = 0

	for off < len(buf) {
		if len(buf)-off < 12 {
			return nil, errors.New("apng: truncated chunk envelope")
		}
		cLen := binary.BigEndian.Uint32(buf[off : off+4])
		if cLen > 0x7FFFFFFF || uint64(len(buf)-off) < uint64(12)+uint64(cLen) {
			return nil, errors.New("apng: invalid or truncated chunk length")
		}
		cType := string(buf[off+4 : off+8])
		data := buf[off+8 : off+8+int(cLen)]
		wantCRC := binary.BigEndian.Uint32(buf[off+8+int(cLen) : off+12+int(cLen)])
		if crc32.ChecksumIEEE(buf[off+4:off+8+int(cLen)]) != wantCRC {
			return nil, fmt.Errorf("apng: CRC-32 mismatch in %s", cType)
		}
		off += 12 + int(cLen)

		if !sawIHDR {
			if cType != "IHDR" || cLen != 13 {
				return nil, errors.New("apng: first chunk must be 13-byte IHDR")
			}
			w := binary.BigEndian.Uint32(data[0:4])
			h := binary.BigEndian.Uint32(data[4:8])
			if w == 0 || w > 0x7FFFFFFF || h == 0 || h > 0x7FFFFFFF {
				return nil, errors.New("apng: invalid IHDR canvas dimensions")
			}
			out.CanvasWidth, out.CanvasHeight = w, h
			sawIHDR = true
			continue
		}

		switch cType {
		case "acTL":
			if sawACTL || sawIDAT || cLen != 8 {
				return nil, errors.New("apng: duplicate, misplaced, or wrong-length acTL")
			}
			nf := binary.BigEndian.Uint32(data[0:4])
			np := binary.BigEndian.Uint32(data[4:8])
			if nf == 0 || nf > 0x7FFFFFFF || np > 0x7FFFFFFF {
				return nil, errors.New("apng: invalid acTL num_frames or num_plays")
			}
			out.NumFrames, out.NumPlays = nf, np
			sawACTL = true

		case "fcTL":
			if !sawACTL || cLen != 26 {
				return nil, errors.New("apng: fcTL without acTL or length != 26")
			}
			seq := binary.BigEndian.Uint32(data[0:4])
			if seq != expectedSeq {
				return nil, fmt.Errorf("apng: fcTL sequence %d != expected %d", seq, expectedSeq)
			}
			expectedSeq++

			fw := binary.BigEndian.Uint32(data[4:8])
			fh := binary.BigEndian.Uint32(data[8:12])
			xo := binary.BigEndian.Uint32(data[12:16])
			yo := binary.BigEndian.Uint32(data[16:20])
			if fw == 0 || fh == 0 ||
				uint64(xo)+uint64(fw) > uint64(out.CanvasWidth) ||
				uint64(yo)+uint64(fh) > uint64(out.CanvasHeight) {
				return nil, errors.New("apng: fcTL rectangle exceeds IHDR canvas bounds")
			}

			disp := data[24]
			blend := data[25]
			if disp > 2 || blend > 1 {
				return nil, errors.New("apng: invalid dispose_op or blend_op in fcTL")
			}
			if len(out.Frames) == 0 && disp == 2 {
				return nil, errors.New("apng: dispose_op=2 (PREVIOUS) forbidden on first frame")
			}
			if !sawIDAT {
				if len(out.Frames) > 0 {
					return nil, errors.New("apng: multiple fcTL chunks before IDAT")
				}
				if xo != 0 || yo != 0 || fw != out.CanvasWidth || fh != out.CanvasHeight {
					return nil, errors.New("apng: pre-IDAT fcTL must match full IHDR canvas")
				}
				defaultImgInAnim = true
			}
			out.Frames = append(out.Frames, FrameControl{
				SeqNumber: seq,
				Width:     fw,
				Height:    fh,
				XOffset:   xo,
				YOffset:   yo,
				DelayNum:  binary.BigEndian.Uint16(data[20:22]),
				DelayDen:  binary.BigEndian.Uint16(data[22:24]),
				DisposeOp: disp,
				BlendOp:   blend,
			})

		case "IDAT":
			if cLen == 0 {
				return nil, errors.New("apng: empty IDAT chunk")
			}
			sawIDAT = true
			if defaultImgInAnim {
				out.Frames[0].DataBytes += int(cLen)
			}

		case "fdAT":
			if !sawACTL || !sawIDAT || cLen < 5 {
				return nil, errors.New("apng: misplaced or <5-byte fdAT chunk")
			}
			if len(out.Frames) == 0 || (len(out.Frames) == 1 && defaultImgInAnim) {
				return nil, errors.New("apng: fdAT missing preceding post-IDAT fcTL")
			}
			seq := binary.BigEndian.Uint32(data[0:4])
			if seq != expectedSeq {
				return nil, fmt.Errorf("apng: fdAT sequence %d != expected %d", seq, expectedSeq)
			}
			expectedSeq++
			out.Frames[len(out.Frames)-1].DataBytes += int(cLen - 4)

		case "IEND":
			if cLen != 0 || off != len(buf) {
				return nil, errors.New("apng: non-empty IEND or trailing bytes")
			}
			sawIEND = true
		}
	}

	if !sawIEND || !sawACTL || !sawIDAT {
		return nil, errors.New("apng: incomplete stream (missing acTL, IDAT, or IEND)")
	}
	if uint32(len(out.Frames)) != out.NumFrames {
		return nil, fmt.Errorf("apng: parsed %d fcTL frames != acTL.num_frames %d", len(out.Frames), out.NumFrames)
	}
	for i, f := range out.Frames {
		if f.DataBytes == 0 {
			return nil, fmt.Errorf("apng: frame %d has zero compressed image bytes", i)
		}
	}
	return &out, nil
}
