package protostream

import (
	"encoding/binary"
	"errors"
	"fmt"
	"unicode/utf8"
)

type Schema struct {
	StringFields   map[uint32]bool
	NestedMessages map[uint32]*Schema
}

type DecodedField struct {
	Number   uint32
	WireType uint8
	Uint64   uint64
	Str      string
	Bytes    []byte
	SubMsg   []DecodedField
}

func readCanonicalVarint(buf []byte, maxBytes int) (uint64, int, error) {
	var val uint64
	for i := 0; i < maxBytes; i++ {
		if i >= len(buf) {
			return 0, 0, errors.New("protostream: truncated varint")
		}
		b := buf[i]
		if maxBytes == 10 && i == 9 && b > 0x01 {
			return 0, 0, errors.New("protostream: uint64 varint overflow")
		}
		if maxBytes == 5 && i == 4 && b > 0x0F {
			return 0, 0, errors.New("protostream: uint32 varint overflow")
		}
		val |= uint64(b&0x7F) << (7 * i)
		if b < 0x80 {
			if i > 0 && b == 0x00 {
				return 0, 0, errors.New("protostream: non-canonical overlong varint")
			}
			return val, i + 1, nil
		}
	}
	return 0, 0, fmt.Errorf("protostream: varint exceeds %d bytes", maxBytes)
}

func decodeMessageSlice(buf []byte, schema *Schema, depth, maxDepth int) ([]DecodedField, error) {
	if depth > maxDepth {
		return nil, fmt.Errorf("protostream: recursion depth %d > %d", depth, maxDepth)
	}
	var fields []DecodedField
	off := 0

	for off < len(buf) {
		tag64, nTag, err := readCanonicalVarint(buf[off:], 5)
		if err != nil {
			return nil, err
		}
		off += nTag
		fNum := uint32(tag64 >> 3)
		wType := uint8(tag64 & 0x07)
		if fNum == 0 || fNum > (1<<29)-1 || (fNum >= 19000 && fNum <= 19999) {
			return nil, fmt.Errorf("protostream: illegal field number %d", fNum)
		}

		isStr := schema != nil && schema.StringFields[fNum]
		var childSchema *Schema
		if schema != nil {
			childSchema = schema.NestedMessages[fNum]
		}
		if (isStr || childSchema != nil) && wType != 2 {
			return nil, fmt.Errorf("protostream: field %d must use wire_type 2, got %d", fNum, wType)
		}

		var df DecodedField
		df.Number = fNum
		df.WireType = wType

		switch wType {
		case 0:
			v, nv, err := readCanonicalVarint(buf[off:], 10)
			if err != nil {
				return nil, err
			}
			df.Uint64 = v
			off += nv
		case 1:
			if len(buf)-off < 8 {
				return nil, errors.New("protostream: truncated fixed64")
			}
			df.Uint64 = binary.LittleEndian.Uint64(buf[off : off+8])
			off += 8
		case 5:
			if len(buf)-off < 4 {
				return nil, errors.New("protostream: truncated fixed32")
			}
			df.Uint64 = uint64(binary.LittleEndian.Uint32(buf[off : off+4]))
			off += 4
		case 2:
			subLen64, nl, err := readCanonicalVarint(buf[off:], 5)
			if err != nil {
				return nil, err
			}
			off += nl
			subLen := int(subLen64)
			if len(buf)-off < subLen {
				return nil, fmt.Errorf("protostream: field %d length %d overruns frame", fNum, subLen)
			}
			slice := buf[off : off+subLen]
			off += subLen

			if isStr {
				if !utf8.Valid(slice) {
					return nil, fmt.Errorf("protostream: invalid UTF-8 in string field %d", fNum)
				}
				df.Str = string(slice)
			} else if childSchema != nil {
				children, err := decodeMessageSlice(slice, childSchema, depth+1, maxDepth)
				if err != nil {
					return nil, err
				}
				df.SubMsg = children
			} else {
				df.Bytes = slice
			}
		default:
			return nil, fmt.Errorf("protostream: unsupported wire_type %d", wType)
		}
		fields = append(fields, df)
	}
	return fields, nil
}

func ParseLengthDelimitedStream(
	stream []byte,
	schema *Schema,
	maxFrameBytes int,
	maxDepth int,
) ([][]DecodedField, error) {
	if maxFrameBytes <= 0 {
		maxFrameBytes = 1 << 20
	}
	var messages [][]DecodedField
	off := 0
	for off < len(stream) {
		fLen64, n, err := readCanonicalVarint(stream[off:], 5)
		if err != nil {
			return nil, err
		}
		off += n
		fLen := int(fLen64)
		if fLen > maxFrameBytes {
			return nil, fmt.Errorf("protostream: frame length %d > maxFrameBytes %d", fLen, maxFrameBytes)
		}
		if len(stream)-off < fLen {
			return nil, errors.New("protostream: truncated length-delimited frame")
		}
		msgFields, err := decodeMessageSlice(stream[off:off+fLen], schema, 0, maxDepth)
		if err != nil {
			return nil, err
		}
		messages = append(messages, msgFields)
		off += fLen
	}
	return messages, nil
}
