@dataclass(frozen=True, slots=True)
class ParsedConnectV5:
    clean_start: bool
    keep_alive: int
    client_id: str
    connect_properties: dict[int, int | str | bytes]
    user_properties: list[tuple[str, str]]
    will_topic: str | None = None
    will_payload: bytes | None = None
