    password: bytes | None = None


@dataclass(frozen=True, slots=True)
class ParsedAuthV5:
    reason_code: int
    properties: dict[int, int | str | bytes]
    user_properties: list[tuple[str, str]]


def parse_mqttv5_connect_or_auth(
    pkt: bytes | bytearray | memoryview,
) -> ParsedConnectV5 | ParsedAuthV5:
    mv = memoryview(pkt)
    if len(mv) < 2:
        raise MQTTv5ConnectAuthError("packet < 2 bytes")

    b0 = mv[0]
    rem_len, cur = _read_varint(mv, 1)
    if cur + rem_len != len(mv):
        raise MQTTv5ConnectAuthError("Remaining Length mismatch")

