            raise MQTTv5ConnectAuthError(f"illegal AUTH Reason Code 0x{rc:02x}")
        cur += 1
        if cur == len(mv):
            if rc != 0x00:
                raise MQTTv5ConnectAuthError("AUTH 0x18/0x19 requires Authentication Method (0x15)")
            return ParsedAuthV5(reason_code=rc, properties={}, user_properties=[])
        props, uprops, end = _parse_prop_block(mv, cur, AUTH_PROPS)
        if end != len(mv) or 0x15 not in props:
            raise MQTTv5ConnectAuthError("AUTH packet missing Authentication Method (0x15) or has trailing bytes")
        return ParsedAuthV5(reason_code=rc, properties=props, user_properties=uprops)

    if b0 != 0x10:
        raise MQTTv5ConnectAuthError(f"expected CONNECT (0x10) or AUTH (0xF0), got 0x{b0:02x}")

    if len(mv) - cur < 10 or bytes(mv[cur : cur + 6]) != b"\x00\x04MQTT":
        raise MQTTv5ConnectAuthError("invalid MQTT protocol name header")
    proto_ver, flags, keep_alive = struct.unpack_from(">BBH", mv, cur + 6)
    cur += 10
    if proto_ver != 5 or (flags & 0x01) != 0:
        raise MQTTv5ConnectAuthError("unsupported MQTT version or non-zero reserved CONNECT flag bit 0")

    clean_start = (flags & 0x02) != 0
    will_flag = (flags & 0x04) != 0
    will_qos = (flags >> 3) & 0x03
    will_retain = (flags & 0x20) != 0
    pass_flag = (flags & 0x40) != 0
    user_flag = (flags & 0x80) != 0

    if will_qos == 3 or (not will_flag and (will_qos != 0 or will_retain)):
        raise MQTTv5ConnectAuthError("illegal Will QoS/Retain combination in CONNECT flags")

    c_props, c_uprops, cur = _parse_prop_block(mv, cur, CONNECT_PROPS)
    client_id, cur = _read_utf8(mv, cur)

    w_props: dict[int, int | str | bytes] = {}
    w_topic: str | None = None
    w_payload: bytes | None = None
    if will_flag:
        w_props, _, cur = _parse_prop_block(mv, cur, WILL_PROPS)
        w_topic, cur = _read_utf8(mv, cur)
        if not w_topic or "+" in w_topic or "#" in w_topic:
            raise MQTTv5ConnectAuthError("empty or wildcard Will Topic forbidden")
        w_payload, cur = _read_bin(mv, cur)
        if w_props.get(0x01) == 1:
            try:
                w_payload.decode("utf-8", errors="strict")
            except UnicodeDecodeError as exc:
                raise MQTTv5ConnectAuthError("Will Payload Format=1 but payload is invalid UTF-8") from exc

    username: str | None = None
    password: bytes | None = None
    if user_flag:
        username, cur = _read_utf8(mv, cur)
    if pass_flag:
        password, cur = _read_bin(mv, cur)

    if cur != len(mv):
        raise MQTTv5ConnectAuthError("trailing unconsumed bytes in CONNECT payload")

    return ParsedConnectV5(
        clean_start=clean_start,
        keep_alive=keep_alive,
        client_id=client_id,
        connect_properties=c_props,
        user_properties=c_uprops,
        will_topic=w_topic,
        will_payload=w_payload,
        will_qos=will_qos,
        will_retain=will_retain,
        will_properties=w_props,
        username=username,
        password=password,
    )
