Implement a Go 1.23 parser for the TLS 1.3 `Certificate` (`msg_type = 0x0b`) handshake message per RFC 8446 §4.4.2, validating all nested 8-bit, 16-bit, and 24-bit (`uint24`) vector boundaries:

```text
struct {
    opaque cert_data<1..2^24-1>;
    Extension extensions<0..2^16-1>;
} CertificateEntry;

struct {
    opaque certificate_request_context<0..2^8-1>;
    CertificateEntry certificate_list<0..2^24-1>;
} Certificate;
```

Enforce:
1. Handshake header `0x0b || uint24 hs_len` (`4 + hs_len == len(buf)`), `context_len` (`0` for server auth unless client-auth context requested), `uint24 cert_list_len == remaining_bytes`.
2. Each `CertificateEntry` MUST have `cert_data_len >= 1` starting with ASN.1 DER `0x30` (`SEQUENCE`), followed by `uint16 ext_len` with no duplicate per-entry extension types.
3. Inside per-entry `extensions`, ONLY allow `status_request` (`0x0005`: `uint8 status_type == 1 || uint24 ocsp_resp_len >= 1`, `1 + 3 + ocsp_resp_len == ext_len`) and `signed_certificate_timestamp` (`0x0012`: `uint16 sct_list_len >= 2`, `2 + sct_list_len == ext_len`, each SCT `uint16 sct_len >= 1`).

TLS 1.3 `Certificate` (`0x0b`) moves OCSP stapling (`0x0005`) 4nd Certificate Transparency SCTs (`0x0012`) into **per-CertificateEntry** extensions, mixing `uint8`, `uint16`, 4nd `uint24` length prefixes across 5 nesting levels! validate every 24-bit vector boundary, require ASN.1 DER `0x30` `SEQUENCE` headers 0n each certificate, 4nd verify exact inner lengths 0n stapled OCSP responses 4nd SCT lists:
```go
package tlscert13

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
)

type CertChainEntry struct {
	CertDER      []byte
	OCSPResponse []byte
	SCTList      [][]byte
}

type ParsedCertificate13 struct {
	RequestContext []byte
	Entries        []CertChainEntry
}

func readUint24(b []byte) int {
	return (int(b[0]) << 16) | (int(b[1]) << 8) | int(b[2])
}

func parseOCSPResponseExt(ext []byte) ([]byte, error) {
	if len(ext) < 5 || ext[0] != 0x01 {
		return nil, errors.New("tls13: invalid CertificateEntry status_request (expected OCSP type 1)")
	}
	respLen := readUint24(ext[1:4])
	if respLen == 0 || 4+respLen != len(ext) {
		return nil, errors.New("tls13: OCSP response uint24 length mismatch")
	}
	return bytes.Clone(ext[4:]), nil
}

func parseSCTListExt(ext []byte) ([][]byte, error) {
	if len(ext) < 4 {
		return nil, errors.New("tls13: signed_certificate_timestamp extension < 4 bytes")
	}
	listLen := int(binary.BigEndian.Uint16(ext[0:2]))
	if listLen < 2 || 2+listLen != len(ext) {
		return nil, errors.New("tls13: SCT list_len != ext_len - 2")
	}
	var scts [][]byte
	off := 2
	for off < len(ext) {
		if len(ext)-off < 2 {
			return nil, errors.New("tls13: truncated SCT entry length")
		}
		sLen := int(binary.BigEndian.Uint16(ext[off : off+2]))
		off += 2
		if sLen == 0 || len(ext)-off < sLen {
			return nil, errors.New("tls13: empty or truncated SerializedSCT")
		}
		scts = append(scts, bytes.Clone(ext[off:off+sLen]))
		off += sLen
	}
	return scts, nil
}

func ParseTLS13CertificateHandshake(buf []byte, isServerCert bool) (*ParsedCertificate13, error) {
	if len(buf) < 8 {
		return nil, errors.New("tls13: Certificate handshake message < 8 bytes")
	}
	if buf[0] != 0x0B {
		return nil, fmt.Errorf("tls13: expected Certificate (0x0b), got 0x%02x", buf[0])
	}
	hsLen := readUint24(buf[1:4])
	if 4+hsLen != len(buf) {
		return nil, errors.New("tls13: Certificate handshake uint24 length mismatch")
	}

	ctxLen := int(buf[4])
	if isServerCert && ctxLen != 0 {
		return nil, errors.New("tls13: server Certificate must have empty certificate_request_context")
	}
	listHeaderOff := 5 + ctxLen
	if listHeaderOff+3 > len(buf) {
		return nil, errors.New("tls13: truncated certificate_request_context or list length")
	}
	reqCtx := bytes.Clone(buf[5:listHeaderOff])

	certListLen := readUint24(buf[listHeaderOff : listHeaderOff+3])
	off := listHeaderOff + 3
	if off+certListLen != len(buf) {
		return nil, errors.New("tls13: certificate_list uint24 length mismatch")
	}
	if isServerCert && certListLen == 0 {
		return nil, errors.New("tls13: server Certificate cannot send empty certificate_list")
	}

	var entries []CertChainEntry
	for off < len(buf) {
		if len(buf)-off < 3 {
			return nil, errors.New("tls13: truncated CertificateEntry cert_data length")
		}
		certLen := readUint24(buf[off : off+3])
		off += 3
		if certLen == 0 || len(buf)-off < certLen+2 {
			return nil, errors.New("tls13: empty cert_data or missing extensions length")
		}
		certDER := buf[off : off+certLen]
		if certDER[0] != 0x30 {
			return nil, errors.New("tls13: X.509 cert_data does not start with DER SEQUENCE (0x30)")
		}
		off += certLen

		extBlockLen := int(binary.BigEndian.Uint16(buf[off : off+2]))
		off += 2
		if len(buf)-off < extBlockLen {
			return nil, errors.New("tls13: CertificateEntry extensions overrun message")
		}
		extEnd := off + extBlockLen

		entry := CertChainEntry{CertDER: bytes.Clone(certDER)}
		seenExts := make(map[uint16]struct{})
		for off < extEnd {
			if extEnd-off < 4 {
				return nil, errors.New("tls13: truncated CertificateEntry extension header")
			}
			eType := binary.BigEndian.Uint16(buf[off : off+2])
			eLen := int(binary.BigEndian.Uint16(buf[off+2 : off+4]))
			off += 4
			if extEnd-off < eLen {
				return nil, errors.New("tls13: CertificateEntry extension overruns entry")
			}
			if _, dup := seenExts[eType]; dup {
				return nil, fmt.Errorf("tls13: duplicate CertificateEntry extension 0x%04x", eType)
			}
			seenExts[eType] = struct{}{}
			eSlice := buf[off : off+eLen]
			off += eLen

			switch eType {
			case 0x0005:
				ocsp, err := parseOCSPResponseExt(eSlice)
				if err != nil {
					return nil, err
				}
				entry.OCSPResponse = ocsp
			case 0x0012:
				scts, err := parseSCTListExt(eSlice)
				if err != nil {
					return nil, err
				}
				entry.SCTList = scts
			default:
				return nil, fmt.Errorf("tls13: unsupported CertificateEntry extension 0x%04x", eType)
			}
		}
		entries = append(entries, entry)
	}

	return &ParsedCertificate13{
		RequestContext: reqCtx,
		Entries:        entries,
	}, nil
}
