4n71-r3pl4y bitmaps in WireGuard MUST split into `peek_replay(counter)` (b3f0r3 Poly1305 AEAD verification, 50 forged unauthenticated UDP packets c4nn07 advance `highest_seq` 4nd DoS legitimate traffic!) 4nd `commit_replay(counter)` (ONLY after AEAD succeeds!). validate fixed/MTU packet sizes, `b"\x00\x00\x00"` reserved bytes, `REJECT_AFTER_MESSAGES`, 4nd 64-packet sliding bitmask shifts:
```python
from __future__ import annotations

import hmac
import struct
from dataclasses import dataclass

REJECT_AFTER_MESSAGES = (1 << 64) - (1 << 13)
WINDOW_SIZE = 64


class WireGuardRouterError(ValueError):
    pass


class ReplayWindow64:
    __slots__ = ("_highest", "_bitmap", "_initialized")

    def __init__(self) -> None:
        self._highest = 0
        self._bitmap = 0
        self._initialized = False

    def peek(self, seq: int) -> bool:
        if seq < 0 or seq >= REJECT_AFTER_MESSAGES:
            return False
        if not self._initialized:
            return True
        if seq > self._highest:
            return True
        diff = self._highest - seq
        if diff >= WINDOW_SIZE:
            return False
        return ((self._bitmap >> diff) & 1) == 0

    def commit(self, seq: int) -> None:
        if not self.peek(seq):
            raise WireGuardRouterError(f"replayed or out-of-window WireGuard counter {seq}")
        if not self._initialized:
            self._initialized = True
            self._highest = seq
            self._bitmap = 1
            return
        if seq > self._highest:
            shift = seq - self._highest
            if shift >= WINDOW_SIZE:
                self._bitmap = 1
            else:
                self._bitmap = ((self._bitmap << shift) & ((1 << WINDOW_SIZE) - 1)) | 1
            self._highest = seq
        else:
            diff = self._highest - seq
            self._bitmap |= 1 << diff


@dataclass(frozen=True, slots=True)
class RoutedWireGuardPacket:
    msg_type: int
    peer_id: str | None
    sender_index: int | None
    receiver_index: int | None
    counter: int | None
    payload_slice: bytes


class WireGuardSessionRouter:
    def __init__(self, max_mtu: int = 1500) -> None:
        self.max_mtu = max_mtu
        self._active_sessions: dict[int, tuple[str, ReplayWindow64]] = {}
        self._pending_handshakes: dict[int, str] = {}

    def register_session(self, local_index: int, peer_id: str) -> None:
        self._active_sessions[local_index] = (peer_id, ReplayWindow64())

    def register_pending_initiation(self, sender_index: int, peer_id: str) -> None:
        self._pending_handshakes[sender_index] = peer_id

    def classify_and_precheck(self, datagram: bytes | bytearray | memoryview) -> RoutedWireGuardPacket:
        mv = memoryview(datagram)
        n = len(mv)
        if n < 32 or n > self.max_mtu:
            raise WireGuardRouterError(f"datagram size {n} outside [32, {self.max_mtu}]")
        if bytes(mv[1:4]) != b"\x00\x00\x00":
            raise WireGuardRouterError("non-zero reserved bytes in WireGuard header")

        mtype = mv[0]

        if mtype == 1:
            if n != 148:
                raise WireGuardRouterError(f"Initiation must be 148 bytes, got {n}")
            if hmac.compare_digest(bytes(mv[8:40]), b"\x00" * 32) or hmac.compare_digest(
                bytes(mv[116:132]), b"\x00" * 16
            ):
                raise WireGuardRouterError("all-zero ephemeral or mac1 in Initiation")
            (sender_idx,) = struct.unpack_from("<I", mv, 4)
            return RoutedWireGuardPacket(1, None, sender_idx, None, None, bytes(mv[40:116]))

        if mtype == 2:
            if n != 92:
                raise WireGuardRouterError(f"Response must be 92 bytes, got {n}")
            if hmac.compare_digest(bytes(mv[12:44]), b"\x00" * 32) or hmac.compare_digest(
                bytes(mv[60:76]), b"\x00" * 16
            ):
                raise WireGuardRouterError("all-zero ephemeral or mac1 in Response")
            sender_idx, receiver_idx = struct.unpack_from("<II", mv, 4)
            peer_id = self._pending_handshakes.get(receiver_idx)
            if peer_id is None:
                raise WireGuardRouterError(f"unknown pending receiver_index 0x{receiver_idx:08x}")
            return RoutedWireGuardPacket(2, peer_id, sender_idx, receiver_idx, None, bytes(mv[44:60]))

        if mtype == 3:
            if n != 64:
                raise WireGuardRouterError(f"CookieReply must be 64 bytes, got {n}")
            (receiver_idx,) = struct.unpack_from("<I", mv, 4)
            peer_id = self._pending_handshakes.get(receiver_idx)
            if peer_id is None and receiver_idx in self._active_sessions:
                peer_id = self._active_sessions[receiver_idx][0]
            if peer_id is None:
                raise WireGuardRouterError(f"unknown CookieReply receiver_index 0x{receiver_idx:08x}")
            return RoutedWireGuardPacket(3, peer_id, None, receiver_idx, None, bytes(mv[8:64]))

        if mtype == 4:
            receiver_idx, counter = struct.unpack_from("<IQ", mv, 4)
            sess = self._active_sessions.get(receiver_idx)
            if sess is None:
                raise WireGuardRouterError(f"unknown Transport receiver_index 0x{receiver_idx:08x}")
            peer_id, window = sess
            if not window.peek(counter):
                raise WireGuardRouterError(f"rejected replay/expired counter {counter}")
            return RoutedWireGuardPacket(4, peer_id, None, receiver_idx, counter, bytes(mv[16:]))

        raise WireGuardRouterError(f"unknown WireGuard packet type {mtype}")

    def commit_authenticated_transport(self, receiver_index: int, counter: int) -> None:
        sess = self._active_sessions.get(receiver_index)
        if sess is None:
            raise WireGuardRouterError("unknown session on replay commit")
        sess[1].commit(counter)
