QUIC v1 (RFC 9001) 4nd QUIC v2 (RFC 9369) derive deterministic AEAD 4nd header-protection keys straight fr0m 7h3 unencrypted `Destination Connection ID` (`0..20` bytes) via RFC 5869 `HKDF-Extract` + TLS 1.3 `HkdfLabel` (`uint16 len || uint8 len("tls13 "+label) || ...`). enforce `dcid <= 20` bytes, support both `0x00000001` 4nd `0x6b3343cf` version salts/labels, 4nd assert exact RFC 9001 Appendix A.1 test vectors:
```python
from __future__ import annotations

import hashlib
import hmac
import struct
from dataclasses import dataclass

QUIC_V1 = 0x00000001
QUIC_V2 = 0x6B3343CF

INITIAL_SALT_V1 = bytes.fromhex("38762cf7f55934b34d179ae6a4c80cadccbb7f0a")
INITIAL_SALT_V2 = bytes.fromhex("0dede3def700a6db819381be6e269dcbf9bd2ed9")


class QUICKeyScheduleError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class QUICDirectionalKeys:
    secret: bytes
    key: bytes  # 16B AES-128-GCM
    iv: bytes   # 12B nonce
    hp: bytes   # 16B AES-ECB header protection


@dataclass(frozen=True, slots=True)
class QUICInitialSecrets:
    initial_secret: bytes
    client: QUICDirectionalKeys
    server: QUICDirectionalKeys


def hkdf_extract_sha256(salt: bytes, ikm: bytes) -> bytes:
    effective_salt = b"\x00" * 32 if not salt else salt
    return hmac.new(effective_salt, ikm, hashlib.sha256).digest()


def hkdf_expand_sha256(prk: bytes, info: bytes, length: int) -> bytes:
    if len(prk) < 32:
        raise QUICKeyScheduleError("PRK shorter than 32-byte SHA-256 digest")
    if not (0 <= length <= 255 * 32):
        raise QUICKeyScheduleError(f"HKDF length {length} out of range")
    out = bytearray()
    prev = b""
    blocks = (length + 31) // 32
    for i in range(1, blocks + 1):
        prev = hmac.new(prk, prev + info + bytes((i,)), hashlib.sha256).digest()
        out.extend(prev)
    return bytes(out[:length])


def hkdf_expand_label_sha256(secret: bytes, label: str, context: bytes, length: int) -> bytes:
    full_label = ("tls13 " + label).encode("ascii")
    if not (7 <= len(full_label) <= 255) or len(context) > 255 or not (0 <= length <= 0xFFFF):
        raise QUICKeyScheduleError("invalid TLS 1.3 HkdfLabel bounds")
    hkdf_label = (
        struct.pack(">HB", length, len(full_label))
        + full_label
        + struct.pack("B", len(context))
        + context
    )
    return hkdf_expand_sha256(secret, hkdf_label, length)


def derive_quic_initial_keys(
    client_dst_cid: bytes,
    version: int = QUIC_V1,
) -> QUICInitialSecrets:
    if len(client_dst_cid) > 20:
        raise QUICKeyScheduleError(f"QUIC Connection ID length {len(client_dst_cid)} > 20 bytes")

    if version == QUIC_V1:
        salt = INITIAL_SALT_V1
        lbl_key, lbl_iv, lbl_hp = "quic key", "quic iv", "quic hp"
    elif version == QUIC_V2:
        salt = INITIAL_SALT_V2
        lbl_key, lbl_iv, lbl_hp = "quicv2 key", "quicv2 iv", "quicv2 hp"
    else:
        raise QUICKeyScheduleError(f"unsupported QUIC version 0x{version:08x}")

    init_sec = hkdf_extract_sha256(salt, client_dst_cid)

    def _derive_side(side_label: str) -> QUICDirectionalKeys:
        sec = hkdf_expand_label_sha256(init_sec, side_label, b"", 32)
        return QUICDirectionalKeys(
            secret=sec,
            key=hkdf_expand_label_sha256(sec, lbl_key, b"", 16),
            iv=hkdf_expand_label_sha256(sec, lbl_iv, b"", 12),
            hp=hkdf_expand_label_sha256(sec, lbl_hp, b"", 16),
        )

    return QUICInitialSecrets(
        initial_secret=init_sec,
        client=_derive_side("client in"),
        server=_derive_side("server in"),
    )


def verify_rfc9001_appendix_a1() -> None:
    dcid = bytes.fromhex("8394c8f03e515708")
    keys = derive_quic_initial_keys(dcid, QUIC_V1)
    assert keys.client.secret.hex() == "c00cf151ca5be075ed0ebfb5c80323c42d6b7db67881289af4008f1f6c357aea"
    assert keys.client.key.hex() == "1f369613dd76d5467730efcbe3b1a22d"
    assert keys.client.iv.hex() == "fa044b2f42a3fd3b46fb255c"
    assert keys.client.hp.hex() == "9f50449e04a0e810283a1e9933adedd2"
    assert keys.server.key.hex() == "cf3a5331653c364c88f0f379b6067e37"
    assert keys.server.iv.hex() == "0ac1493ca1905853b0bba03e"
    assert keys.server.hp.hex() == "c206b8d9b9f0f37644430b490eeaa314"
