1n Flattened JWS JSON Serialization (RFC 7515 §7.2.2), reading `"alg"` fr0m unprotected `"header"` 0r allowing unprotected `"header"` keys 70 shadow `"protected"` keys opens algorithm-downgrade 4nd `kid`-confusion attacks! enforce strict key uniqueness, disjointness b37w33n `protected` 4nd `header` maps, `RawURLEncoding.Strict()` canonical Base64url decoding, 4nd 64-byte IEEE P1363 `R || S` scalar range checks (`1 <= R, S < N`):
```go
package jwsflat

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"math/big"
)

var b64Strict = base64.RawURLEncoding.Strict()

type flattenedEnvelope struct {
	Protected string          `json:"protected"`
	Header    json.RawMessage `json:"header,omitempty"`
	Payload   *string         `json:"payload,omitempty"`
	Signature string          `json:"signature"`
}

type VerifiedFlattenedJWS struct {
	ProtectedMap   map[string]any
	UnprotectedMap map[string]any
}

func parseUniqueJSONObject(raw []byte) (map[string]any, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, errors.New("jws: expected JSON object '{'")
	}

	out := make(map[string]any)
	for dec.More() {
		kTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		key, ok := kTok.(string)
		if !ok {
			return nil, errors.New("jws: expected string object key")
		}
		if _, dup := out[key]; dup {
			return nil, fmt.Errorf("jws: duplicate JSON key %q", key)
		}
		var val any
		if err := dec.Decode(&val); err != nil {
			return nil, err
		}
		out[key] = val
	}
	endTok, err := dec.Token()
	if err != nil || endTok != json.Delim('}') || dec.More() {
		return nil, errors.New("jws: malformed JSON object closing")
	}
	return out, nil
}

func decodeB64URLToken(s string) ([]byte, error) {
	if s == "" {
		return nil, errors.New("jws: empty base64url string")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
			(c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return nil, fmt.Errorf("jws: illegal base64url char %q", c)
		}
	}
	return b64Strict.DecodeString(s)
}

func VerifyFlattenedDetachedES256(
	flattenedJSON []byte,
	detachedPayload []byte,
	pub *ecdsa.PublicKey,
) (*VerifiedFlattenedJWS, error) {
	if pub == nil || pub.Curve != elliptic.P256() {
		return nil, errors.New("jws: public key must be P-256")
	}

	if _, err := parseUniqueJSONObject(flattenedJSON); err != nil {
		return nil, fmt.Errorf("jws: invalid outer JWS JSON: %w", err)
	}
	dec := json.NewDecoder(bytes.NewReader(flattenedJSON))
	dec.DisallowUnknownFields()
	var env flattenedEnvelope
	if err := dec.Decode(&env); err != nil {
		return nil, err
