	TransactionStatus byte // 'I' (idle), 'T' (in tx), 'E' (failed tx)
}

func readNullTermUTF8(b []byte) (string, int, error) {
	idx := bytes.IndexByte(b, 0x00)
	if idx < 0 {
		return "", 0, errors.New("pghandshake: missing NUL terminator")
	}
	raw := b[:idx]
	if !utf8.Valid(raw) {
		return "", 0, errors.New("pghandshake: invalid UTF-8 in ParameterStatus")
	}
	return string(raw), idx + 1, nil
}

func ParsePostAuthReadySequence(buf []byte) (*ReadyHandshake, error) {
	if len(buf) < 9+6 {
		return nil, errors.New("pghandshake: buffer shorter than AuthOk + ReadyForQuery")
	}

	// 1. Mandatory leading AuthenticationOk ('R', len=8, code=0)
	if buf[0] != 'R' {
		return nil, fmt.Errorf("pghandshake: expected leading 'R', got %q", buf[0])
	}
	rLen := int32(binary.BigEndian.Uint32(buf[1:5]))
	rCode := int32(binary.BigEndian.Uint32(buf[5:9]))
	if rLen != 8 || rCode != 0 {
		return nil, fmt.Errorf("pghandshake: expected AuthenticationOk (len=8, code=0), got (%d, %d)", rLen, rCode)
	}

	out := &ReadyHandshake{
		Parameters: make(map[string]string),
	}
	off := 9
	sawReady := false

	for off < len(buf) {
		if len(buf)-off < 5 {
			return nil, errors.New("pghandshake: truncated backend frame header")
		}
		tag := buf[off]
		fLen := int(int32(binary.BigEndian.Uint32(buf[off+1 : off+5])))
		if fLen < 4 || len(buf)-off < 1+fLen {
			return nil, fmt.Errorf("pghandshake: invalid or truncated frame %q length %d", tag, fLen)
		}
		body := buf[off+5 : off+1+fLen]
		off += 1 + fLen

		switch tag {
		case 'S':
			k, nk, err := readNullTermUTF8(body)
			if err != nil || k == "" {
				return nil, errors.New("pghandshake: invalid or empty ParameterStatus key")
