			out.Parameters[k] = v

		case 'K':
			if fLen != 12 {
				return nil, fmt.Errorf("pghandshake: BackendKeyData length %d != 12", fLen)
			}
			if out.CancelKey != nil {
				return nil, errors.New("pghandshake: duplicate BackendKeyData frame")
			}
			pid := int32(binary.BigEndian.Uint32(body[0:4]))
			sec := int32(binary.BigEndian.Uint32(body[4:8]))
