    return {
      item: arg <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(arg) : arg,
      nextOff,
    };
  }
  if (major === 1) {
    const neg = -1n - arg;
    return {
      item: neg >= BigInt(Number.MIN_SAFE_INTEGER) ? Number(neg) : neg,
      nextOff,
    };
  }
  if (major === 2 || major === 3) {
    if (arg > BigInt(view.byteLength - nextOff)) {
      throw new IncompleteCborError();
    }
    const end = nextOff + Number(arg);
    const slice = buf.subarray(nextOff, end);
    return {
      item: major === 2 ? slice : utf8Fatal.decode(slice),
      nextOff: end,
    };
  }
  if (major === 4) {
    if (arg > 65_536n) {
      throw new Error(`CBOR array count ${arg} exceeds sequence safety cap`);
    }
    const cnt = Number(arg);
    const arr: CborSeqItem[] = [];
    let cur = nextOff;
    for (let i = 0; i < cnt; i++) {
      const el = decodeOne(view, buf, cur, depth + 1, maxDepth);
      arr.push(el.item);
      cur = el.nextOff;
    }
    return { item: arr, nextOff: cur };
  }
  if (major === 5) {
    if (arg > 65_536n) {
      throw new Error(`CBOR map count ${arg} exceeds sequence safety cap`);
    }
    const cnt = Number(arg);
    const map = new Map<CborSeqItem, CborSeqItem>();
    let cur = nextOff;
    let prevKey: Uint8Array | null = null;
    for (let i = 0; i < cnt; i++) {
      const kStart = cur;
      const k = decodeOne(view, buf, cur, depth + 1, maxDepth);
      const kWire = buf.subarray(kStart, k.nextOff);
      if (prevKey !== null) {
