}

export function decodeCborSequence(
  buf: Uint8Array,
  opts: { allowPartialTail?: boolean; maxDepth?: number } = {},
): { items: CborSeqItem[]; bytesConsumed: number } {
  const allowPartialTail = opts.allowPartialTail ?? true;
  const maxDepth = opts.maxDepth ?? 24;
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);

  const items: CborSeqItem[] = [];
  let off = 0;

  while (off < buf.byteLength) {
    try {
      const res = decodeOne(view, buf, off, 0, maxDepth);
      items.push(res.item);
      off = res.nextOff;
    } catch (err) {
      if (err instanceof IncompleteCborError) {
        if (allowPartialTail) {
          break;
        }
        throw new Error(`Truncated trailing item in CBOR sequence at offset ${off}`);
      }
      throw err;
    }
  }

  return { items, bytesConsumed: off };
}
