func ParseCommandAPDU(raw []byte, parseDataAsBERTLV bool) (*CommandAPDU, error) {
	n := len(raw)
	if n < 4 {
		return nil, fmt.Errorf("apdu: shorter than 4-byte header (%d bytes)", n)
	}
