			le := raw[5+lc]
			if le == 0x00 {
				cmd.MaxExpected = 256
			} else {
				cmd.MaxExpected = int(le)
			}
		} else {
			return nil, fmt.Errorf("apdu: invalid short APDU length %d for Lc=%d", n, lc)
		}
	} else {
