			return nil, fmt.Errorf("apdu: invalid extended APDU length %d (< 7)", n)
		}
		if n == 7 {
			cmd.Case = Case2E
			cmd.HasLe = true
			le16 := int(binary.BigEndian.Uint16(raw[5:7]))
			if le16 == 0 {
				cmd.MaxExpected = 65536
			} else {
