			return nil, errors.New("apdu: Lc16 == 0 is illegal in Case 3E/4E")
		}
		if n == 7+lc16 {
			cmd.Case = Case3E
			cmd.Data = bytes.Clone(raw[7:])
		} else if n == 9+lc16 {
			cmd.Case = Case4E
			cmd.Data = bytes.Clone(raw[7 : 7+lc16])
			cmd.HasLe = true
			le16 := int(binary.BigEndian.Uint16(raw[7+lc16 : 9+lc16]))
			if le16 == 0 {
				cmd.MaxExpected = 65536
			} else {
				cmd.MaxExpected = le16
			}
		} else {
			return nil, fmt.Errorf("apdu: invalid extended APDU length %d for Lc16=%d", n, lc16)
		}
	}

