const utf8Fatal = new TextDecoder("utf-8", { fatal: true });

export type ParsedCoseCredentialKey =
  | { kty: "OKP"; alg: -8; x: Uint8Array }
  | { kty: "EC2"; alg: -7; x: Uint8Array; y: Uint8Array }
  | { kty: "RSA"; alg: -257; modulusN: Uint8Array; exponentE: Uint8Array };

export interface ParsedWebAuthnRegFull {
  rpIdHash: Uint8Array;
  flags: number;
  signCount: number;
  aaguid: Uint8Array;
  credentialId: Uint8Array;
  publicKey: ParsedCoseCredentialKey;
  extensions: Map<string, number | boolean | Uint8Array>;
}

type CtapVal = number | boolean | Uint8Array | string | Map<number | string, CtapVal>;

function compareBytes(a: Uint8Array, b: Uint8Array): number {
  const n = Math.min(a.byteLength, b.byteLength);
  for (let i = 0; i < n; i++) {
    const d = a[i]! - b[i]!;
    if (d !== 0) return d;
  }
  return a.byteLength - b.byteLength;
}

function readCtapArg(
  view: DataView,
  off: number,
): { major: number; ai: number; arg: number; nextOff: number } {
  if (off >= view.byteLength) throw new Error("Truncated CTAP2 CBOR head");
  const b0 = view.getUint8(off);
  const major = b0 >>> 5;
  const ai = b0 & 0x1f;
  const cur = off + 1;

  if (major === 7) return { major, ai, arg: ai, nextOff: cur };
  if (ai < 24) return { major, ai, arg: ai, nextOff: cur };
  if (ai === 24) {
    if (cur + 1 > view.byteLength) throw new Error("Truncated 1B CBOR arg");
    const v = view.getUint8(cur);
    if (v < 24) throw new Error("Non-canonical 1B CBOR arg");
    return { major, ai, arg: v, nextOff: cur + 1 };
  }
  if (ai === 25) {
    if (cur + 2 > view.byteLength) throw new Error("Truncated 2B CBOR arg");
    const v = view.getUint16(cur, false);
    if (v < 256) throw new Error("Non-canonical 2B CBOR arg");
    return { major, ai, arg: v, nextOff: cur + 2 };
  }
  throw new Error(`Unsupported CTAP2 CBOR ai=${ai}`);
}

function decodeCtapItem(
  view: DataView,
  buf: Uint8Array,
  off: number,
): { val: CtapVal; nextOff: number } {
  const { major, ai, arg, nextOff } = readCtapArg(view, off);
  if (major === 0) return { val: arg, nextOff };
  if (major === 1) return { val: -1 - arg, nextOff };
  if (major === 2 || major === 3) {
    const end = nextOff + arg;
    if (end > view.byteLength) throw new Error("Truncated CTAP2 CBOR bstr/tstr");
    const slice = buf.subarray(nextOff, end);
    return { val: major === 2 ? slice : utf8Fatal.decode(slice), nextOff: end };
  }
  if (major === 5) {
    const map = new Map<number | string, CtapVal>();
    let cur = nextOff;
    let prevKeyWire: Uint8Array | null = null;
    for (let i = 0; i < arg; i++) {
      const ks = cur;
      const k = decodeCtapItem(view, buf, cur);
      if (typeof k.val !== "number" && typeof k.val !== "string") {
        throw new Error("CTAP2 map key must be int or string");
      }
      const kWire = buf.subarray(ks, k.nextOff);
      if (prevKeyWire !== null && compareBytes(prevKeyWire, kWire) >= 0) {
        throw new Error("Non-canonical or duplicate CTAP2 CBOR map key order");
      }
      prevKeyWire = kWire;
      const v = decodeCtapItem(view, buf, k.nextOff);
      map.set(k.val, v.val);
      cur = v.nextOff;
    }
    return { val: map, nextOff: cur };
  }
  if (major === 7 && (ai === 20 || ai === 21)) {
    return { val: ai === 21, nextOff };
  }
  throw new Error(`Unsupported CTAP2 CBOR major=${major}`);
}

function validateCoseKeyMap(map: Map<number | string, CtapVal>): ParsedCoseCredentialKey {
  const kty = map.get(1);
  const alg = map.get(3);

  if (kty === 1 && alg === -8 && map.get(-1) === 6 && map.size === 4) {
    const x = map.get(-2);
    if (!(x instanceof Uint8Array) || x.byteLength !== 32) {
      throw new Error("Invalid Ed25519 COSE_Key x coordinate");
    }
    return { kty: "OKP", alg: -8, x };
  }

  if (kty === 2 && alg === -7 && map.get(-1) === 1 && map.size === 5) {
    const x = map.get(-2);
    const y = map.get(-3);
    if (!(x instanceof Uint8Array) || x.byteLength !== 32 || !(y instanceof Uint8Array) || y.byteLength !== 32) {
      throw new Error("Invalid ES256 P-256 COSE_Key coordinates");
    }
    return { kty: "EC2", alg: -7, x, y };
  }

  if (kty === 3 && alg === -257 && map.size === 4) {
    const n = map.get(-1);
    const e = map.get(-2);
    if (
      !(n instanceof Uint8Array) ||
      n.byteLength < 256 ||
      n.byteLength > 512 ||
      (n[0]! & 0x80) === 0
    ) {
      throw new Error("Invalid RS256 modulus n (must be 256..512 bytes with MSB set)");
    }
    if (
      !(e instanceof Uint8Array) ||
      e.byteLength < 3 ||
      e.byteLength > 8 ||
      e[0] === 0x00 ||
      (e[e.byteLength - 1]! & 1) === 0
    ) {
      throw new Error("Invalid RS256 public exponent e (must be canonical odd >= 65537)");
    }
    let eVal = 0;
    for (let i = 0; i < e.byteLength && i < 4; i++) eVal = (eVal << 8) | e[i]!;
    if (e.byteLength === 3 && eVal < 65_537) {
      throw new Error("Weak RSA exponent < 65537 rejected");
    }
    return { kty: "RSA", alg: -257, modulusN: n, exponentE: e };
  }

  throw new Error("Unsupported or non-minimal COSE_Key structure");
}

export function parseWebAuthnRegistrationAuthData(buf: Uint8Array): ParsedWebAuthnRegFull {
  if (buf.byteLength < 55) {
    throw new Error("Registration authenticatorData < 55 bytes");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const flags = view.getUint8(32);
  if ((flags & 0x01) === 0 || (flags & 0x40) === 0) {
    throw new Error("Registration authenticatorData requires UP=1 and AT=1");
  }
  if ((flags & 0x18) === 0x10) {
    throw new Error("Illegal WebAuthn flags: BS=1 while BE=0");
  }
  const hasEd = (flags & 0x80) !== 0;

  const signCount = view.getUint32(33, false);
  const credIdLen = view.getUint16(53, false);
  if (credIdLen < 1 || credIdLen > 1023 || 55 + credIdLen >= buf.byteLength) {
    throw new Error("Invalid or truncated credentialId");
  }

  const coseStart = 55 + credIdLen;
  const coseDecoded = decodeCtapItem(view, buf, coseStart);
  if (!(coseDecoded.val instanceof Map)) {
    throw new Error("credentialPublicKey is not a CBOR map");
  }
  const publicKey = validateCoseKeyMap(coseDecoded.val);

  const extensions = new Map<string, number | boolean | Uint8Array>();
  if (!hasEd) {
    if (coseDecoded.nextOff !== buf.byteLength) {
      throw new Error("Trailing bytes after COSE_Key when ED=0");
    }
  } else {
    if (coseDecoded.nextOff >= buf.byteLength) {
      throw new Error("ED=1 set but extensions map is missing");
    }
    const extDecoded = decodeCtapItem(view, buf, coseDecoded.nextOff);
    if (extDecoded.nextOff !== buf.byteLength || !(extDecoded.val instanceof Map) || extDecoded.val.size === 0) {
      throw new Error("Malformed or non-terminal extensions CBOR map");
    }
    for (const [k, v] of extDecoded.val.entries()) {
      if (typeof k !== "string" || (typeof v !== "number" && typeof v !== "boolean" && !(v instanceof Uint8Array))) {
        throw new Error("Unsupported extension key/value type");
      }
      extensions.set(k, v);
    }
  }

  return {
    rpIdHash: buf.subarray(0, 32),
    flags,
    signCount,
    aaguid: buf.subarray(37, 53),
    credentialId: buf.subarray(55, coseStart),
    publicKey,
    extensions,
  };
}
