from __future__ import annotations

import hmac
from dataclasses import dataclass

CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
REV = {c: i for i, c in enumerate(CHARSET)}
GEN = (0x3B6A57B2, 0x26508E6D, 0x1EA119FA, 0x3D4233DD, 0x2A1462B3)

CONST_BECH32 = 1
CONST_BECH32M = 0x2BC830A3

SECP256K1_P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
SECP256K1_N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141

# hrp_lower -> (must_be_upper, required_polymod_const, key_kind)
HRP_PROFILES: dict[str, tuple[bool, int, str]] = {
    "age": (False, CONST_BECH32, "age-x25519-public"),
    "age-secret-key-": (True, CONST_BECH32, "age-x25519-secret"),
    "npub": (False, CONST_BECH32, "nostr-secp256k1-xonly-pub"),
    "nsec": (False, CONST_BECH32, "nostr-secp256k1-secret"),
    "b32mkey": (False, CONST_BECH32M, "generic-bech32m-256"),
}


class TypedBech32KeyError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class ParsedCryptoKey:
    hrp: str
    key_kind: str
    variant: str
    raw_key: bytes  # 32 bytes


def _polymod(hrp_lower: str, data_words: list[int]) -> int:
    chk = 1
    expanded = [ord(c) >> 5 for c in hrp_lower] + [0] + [ord(c) & 31 for c in hrp_lower] + data_words
    for v in expanded:
        top = chk >> 25
        chk = ((chk & 0x1FFFFFF) << 5) ^ v
        for i in range(5):
            if (top >> i) & 1:
                chk ^= GEN[i]
    return chk


def parse_typed_bech32_key(token: str) -> ParsedCryptoKey:
    if len(token) < 60 or len(token) > 90:
        raise TypedBech32KeyError(f"invalid key token length {len(token)}")
    if token.lower() != token and token.upper() != token:
        raise TypedBech32KeyError("mixed-case Bech32 string is forbidden")

    norm = token.lower()
    sep = norm.rfind("1")
    if sep < 1:
        raise TypedBech32KeyError("missing '1' HRP separator")

    hrp_lower = norm[:sep]
    profile = HRP_PROFILES.get(hrp_lower)
    if profile is None:
        raise TypedBech32KeyError(f"unsupported key HRP {hrp_lower!r}")

    must_be_upper, want_const, key_kind = profile
    if must_be_upper and token != token.upper():
        raise TypedBech32KeyError(f"{key_kind} MUST be encoded in uppercase")
    if not must_be_upper and token != token.lower():
        raise TypedBech32KeyError(f"{key_kind} MUST be encoded in lowercase")

    tail = norm[sep + 1 :]
    if len(tail) != 58:  # 52 data words (260 bits -> 32B) + 6 checksum words
        raise TypedBech32KeyError(f"32-byte key requires 58 post-separator chars, got {len(tail)}")

    try:
        words = [REV[ch] for ch in tail]
    except KeyError as exc:
        raise TypedBech32KeyError(f"invalid Base32 char {exc}") from exc

    if _polymod(hrp_lower, words) != want_const:
        raise TypedBech32KeyError(f"checksum mismatch for {key_kind}")

    data5 = words[:-6]
    if (data5[51] & 0x0F) != 0:
        raise TypedBech32KeyError("non-zero 4-bit padding in 52nd 5-bit symbol")

    acc = 0
    bits = 0
    out = bytearray()
    for w in data5:
        acc = (acc << 5) | w
        bits += 5
        if bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 0xFF)

    raw = bytes(out)
    assert len(raw) == 32

    if hmac.compare_digest(raw, b"\x00" * 32):
        raise TypedBech32KeyError("all-zero 32-byte cryptographic key rejected")

    int_val = int.from_bytes(raw, "big")
    if hrp_lower == "npub" and int_val >= SECP256K1_P:
        raise TypedBech32KeyError("npub x-only coordinate >= secp256k1 field prime P")
    if hrp_lower == "nsec" and not (1 <= int_val < SECP256K1_N):
        raise TypedBech32KeyError("nsec scalar outside [1, secp256k1_N - 1]")

    return ParsedCryptoKey(
        hrp=hrp_lower,
        key_kind=key_kind,
        variant="bech32m" if want_const == CONST_BECH32M else "bech32",
        raw_key=raw,
    )
