```go
package ipfix6313

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
)

type TemplateField struct {
	ElementID uint16
	Length    uint16 // Fixed >= 1
}

type Template struct {
	ID         uint16
	Fields     []TemplateField
	RecordSize int
}

type DecodedBlock struct {
	TemplateID uint16
	Records    [][][]byte
}

type StructuredList struct {
	Semantic uint8
	Blocks   []DecodedBlock
}

func isValidSemantic(s uint8) bool {
	return s <= 0x04 || s == 0xFF
}

func readVarlenPrefix(buf []byte, off, end int) (int, int, error) {
	if off >= end {
		return 0, 0, errors.New("ipfix6313: truncated varlen header")
	}
	b0 := buf[off]
	if b0 < 255 {
		return int(b0), off + 1, nil
	}
	if end-off < 3 {
		return 0, 0, errors.New("ipfix6313: truncated 3-byte 0xFF varlen header")
	}
	return int(binary.BigEndian.Uint16(buf[off+1 : off+3])), off + 3, nil
}

func decodeFixedRecords(slice []byte, tmpl Template) ([][][]byte, error) {
	if tmpl.RecordSize <= 0 {
		return nil, errors.New("ipfix6313: invalid zero/negative template RecordSize")
	}
	if len(slice)%tmpl.RecordSize != 0 {
		return nil, fmt.Errorf(
			"ipfix6313: block length %d not divisible by template %d size %d",
			len(slice), tmpl.ID, tmpl.RecordSize,
		)
	}
	count := len(slice) / tmpl.RecordSize
	rows := make([][][]byte, 0, count)
	off := 0
	for range count {
		row := make([][]byte, len(tmpl.Fields))
		for i, f := range tmpl.Fields {
			fLen := int(f.Length)
			row[i] = bytes.Clone(slice[off : off+fLen])
			off += fLen
		}
		rows = append(rows, row)
	}
	return rows, nil
}

func DecodeSubTemplateList(buf []byte, templates map[uint16]Template) (*StructuredList, int, error) {
	bodyLen, cur, err := readVarlenPrefix(buf, 0, len(buf))
	if err != nil {
		return nil, 0, err
	}
	end := cur + bodyLen
	if bodyLen < 3 || end > len(buf) {
		return nil, 0, errors.New("ipfix6313: truncated or <3B subTemplateList")
	}

	semantic := buf[cur]
	if !isValidSemantic(semantic) {
		return nil, 0, fmt.Errorf("ipfix6313: invalid semantic 0x%02x", semantic)
	}
	tmplID := binary.BigEndian.Uint16(buf[cur+1 : cur+3])
	cur += 3
	if tmplID < 256 {
		return nil, 0, fmt.Errorf("ipfix6313: subTemplateList templateID %d < 256", tmplID)
	}

	var rows [][][]byte
	if cur < end {
		tmpl, ok := templates[tmplID]
		if !ok {
			return nil, 0, fmt.Errorf("ipfix6313: unknown template %d in subTemplateList", tmplID)
		}
		rows, err = decodeFixedRecords(buf[cur:end], tmpl)
		if err != nil {
			return nil, 0, err
		}
	}

	return &StructuredList{
		Semantic: semantic,
		Blocks:   []DecodedBlock{{TemplateID: tmplID, Records: rows}},
	}, end, nil
}

func DecodeSubTemplateMultiList(buf []byte, templates map[uint16]Template) (*StructuredList, int, error) {
	bodyLen, cur, err := readVarlenPrefix(buf, 0, len(buf))
	if err != nil {
		return nil, 0, err
	}
	end := cur + bodyLen
	if bodyLen < 1 || end > len(buf) {
		return nil, 0, errors.New("ipfix6313: truncated or empty subTemplateMultiList")
	}

	semantic := buf[cur]
	if !isValidSemantic(semantic) {
		return nil, 0, fmt.Errorf("ipfix6313: invalid semantic 0x%02x", semantic)
	}
	cur++

	var blocks []DecodedBlock
	for cur < end {
		if end-cur < 3 {
			return nil, 0, errors.New("ipfix6313: truncated subTemplateMultiList entry header")
		}
		tmplID := binary.BigEndian.Uint16(buf[cur : cur+2])
		if tmplID < 256 {
			return nil, 0, fmt.Errorf("ipfix6313: invalid templateID %d in MultiList", tmplID)
		}
		blkLen, dataStart, err := readVarlenPrefix(buf, cur+2, end)
		if err != nil {
			return nil, 0, err
		}
		dataEnd := dataStart + blkLen
		if dataEnd > end {
			return nil, 0, errors.New("ipfix6313: MultiList block overruns outer list")
		}

		var rows [][][]byte
		if blkLen > 0 {
			tmpl, ok := templates[tmplID]
			if !ok {
				return nil, 0, fmt.Errorf("ipfix6313: unknown template %d in MultiList", tmplID)
			}
			rows, err = decodeFixedRecords(buf[dataStart:dataEnd], tmpl)
			if err != nil {
				return nil, 0, err
			}
		}
		blocks = append(blocks, DecodedBlock{TemplateID: tmplID, Records: rows})
		cur = dataEnd
	}

	return &StructuredList{Semantic: semantic, Blocks: blocks}, end, nil
}
