    val += (b & 0x7f) * mul;
    if ((b & 0x80) === 0) {
      if (val < MIN_VARINT[i + 1]!) {
        throw new Error("Malformed Packet: non-canonical overlong MQTT v5 varint");
      }
      return { val, nextOff: pos + 1 };
    }
    mul *= 128;
  }
  throw new Error("Malformed Packet: MQTT v5 varint > 4 bytes");
}

function readUtf8(
  view: DataView,
  buf: Uint8Array,
  off: number,
  end: number,
): { str: string; nextOff: number } {
  if (off + 2 > end) throw new Error("Malformed Packet: truncated UTF-8 length");
  const len = view.getUint16(off, false);
  const strEnd = off + 2 + len;
  if (strEnd > end) throw new Error("Malformed Packet: truncated UTF-8 payload");
  const raw = buf.subarray(off + 2, strEnd);
  for (let i = 0; i < raw.byteLength; i++) {
    if (raw[i] === 0x00) throw new Error("Malformed Packet: U+0000 in MQTT string");
  }
  return { str: utf8Fatal.decode(raw), nextOff: strEnd };
}

export function parseMqttV5SubOrUnsubAck(buf: Uint8Array): ParsedMqttSubUnsubAck {
  if (buf.byteLength < 5) {
    throw new Error("Malformed Packet: SUBACK/UNSUBACK shorter than 5 bytes");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const b0 = view.getUint8(0);
  if ((b0 & 0x0f) !== 0x00 || (b0 !== 0x90 && b0 !== 0xb0)) {
    throw new Error(`Malformed Packet: invalid fixed header 0x${b0.toString(16)}`);
  }
  const kind = b0 === 0x90 ? "SUBACK" : "UNSUBACK";

  const rem = readVarint(view, 1, buf.byteLength);
  if (rem.nextOff + rem.val !== buf.byteLength) {
    throw new Error("Malformed Packet: Remaining Length mismatch");
  }

  let off = rem.nextOff;
  if (off + 2 > buf.byteLength) {
    throw new Error("Malformed Packet: missing Packet Identifier");
  }
  const packetId = view.getUint16(off, false);
  if (packetId === 0) {
    throw new Error("Protocol Error: Packet Identifier cannot be 0");
  }
  off += 2;

  const propLen = readVarint(view, off, buf.byteLength);
  off = propLen.nextOff;
  const propEnd = off + propLen.val;
  if (propEnd > buf.byteLength) {
    throw new Error("Malformed Packet: properties overrun packet");
  }

  let reasonString: string | undefined;
  const userProperties: Array<[string, string]> = [];

  while (off < propEnd) {
    const pid = view.getUint8(off++);
    if (pid === 0x1f) {
      if (reasonString !== undefined) {
        throw new Error("Protocol Error: duplicate Reason String (0x1F)");
      }
      const s = readUtf8(view, buf, off, propEnd);
      reasonString = s.str;
      off = s.nextOff;
    } else if (pid === 0x26) {
      const k = readUtf8(view, buf, off, propEnd);
      const v = readUtf8(view, buf, k.nextOff, propEnd);
      userProperties.push([k.str, v.str]);
      off = v.nextOff;
    } else {
      throw new Error(`Protocol Error: illegal property 0x${pid.toString(16)} in ${kind}`);
    }
  }

  if (off >= buf.byteLength) {
    throw new Error(`Protocol Error: ${kind} payload must contain >= 1 Reason Code`);
  }

  const allowedCodes = kind === "SUBACK" ? SUBACK_REASON_CODES : UNSUBACK_REASON_CODES;
  const reasonCodes: number[] = [];
  while (off < buf.byteLength) {
    const rc = view.getUint8(off++);
    if (!allowedCodes.has(rc)) {
      throw new Error(`Protocol Error: invalid ${kind} Reason Code 0x${rc.toString(16)}`);
    }
    reasonCodes.push(rc);
  }

  return {
    kind,
    packetId,
    ...(reasonString !== undefined ? { reasonString } : {}),
    userProperties,
    reasonCodes,
  };
}
