    pass


def is_grease_u16(val: int) -> bool:
    return (val & 0x0F0F) == 0x0A0A and ((val >> 8) & 0xFF) == (val & 0xFF)


def is_grease_alpn(proto: bytes) -> bool:
    return len(proto) == 2 and proto[0] == proto[1] and (proto[0] & 0x0F) == 0x0A


@dataclass(frozen=True, slots=True)
class CleanClientHello13:
    server_name: str | None
    cipher_suites: tuple[int, ...]
    alpn_protocols: tuple[str, ...]
    supported_versions: tuple[int, ...]
    key_share_groups: tuple[tuple[int, bytes], ...]
