    off += cs_len

    grease_seen = sum(1 for s in raw_suites if is_grease_u16(s))
    clean_suites = tuple(s for s in raw_suites if not is_grease_u16(s))
    if not clean_suites:
        raise TLS13GreaseParseError("ClientHello contains only GREASE cipher suites")

    if body[off] != 1 or body[off + 1] != 0x00:
        raise TLS13GreaseParseError("TLS 1.3 requires legacy_compression_methods == 0x0100")
    off += 2

    if len(body) - off < 2:
        raise TLS13GreaseParseError("missing ClientHello extensions vector")
