    off += 2
    if ext_total < 8 or off + ext_total != len(body):
        raise TLS13GreaseParseError("extensions vector length mismatch")

    seen_exts: set[int] = set()
    sni_host: str | None = None
    clean_alpn: list[str] = []
    saw_alpn = False
    clean_versions: list[int] | None = None
    clean_shares: list[tuple[int, bytes]] | None = None

