                raise TLS13GreaseParseError("invalid SNI host_name")
            sni_host = host

        elif ext_type == 0x0010:  # ALPN
            saw_alpn = True
            if ext_len < 4:
                raise TLS13GreaseParseError("ALPN extension < 4 bytes")
            (list_len,) = struct.unpack_from(">H", ext, 0)
            if 2 + list_len != ext_len:
                raise TLS13GreaseParseError("ALPN list_len != ext_len - 2")
