    if clean_shares is None:
        raise TLS13GreaseParseError("missing key_share (0x0033) extension")
    if saw_alpn and not clean_alpn:
        raise TLS13GreaseParseError("empty clean ALPN list")

    return CleanClientHello13(
        server_name=sni_host,
        cipher_suites=clean_suites,
        alpn_protocols=tuple(clean_alpn),
        supported_versions=tuple(clean_versions),
        key_share_groups=tuple(clean_shares),
        grease_count=grease_seen,
    )
