export const WG_HANDSHAKE_RESPONSE_SIZE = 92;

const CURVE25519_P = (1n << 255n) - 19n;
const LOW_ORDER_MOD_P = new Set<bigint>([
  0n,
  1n,
  325606250916557431795983626356110631294008115727848805560023387167927233504n,
  39382357235489614581723060781553021112529911719440698176882885853963445705823n,
  CURVE25519_P - 1n,
]);

export interface WireGuardHandshakeResponse {
  messageType: 2;
  senderIndex: number;
  receiverIndex: number;
  unencryptedEphemeral: Uint8Array;
  encryptedNothingTag: Uint8Array;
  mac1: Uint8Array;
  mac2: Uint8Array;
  hasMac2Cookie: boolean;
  mac1Input: Uint8Array;
  mac2Input: Uint8Array;
}

function isAllZeroCT(b: Uint8Array): boolean {
  let acc = 0;
  for (let i = 0; i < b.byteLength; i++) acc |= b[i]!;
  return acc === 0;
}

function isLowOrderX25519Point(view: DataView, off: number): boolean {
  const w0 = view.getBigUint64(off, true);
  const w1 = view.getBigUint64(off + 8, true);
  const w2 = view.getBigUint64(off + 16, true);
  const w3 = view.getBigUint64(off + 24, true) & 0x7fffffffffffffffn; // Mask bit 255 per RFC 7748
  const u = w0 | (w1 << 64n) | (w2 << 128n) | (w3 << 192n);
  return LOW_ORDER_MOD_P.has(u % CURVE25519_P);
}

export function parseWireGuardHandshakeResponse(
  pkt: Uint8Array,
  expectedInitiatorIndex?: number,
): WireGuardHandshakeResponse {
  if (pkt.byteLength !== WG_HANDSHAKE_RESPONSE_SIZE) {
    throw new Error(
      `Invalid WireGuard Response length: expected ${WG_HANDSHAKE_RESPONSE_SIZE}, got ${pkt.byteLength}`,
    );
  }

  const view = new DataView(pkt.buffer, pkt.byteOffset, pkt.byteLength);
  if (view.getUint8(0) !== 2) {
    throw new Error(`Expected WireGuard message_type=2, got ${view.getUint8(0)}`);
  }
  if ((view.getUint8(1) | view.getUint8(2) | view.getUint8(3)) !== 0) {
    throw new Error("Non-zero reserved bytes in WireGuard Handshake Response");
  }

  const senderIndex = view.getUint32(4, true);
  const receiverIndex = view.getUint32(8, true);
  if (expectedInitiatorIndex !== undefined && receiverIndex !== expectedInitiatorIndex >>> 0) {
    throw new Error(
      `WireGuard receiver_index 0x${receiverIndex.toString(16)} != expected 0x${expectedInitiatorIndex.toString(16)}`,
    );
  }

  if (isLowOrderX25519Point(view, 12)) {
    throw new Error("Rejected low-order Curve25519 ephemeral point in WireGuard Response");
  }

  const mac1 = pkt.subarray(60, 76);
  if (isAllZeroCT(mac1)) {
    throw new Error("Rejected all-zero mac1 in WireGuard Handshake Response");
  }
  const mac2 = pkt.subarray(76, 92);

  return {
    messageType: 2,
    senderIndex,
    receiverIndex,
    unencryptedEphemeral: pkt.subarray(12, 44),
    encryptedNothingTag: pkt.subarray(44, 60),
    mac1,
    mac2,
    hasMac2Cookie: !isAllZeroCT(mac2),
    mac1Input: pkt.subarray(0, 60),
    mac2Input: pkt.subarray(0, 76),
  };
}
