```go
package hkdfstream

import (
	"bytes"
	"crypto/hmac"
	"errors"
	"fmt"
	"hash"
	"io"
)

var ErrHKDFEntropyExhausted = errors.New("hkdf: 255*HashLen entropy limit exceeded")

type ExpandReader struct {
	mac       hash.Hash
	hashSize  int
	info      []byte
	prevBlock []byte
	rem       []byte
	counter   uint16 // 1..256 (256 => exhausted, avoiding uint8 wraparound!)
}

func HKDFExtract(hashFn func() hash.Hash, salt, ikm []byte) []byte {
	hLen := hashFn().Size()
	if len(salt) == 0 {
		salt = make([]byte, hLen)
	}
	mac := hmac.New(hashFn, salt)
	_, _ = mac.Write(ikm)
	return mac.Sum(nil)
}

func NewHKDFExpandReader(hashFn func() hash.Hash, prk, info []byte) (io.Reader, error) {
	mac := hmac.New(hashFn, prk)
	hLen := mac.Size()
	if len(prk) < hLen {
		return nil, fmt.Errorf("hkdf: PRK length %d < HashLen %d", len(prk), hLen)
	}
	return &ExpandReader{
		mac:      mac,
		hashSize: hLen,
		info:     bytes.Clone(info),
		counter:  1,
	}, nil
}

func (r *ExpandReader) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}

	maxRemaining := len(r.rem) + int(256-r.counter)*r.hashSize
	if len(p) > maxRemaining {
		return 0, ErrHKDFEntropyExhausted
	}

	written := 0
	for written < len(p) {
		if len(r.rem) == 0 {
			if r.counter > 255 {
				return written, ErrHKDFEntropyExhausted
			}
			r.mac.Reset()
			if len(r.prevBlock) > 0 {
				_, _ = r.mac.Write(r.prevBlock)
			}
			if len(r.info) > 0 {
				_, _ = r.mac.Write(r.info)
			}
			_, _ = r.mac.Write([]byte{byte(r.counter)})
			r.prevBlock = r.mac.Sum(r.prevBlock[:0])
			r.rem = r.prevBlock
			r.counter++
		}

		n := copy(p[written:], r.rem)
		r.rem = r.rem[n:]
		written += n
	}
	return written, nil
}
