const B32HEX = "0123456789ABCDEFGHIJKLMNOPQRSTUV";
const B32HEX_REV = new Int8Array(128).fill(-1);
for (let i = 0; i < B32HEX.length; i++) {
  B32HEX_REV[B32HEX.charCodeAt(i)] = i;
}

export interface DecodedSortableEventId {
  timestampMs: bigint;
  random80: Uint8Array; // 10 bytes
  crc16: number;
}

export function crc16T10Dif(data: Uint8Array): number {
  let crc = 0x0000;
  for (let i = 0; i < data.byteLength; i++) {
    crc ^= data[i]! << 8;
    for (let bit = 0; bit < 8; bit++) {
      crc = (crc & 0x8000) !== 0 ? ((crc << 1) ^ 0x8bb7) & 0xffff : (crc << 1) & 0xffff;
    }
  }
  return crc;
}

export function encodeSortableId(timestampMs: bigint, random80?: Uint8Array): string {
  if (timestampMs <= 0n || timestampMs > 0xffffffffffffn) {
    throw new RangeError("timestampMs must fit in positive 48-bit integer");
  }
  const rnd = random80 ?? crypto.getRandomValues(new Uint8Array(10));
  if (rnd.byteLength !== 10) {
    throw new Error("random80 must be 10 bytes");
  }
  let nonZero = 0;
  for (let i = 0; i < 10; i++) nonZero |= rnd[i]!;
  if (nonZero === 0) {
    throw new Error("Refusing all-zero 80-bit entropy");
  }

  const raw = new Uint8Array(18);
  const view = new DataView(raw.buffer);
  view.setUint16(0, Number((timestampMs >> 32n) & 0xffffn), false);
  view.setUint32(2, Number(timestampMs & 0xffffffffn), false);
  raw.set(rnd, 6);
  view.setUint16(16, crc16T10Dif(raw.subarray(0, 16)), false);

  let out = "";
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < 18; i++) {
    acc = (acc << 8) | raw[i]!;
    bits += 8;
    while (bits >= 5) {
      bits -= 5;
      out += B32HEX[(acc >>> bits) & 0x1f]!;
    }
  }
  if (bits > 0) {
    out += B32HEX[(acc << (5 - bits)) & 0x1f]!;
  }
  return out;
}

export function decodeSortableId(id: string): DecodedSortableEventId {
  if (id.length !== 29) {
    throw new Error(`Invalid SortableId length ${id.length} (expected 29)`);
  }

  const raw = new Uint8Array(18);
  let acc = 0;
  let bits = 0;
  let w = 0;

  for (let i = 0; i < 29; i++) {
    const code = id.charCodeAt(i);
    const val = code < 128 ? B32HEX_REV[code]! : -1;
    if (val < 0) {
      throw new Error(`Illegal uppercase Base32hex char at index ${i}`);
    }
    if (i === 28 && (val & 0x01) !== 0) {
      throw new Error("Non-canonical Base32hex ID: unused 145th trailing bit must be 0");
    }
    acc = (acc << 5) | val;
    bits += 5;
    if (bits >= 8) {
      bits -= 8;
      raw[w++] = (acc >>> bits) & 0xff;
    }
  }

  const view = new DataView(raw.buffer, 0, 18);
  const gotCrc = view.getUint16(16, false);
  const wantCrc = crc16T10Dif(raw.subarray(0, 16));
  if (gotCrc !== wantCrc) {
    throw new Error("T10-DIF CRC-16 checksum mismatch");
  }

  const tsHi = BigInt(view.getUint16(0, false));
  const tsLo = BigInt(view.getUint32(2, false));
  const timestampMs = (tsHi << 32n) | tsLo;
  if (timestampMs === 0n) {
    throw new Error("Zero timestampMs forbidden");
  }

  const random80 = raw.subarray(6, 16);
  let nonZero = 0;
  for (let i = 0; i < 10; i++) nonZero |= random80[i]!;
  if (nonZero === 0) {
    throw new Error("All-zero 80-bit random field rejected");
  }

  return { timestampMs, random80, crc16: gotCrc };
}
