export function decodeNetFlowV9WithExactCount(
  pkt: Uint8Array,
  templates: Map<number, NetFlowV9TemplateSpec>,
): DecodedNetFlowV9Packet {
  if (pkt.byteLength < 24 || pkt.byteLength % 4 !== 0) {
    throw new Error("NetFlow v9 packet must be >= 24 bytes and 4-byte aligned");
  }
  const view = new DataView(pkt.buffer, pkt.byteOffset, pkt.byteLength);
  if (view.getUint16(0, false) !== 9) {
    throw new Error("Expected NetFlow version 9");
  }
  const headerCount = view.getUint16(2, false);
  if (headerCount === 0) {
    throw new Error("NetFlow v9 header count cannot be 0");
  }
  const sequenceNumber = view.getUint32(12, false);
  const sourceId = view.getUint32(16, false);

  let recordsBudget = headerCount;
  const flowRecords: Array<{
    templateId: number;
    values: Array<{ type: number; value: DecodedNetFlowField }>;
  }> = [];

  let off = 20;
  while (off < pkt.byteLength) {
    if (pkt.byteLength - off < 4) {
      throw new Error("Truncated NetFlow v9 FlowSet header");
    }
    const fsId = view.getUint16(off, false);
    const fsLen = view.getUint16(off + 2, false);
    if (fsLen < 4 || fsLen % 4 !== 0 || off + fsLen > pkt.byteLength) {
      throw new Error(`Invalid or unaligned FlowSet length ${fsLen}`);
    }
    const fsEnd = off + fsLen;
    let cur = off + 4;

    if (fsId === 0) {
      while (cur < fsEnd) {
        if (recordsBudget === 0 || fsEnd - cur < 4) {
          if (fsEnd - cur >= 4) throw new Error("Excess padding (>=4B) in Template FlowSet");
          for (let p = cur; p < fsEnd; p++) {
            if (view.getUint8(p) !== 0) throw new Error("Non-zero Template FlowSet padding");
          }
          break;
        }
        const tmplId = view.getUint16(cur, false);
        const fCount = view.getUint16(cur + 2, false);
        if (tmplId === 0 && fCount === 0) {
          if (fsEnd - cur >= 4) throw new Error("Excess zero padding in Template FlowSet");
          break;
        }
        if (tmplId < 256 || fCount === 0 || cur + 4 + fCount * 4 > fsEnd) {
          throw new Error(`Malformed Template record ${tmplId}`);
        }
        cur += 4;
        const fields: Array<{ type: number; length: number }> = [];
        let recordSize = 0;
        for (let i = 0; i < fCount; i++) {
          const t = view.getUint16(cur, false);
          const l = view.getUint16(cur + 2, false);
          if (l === 0) throw new Error("Zero field length forbidden");
          fields.push({ type: t, length: l });
          recordSize += l;
          cur += 4;
        }
        templates.set(tmplId, { templateId: tmplId, fields, recordSize });
        recordsBudget--;
      }
    } else if (fsId >= 256) {
      const tmpl = templates.get(fsId);
      if (!tmpl) {
        throw new Error(`Unknown NetFlow v9 template ${fsId}`);
      }
      while (fsEnd - cur >= tmpl.recordSize && recordsBudget > 0) {
        // Guard small-record padding when remaining bytes < 4 and all-zero if another FlowSet follows
        const values: Array<{ type: number; value: DecodedNetFlowField }> = [];
        let fOff = cur;
        for (const f of tmpl.fields) {
          values.push({
            type: f.type,
            value: formatTypedField(view, pkt, fOff, f.type, f.length),
          });
          fOff += f.length;
        }
        flowRecords.push({ templateId: fsId, values });
        cur += tmpl.recordSize;
        recordsBudget--;
      }
      if (fsEnd - cur >= 4 && fsEnd - cur >= tmpl.recordSize) {
        throw new Error("Data FlowSet contains uncounted records exceeding header.count");
      }
      if (fsEnd - cur >= 4) {
        throw new Error(`Excess ${fsEnd - cur}-byte trailing padding in Data FlowSet`);
      }
      for (let p = cur; p < fsEnd; p++) {
        if (view.getUint8(p) !== 0) {
          throw new Error("Non-zero alignment padding in Data FlowSet");
        }
      }
    } else {
      throw new Error(`Unsupported FlowSet ID ${fsId}`);
    }

    off = fsEnd;
  }

  if (recordsBudget !== 0) {
    throw new Error(`NetFlow v9 header.count mismatch: ${recordsBudget} declared records missing`);
  }

  return { headerCount, sourceId, sequenceNumber, flowRecords };
}
