			return 0, 0, 0, 0, errors.New("cose: truncated 2B CBOR arg")
		}
		v := binary.BigEndian.Uint16(buf[cur : cur+2])
		if v < 256 {
			return 0, 0, 0, 0, errors.New("cose: non-canonical 2B CBOR arg")
		}
		return maj, ai, uint64(v), cur + 2, nil
	case 26:
		if cur+4 > len(buf) {
			return 0, 0, 0, 0, errors.New("cose: truncated 4B CBOR arg")
		}
		v := binary.BigEndian.Uint32(buf[cur : cur+4])
		if v < 65536 {
			return 0, 0, 0, 0, errors.New("cose: non-canonical 4B CBOR arg")
		}
		return maj, ai, uint64(v), cur + 4, nil
	default:
		return 0, 0, 0, 0, fmt.Errorf("cose: unsupported CBOR ai=%d", ai)
	}
}

func appendCanonicalHead(dst []byte, maj uint8, n int) []byte {
	prefix := maj << 5
	switch {
	case n < 24:
		return append(dst, prefix|byte(n))
	case n <= 0xFF:
		return append(dst, prefix|24, byte(n))
	case n <= 0xFFFF:
		return append(dst, prefix|25, byte(n>>8), byte(n))
	default:
		return append(dst, prefix|26, byte(n>>24), byte(n>>16), byte(n>>8), byte(n))
	}
}

func parseProtectedMap(b []byte) (alg int, kid []byte, err error) {
	if bytes.Equal(b, []byte{0xA0}) {
		return 0, nil, errors.New("cose: RFC 9052 §3 forbids 0xa0 empty map inside protected bstr")
	}
	maj, _, count, cur, err := readCanonicalCBORHead(b, 0)
	if err != nil || maj != 5 || count == 0 {
		return 0, nil, errors.New("cose: protected header must be a non-empty CBOR map")
	}

	hasAlg := false
	var prevKey []byte
	for range int(count) {
		kStart := cur
		kmaj, _, karg, kEnd, err := readCanonicalCBORHead(b, cur)
		if err != nil || (kmaj != 0 && kmaj != 1) {
			return 0, nil, errors.New("cose: protected header keys must be canonical CBOR ints")
		}
		kWire := b[kStart:kEnd]
		if prevKey != nil && bytes.Compare(prevKey, kWire) >= 0 {
			return 0, nil, errors.New("cose: unsorted or duplicate protected header keys")
		}
		prevKey = kWire
		cur = kEnd

		label := int(karg)
		if kmaj == 1 {
			label = -1 - int(karg)
		}

		vmaj, _, varg, vEnd, err := readCanonicalCBORHead(b, cur)
		if err != nil {
			return 0, nil, err
		}
		cur = vEnd

		switch label {
		case 1: // alg
			if vmaj != 1 {
				return 0, nil, errors.New("cose: unsupported positive alg in COSE_Sign1")
			}
			a := -1 - int(varg)
			if a != -7 && a != -8 {
				return 0, nil, fmt.Errorf("cose: unsupported COSE alg %d (expected -7 or -8)", a)
			}
			alg = a
			hasAlg = true
		case 4: // kid
			if vmaj != 2 || varg == 0 || len(b)-cur < int(varg) {
				return 0, nil, errors.New("cose: invalid kid bstr in protected header")
			}
			kid = bytes.Clone(b[cur : cur+int(varg)])
			cur += int(varg)
		default:
			return 0, nil, fmt.Errorf("cose: unsupported protected header label %d", label)
		}
	}
	if cur != len(b) || !hasAlg {
		return 0, nil, errors.New("cose: protected map missing alg (1) or has trailing bytes")
	}
	return alg, kid, nil
}

func ParseCOSESign1(coseBuf, externalAAD, detachedPayload []byte, requireTag18 bool) (*ParsedCOSESign1, error) {
	off := 0
	if len(coseBuf) < 5 {
		return nil, errors.New("cose: buffer too short")
	}
	if coseBuf[0] == 0xD2 {
		off = 1
	} else if requireTag18 {
		return nil, errors.New("cose: missing mandatory CBOR Tag 18 (0xd2)")
	}

	if off >= len(coseBuf) || coseBuf[off] != 0x84 {
		return nil, errors.New("cose: COSE_Sign1 must be a 4-element CBOR array (0x84)")
	}
	off++

	// 1. protected: bstr
	pmaj, _, plen, pStart, err := readCanonicalCBORHead(coseBuf, off)
	if err != nil || pmaj != 2 || len(coseBuf)-pStart < int(plen) {
		return nil, errors.New("cose: invalid protected bstr")
	}
	protBytes := coseBuf[pStart : pStart+int(plen)]
	off = pStart + int(plen)
	alg, kid, err := parseProtectedMap(protBytes)
	if err != nil {
		return nil, err
	}

	// 2. unprotected: empty map 0xa0 in strict profile
	if off >= len(coseBuf) || coseBuf[off] != 0xA0 {
		return nil, errors.New("cose: strict COSE_Sign1 profile requires empty unprotected map (0xa0)")
	}
	off++

	// 3. payload: bstr or nil (0xf6)
	var effPayload []byte
	if off >= len(coseBuf) {
		return nil, errors.New("cose: truncated payload slot")
	}
	if coseBuf[off] == 0xF6 {
		if detachedPayload == nil {
			return nil, errors.New("cose: COSE_Sign1 payload is nil (detached) but detachedPayload is nil")
		}
		effPayload = detachedPayload
		off++
	} else {
		if detachedPayload != nil {
			return nil, errors.New("cose: inline payload present alongside non-nil detachedPayload")
		}
		bmaj, _, blen, bStart, err := readCanonicalCBORHead(coseBuf, off)
		if err != nil || bmaj != 2 || len(coseBuf)-bStart < int(blen) {
			return nil, errors.New("cose: invalid inline payload bstr")
		}
		effPayload = bytes.Clone(coseBuf[bStart : bStart+int(blen)])
		off = bStart + int(blen)
	}

	// 4. signature: 64-byte bstr for ES256 / EdDSA
	smaj, _, slen, sStart, err := readCanonicalCBORHead(coseBuf, off)
	if err != nil || smaj != 2 || slen != 64 || sStart+64 != len(coseBuf) {
		return nil, errors.New("cose: signature must be exact 64-byte bstr at end of COSE_Sign1")
	}
	sig := bytes.Clone(coseBuf[sStart : sStart+64])

	// Build Sig_structure = ["Signature1", body_protected, external_aad, payload]
	sigStruct := make([]byte, 0, 16+len(protBytes)+len(externalAAD)+len(effPayload))
	sigStruct = append(sigStruct, 0x84, 0x6A) // 4-elem array + 10-byte tstr
	sigStruct = append(sigStruct, "Signature1"...)
	sigStruct = appendCanonicalHead(sigStruct, 2, len(protBytes))
	sigStruct = append(sigStruct, protBytes...)
	sigStruct = appendCanonicalHead(sigStruct, 2, len(externalAAD))
	sigStruct = append(sigStruct, externalAAD...)
	sigStruct = appendCanonicalHead(sigStruct, 2, len(effPayload))
	sigStruct = append(sigStruct, effPayload...)

	return &ParsedCOSESign1{
		Alg:              alg,
		KeyID:            kid,
		ProtectedRaw:     bytes.Clone(protBytes),
		EffectivePayload: effPayload,
		Signature:        sig,
		SigStructureCBOR: sigStruct,
	}, nil
}
