from __future__ import annotations

import struct
from dataclasses import dataclass
from typing import Literal


class EMVDiscretionaryError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class IssuerAppDataParsed:
    raw: bytes
    derivation_key_index: int
    cryptogram_version: int
    card_verification_results: bytes


@dataclass(frozen=True, slots=True)
class BerNode:
    tag: str
    constructed: bool
    value: bytes
    children: tuple["BerNode", ...] = ()
    iad_parsed: IssuerAppDataParsed | None = None


def _read_emv_tag(mv: memoryview, off: int, end: int) -> tuple[str, bool, int]:
    if off >= end:
        raise EMVDiscretionaryError("truncated EMV BER-TLV tag")
    b0 = mv[off]
    constructed = (b0 & 0x20) != 0
    if (b0 & 0x1F) != 0x1F:
        return f"{b0:02X}", constructed, off + 1

    cur = off + 1
    tnum = 0
    cnt = 0
    while True:
        if cur >= end or cnt >= 2:
            raise EMVDiscretionaryError("truncated or >3-byte EMV tag")
        b = mv[cur]
        cur += 1
        cnt += 1
        if cnt == 1 and (b & 0x7F) == 0:
            raise EMVDiscretionaryError("non-canonical leading zero in multi-byte EMV tag")
        tnum = (tnum << 7) | (b & 0x7F)
        if (b & 0x80) == 0:
            break
    if tnum < 31:
        raise EMVDiscretionaryError("non-canonical multi-byte EMV tag < 31")
    return bytes(mv[off:cur]).hex().upper(), constructed, cur


def _read_emv_len(mv: memoryview, off: int, end: int) -> tuple[int, int]:
    if off >= end:
        raise EMVDiscretionaryError("truncated BER length")
    b0 = mv[off]
    if b0 < 0x80:
        return b0, off + 1
    if b0 == 0x81:
        if off + 2 > end or mv[off + 1] < 128:
            raise EMVDiscretionaryError("invalid or non-canonical 0x81 length")
        return mv[off + 1], off + 2
    if b0 == 0x82:
        if off + 3 > end:
            raise EMVDiscretionaryError("truncated 0x82 length")
        (v,) = struct.unpack_from(">H", mv, off + 1)
        if v < 256:
            raise EMVDiscretionaryError("non-canonical 0x82 length < 256")
        return v, off + 3
    raise EMVDiscretionaryError(f"unsupported or indefinite BER length 0x{b0:02X}")


def _decode_iad_9f10(val: bytes) -> IssuerAppDataParsed:
    if not (4 <= len(val) <= 32):
        raise EMVDiscretionaryError(f"9F10 IAD length {len(val)} outside 4..32 bytes")
    prefix_len = val[0]
    if prefix_len < 3 or 1 + prefix_len > len(val):
        raise EMVDiscretionaryError(f"9F10 IAD internal length byte {prefix_len} out of bounds")
    dki = val[1]
    cvn = val[2]
    cvr = val[3 : 1 + prefix_len]
    return IssuerAppDataParsed(
        raw=val,
        derivation_key_index=dki,
        cryptogram_version=cvn,
        card_verification_results=cvr,
    )


def parse_emv_ber_stream(
    data: bytes | bytearray | memoryview,
    *,
    duplicate_policy: Literal["reject", "preserve_order"] = "reject",
    max_depth: int = 6,
) -> tuple[BerNode, ...]:
    if duplicate_policy not in ("reject", "preserve_order"):
        raise ValueError(f"invalid duplicate_policy {duplicate_policy!r}")
    mv = memoryview(data)

    def _walk(start: int, end: int, depth: int) -> tuple[BerNode, ...]:
        if depth > max_depth:
            raise EMVDiscretionaryError(f"BER-TLV depth {depth} > {max_depth}")
        nodes: list[BerNode] = []
        seen: set[str] = set()
        off = start

        while off < end:
            tag, cons, after_tag = _read_emv_tag(mv, off, end)
            vlen, val_start = _read_emv_len(mv, after_tag, end)
            val_end = val_start + vlen
            if val_end > end:
                raise EMVDiscretionaryError(f"tag {tag} overruns container")

            if duplicate_policy == "reject" and tag in seen:
                raise EMVDiscretionaryError(f"duplicate tag {tag} rejected by policy")
            seen.add(tag)

            val_bytes = bytes(mv[val_start:val_end])
            if tag == "9F10":
                if cons:
                    raise EMVDiscretionaryError("9F10 (IAD) must be a primitive BER-TLV")
                nodes.append(BerNode(tag=tag, constructed=False, value=val_bytes, iad_parsed=_decode_iad_9f10(val_bytes)))
            elif cons:
                children = _walk(val_start, val_end, depth + 1)
                nodes.append(BerNode(tag=tag, constructed=True, value=val_bytes, children=children))
            else:
                nodes.append(BerNode(tag=tag, constructed=False, value=val_bytes))

            off = val_end

        return tuple(nodes)

    return _walk(0, len(mv), 0)
