```go
package tlshrr

import (
	"bytes"
	"crypto/subtle"
	"encoding/binary"
	"errors"
	"fmt"
)

type RetriedClientHelloResult struct {
	SelectedGroup uint16
	KeyExchange   []byte
	PSKModes      []uint8
	CookieMatched bool
}

func ValidateRetriedClientHelloExtensions(
	extBlock []byte,
	selectedGroup *uint16,
	expectedHRRCookie []byte,
) (*RetriedClientHelloResult, error) {
	if len(extBlock) < 6 {
		return nil, errors.New("tlshrr: extensions block too short")
	}
	blockLen := int(binary.BigEndian.Uint16(extBlock[0:2]))
	if 2+blockLen != len(extBlock) {
		return nil, errors.New("tlshrr: outer extensions block length mismatch")
	}

	seen := make(map[uint16]struct{})
	var out RetriedClientHelloResult
	sawKeyShare := false
	sawCookie := false

	off := 2
	for off < len(extBlock) {
		if len(extBlock)-off < 4 {
			return nil, errors.New("tlshrr: truncated extension header")
		}
		eType := binary.BigEndian.Uint16(extBlock[off : off+2])
		eLen := int(binary.BigEndian.Uint16(extBlock[off+2 : off+4]))
		off += 4
		if len(extBlock)-off < eLen {
			return nil, fmt.Errorf("tlshrr: extension 0x%04x overruns block", eType)
		}
		if _, dup := seen[eType]; dup {
			return nil, fmt.Errorf("tlshrr: duplicate extension 0x%04x", eType)
		}
		seen[eType] = struct{}{}
		ext := extBlock[off : off+eLen]
		off += eLen

		switch eType {
		case 0x002A: // early_data
			return nil, errors.New("tlshrr: illegal_parameter: early_data (0x002a) forbidden in retried ClientHello")

		case 0x002C: // cookie
			if len(expectedHRRCookie) == 0 {
				return nil, errors.New("tlshrr: unsolicited cookie (0x002c) in ClientHello2")
			}
			if eLen < 3 {
				return nil, errors.New("tlshrr: cookie extension < 3 bytes")
			}
			cLen := int(binary.BigEndian.Uint16(ext[0:2]))
			if cLen == 0 || 2+cLen != eLen {
				return nil, errors.New("tlshrr: cookie nested length mismatch")
			}
			if len(ext[2:]) != len(expectedHRRCookie) ||
				subtle.ConstantTimeCompare(ext[2:], expectedHRRCookie) != 1 {
				return nil, errors.New("tlshrr: illegal_parameter: ClientHello2 cookie mismatch")
			}
			sawCookie = true
			out.CookieMatched = true

		case 0x0033: // key_share
			if eLen < 7 {
				return nil, errors.New("tlshrr: key_share too short")
			}
			sharesLen := int(binary.BigEndian.Uint16(ext[0:2]))
			if 2+sharesLen != eLen {
				return nil, errors.New("tlshrr: key_share client_shares_len mismatch")
			}
			if selectedGroup != nil {
				grp := binary.BigEndian.Uint16(ext[2:4])
				kexLen := int(binary.BigEndian.Uint16(ext[4:6]))
				if kexLen == 0 || 4+kexLen != sharesLen {
					return nil, errors.New("tlshrr: illegal_parameter: retried key_share MUST contain exactly 1 share")
				}
				if grp != *selectedGroup {
					return nil, fmt.Errorf("tlshrr: key_share group 0x%04x != HRR selected 0x%04x", grp, *selectedGroup)
				}
				out.SelectedGroup = grp
				out.KeyExchange = bytes.Clone(ext[6:])
			}
			sawKeyShare = true

		case 0x002D: // psk_key_exchange_modes
			if eLen < 2 {
				return nil, errors.New("tlshrr: psk_key_exchange_modes < 2 bytes")
			}
			mLen := int(ext[0])
			if mLen == 0 || 1+mLen != eLen {
				return nil, errors.New("tlshrr: psk_key_exchange_modes length mismatch")
			}
			seenModes := make(map[uint8]struct{}, mLen)
			for i := 1; i < eLen; i++ {
				m := ext[i]
				if _, dup := seenModes[m]; dup {
					return nil, errors.New("tlshrr: duplicate mode in psk_key_exchange_modes")
				}
				seenModes[m] = struct{}{}
				out.PSKModes = append(out.PSKModes, m)
			}
		}
	}

	if len(expectedHRRCookie) > 0 && !sawCookie {
		return nil, errors.New("tlshrr: missing_extension: retried ClientHello omitted HRR cookie")
	}
	if selectedGroup != nil && !sawKeyShare {
		return nil, errors.New("tlshrr: missing_extension: retried ClientHello omitted key_share")
	}
	return &out, nil
}
