from __future__ import annotations

import base64
import hashlib
import hmac
import json
import re
from dataclasses import dataclass
from typing import Any
from urllib.parse import urlsplit

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import encode_dss_signature

SECP256R1_N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
B64U_RE = re.compile(r"^[A-Za-z0-9_-]+$")


class DPoPVerificationError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class VerifiedDPoPProof:
    jti: str
    iat: int
    jwk_thumbprint_s256: str
    htm: str
    htu: str


def _b64u_encode(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode("ascii")


def _b64u_decode_strict(s: str) -> bytes:
    if not isinstance(s, str) or not s or not B64U_RE.fullmatch(s) or (len(s) % 4) == 1:
        raise DPoPVerificationError("invalid unpadded Base64url segment")
    raw = base64.urlsafe_b64decode(s + ("=" * ((4 - (len(s) % 4)) % 4)))
    if _b64u_encode(raw) != s:
        raise DPoPVerificationError("non-canonical Base64url trailing bits")
    return raw


def _no_dup_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for k, v in pairs:
        if k in out:
            raise DPoPVerificationError(f"duplicate JSON key {k!r} in DPoP JWS")
        out[k] = v
    return out


def _canonical_htu(uri: str) -> str:
    sp = urlsplit(uri)
    if sp.scheme not in ("http", "https") or not sp.netloc or sp.query or sp.fragment:
        raise DPoPVerificationError(f"invalid DPoP htu (query/fragment forbidden): {uri!r}")
    return f"{sp.scheme}://{sp.netloc}{sp.path or '/'}"


def verify_dpop_es256(
    dpop_jwt: str,
    *,
    expected_method: str,
    expected_uri: str,
    now_epoch_sec: int,
    bound_access_token: str | None = None,
    max_past_sec: int = 120,
    max_skew_sec: int = 15,
) -> VerifiedDPoPProof:
    parts = dpop_jwt.split(".")
    if len(parts) != 3 or not all(parts):
        raise DPoPVerificationError("DPoP proof must be a 3-segment compact JWS")

    hdr_bytes = _b64u_decode_strict(parts[0])
    pay_bytes = _b64u_decode_strict(parts[1])
    sig_bytes = _b64u_decode_strict(parts[2])
    if len(sig_bytes) != 64:
        raise DPoPVerificationError("ES256 DPoP signature must be 64 bytes")

    try:
        hdr = json.loads(hdr_bytes.decode("utf-8", errors="strict"), object_pairs_hook=_no_dup_keys)
        claims = json.loads(pay_bytes.decode("utf-8", errors="strict"), object_pairs_hook=_no_dup_keys)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise DPoPVerificationError("malformed JSON in DPoP header or claims") from exc

    if not isinstance(hdr, dict) or not isinstance(claims, dict):
        raise DPoPVerificationError("DPoP header and claims must be JSON objects")

    typ = hdr.get("typ")
    if not isinstance(typ, str) or typ.lower() != "dpop+jwt":
        raise DPoPVerificationError("DPoP header typ must equal 'dpop+jwt'")
    if hdr.get("alg") != "ES256" or "crit" in hdr:
        raise DPoPVerificationError("DPoP header must pin alg='ES256' without unknown crit")

