    x_b = _b64u_decode_strict(x_str) if isinstance(x_str, str) else b""
    y_b = _b64u_decode_strict(y_str) if isinstance(y_str, str) else b""
    if len(x_b) != 32 or len(y_b) != 32:
        raise DPoPVerificationError("invalid P-256 x/y coordinate length in header.jwk")

    try:
        pub_nums = ec.EllipticCurvePublicNumbers(
            int.from_bytes(x_b, "big"),
            int.from_bytes(y_b, "big"),
            ec.SECP256R1(),
        )
        pub_key = pub_nums.public_key()
    except ValueError as exc:
        raise DPoPVerificationError("header.jwk point is not on P-256 curve") from exc

    r = int.from_bytes(sig_bytes[:32], "big")
    s = int.from_bytes(sig_bytes[32:], "big")
