    except InvalidSignature as exc:
        raise DPoPVerificationError("DPoP ES256 signature verification failed") from exc

    jti = claims.get("jti")
    iat = claims.get("iat")
    htm = claims.get("htm")
    htu = claims.get("htu")
    if not isinstance(jti, str) or not (1 <= len(jti) <= 256):
        raise DPoPVerificationError("invalid or missing DPoP jti")
    if type(iat) is not int or not (now_epoch_sec - max_past_sec <= iat <= now_epoch_sec + max_skew_sec):
        raise DPoPVerificationError("DPoP iat outside freshness window")
    if htm != expected_method:
        raise DPoPVerificationError(f"DPoP htm {htm!r} != {expected_method!r}")
    if not isinstance(htu, str) or _canonical_htu(htu) != _canonical_htu(expected_uri):
        raise DPoPVerificationError("DPoP htu mismatch")

