```go
package webauthnpolicy

import (
	"bytes"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/binary"
	"errors"
	"fmt"
)

type EnterprisePolicy struct {
	RPID                   string
	PrevSignCount          uint32
	ForbidSyncedPasskeys   bool // Reject BE=1 (0x08)
	RequireHardwareCounter bool // Reject signCount==0 or <= PrevSignCount
}

type AuditedAssertionAuthData struct {
	SignCount        uint32
	BackupEligible   bool
	BackupState      bool
	CredBlob         []byte
	HMACSecretOutput []byte // 32 or 64 bytes
}

func readCanonicalCBORHead(b []byte, off int) (maj uint8, arg int, next int, err error) {
	if off >= len(b) {
		return 0, 0, 0, errors.New("webauthn: truncated extension CBOR head")
	}
	maj = b[off] >> 5
	ai := b[off] & 0x1F
	cur := off + 1
	if ai < 24 {
		return maj, int(ai), cur, nil
	}
	switch ai {
	case 24:
		if cur+1 > len(b) || b[cur] < 24 {
			return 0, 0, 0, errors.New("webauthn: non-canonical 1B CBOR length")
		}
		return maj, int(b[cur]), cur + 1, nil
	case 25:
		if cur+2 > len(b) {
			return 0, 0, 0, errors.New("webauthn: truncated 2B CBOR length")
		}
		v := int(binary.BigEndian.Uint16(b[cur : cur+2]))
		if v < 256 {
			return 0, 0, 0, errors.New("webauthn: non-canonical 2B CBOR length")
		}
		return maj, v, cur + 2, nil
	default:
		return 0, 0, 0, fmt.Errorf("webauthn: unsupported CBOR ai=%d", ai)
	}
}

func AuditAssertionAuthData(authData []byte, pol EnterprisePolicy) (*AuditedAssertionAuthData, error) {
	if len(authData) < 37 {
		return nil, errors.New("webauthn: authenticatorData < 37 bytes")
	}
	wantRP := sha256.Sum256([]byte(pol.RPID))
	if subtle.ConstantTimeCompare(authData[0:32], wantRP[:]) != 1 {
		return nil, errors.New("webauthn: rpIdHash mismatch")
	}

	flags := authData[32]
	if (flags&0x01) == 0 || (flags&0x04) == 0 {
		return nil, errors.New("webauthn: enterprise policy requires both UP=1 and UV=1")
	}
	if (flags & 0x40) != 0 {
		return nil, errors.New("webauthn: AT=1 forbidden in assertion")
	}
	be := (flags & 0x08) != 0
	bs := (flags & 0x10) != 0
	if bs && !be {
		return nil, errors.New("webauthn: illegal BS=1 with BE=0")
	}
	if pol.ForbidSyncedPasskeys && be {
		return nil, errors.New("webauthn: policy forbids backup-eligible (synced) passkeys")
	}

	signCount := binary.BigEndian.Uint32(authData[33:37])
	if pol.RequireHardwareCounter {
		if signCount == 0 || signCount <= pol.PrevSignCount {
			return nil, fmt.Errorf("webauthn: hardware signCount %d invalid (prev=%d)", signCount, pol.PrevSignCount)
		}
	} else if (pol.PrevSignCount > 0 || signCount > 0) && signCount <= pol.PrevSignCount {
		return nil, errors.New("webauthn: signCount rollback detected")
	}

	out := &AuditedAssertionAuthData{
		SignCount:      signCount,
		BackupEligible: be,
		BackupState:    bs,
	}

	hasED := (flags & 0x80) != 0
	if !hasED {
		if len(authData) != 37 {
			return nil, errors.New("webauthn: trailing bytes when ED=0")
		}
		return out, nil
	}

	ext := authData[37:]
	maj, mapCnt, cur, err := readCanonicalCBORHead(ext, 0)
	if err != nil || maj != 5 || mapCnt == 0 {
		return nil, errors.New("webauthn: ED=1 requires non-empty CBOR extension map")
	}

	var prevKeyWire []byte
	for range mapCnt {
		kStart := cur
		kmaj, klen, kValStart, err := readCanonicalCBORHead(ext, cur)
		if err != nil || kmaj != 3 || len(ext)-kValStart < klen {
			return nil, errors.New("webauthn: extension key must be canonical tstr")
		}
		kEnd := kValStart + klen
		kWire := ext[kStart:kEnd]
		if prevKeyWire != nil && bytes.Compare(prevKeyWire, kWire) >= 0 {
			return nil, errors.New("webauthn: non-canonical or duplicate extension map key")
		}
		prevKeyWire = kWire
		keyName := string(ext[kValStart:kEnd])
		cur = kEnd

		vmaj, vlen, vStart, err := readCanonicalCBORHead(ext, cur)
		if err != nil || vmaj != 2 || len(ext)-vStart < vlen {
			return nil, fmt.Errorf("webauthn: extension %q value must be canonical bstr", keyName)
		}
		val := ext[vStart : vStart+vlen]
		cur = vStart + vlen

		switch keyName {
		case "credBlob":
			if vlen < 1 || vlen > 256 {
				return nil, errors.New("webauthn: credBlob length outside 1..256")
			}
			out.CredBlob = bytes.Clone(val)
		case "hmac-secret":
			if vlen != 32 && vlen != 64 {
				return nil, fmt.Errorf("webauthn: hmac-secret output must be 32 or 64 bytes, got %d", vlen)
			}
			out.HMACSecretOutput = bytes.Clone(val)
		default:
			return nil, fmt.Errorf("webauthn: unapproved assertion extension %q", keyName)
		}
	}

	if cur != len(ext) {
		return nil, errors.New("webauthn: unconsumed trailing bytes after extensions map")
	}
	return out, nil
}
