            self._opt_templates[(source_id, tmpl_id)] = OptionsTemplateLayout(
                template_id=tmpl_id,
                scope_fields=tuple(scopes),
                option_fields=tuple(opts),
                record_size=rec_sz,
            )

    def _decode_options_data(
        self,
        source_id: int,
        flowset_id: int,
        body: memoryview,
    ) -> list[DecodedOptionsRecord]:
