const VALID_SEV_WORDS = new Set(["Unknown", "Low", "Medium", "High", "Very-High"]);

export interface StreamedCefRecord {
  syslogPrefix: string;
  version: 0 | 1;
  vendor: string;
  product: string;
  deviceVersion: string;
  eventClassId: string;
  name: string;
  severity: string;
  extensions: Record<string, string>;
}

function isExtKeyByte(b: number): boolean {
  return (
    (b >= 0x41 && b <= 0x5a) ||
    (b >= 0x61 && b <= 0x7a) ||
    (b >= 0x30 && b <= 0x39) ||
    b === 0x5f ||
    b === 0x2e ||
    b === 0x2d
  );
}

function isValidSev(s: string): boolean {
  if (VALID_SEV_WORDS.has(s) || s === "10") return true;
  return s.length === 1 && s.charCodeAt(0) >= 0x30 && s.charCodeAt(0) <= 0x39;
}

function parseSingleCefLine(line: Uint8Array): StreamedCefRecord {
  if (line.byteLength < 11) {
    throw new Error("Empty or truncated CEF line");
  }

