export function parseCefTcpStream(
  chunk: Uint8Array,
  maxLineBytes = 65_536,
): { events: StreamedCefRecord[]; bytesConsumed: number } {
  const view = new DataView(chunk.buffer, chunk.byteOffset, chunk.byteLength);
  const events: StreamedCefRecord[] = [];
  let lineStart = 0;

  for (let i = 0; i < chunk.byteLength; i++) {
    const b = view.getUint8(i);
    if (b === 0x00) {
      throw new Error(`Forbidden NUL byte in CEF TCP stream at offset ${i}`);
    }
    if (i - lineStart > maxLineBytes) {
      throw new Error(`CEF line exceeds maxLineBytes (${maxLineBytes})`);
    }

    if (b === 0x0d) {
      if (i + 1 >= chunk.byteLength) {
        // Trailing '\r' split right across TCP read boundary: wait for '\n'
        return { events, bytesConsumed: lineStart };
      }
      if (view.getUint8(i + 1) !== 0x0a) {
        throw new Error(`Bare CR without LF in CEF TCP stream at offset ${i}`);
      }
      events.push(parseSingleCefLine(chunk.subarray(lineStart, i)));
      i++; // consume LF
      lineStart = i + 1;
      continue;
    }

    if (b === 0x0a) {
      events.push(parseSingleCefLine(chunk.subarray(lineStart, i)));
      lineStart = i + 1;
    }
  }

  if (chunk.byteLength - lineStart > maxLineBytes) {
    throw new Error(`Incomplete trailing CEF line exceeds maxLineBytes (${maxLineBytes})`);
  }

  return { events, bytesConsumed: lineStart };
}
