  | { kind: "blob"; value: Uint8Array; attrs?: Map<string, Resp3DemuxNode> }
  | { kind: "verbatim"; format: string; value: Uint8Array; attrs?: Map<string, Resp3DemuxNode> }
  | { kind: "array"; items: Resp3DemuxNode[]; attrs?: Map<string, Resp3DemuxNode> }
  | { kind: "push"; pushType: string; items: Resp3DemuxNode[]; attrs?: Map<string, Resp3DemuxNode> };

export type Resp3DemuxResult =
