export type BgpStreamFrame =
  | { kind: "KEEPALIVE" }
  | {
      kind: "OPEN";
      myAs: number;
      fourOctetAsn?: number;
      holdTime: number;
      bgpId: string;
      multiprotocol: Array<{ afi: number; safi: number }>;
      routeRefresh: boolean;
      enhancedRouteRefresh: boolean;
