export function parseBgpTcpStream(buf: Uint8Array): {
  messages: BgpStreamFrame[];
  bytesConsumed: number;
} {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const messages: BgpStreamFrame[] = [];
  let off = 0;

