      if (msgLen !== 19) {
        throw new BgpHeaderError(1, 2, `Bad Message Length: KEEPALIVE length ${msgLen} != 19`);
      }
      messages.push({ kind: "KEEPALIVE" });
      off += 19;
      continue;
    }

    if (msgType !== 1) {
      throw new BgpHeaderError(1, 3, `Bad Message Type ${msgType} in OPEN/KEEPALIVE handshake state`);
    }
    if (msgLen < 29) {
      throw new BgpHeaderError(1, 2, `Bad Message Length: OPEN length ${msgLen} < 29`);
    }

    if (buf.byteLength - off < msgLen) {
      break; // Wait for full TCP BGP OPEN frame
    }

    const msgEnd = off + msgLen;
    const version = view.getUint8(off + 19);
    if (version !== 4) {
      throw new BgpHeaderError(2, 1, `Unsupported Version Number ${version}`);
    }

    const myAs = view.getUint16(off + 20, false);
    if (myAs === 0) {
      throw new BgpHeaderError(2, 2, "Bad Peer AS: AS 0 forbidden");
    }

    const holdTime = view.getUint16(off + 22, false);
    if (holdTime === 1 || holdTime === 2) {
      throw new BgpHeaderError(2, 6, `Unacceptable Hold Time ${holdTime}`);
    }

    const id0 = view.getUint8(off + 24);
    if ((id0 === 0 && view.getUint32(off + 24, false) === 0) || id0 >= 224) {
      throw new BgpHeaderError(2, 3, "Bad BGP Identifier");
    }
    const bgpId = `${id0}.${view.getUint8(off + 25)}.${view.getUint8(off + 26)}.${view.getUint8(off + 27)}`;

    const optLen = view.getUint8(off + 28);
    if (off + 29 + optLen !== msgEnd) {
      throw new BgpHeaderError(2, 0, "OPEN Opt Parm Len mismatch");
    }

    let pCur = off + 29;
    let fourOctetAsn: number | undefined;
    const multiprotocol: Array<{ afi: number; safi: number }> = [];
    let routeRefresh = false;
    let enhancedRouteRefresh = false;

    while (pCur < msgEnd) {
      if (msgEnd - pCur < 2) {
        throw new BgpHeaderError(2, 0, "Truncated Optional Parameter header");
      }
      const pType = view.getUint8(pCur);
      const pLen = view.getUint8(pCur + 1);
