import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
	"strings"
)

type CertCompressionAlg struct {
	Code uint16
	Name string
}

type AuditedClientHelloExts struct {
	ServerName          string
	ALPNProtocols       []string
