	out := make([]CertCompressionAlg, 0, vecLen/2)
	for off := 1; off < len(ext); off += 2 {
		code := binary.BigEndian.Uint16(ext[off : off+2])
		if code == 0 {
			return nil, errors.New("tls8879: reserved CertificateCompressionAlgorithm 0x0000 rejected")
		}
		if _, dup := seen[code]; dup {
			return nil, fmt.Errorf("tls8879: duplicate compression algorithm 0x%04x", code)
		}
		seen[code] = struct{}{}
		out = append(out, CertCompressionAlg{Code: code, Name: algName(code)})
	}
	return out, nil
}

