@dataclass(frozen=True, slots=True)
class ParsedNSEC3RData:
    hash_algorithm: int
    opt_out: bool
    iterations: int
    salt: bytes
    next_hashed_owner_b32hex: str  # Canonical lowercase 32-char RFC 5155 presentation
    covered_rr_types: tuple[int, ...]


def encode_nsec3_owner_hash(raw20: bytes) -> str:
