        raise NSEC3ParseError(f"SHA-1 NSEC3 hash_length must be 20, got {hash_len}")

    hash_start = salt_end + 1
    hash_end = hash_start + 20
    if hash_end > len(mv):
        raise NSEC3ParseError("truncated 20-byte NSEC3 next_hashed_owner")

    owner_b32 = encode_nsec3_owner_hash(bytes(mv[hash_start:hash_end]))
    rr_types = _parse_type_bit_maps(mv[hash_end:])

    return ParsedNSEC3RData(
        hash_algorithm=hash_alg,
        opt_out=(flags & 0x01) != 0,
        iterations=iterations,
        salt=salt,
        next_hashed_owner_b32hex=owner_b32,
        covered_rr_types=rr_types,
    )
