package ipfixtime

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
	"time"
)

const ntpToUnixEpochDiff int64 = 2_208_988_800 // Seconds between 1900-01-01 and 1970-01-01

type FieldDef struct {
	IEID   uint16
	Length uint16
}

type DecodedTimedFlow struct {
	SourceAddr netip.Addr
	StartTime  time.Time
}

func ntp64ToUTC(ntpSec, ntpFrac uint32, isMicro bool) (time.Time, error) {
	if isMicro && (ntpFrac&0x000007FF) != 0 {
		return time.Time{}, fmt.Errorf(
			"ipfix: RFC 7011 §6.1.8 violation: non-zero bottom 11 bits in dateTimeMicroseconds fraction 0x%08x",
			ntpFrac,
		)
	}
	// RFC 4330 §3: if MSB (bit 31) is 0, time is in NTP Era 1 (2036-02-07..2104)
	var fullNTP uint64
	if (ntpSec & 0x80000000) == 0 {
		fullNTP = uint64(ntpSec) + (1 << 32)
	} else {
		fullNTP = uint64(ntpSec)
	}
	unixSec := int64(fullNTP) - ntpToUnixEpochDiff
	nanos := int64((uint64(ntpFrac) * 1_000_000_000) >> 32)
	return time.Unix(unixSec, nanos).UTC(), nil
}

func DecodeTimedDataSet(setBytes []byte, expectedTemplateID uint16, fields []FieldDef) ([]DecodedTimedFlow, error) {
	if len(setBytes) < 4 {
		return nil, errors.New("ipfix: Data Set < 4 bytes")
	}
	setID := binary.BigEndian.Uint16(setBytes[0:2])
	setLen := int(binary.BigEndian.Uint16(setBytes[2:4]))
	if setID != expectedTemplateID || setLen != len(setBytes) {
		return nil, errors.New("ipfix: Data Set header ID or length mismatch")
	}

	recSize := 0
	for _, f := range fields {
		switch f.IEID {
		case 8:
			if f.Length != 4 {
				return nil, errors.New("ipfix: sourceIPv4Address (8) must be 4 bytes")
			}
		case 27:
			if f.Length != 16 {
				return nil, errors.New("ipfix: sourceIPv6Address (27) must be 16 bytes")
			}
		case 152, 154, 156:
			if f.Length != 8 {
				return nil, fmt.Errorf("ipfix: timestamp IE %d must be 8 bytes", f.IEID)
			}
		default:
			if f.Length == 0 {
				return nil, errors.New("ipfix: zero field length")
			}
		}
		recSize += int(f.Length)
	}
	if recSize == 0 {
		return nil, errors.New("ipfix: empty template")
	}

	var out []DecodedTimedFlow
	off := 4
	for len(setBytes)-off >= recSize {
		if len(out) > 0 && len(setBytes)-off < 4 {
			break
		}
		var flow DecodedTimedFlow
		cur := off
		for _, f := range fields {
			val := setBytes[cur : cur+int(f.Length)]
			cur += int(f.Length)

			switch f.IEID {
			case 8:
				flow.SourceAddr = netip.AddrFrom4([4]byte(val))
			case 27:
				flow.SourceAddr = netip.AddrFrom16([16]byte(val))
			case 152:
				ms := binary.BigEndian.Uint64(val)
				flow.StartTime = time.UnixMilli(int64(ms)).UTC()
			case 154:
				sec := binary.BigEndian.Uint32(val[0:4])
				frac := binary.BigEndian.Uint32(val[4:8])
				t, err := ntp64ToUTC(sec, frac, true)
				if err != nil {
					return nil, err
				}
				flow.StartTime = t
			case 156:
				sec := binary.BigEndian.Uint32(val[0:4])
				frac := binary.BigEndian.Uint32(val[4:8])
				t, err := ntp64ToUTC(sec, frac, false)
				if err != nil {
					return nil, err
				}
				flow.StartTime = t
			}
		}
		out = append(out, flow)
		off = cur
	}

	for p := off; p < len(setBytes); p++ {
		if setBytes[p] != 0 {
			return nil, errors.New("ipfix: non-zero padding in Data Set")
		}
	}
	return out, nil
}
