from collections.abc import Sequence
from dataclasses import dataclass

LOWER_HEX = frozenset("0123456789abcdef")
SIMPLE_KEY_RE = re.compile(r"^[a-z][a-z0-9_\-*/]{0,255}$")
TENANT_KEY_RE = re.compile(r"^[a-z0-9][a-z0-9_\-*/]{0,240}@[a-z][a-z0-9_\-*/]{0,13}$")


class HTTPTraceContextError(ValueError):
    pass


class DuplicateTraceparentError(HTTPTraceContextError):
    pass


@dataclass(frozen=True, slots=True)
class PropagatedHTTPTraceContext:
    version: int
    trace_id: str
    parent_id: str
    trace_flags: int
    tracestate_pairs: tuple[tuple[str, str], ...]
