    return 0x21 <= ord(last) <= 0x7E and last not in (",", "=")


def parse_http_trace_headers(
    traceparent_headers: Sequence[str],
    tracestate_headers: Sequence[str] = (),
) -> PropagatedHTTPTraceContext:
