        raise HTTPTraceContextError("traceparent requires strictly lowercase hex")
    if ver_s == "ff":
        raise HTTPTraceContextError("traceparent version 'ff' is forbidden")
    if tid == "0" * 32 or pid == "0" * 16:
        raise HTTPTraceContextError("all-zero trace-id or parent-id is forbidden")

    ver = int(ver_s, 16)
    if ver == 0 and len(tp) != 55:
        raise HTTPTraceContextError("v00 traceparent must be exact 55 characters")
    if ver > 0 and len(tp) > 55 and tp[55] != "-":
        raise HTTPTraceContextError("future traceparent suffix must start with '-'")

    combined_ts = ",".join(tracestate_headers)
    pairs: list[tuple[str, str]] = []
    seen_keys: set[str] = set()

    if combined_ts:
        for raw_member in combined_ts.split(","):
            member = raw_member.strip(" \t")
            if not member:
                continue
            if "=" not in member:
                raise HTTPTraceContextError(f"tracestate member missing '=': {member!r}")
            k, v = member.split("=", 1)
            if not _valid_ts_key(k) or not _valid_ts_val(v):
                raise HTTPTraceContextError(f"invalid tracestate member {member!r}")
            if k in seen_keys:
                raise HTTPTraceContextError(f"duplicate tracestate key {k!r} across HTTP headers")
            seen_keys.add(k)
            pairs.append((k, v))
            if len(pairs) > 32:
                raise HTTPTraceContextError("combined tracestate exceeds 32 list-members")

    canonical_ts = ",".join(f"{k}={v}" for k, v in pairs)
    return PropagatedHTTPTraceContext(
        version=ver,
        trace_id=tid,
        parent_id=pid,
        trace_flags=int(flg_s, 16),
        tracestate_pairs=tuple(pairs),
        canonical_tracestate_header=canonical_ts,
    )
