class PNGColorSpaceError(ValueError):
    pass


@dataclass(frozen=True, slots=True)
class PNGColorSpaceProfile:
    srgb_intent: int | None
    gamma_scaled: int | None
    chromaticities: tuple[int, ...] | None
    icc_profile_name: str | None
    icc_color_space_sig: str | None
    icc_raw_bytes: bytes | None


