        raise PNGColorSpaceError("incomplete, oversized, or trailing-garbage iCCP zlib stream")
    if len(icc) < 128:
        raise PNGColorSpaceError(f"ICC profile shorter than 128-byte ICC.1 header ({len(icc)} B)")
