    if declared_size != len(icc):
        raise PNGColorSpaceError(
            f"ICC header size {declared_size} != decompressed length {len(icc)}"
        )
    if icc[36:40] != b"acsp":
        raise PNGColorSpaceError(f"missing ICC 'acsp' signature at offset 36: {icc[36:40]!r}")
