        raise PNGColorSpaceError("invalid 8-byte PNG signature")

    off = 8
    idx = 0
    locked_after_plte_or_idat = False
    saw_iend = False

    srgb_intent: int | None = None
    gamma_scaled: int | None = None
    chrm: tuple[int, ...] | None = None
    icc_name: str | None = None
    icc_cs: str | None = None
    icc_bytes: bytes | None = None

