const utf8Fatal = new TextDecoder("utf-8", { fatal: true });

export type PgNegotiateOrAuthChallenge =
  | {
      kind: "NegotiateProtocolVersion";
      majorVersion: number;
      minorVersion: number;
      unrecognizedOptions: string[];
    }
  | { kind: "AuthenticationCleartextPassword" }
  | { kind: "AuthenticationMD5Password"; salt: Uint8Array }
  | { kind: "AuthenticationGSS" };

export function parsePgNegotiateOrAuthChallenge(
  buf: Uint8Array,
): PgNegotiateOrAuthChallenge {
  if (buf.byteLength < 9) {
    throw new Error(`Truncated PostgreSQL backend frame (${buf.byteLength} < 9 bytes)`);
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const tag = view.getUint8(0);
  const frameLen = view.getInt32(1, false);
  if (frameLen < 8 || 1 + frameLen !== buf.byteLength) {
    throw new Error(`PostgreSQL frame length ${frameLen} mismatches buffer ${buf.byteLength}`);
  }

  if (tag === 0x76) {
    // 'v' NegotiateProtocolVersion
    if (buf.byteLength < 13) {
      throw new Error("Truncated NegotiateProtocolVersion header");
    }
    const rawProto = view.getUint32(5, false);
    const majorVersion = rawProto >>> 16;
    const minorVersion = rawProto & 0xffff;
    if (majorVersion < 3) {
      throw new Error(`Unsupported PostgreSQL protocol major version ${majorVersion}`);
    }

    const numOpts = view.getInt32(9, false);
    if (numOpts < 0 || numOpts > 256) {
      throw new Error(`Invalid NegotiateProtocolVersion option count ${numOpts}`);
    }

    const unrecognizedOptions: string[] = [];
    let off = 13;
    for (let i = 0; i < numOpts; i++) {
      let nul = -1;
      for (let p = off; p < buf.byteLength; p++) {
        if (buf[p] === 0x00) {
          nul = p;
          break;
        }
      }
      if (nul < 0) {
        throw new Error("Unterminated option C-string in NegotiateProtocolVersion");
      }
      if (nul === off) {
        throw new Error("Empty unrecognized option name in NegotiateProtocolVersion");
      }
      unrecognizedOptions.push(utf8Fatal.decode(buf.subarray(off, nul)));
      off = nul + 1;
    }
    if (off !== buf.byteLength) {
      throw new Error("Trailing bytes after NegotiateProtocolVersion option list");
    }

    return {
      kind: "NegotiateProtocolVersion",
      majorVersion,
      minorVersion,
      unrecognizedOptions,
    };
  }

  if (tag === 0x52) {
    // 'R' Authentication*
    const authCode = view.getInt32(5, false);
    if (authCode === 3) {
      if (frameLen !== 8) {
        throw new Error("AuthenticationCleartextPassword must have length 8");
      }
      return { kind: "AuthenticationCleartextPassword" };
    }
    if (authCode === 5) {
      if (frameLen !== 12) {
        throw new Error("AuthenticationMD5Password must have length 12");
      }
      if (view.getUint32(9, false) === 0) {
        throw new Error("Rejected weak all-zero 4-byte MD5 salt");
      }
      return { kind: "AuthenticationMD5Password", salt: buf.subarray(9, 13) };
    }
    if (authCode === 7) {
      if (frameLen !== 8) {
        throw new Error("AuthenticationGSS must have length 8");
      }
      return { kind: "AuthenticationGSS" };
    }
