```go
package nip19tlv

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/url"
	"strings"
)

const (
	b32Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
	maxNIP19   = 5000
)

var (
	pmodGen = [5]uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	b32Rev  = func() [128]int8 {
		var t [128]int8
		for i := range t {
			t[i] = -1
		}
		for i := 0; i < len(b32Charset); i++ {
			t[b32Charset[i]] = int8(i)
		}
		return t
	}()
)

type ShareableEntity struct {
	HRP     string // "nprofile" or "nevent"
	Primary [32]byte
	Relays  []string
	Author  *[32]byte
	Kind    *uint32
}

func polymod(hrp string, data []uint8) uint32 {
	chk := uint32(1)
	feed := func(v uint8) {
		top := chk >> 25
		chk = ((chk & 0x1ffffff) << 5) ^ uint32(v)
		for i := range 5 {
			if ((top >> i) & 1) != 0 {
				chk ^= pmodGen[i]
			}
		}
	}
	for i := 0; i < len(hrp); i++ {
		feed(hrp[i] >> 5)
	}
	feed(0)
	for i := 0; i < len(hrp); i++ {
		feed(hrp[i] & 31)
	}
	for _, d := range data {
		feed(d)
	}
	return chk
}

func convertBits(in []byte, fromBits, toBits uint, pad bool) ([]byte, error) {
	var acc uint32
	var bits uint
	maxv := uint32((1 << toBits) - 1)
	out := make([]byte, 0, (len(in)*int(fromBits)+int(toBits)-1)/int(toBits))

	for _, b := range in {
		if (uint32(b) >> fromBits) != 0 {
			return nil, errors.New("nip19: bit group out of range")
		}
		acc = (acc << fromBits) | uint32(b)
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			out = append(out, byte((acc>>bits)&maxv))
		}
	}
	if pad {
		if bits > 0 {
			out = append(out, byte((acc<<(toBits-bits))&maxv))
		}
	} else if bits >= fromBits || ((acc<<(toBits-bits))&maxv) != 0 {
		return nil, errors.New("nip19: non-zero or excess trailing padding bits")
	}
	return out, nil
}

func isValidRelayURL(s string) bool {
	if len(s) == 0 || len(s) > 255 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] <= 0x20 || s[i] > 0x7e {
			return false
		}
	}
	u, err := url.Parse(s)
	return err == nil && (u.Scheme == "ws" || u.Scheme == "wss") && u.Host != ""
}

func isNonZero32(b []byte) bool {
	var acc byte
	for _, x := range b {
		acc |= x
	}
	return acc != 0
}

func EncodeNIP19Entity(ent ShareableEntity) (string, error) {
	if ent.HRP != "nprofile" && ent.HRP != "nevent" {
		return "", fmt.Errorf("nip19: unsupported HRP %q", ent.HRP)
	}
	if !isNonZero32(ent.Primary[:]) {
		return "", errors.New("nip19: all-zero 32-byte primary ID")
	}
	if ent.HRP == "nprofile" && (ent.Author != nil || ent.Kind != nil) {
		return "", errors.New("nip19: author/kind TLVs forbidden in nprofile")
	}

	raw := make([]byte, 0, 34+len(ent.Relays)*32)
	raw = append(raw, 0x00, 32)
	raw = append(raw, ent.Primary[:]...)

	for _, r := range ent.Relays {
		if !isValidRelayURL(r) {
			return "", fmt.Errorf("nip19: invalid relay URL %q", r)
		}
		raw = append(raw, 0x01, byte(len(r)))
		raw = append(raw, r...)
	}
	if ent.Author != nil {
		if !isNonZero32(ent.Author[:]) {
			return "", errors.New("nip19: all-zero author pubkey")
		}
		raw = append(raw, 0x02, 32)
		raw = append(raw, ent.Author[:]...)
	}
	if ent.Kind != nil {
		var kb [4]byte
		binary.BigEndian.PutUint32(kb[:], *ent.Kind)
		raw = append(raw, 0x03, 4)
		raw = append(raw, kb[:]...)
	}

	words, err := convertBits(raw, 8, 5, true)
	if err != nil {
		return "", err
	}
	padded := append(append([]byte{}, words...), 0, 0, 0, 0, 0, 0)
	mod := polymod(ent.HRP, padded) ^ 1

	var sb strings.Builder
	sb.Grow(len(ent.HRP) + 1 + len(words) + 6)
	sb.WriteString(ent.HRP)
	sb.WriteByte('1')
	for _, w := range words {
		sb.WriteByte(b32Charset[w])
	}
	for i := range 6 {
		sb.WriteByte(b32Charset[(mod>>(5*(5-i)))&31])
	}
	if sb.Len() > maxNIP19 {
		return "", errors.New("nip19: encoded entity exceeds 5000 chars")
	}
	return sb.String(), nil
}

func DecodeNIP19Entity(token string) (*ShareableEntity, error) {
	if len(token) < 60 || len(token) > maxNIP19 || token != strings.ToLower(token) {
		return nil, errors.New("nip19: invalid length or non-lowercase NIP-19 token")
	}
	sep := strings.LastIndexByte(token, '1')
	if sep < 1 || sep+7 > len(token) {
		return nil, errors.New("nip19: missing '1' separator")
	}
	hrp := token[:sep]
	if hrp != "nprofile" && hrp != "nevent" {
		return nil, fmt.Errorf("nip19: unsupported HRP %q", hrp)
	}

	words := make([]byte, len(token)-sep-1)
	for i := range words {
		c := token[sep+1+i]
		if c >= 128 || b32Rev[c] < 0 {
			return nil, errors.New("nip19: invalid Bech32 char")
		}
		words[i] = byte(b32Rev[c])
	}
	if polymod(hrp, words) != 1 {
		return nil, errors.New("nip19: Bech32 checksum mismatch")
	}

	tlvBuf, err := convertBits(words[:len(words)-6], 5, 8, false)
	if err != nil {
		return nil, err
	}

	out := &ShareableEntity{HRP: hrp}
	hasPrimary := false
	off := 0
	for off < len(tlvBuf) {
		if len(tlvBuf)-off < 2 {
			return nil, errors.New("nip19: truncated TLV header")
		}
		t := tlvBuf[off]
		l := int(tlvBuf[off+1])
		off += 2
		if len(tlvBuf)-off < l {
			return nil, errors.New("nip19: TLV value overruns entity")
		}
		val := tlvBuf[off : off+l]
		off += l

		switch t {
		case 0x00:
			if hasPrimary || l != 32 || !isNonZero32(val) {
				return nil, errors.New("nip19: invalid or duplicate TLV 0x00 primary ID")
			}
			copy(out.Primary[:], val)
			hasPrimary = true
		case 0x01:
			r := string(val)
			if !isValidRelayURL(r) {
				return nil, fmt.Errorf("nip19: invalid relay URL %q", r)
			}
			out.Relays = append(out.Relays, r)
		case 0x02:
			if hrp == "nprofile" || out.Author != nil || l != 32 || !isNonZero32(val) {
				return nil, errors.New("nip19: invalid TLV 0x02 author")
			}
			var a [32]byte
			copy(a[:], val)
			out.Author = &a
		case 0x03:
			if hrp == "nprofile" || out.Kind != nil || l != 4 {
				return nil, errors.New("nip19: invalid TLV 0x03 kind")
			}
			k := binary.BigEndian.Uint32(val)
			out.Kind = &k
		default:
			return nil, fmt.Errorf("nip19: unknown TLV type 0x%02x in strict mode", t)
		}
	}
	if !hasPrimary {
		return nil, errors.New("nip19: missing mandatory TLV 0x00 primary ID")
	}
	return out, nil
}
