const ED25519_L = (1n << 252n) + 27742317777372353535851937790883648493n;

const B64U_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
const B64U_MAP = new Int8Array(128).fill(-1);
for (let i = 0; i < B64U_CHARS.length; i++) B64U_MAP[B64U_CHARS.charCodeAt(i)] = i;

const utf8Fatal = new TextDecoder("utf-8", { fatal: true });
const asciiEnc = new TextEncoder();

export interface StrictEdDsaHeader {
  alg: "EdDSA";
  kid?: string;
  typ?: string;
}

function encodeB64Url(buf: Uint8Array): string {
  let out = "";
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < buf.byteLength; i++) {
    acc = (acc << 8) | buf[i]!;
    bits += 8;
    while (bits >= 6) {
      bits -= 6;
      out += B64U_CHARS[(acc >>> bits) & 0x3f]!;
    }
  }
  if (bits > 0) out += B64U_CHARS[(acc << (6 - bits)) & 0x3f]!;
  return out;
}

function decodeB64UrlStrict(seg: string): Uint8Array {
  if (seg.length === 0 || seg.length % 4 === 1) {
    throw new Error("Invalid unpadded Base64url length");
  }
  const out = new Uint8Array(Math.floor((seg.length * 6) / 8));
  let acc = 0;
  let bits = 0;
  let w = 0;
  for (let i = 0; i < seg.length; i++) {
    const c = seg.charCodeAt(i);
    const v = c < 128 ? B64U_MAP[c]! : -1;
    if (v < 0) throw new Error(`Illegal Base64url character at ${i}`);
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[w++] = (acc >>> bits) & 0xff;
    }
  }
  if (bits > 0 && (acc & ((1 << bits) - 1)) !== 0) {
    throw new Error("Non-canonical Base64url padding bits");
  }
  return out;
}

function parseStrictFlatHeaderJson(s: string): StrictEdDsaHeader {
  let i = 0;
  const n = s.length;
  const skipWs = () => {
    while (i < n && (s[i] === " " || s[i] === "\t" || s[i] === "\r" || s[i] === "\n")) i++;
  };
  const readString = (): string => {
    if (i >= n || s[i] !== '"') throw new Error("Expected '\"' in JWS header JSON");
    i++;
    let out = "";
    while (i < n) {
      const ch = s[i]!;
      const code = ch.charCodeAt(0);
      if (code < 0x20) throw new Error("Unescaped control char in JWS header string");
      if (ch === '"') {
        i++;
        return out;
      }
      if (ch === "\\") {
        if (++i >= n) throw new Error("Unterminated escape in JWS header");
        const esc = s[i++]!;
        if (esc === '"' || esc === "\\" || esc === "/") out += esc;
        else throw new Error(`Disallowed JSON escape '\\${esc}' in strict JWS header`);
      } else {
        out += ch;
        i++;
      }
    }
    throw new Error("Unterminated string in JWS header JSON");
  };

  skipWs();
  if (i >= n || s[i] !== "{") throw new Error("JWS header must begin with '{'");
  i++;
  skipWs();
  if (i >= n || s[i] === "}") throw new Error("Empty JWS header object");

  const map = new Map<string, string>();
  while (true) {
    skipWs();
    const key = readString();
    if (map.has(key)) {
      throw new Error(`Duplicate JSON key '${key}' in JWS protected header`);
    }
    if (key !== "alg" && key !== "kid" && key !== "typ") {
      throw new Error(`Disallowed JWS protected header parameter '${key}'`);
    }
    skipWs();
    if (i >= n || s[i] !== ":") throw new Error("Expected ':' after JWS header key");
    i++;
    skipWs();
    const val = readString();
    map.set(key, val);
    skipWs();
    if (i < n && s[i] === ",") {
      i++;
      continue;
    }
    if (i < n && s[i] === "}") {
      i++;
      break;
    }
    throw new Error("Malformed JWS protected header object delimiter");
  }
  skipWs();
  if (i !== n) throw new Error("Trailing characters after JWS header JSON");

  if (map.get("alg") !== "EdDSA") {
    throw new Error("JWS protected header must pin alg='EdDSA'");
  }
  const kid = map.get("kid");
  const typ = map.get("typ");
  return {
    alg: "EdDSA",
    ...(kid !== undefined ? { kid } : {}),
    ...(typ !== undefined ? { typ } : {}),
  };
}

export async function verifyDetachedJwsEd25519(
  compactDetachedJws: string,
  detachedPayload: Uint8Array,
  ed25519PublicKey: CryptoKey,
): Promise<StrictEdDsaHeader> {
  const parts = compactDetachedJws.split(".");
  if (parts.length !== 3 || parts[1] !== "") {
    throw new Error("Detached JWS must follow '<protected>..<signature>'");
  }

  const hdrBytes = decodeB64UrlStrict(parts[0]!);
  const sigBytes = decodeB64UrlStrict(parts[2]!);
  if (sigBytes.byteLength !== 64) {
    throw new Error(`Ed25519 signature must be 64 bytes, got ${sigBytes.byteLength}`);
  }

  // RFC 8032 §5.1.7: S (sig[32..64] little-endian) MUST satisfy 0 <= S < L
  const sigView = new DataView(sigBytes.buffer, sigBytes.byteOffset, 64);
  const sScalar =
    sigView.getBigUint64(32, true) |
    (sigView.getBigUint64(40, true) << 64n) |
    (sigView.getBigUint64(48, true) << 128n) |
    (sigView.getBigUint64(56, true) << 192n);
  if (sScalar >= ED25519_L) {
    throw new Error("RFC 8032 §5.1.7 violation: malleable Ed25519 signature S >= L rejected");
  }

  const header = parseStrictFlatHeaderJson(utf8Fatal.decode(hdrBytes));
  const signingInput = asciiEnc.encode(`${parts[0]!}.${encodeB64Url(detachedPayload)}`);

  const ok = await crypto.subtle.verify(
    { name: "Ed25519" },
    ed25519PublicKey,
    sigBytes,
    signingInput,
  );
  if (!ok) {
    throw new Error("Detached Ed25519 JWS signature verification failed");
  }
  return header;
}
