```ts
const RFC5103_REVERSE_PEN = 29_305;

export interface BiflowFieldSpec {
  ieId: number;
  length: number;
  direction: "forward" | "reverse" | "vendor";
  enterpriseNumber?: number;
}

export interface DecodedBiflowRecord {
  templateId: number;
  srcIpv4?: string;
  dstIpv4?: string;
  srcPort?: number;
  dstPort?: number;
  biflowDirection?: 0 | 1 | 2 | 3;
  forwardOctets: bigint;
  reverseOctets: bigint;
  forwardPackets: bigint;
  reversePackets: bigint;
}

function readUnsignedBigIntBE(buf: Uint8Array, off: number, len: number): bigint {
  let v = 0n;
  for (let i = 0; i < len; i++) {
    v = (v << 8n) | BigInt(buf[off + i]!);
  }
  return v;
}

export class IpfixBiflowDecoder {
  private readonly templates = new Map<string, { fields: BiflowFieldSpec[]; recordSize: number }>();

  private parseTemplateSet(domainId: number, view: DataView, start: number, end: number): void {
    let off = start;
    while (off < end) {
      if (end - off < 4) {
        for (let p = off; p < end; p++) {
          if (view.getUint8(p) !== 0) throw new Error("Non-zero padding in Biflow Template Set");
        }
        break;
      }
      const tmplId = view.getUint16(off, false);
      const fCount = view.getUint16(off + 2, false);
      off += 4;

      if (fCount === 0) {
        if (tmplId >= 256) this.templates.delete(`${domainId}:${tmplId}`);
        continue;
      }
      if (tmplId < 256) throw new Error(`Invalid IPFIX Template ID ${tmplId}`);

      const fields: BiflowFieldSpec[] = [];
      let recordSize = 0;
      for (let i = 0; i < fCount; i++) {
        if (end - off < 4) throw new Error("Truncated Biflow FieldSpecifier");
        const rawIe = view.getUint16(off, false);
        const fLen = view.getUint16(off + 2, false);
        off += 4;
        if (fLen === 0 || fLen === 0xffff) {
          throw new Error(`Invalid or unsupported fieldLength ${fLen}`);
        }

        const ieId = rawIe & 0x7fff;
        let direction: "forward" | "reverse" | "vendor" = "forward";
        let pen: number | undefined;

        if ((rawIe & 0x8000) !== 0) {
          if (end - off < 4) throw new Error("Truncated Enterprise Number");
          pen = view.getUint32(off, false);
          off += 4;
          direction = pen === RFC5103_REVERSE_PEN ? "reverse" : "vendor";
        }

        if (direction !== "vendor") {
          if ((ieId === 1 || ieId === 2) && fLen > 8) {
            throw new Error(`Counter IE ${ieId} length ${fLen} > 8`);
          }
          if ((ieId === 8 || ieId === 12) && fLen !== 4) {
            throw new Error(`IPv4 IE ${ieId} must be 4 bytes`);
          }
          if ((ieId === 7 || ieId === 11) && fLen !== 2) {
            throw new Error(`Port IE ${ieId} must be 2 bytes`);
          }
          if (ieId === 239 && (direction !== "forward" || fLen !== 1)) {
            throw new Error("biflowDirection (IE 239) must be 1-byte forward IANA IE");
          }
        }

        fields.push({
          ieId,
          length: fLen,
          direction,
          ...(pen !== undefined ? { enterpriseNumber: pen } : {}),
        });
        recordSize += fLen;
      }
      this.templates.set(`${domainId}:${tmplId}`, { fields, recordSize });
    }
  }

  public decodePacket(pkt: Uint8Array): DecodedBiflowRecord[] {
    if (pkt.byteLength < 16) throw new Error("Truncated 16-byte IPFIX header");
    const view = new DataView(pkt.buffer, pkt.byteOffset, pkt.byteLength);
    if (view.getUint16(0, false) !== 10 || view.getUint16(2, false) !== pkt.byteLength) {
      throw new Error("Invalid IPFIX v10 message header");
    }
    const domainId = view.getUint32(12, false);

    const out: DecodedBiflowRecord[] = [];
    let off = 16;
    while (off < pkt.byteLength) {
      if (pkt.byteLength - off < 4) throw new Error("Truncated IPFIX Set header");
      const setId = view.getUint16(off, false);
      const setLen = view.getUint16(off + 2, false);
      if (setLen < 4 || off + setLen > pkt.byteLength) {
        throw new Error(`Invalid IPFIX Set length ${setLen}`);
      }
      const setEnd = off + setLen;

      if (setId === 2) {
        this.parseTemplateSet(domainId, view, off + 4, setEnd);
      } else if (setId >= 256) {
        const tmpl = this.templates.get(`${domainId}:${setId}`);
        if (!tmpl) throw new Error(`Unknown Biflow template ${setId}`);

        let cur = off + 4;
        while (setEnd - cur >= tmpl.recordSize) {
          if (out.length > 0 && setEnd - cur < 4) {
            let allZero = true;
            for (let z = cur; z < setEnd; z++) if (pkt[z] !== 0) allZero = false;
            if (allZero) {
              cur = setEnd;
              break;
            }
          }

          const rec: DecodedBiflowRecord = {
            templateId: setId,
            forwardOctets: 0n,
            reverseOctets: 0n,
            forwardPackets: 0n,
            reversePackets: 0n,
          };

          for (const f of tmpl.fields) {
            if (f.direction === "forward") {
              if (f.ieId === 1) rec.forwardOctets = readUnsignedBigIntBE(pkt, cur, f.length);
              else if (f.ieId === 2) rec.forwardPackets = readUnsignedBigIntBE(pkt, cur, f.length);
              else if (f.ieId === 8) rec.srcIpv4 = `${pkt[cur]!}.${pkt[cur + 1]!}.${pkt[cur + 2]!}.${pkt[cur + 3]!}`;
              else if (f.ieId === 12) rec.dstIpv4 = `${pkt[cur]!}.${pkt[cur + 1]!}.${pkt[cur + 2]!}.${pkt[cur + 3]!}`;
              else if (f.ieId === 7) rec.srcPort = view.getUint16(cur, false);
              else if (f.ieId === 11) rec.dstPort = view.getUint16(cur, false);
              else if (f.ieId === 239) {
                const dir = view.getUint8(cur);
                if (dir > 3) throw new Error(`Invalid biflowDirection ${dir} (> 3)`);
                rec.biflowDirection = dir as 0 | 1 | 2 | 3;
              }
            } else if (f.direction === "reverse") {
              if (f.ieId === 1) rec.reverseOctets = readUnsignedBigIntBE(pkt, cur, f.length);
              else if (f.ieId === 2) rec.reversePackets = readUnsignedBigIntBE(pkt, cur, f.length);
            }
            cur += f.length;
          }
          out.push(rec);
        }

        for (let p = cur; p < setEnd; p++) {
          if (view.getUint8(p) !== 0) throw new Error("Non-zero padding in Biflow Data Set");
        }
      } else if (setId !== 3) {
        throw new Error(`Illegal IPFIX Set ID ${setId}`);
      }
      off = setEnd;
    }

    return out;
  }
}
