var sevWords = map[string]struct{}{
	"Unknown": {}, "Low": {}, "Medium": {}, "High": {}, "Very-High": {},
}

var cefTimeLayouts = []string{
	"Jan 02 2006 15:04:05.000 MST",
	"Jan 02 2006 15:04:05 MST",
	"Jan 02 2006 15:04:05.000",
	"Jan 02 2006 15:04:05",
}

func validSeverity(s string) bool {
	if _, ok := sevWords[s]; ok {
		return true
	}
	v, err := strconv.Atoi(s)
	return err == nil && v >= 0 && v <= 10 && strconv.Itoa(v) == s
}

func isKeyByte(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') ||
		(b >= '0' && b <= '9') || b == '_' || b == '.' || b == '-'
}

func oddBackslashesBefore(s string, pos int) bool {
	cnt := 0
	for i := pos - 1; i >= 0 && s[i] == '\\'; i-- {
		cnt++
	}
	return cnt%2 == 1
}

func unescapeExt(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case '\\', '=':
				b.WriteByte(s[i+1])
				i++
				continue
			case 'n':
				b.WriteByte('\n')
				i++
				continue
			case 'r':
				b.WriteByte('\r')
				i++
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func parseCEFPolymorphicTime(raw string) (time.Time, error) {
	if len(raw) >= 10 && len(raw) <= 16 && raw[0] >= '1' && raw[0] <= '9' {
		allDigits := true
		for i := 0; i < len(raw); i++ {
			if raw[i] < '0' || raw[i] > '9' {
				allDigits = false
				break
			}
		}
		if allDigits {
			ms, err := strconv.ParseInt(raw, 10, 64)
			if err != nil {
				return time.Time{}, err
			}
			return time.UnixMilli(ms).UTC(), nil
		}
	}
	for _, layout := range cefTimeLayouts {
		if t, err := time.ParseInLocation(layout, raw, time.UTC); err == nil {
			return t.UTC(), nil
		}
	}
	return time.Time{}, fmt.Errorf("cefv1: unrecognized timestamp %q", raw)
}

func parsePort(raw string) (uint16, error) {
	if len(raw) == 0 || (len(raw) > 1 && raw[0] == '0') {
		return 0, fmt.Errorf("cefv1: non-canonical port %q", raw)
	}
	p, err := strconv.ParseUint(raw, 10, 16)
	if err != nil {
		return 0, fmt.Errorf("cefv1: invalid uint16 port %q", raw)
	}
	return uint16(p), nil
}

func ParseCEF1NetworkEvent(line string) (*NetworkCEFEvent, error) {
	if !utf8.ValidString(line) || strings.ContainsAny(line, "\r\n\x00") {
		return nil, errors.New("cefv1: invalid UTF-8 or CR/LF/NUL")
	}
	pos := strings.Index(line, "CEF:")
	if pos < 0 || (pos > 0 && line[pos-1] != ' ') {
		return nil, errors.New("cefv1: missing 'CEF:' marker")
	}

	rest := line[pos+4:]
	hdrs := make([]string, 0, 7)
	var cur strings.Builder
	extOff := -1
	for i := 0; i < len(rest); i++ {
		if rest[i] == '\\' && i+1 < len(rest) && (rest[i+1] == '|' || rest[i+1] == '\\') {
			cur.WriteByte(rest[i+1])
			i++
			continue
		}
		if rest[i] == '|' {
			hdrs = append(hdrs, cur.String())
			cur.Reset()
			if len(hdrs) == 7 {
				extOff = i + 1
				break
			}
			continue
		}
		cur.WriteByte(rest[i])
	}
	if len(hdrs) != 7 || extOff < 0 {
		return nil, errors.New("cefv1: expected 7 pipe-terminated header fields")
	}
	ver, err := strconv.Atoi(hdrs[0])
	if err != nil || (ver != 0 && ver != 1) || !validSeverity(hdrs[6]) {
		return nil, errors.New("cefv1: invalid version or severity")
	}

	out := &NetworkCEFEvent{
		Version:    ver,
		Vendor:     hdrs[1],
		Product:    hdrs[2],
		EventClass: hdrs[4],
		Name:       hdrs[5],
		Severity:   hdrs[6],
		CustomIPv6: make(map[string]netip.Addr),
		RawOther:   make(map[string]string),
	}

	extStr := strings.TrimLeft(rest[extOff:], " ")
	if extStr == "" {
		return out, nil
	}

	type anchor struct{ ks, eq int }
	var anchors []anchor
	for i := 0; i < len(extStr); {
		if i == 0 || (extStr[i-1] == ' ' && !oddBackslashesBefore(extStr, i-1)) {
			ks := i
			for i < len(extStr) && isKeyByte(extStr[i]) {
				i++
			}
			if i > ks && i < len(extStr) && extStr[i] == '=' {
				anchors = append(anchors, anchor{ks: ks, eq: i})
				i++
				continue
			}
			if i == ks {
				i++
			}
		} else {
			i++
		}
	}
	if len(anchors) == 0 || anchors[0].ks != 0 {
		return nil, errors.New("cefv1: malformed extension tail")
	}

	seen := make(map[string]struct{}, len(anchors))
	for idx, a := range anchors {
		key := extStr[a.ks:a.eq]
		if _, dup := seen[key]; dup {
			return nil, fmt.Errorf("cefv1: duplicate extension key %q", key)
		}
		seen[key] = struct{}{}

		vs := a.eq + 1
		ve := len(extStr)
		if idx+1 < len(anchors) {
			ve = anchors[idx+1].ks - 1
			for ve > vs && extStr[ve-1] == ' ' && !oddBackslashesBefore(extStr, ve-1) {
				ve--
			}
		}
		val := unescapeExt(extStr[vs:ve])

		switch key {
		case "src", "dst":
			ip, err := netip.ParseAddr(val)
			if err != nil {
				return nil, fmt.Errorf("cefv1: invalid IP in %s: %q", key, val)
			}
			if ver == 0 && ip.Is6() {
				return nil, fmt.Errorf("cefv1: IPv6 %q in %s requires CEF:1", val, key)
			}
			if key == "src" {
				out.SrcAddr = &ip
			} else {
				out.DstAddr = &ip
			}
		case "c6a1", "c6a2", "c6a3", "c6a4":
			ip, err := netip.ParseAddr(val)
			if err != nil || !ip.Is6() || ip.Is4In6() {
				return nil, fmt.Errorf("cefv1: %s must be native IPv6 address, got %q", key, val)
			}
			out.CustomIPv6[key] = ip
		case "spt", "dpt":
			p, err := parsePort(val)
			if err != nil {
				return nil, err
			}
			if key == "spt" {
				out.SrcPort = &p
			} else {
				out.DstPort = &p
			}
		case "rt", "start", "end":
			t, err := parseCEFPolymorphicTime(val)
			if err != nil {
				return nil, err
			}
			switch key {
			case "rt":
				out.ReceiptTime = &t
			case "start":
				out.StartTime = &t
			case "end":
				out.EndTime = &t
			}
		default:
			out.RawOther[key] = val
		}
	}
	return out, nil
}
