#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GrpcFrameError {
    NeedMoreBytes { needed: usize },
    InvalidCompressedFlag(u8),
    CompressionNotSupported,
    MessageTooLarge { length: usize, max: usize },
    LengthOverflow,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GrpcFrameView<'a> {
    pub compressed: bool,
    pub payload: &'a [u8],
    pub frame_bytes_consumed: usize,
}

pub fn decode_grpc_frame<'a>(
    buf: &'a [u8],
    max_message_bytes: usize,
    allow_compressed: bool,
) -> Result<GrpcFrameView<'a>, GrpcFrameError> {
    let hdr = buf
        .get(..5)
        .ok_or_else(|| GrpcFrameError::NeedMoreBytes { needed: 5 - buf.len() })?;

    let compressed = match hdr[0] {
        0x00 => false,
        0x01 => {
            if !allow_compressed {
                return Err(GrpcFrameError::CompressionNotSupported);
            }
            true
        }
        bad => return Err(GrpcFrameError::InvalidCompressedFlag(bad)),
    };

    let len_bytes: [u8; 4] = [hdr[1], hdr[2], hdr[3], hdr[4]];
    let msg_len = u32::from_be_bytes(len_bytes) as usize;
    if msg_len > max_message_bytes {
        return Err(GrpcFrameError::MessageTooLarge {
            length: msg_len,
            max: max_message_bytes,
        });
    }

    let total = 5_usize
        .checked_add(msg_len)
        .ok_or(GrpcFrameError::LengthOverflow)?;
    let payload = buf.get(5..total).ok_or_else(|| GrpcFrameError::NeedMoreBytes {
        needed: total - buf.len(),
    })?;

    Ok(GrpcFrameView {
        compressed,
        payload,
        frame_bytes_consumed: total,
    })
}

pub fn encode_grpc_frame(
    compressed: bool,
    payload: &[u8],
    max_message_bytes: usize,
) -> Result<Vec<u8>, GrpcFrameError> {
    if payload.len() > max_message_bytes {
        return Err(GrpcFrameError::MessageTooLarge {
            length: payload.len(),
            max: max_message_bytes,
        });
    }
    let msg_len_u32 = u32::try_from(payload.len()).map_err(|_| GrpcFrameError::LengthOverflow)?;
    let total = 5_usize
        .checked_add(payload.len())
        .ok_or(GrpcFrameError::LengthOverflow)?;

    let mut out = Vec::with_capacity(total);
    out.push(u8::from(compressed));
    out.extend_from_slice(&msg_len_u32.to_be_bytes());
    out.extend_from_slice(payload);
    Ok(out)
}
