#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    GZ_OK = 0,
    GZ_ERR_NULL,
    GZ_ERR_TRUNCATED,
    GZ_ERR_BAD_MAGIC_OR_CM,
    GZ_ERR_RESERVED_FLAGS,
    GZ_ERR_UNTERMINATED_STR,
    GZ_ERR_HEADER_CRC,
} gz_status_t;

typedef struct {
    uint8_t flg;
    uint32_t mtime;
    uint8_t xfl;
    uint8_t os;
    const uint8_t *extra;
    uint16_t extra_len;
    const char *fname;     // NUL-terminated inside buf, or nullptr
    const char *fcomment;  // NUL-terminated inside buf, or nullptr
    const uint8_t *deflate_data;
    size_t deflate_len;
    uint32_t trailer_crc;
    uint32_t trailer_isize;
} gz_envelope_t;

constexpr uint8_t GZ_FTEXT    = 0x01;
constexpr uint8_t GZ_FHCRC    = 0x02;
constexpr uint8_t GZ_FEXTRA   = 0x04;
constexpr uint8_t GZ_FNAME    = 0x08;
constexpr uint8_t GZ_FCOMMENT = 0x10;
constexpr uint8_t GZ_RESERVED = 0xE0;

static uint16_t rd_u16_le(const uint8_t *p) {
    return (uint16_t)p[0] | (uint16_t)((uint16_t)p[1] << 8);
}

static uint32_t rd_u32_le(const uint8_t *p) {
    return (uint32_t)p[0]
         | ((uint32_t)p[1] << 8)
         | ((uint32_t)p[2] << 16)
         | ((uint32_t)p[3] << 24);
}

static uint32_t ieee_crc_calc(const uint8_t *data, size_t len) {
    uint32_t crc = UINT32_C(0xFFFFFFFF);
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int b = 0; b < 8; ++b) {
            uint32_t mask = (crc & 1U) ? UINT32_C(0xEDB88320) : 0U;
            crc = (crc >> 1) ^ mask;
        }
    }
    return ~crc;
}

[[nodiscard]] gz_status_t parse_gzip_envelope(
    const uint8_t *buf,
    size_t len,
    gz_envelope_t *out
) {
    if (buf == nullptr || out == nullptr) return GZ_ERR_NULL;
    if (len < 18) return GZ_ERR_TRUNCATED; // 10B header + 8B trailer minimum
    if (buf[0] != 0x1F || buf[1] != 0x8B || buf[2] != 0x08) {
        return GZ_ERR_BAD_MAGIC_OR_CM;
    }
    uint8_t flg = buf[3];
    if ((flg & GZ_RESERVED) != 0) return GZ_ERR_RESERVED_FLAGS;

    *out = (gz_envelope_t){0};
    out->flg = flg;
    out->mtime = rd_u32_le(buf + 4);
    out->xfl = buf[8];
    out->os = buf[9];

    size_t body_limit = len - 8;
    size_t pos = 10;

    if ((flg & GZ_FEXTRA) != 0) {
        if (body_limit - pos < 2) return GZ_ERR_TRUNCATED;
        uint16_t xlen = rd_u16_le(buf + pos);
        pos += 2;
        if (body_limit - pos < xlen) return GZ_ERR_TRUNCATED;
        out->extra = buf + pos;
        out->extra_len = xlen;
        pos += xlen;
    }

    if ((flg & GZ_FNAME) != 0) {
        const uint8_t *nul = memchr(buf + pos, 0, body_limit - pos);
        if (nul == nullptr) return GZ_ERR_UNTERMINATED_STR;
        out->fname = (const char *)(buf + pos);
        pos = (size_t)(nul - buf) + 1;
    }

    if ((flg & GZ_FCOMMENT) != 0) {
        const uint8_t *nul = memchr(buf + pos, 0, body_limit - pos);
        if (nul == nullptr) return GZ_ERR_UNTERMINATED_STR;
        out->fcomment = (const char *)(buf + pos);
        pos = (size_t)(nul - buf) + 1;
    }

    if ((flg & GZ_FHCRC) != 0) {
        if (body_limit - pos < 2) return GZ_ERR_TRUNCATED;
        uint16_t expected_crc = rd_u16_le(buf + pos);
        uint16_t actual_crc = (uint16_t)(ieee_crc_calc(buf, pos) & UINT32_C(0xFFFF));
        if (expected_crc != actual_crc) return GZ_ERR_HEADER_CRC;
        pos += 2;
    }

    out->deflate_data = buf + pos;
    out->deflate_len = body_limit - pos;
    out->trailer_crc = rd_u32_le(buf + body_limit);
    out->trailer_isize = rd_u32_le(buf + body_limit + 4);
    return GZ_OK;
}
