```rust
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HpackCodecError {
    InvalidPrefixWidth(u8),
    Truncated,
    IntegerOverflow,
    NonCanonicalTrailingZero,
    StringTooLong { len: usize, max: usize },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HpackStringRef<'a> {
    pub huffman: bool,
    pub raw: &'a [u8],
    pub consumed: usize,
}

pub fn encode_hpack_int(
    mut value: u64,
    prefix_bits: u8,
    high_tag_bits: u8,
    out: &mut Vec<u8>,
) -> Result<(), HpackCodecError> {
    if !(1..=8).contains(&prefix_bits) {
        return Err(HpackCodecError::InvalidPrefixWidth(prefix_bits));
    }
    let mask: u8 = if prefix_bits == 8 { 0xFF } else { (1_u8 << prefix_bits) - 1 };
    let tag_masked = high_tag_bits & !mask;
    let max_prefix = u64::from(mask);

    if value < max_prefix {
        out.push(tag_masked | (value as u8));
        return Ok(());
    }

    out.push(tag_masked | mask);
    value -= max_prefix;
    while value >= 128 {
        out.push(((value & 0x7F) as u8) | 0x80);
        value >>= 7;
    }
    out.push(value as u8);
    Ok(())
}

pub fn decode_hpack_int(
    buf: &[u8],
    prefix_bits: u8,
) -> Result<(u64, usize), HpackCodecError> {
    if !(1..=8).contains(&prefix_bits) {
        return Err(HpackCodecError::InvalidPrefixWidth(prefix_bits));
    }
    let first = *buf.first().ok_or(HpackCodecError::Truncated)?;
    let mask: u8 = if prefix_bits == 8 { 0xFF } else { (1_u8 << prefix_bits) - 1 };
    let mut val = u64::from(first & mask);
    if (first & mask) < mask {
        return Ok((val, 1));
    }

    let mut shift: u32 = 0;
    let mut pos: usize = 1;
    loop {
        let b = *buf.get(pos).ok_or(HpackCodecError::Truncated)?;
        pos += 1;
        if (b & 0x80) == 0 && b == 0 && shift >= 7 {
            return Err(HpackCodecError::NonCanonicalTrailingZero);
        }
        let low = u64::from(b & 0x7F);
        let addend = if shift == 0 {
            low
        } else {
            let factor = 1_u64.checked_shl(shift).ok_or(HpackCodecError::IntegerOverflow)?;
            low.checked_mul(factor).ok_or(HpackCodecError::IntegerOverflow)?
        };
        val = val.checked_add(addend).ok_or(HpackCodecError::IntegerOverflow)?;
        if (b & 0x80) == 0 {
            return Ok((val, pos));
        }
        shift = shift.checked_add(7).ok_or(HpackCodecError::IntegerOverflow)?;
        if shift > 63 {
            return Err(HpackCodecError::IntegerOverflow);
        }
    }
}

pub fn decode_hpack_string<'a>(
    buf: &'a [u8],
    max_str_len: usize,
) -> Result<HpackStringRef<'a>, HpackCodecError> {
    let first = *buf.first().ok_or(HpackCodecError::Truncated)?;
    let huffman = (first & 0x80) != 0;
    let (raw_len, hdr_used) = decode_hpack_int(buf, 7)?;
    let str_len = usize::try_from(raw_len).map_err(|_| HpackCodecError::IntegerOverflow)?;
    if str_len > max_str_len {
        return Err(HpackCodecError::StringTooLong { len: str_len, max: max_str_len });
    }
    let end = hdr_used.checked_add(str_len).ok_or(HpackCodecError::IntegerOverflow)?;
    let raw = buf.get(hdr_used..end).ok_or(HpackCodecError::Truncated)?;
    Ok(HpackStringRef { huffman, raw, consumed: end })
}
