typedef enum : uint8_t {
    NDN_OK = 0,
    NDN_ERR_NULL,
    NDN_ERR_TRUNCATED,
    NDN_ERR_NON_CANONICAL,
    NDN_ERR_INVALID_TYPE,
    NDN_ERR_LENGTH_OVERFLOW,
    NDN_ERR_DST_SMALL,
} ndn_status_t;

typedef struct {
    uint32_t tlv_type;
    uint64_t tlv_len;
    const uint8_t *value;
    size_t total_consumed;
} ndn_tlv_view_t;

[[nodiscard]] ndn_status_t ndn_decode_varnum(
    const uint8_t *buf,
    size_t len,
    uint64_t *out_val,
    size_t *out_used
