               | ((uint64_t)buf[3] << 40) | ((uint64_t)buf[4] << 32)
               | ((uint64_t)buf[5] << 24) | ((uint64_t)buf[6] << 16)
               | ((uint64_t)buf[7] << 8)  | (uint64_t)buf[8];
    if (v <= UINT64_C(0xFFFFFFFF)) return NDN_ERR_NON_CANONICAL;
    *out_val = v;
    *out_used = 9;
    return NDN_OK;
