        dst[1] = (uint8_t)(val >> 8);
        dst[2] = (uint8_t)val;
        *out_written = 3;
        return NDN_OK;
    }
    if (val <= UINT64_C(0xFFFFFFFF)) {
        if (dst_cap < 5) return NDN_ERR_DST_SMALL;
        dst[0] = 0xFE;
        dst[1] = (uint8_t)(val >> 24);
        dst[2] = (uint8_t)(val >> 16);
        dst[3] = (uint8_t)(val >> 8);
        dst[4] = (uint8_t)val;
        *out_written = 5;
        return NDN_OK;
    }
    if (dst_cap < 9) return NDN_ERR_DST_SMALL;
    dst[0] = 0xFF;
    for (int i = 0; i < 8; ++i) {
        dst[1 + i] = (uint8_t)(val >> (56 - 8 * i));
    }
    *out_written = 9;
    return NDN_OK;
}

[[nodiscard]] ndn_status_t ndn_parse_tlv(
    const uint8_t *buf,
    size_t len,
    ndn_tlv_view_t *out
) {
    if (buf == nullptr || out == nullptr) return NDN_ERR_NULL;
    uint64_t raw_type = 0;
    size_t type_bytes = 0;
    ndn_status_t st = ndn_decode_varnum(buf, len, &raw_type, &type_bytes);
    if (st != NDN_OK) return st;
    if (raw_type == 0 || raw_type > UINT64_C(0xFFFFFFFF)) return NDN_ERR_INVALID_TYPE;

    uint64_t raw_len = 0;
    size_t len_bytes = 0;
    st = ndn_decode_varnum(buf + type_bytes, len - type_bytes, &raw_len, &len_bytes);
    if (st != NDN_OK) return st;

    size_t hdr_bytes = type_bytes + len_bytes;
    size_t val_size = 0;
    if (ckd_add(&val_size, (size_t)0, raw_len)) return NDN_ERR_LENGTH_OVERFLOW;
    size_t total = 0;
    if (ckd_add(&total, hdr_bytes, val_size)) return NDN_ERR_LENGTH_OVERFLOW;
    if (total > len) return NDN_ERR_TRUNCATED;

    out->tlv_type = (uint32_t)raw_type;
    out->tlv_len = raw_len;
    out->value = buf + hdr_bytes;
    out->total_consumed = total;
    return NDN_OK;
}
