#[repr(u8)]
pub enum NshNextProto {
    Ipv4 = 0x01,
    Ipv6 = 0x02,
    Ethernet = 0x03,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum VxlanNshError {
    Truncated,
    InvalidVxlanGpeFlags(u8),
    NonZeroVxlanReserved,
    UnsupportedGpeNextProto(u8),
    InvalidNshVersion(u8),
    NonZeroNshUnassigned,
    ExpiredTtlOrServiceIndex,
    InvalidMdType1Length(u8),
    UnsupportedMdType(u8),
    UnsupportedNshNextProto(u8),
    ValueOutOf24BitRange(u32),
    InvalidTtlRange(u8),
