#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VxlanGpeNshMd1<'a> {
    pub vni: u32,
    pub oam: bool,
    pub ttl: u8,
    pub next_proto: NshNextProto,
    pub spi: u32,
    pub si: u8,
    pub context: [u32; 4],
    pub inner_payload: &'a [u8],
}

pub fn parse_vxlan_gpe_nsh<'a>(pkt: &'a [u8]) -> Result<VxlanGpeNshMd1<'a>, VxlanNshError> {
    let hdr = pkt.get(..32).ok_or(VxlanNshError::Truncated)?;

    // VXLAN-GPE: I(0x08) and P(0x04) must be 1; only O(0x01) optional; all other bits 0
    let gpe_flags = hdr[0];
    if (gpe_flags & 0x0C) != 0x0C || (gpe_flags & !0x0D) != 0 {
        return Err(VxlanNshError::InvalidVxlanGpeFlags(gpe_flags));
    }
    if hdr[1] != 0 || hdr[2] != 0 || hdr[7] != 0 {
        return Err(VxlanNshError::NonZeroVxlanReserved);
    }
    if hdr[3] != 0x04 {
        return Err(VxlanNshError::UnsupportedGpeNextProto(hdr[3]));
    }
    let vni = u32::from_be_bytes([0, hdr[4], hdr[5], hdr[6]]);

    // NSH Base Header (hdr[8..12])
    let word0 = u16::from_be_bytes([hdr[8], hdr[9]]);
    let ver = ((word0 >> 14) & 0x03) as u8;
    if ver != 0 {
        return Err(VxlanNshError::InvalidNshVersion(ver));
    }
    let oam = ((word0 >> 13) & 0x01) != 0;
    let u_bit = (word0 >> 12) & 0x01;
    if u_bit != 0 || (hdr[10] & 0xF0) != 0 {
        return Err(VxlanNshError::NonZeroNshUnassigned);
    }
    let ttl = ((word0 >> 6) & 0x3F) as u8;
    let nsh_len_words = (word0 & 0x3F) as u8;
    let md_type = hdr[10] & 0x0F;
    if md_type != 0x01 {
        return Err(VxlanNshError::UnsupportedMdType(md_type));
    }
    if nsh_len_words != 0x06 {
        return Err(VxlanNshError::InvalidMdType1Length(nsh_len_words));
    }
    let next_proto = match hdr[11] {
        0x01 => NshNextProto::Ipv4,
        0x02 => NshNextProto::Ipv6,
        0x03 => NshNextProto::Ethernet,
        other => return Err(VxlanNshError::UnsupportedNshNextProto(other)),
    };
    let spi = u32::from_be_bytes([0, hdr[12], hdr[13], hdr[14]]);
    let si = hdr[15];
    if ttl == 0 || si == 0 {
        return Err(VxlanNshError::ExpiredTtlOrServiceIndex);
    }

    let mut context = [0_u32; 4];
    for (i, slot) in context.iter_mut().enumerate() {
        let off = 16 + i * 4;
        *slot = u32::from_be_bytes([hdr[off], hdr[off + 1], hdr[off + 2], hdr[off + 3]]);
    }

    Ok(VxlanGpeNshMd1 {
        vni,
        oam,
        ttl,
        next_proto,
        spi,
        si,
        context,
        inner_payload: &pkt[32..],
    })
}

pub fn serialize_vxlan_gpe_nsh(frame: &VxlanGpeNshMd1<'_>) -> Result<Vec<u8>, VxlanNshError> {
    if frame.vni > 0x00FF_FFFF {
        return Err(VxlanNshError::ValueOutOf24BitRange(frame.vni));
    }
    if frame.spi > 0x00FF_FFFF {
        return Err(VxlanNshError::ValueOutOf24BitRange(frame.spi));
    }
    if frame.ttl == 0 || frame.ttl > 0x3F {
        return Err(VxlanNshError::InvalidTtlRange(frame.ttl));
    }
    if frame.si == 0 {
        return Err(VxlanNshError::ExpiredTtlOrServiceIndex);
    }

    let mut out = Vec::with_capacity(32 + frame.inner_payload.len());
    let gpe_flags = 0x0C | u8::from(frame.oam);
    let vni_be = frame.vni.to_be_bytes();
    out.extend_from_slice(&[gpe_flags, 0, 0, 0x04, vni_be[1], vni_be[2], vni_be[3], 0]);

    let word0: u16 = ((u16::from(frame.oam)) << 13) | (u16::from(frame.ttl) << 6) | 0x0006;
    out.extend_from_slice(&word0.to_be_bytes());
    out.push(0x01);
    out.push(frame.next_proto as u8);

    let spi_be = frame.spi.to_be_bytes();
    out.extend_from_slice(&[spi_be[1], spi_be[2], spi_be[3], frame.si]);
    for &ctx_word in &frame.context {
        out.extend_from_slice(&ctx_word.to_be_bytes());
    }
    out.extend_from_slice(frame.inner_payload);
    Ok(out)
}
