#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    EDNS_OK = 0,
    EDNS_ERR_NULL,
    EDNS_ERR_TRUNCATED,
    EDNS_ERR_NOT_ROOT_OPT,
    EDNS_ERR_UDP_SIZE_TOO_SMALL,
    EDNS_ERR_BAD_VERSION_OR_Z,
    EDNS_ERR_LENGTH_MISMATCH,
    EDNS_ERR_BAD_ECS_FAMILY_OR_PREFIX,
    EDNS_ERR_NONZERO_ECS_TAIL_BITS,
} edns_status_t;

typedef struct {
    bool present;
    uint16_t family;       // 1 = IPv4, 2 = IPv6
    uint8_t src_prefix;
    uint8_t scope_prefix;
    uint8_t addr_padded[16];
} edns_ecs_t;

typedef struct {
    uint16_t udp_payload_size;
    uint8_t ext_rcode;
    bool dnssec_ok;
    edns_ecs_t ecs;
} edns_opt_parsed_t;

static uint16_t rd_be16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

[[nodiscard]] edns_status_t parse_edns_opt_rr(
    const uint8_t *buf,
    size_t len,
    edns_opt_parsed_t *out
) {
    if (buf == nullptr || out == nullptr) return EDNS_ERR_NULL;
    if (len < 11) return EDNS_ERR_TRUNCATED;
    if (buf[0] != 0x00 || rd_be16(buf + 1) != 41) return EDNS_ERR_NOT_ROOT_OPT;

    uint16_t udp_sz = rd_be16(buf + 3);
    if (udp_sz < 512) return EDNS_ERR_UDP_SIZE_TOO_SMALL;

    uint8_t ext_rcode = buf[5];
    uint8_t version = buf[6];
    uint16_t flags = rd_be16(buf + 7);
    if (version != 0 || (flags & UINT16_C(0x7FFF)) != 0) {
        return EDNS_ERR_BAD_VERSION_OR_Z;
    }

    uint16_t rdlen = rd_be16(buf + 9);
    if ((size_t)11 + (size_t)rdlen != len) return EDNS_ERR_LENGTH_MISMATCH;

    *out = (edns_opt_parsed_t){
        .udp_payload_size = udp_sz,
        .ext_rcode = ext_rcode,
        .dnssec_ok = (flags & UINT16_C(0x8000)) != 0,
    };

    size_t pos = 11;
    while (pos < len) {
        if (len - pos < 4) return EDNS_ERR_TRUNCATED;
        uint16_t opt_code = rd_be16(buf + pos);
        uint16_t opt_len = rd_be16(buf + pos + 2);
        pos += 4;
        if (len - pos < opt_len) return EDNS_ERR_TRUNCATED;

        if (opt_code == 8) {
            if (out->ecs.present || opt_len < 4) return EDNS_ERR_BAD_ECS_FAMILY_OR_PREFIX;
            uint16_t fam = rd_be16(buf + pos);
            uint8_t src_p = buf[pos + 2];
            uint8_t scope_p = buf[pos + 3];
            uint8_t max_bits = (fam == 1) ? 32 : ((fam == 2) ? 128 : 0);
            if (max_bits == 0 || src_p > max_bits || scope_p > max_bits) {
                return EDNS_ERR_BAD_ECS_FAMILY_OR_PREFIX;
            }
            size_t addr_bytes = ((size_t)src_p + 7U) / 8U;
            if ((size_t)opt_len != 4U + addr_bytes) {
                return EDNS_ERR_BAD_ECS_FAMILY_OR_PREFIX;
            }
            const uint8_t *addr_ptr = buf + pos + 4;
            uint8_t rem_bits = (uint8_t)(src_p % 8U);
            if (rem_bits != 0) {
                uint8_t host_mask = (uint8_t)((1U << (8U - rem_bits)) - 1U);
                if ((addr_ptr[addr_bytes - 1] & host_mask) != 0) {
                    return EDNS_ERR_NONZERO_ECS_TAIL_BITS;
                }
            }
            out->ecs.present = true;
            out->ecs.family = fam;
            out->ecs.src_prefix = src_p;
            out->ecs.scope_prefix = scope_p;
            if (addr_bytes > 0) {
                memcpy(out->ecs.addr_padded, addr_ptr, addr_bytes);
            }
        }
        pos += opt_len;
    }
    return EDNS_OK;
}
