```rust
pub const OPENSSH_KEY_V1_MAGIC: &[u8; 15] = b"openssh-key-v1\0";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SshKeyParseError {
    Truncated,
    InvalidMagic,
    EncryptedKeyUnsupported,
    NonEmptyKdfOptions,
    UnsupportedKeyCount(u32),
    UnsupportedAlgorithm,
    UnalignedPrivateBlock,
    CheckIntMismatch,
    PublicKeyMismatch,
    InvalidKeyLength,
    InvalidCommentUtf8OrLength,
    InvalidDeterministicPadding,
    TrailingBytes,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedOpenSshEd25519 {
    pub seed: [u8; 32],
    pub public_key: [u8; 32],
    pub comment: String,
}

struct SshReader<'a> {
    buf: &'a [u8],
    pos: usize,
}

impl<'a> SshReader<'a> {
    fn new(buf: &'a [u8]) -> Self {
        Self { buf, pos: 0 }
    }

    fn read_fixed<const N: usize>(&mut self) -> Result<&'a [u8; N], SshKeyParseError> {
        let end = self.pos.checked_add(N).ok_or(SshKeyParseError::Truncated)?;
        let slice = self.buf.get(self.pos..end).ok_or(SshKeyParseError::Truncated)?;
        self.pos = end;
        slice.try_into().map_err(|_| SshKeyParseError::Truncated)
    }

    fn read_u32(&mut self) -> Result<u32, SshKeyParseError> {
        Ok(u32::from_be_bytes(*self.read_fixed::<4>()?))
    }

    fn read_string(&mut self, max_len: usize) -> Result<&'a [u8], SshKeyParseError> {
        let len = self.read_u32()? as usize;
        if len > max_len {
            return Err(SshKeyParseError::Truncated);
        }
        let end = self.pos.checked_add(len).ok_or(SshKeyParseError::Truncated)?;
        let out = self.buf.get(self.pos..end).ok_or(SshKeyParseError::Truncated)?;
        self.pos = end;
        Ok(out)
    }

    fn rest(&self) -> &'a [u8] {
        &self.buf[self.pos..]
    }
}

pub fn parse_openssh_ed25519_unencrypted(
    blob: &[u8],
) -> Result<ParsedOpenSshEd25519, SshKeyParseError> {
    let mut rd = SshReader::new(blob);
    if rd.read_fixed::<15>()? != OPENSSH_KEY_V1_MAGIC {
        return Err(SshKeyParseError::InvalidMagic);
    }
    let cipher = rd.read_string(64)?;
    let kdf = rd.read_string(64)?;
    if cipher != b"none" || kdf != b"none" {
        return Err(SshKeyParseError::EncryptedKeyUnsupported);
    }
    if !rd.read_string(64)?.is_empty() {
        return Err(SshKeyParseError::NonEmptyKdfOptions);
    }
    let nkeys = rd.read_u32()?;
    if nkeys != 1 {
        return Err(SshKeyParseError::UnsupportedKeyCount(nkeys));
    }

    let pub_blob = rd.read_string(256)?;
    let mut pub_rd = SshReader::new(pub_blob);
    if pub_rd.read_string(32)? != b"ssh-ed25519" {
        return Err(SshKeyParseError::UnsupportedAlgorithm);
    }
    let outer_pk: [u8; 32] = pub_rd
        .read_string(32)?
        .try_into()
        .map_err(|_| SshKeyParseError::InvalidKeyLength)?;
    if !pub_rd.rest().is_empty() {
        return Err(SshKeyParseError::TrailingBytes);
    }

    let priv_section = rd.read_string(4096)?;
    if !rd.rest().is_empty() {
        return Err(SshKeyParseError::TrailingBytes);
    }
    if priv_section.is_empty() || (priv_section.len() % 8) != 0 {
        return Err(SshKeyParseError::UnalignedPrivateBlock);
    }

    let mut pr = SshReader::new(priv_section);
    let c1 = pr.read_u32()?;
    let c2 = pr.read_u32()?;
    if c1 != c2 {
        return Err(SshKeyParseError::CheckIntMismatch);
    }
    if pr.read_string(32)? != b"ssh-ed25519" {
        return Err(SshKeyParseError::UnsupportedAlgorithm);
    }
    let inner_pk = pr.read_string(32)?;
    let sk_pk = pr.read_string(64)?;
    if inner_pk.len() != 32 || sk_pk.len() != 64 {
        return Err(SshKeyParseError::InvalidKeyLength);
    }
    if inner_pk != outer_pk || &sk_pk[32..64] != outer_pk {
        return Err(SshKeyParseError::PublicKeyMismatch);
    }

    let comment_bytes = pr
        .read_string(1024)
        .map_err(|_| SshKeyParseError::InvalidCommentUtf8OrLength)?;
    let comment = std::str::from_utf8(comment_bytes)
        .map_err(|_| SshKeyParseError::InvalidCommentUtf8OrLength)?
        .to_owned();

    let pad = pr.rest();
    if pad.len() >= 8 {
        return Err(SshKeyParseError::InvalidDeterministicPadding);
    }
    for (idx, &b) in pad.iter().enumerate() {
        if b != ((idx + 1) as u8) {
            return Err(SshKeyParseError::InvalidDeterministicPadding);
        }
    }

    let mut seed = [0_u8; 32];
    seed.copy_from_slice(&sk_pk[..32]);
    Ok(ParsedOpenSshEd25519 {
        seed,
        public_key: outer_pk,
        comment,
    })
}
