```c
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    TPM_SIG_OK = 0,
    TPM_SIG_ERR_NULL,
    TPM_SIG_ERR_TRUNCATED,
    TPM_SIG_ERR_ALG_MISMATCH,
    TPM_SIG_ERR_PARAM_LEN,
    TPM_SIG_ERR_TRAILING,
    TPM_SIG_ERR_SCALAR_OUT_OF_RANGE,
} tpm_sig_status_t;

typedef struct {
    uint8_t r[32];
    uint8_t s[32];
} tpm_p256_sig_t;

static const uint8_t P256_ORDER_BE[32] = {
    0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00,
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
    0xBC, 0xE6, 0xFA, 0xAD, 0xA7, 0x17, 0x9E, 0x84,
    0xF3, 0xB9, 0xCA, 0xC2, 0xFC, 0x63, 0x25, 0x51,
};

static uint16_t rd_u16_be(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

// Constant-time check: 0 < x < P256_ORDER_BE
static bool ct_is_valid_p256_scalar(const uint8_t x[32]) {
    uint32_t nonzero_acc = 0;
    uint32_t borrow = 0;
    for (int i = 31; i >= 0; --i) {
        nonzero_acc |= x[i];
        uint32_t xi = x[i];
        uint32_t ni = P256_ORDER_BE[i];
        uint32_t diff = xi - ni - borrow;
        borrow = (diff >> 31) & 1U;
    }
    // x < n iff final subtraction borrowed (borrow == 1), and x > 0 iff nonzero_acc != 0
    return (nonzero_acc != 0U) && (borrow == 1U);
}

[[nodiscard]] tpm_sig_status_t parse_tpm2_ecdsa_p256_sig(
    const uint8_t *buf,
    size_t len,
    tpm_p256_sig_t *out
) {
    if (buf == nullptr || out == nullptr) return TPM_SIG_ERR_NULL;
    if (len < 8) return TPM_SIG_ERR_TRUNCATED;

    uint16_t sig_alg = rd_u16_be(buf);
    uint16_t hash_alg = rd_u16_be(buf + 2);
    if (sig_alg != UINT16_C(0x0018) || hash_alg != UINT16_C(0x000B)) {
        return TPM_SIG_ERR_ALG_MISMATCH;
    }

    size_t pos = 4;
    uint16_t r_len = rd_u16_be(buf + pos);
    pos += 2;
    if (r_len == 0 || r_len > 32) return TPM_SIG_ERR_PARAM_LEN;
    if (len - pos < (size_t)r_len + 2U) return TPM_SIG_ERR_TRUNCATED;
    const uint8_t *r_src = buf + pos;
    pos += r_len;

    uint16_t s_len = rd_u16_be(buf + pos);
    pos += 2;
    if (s_len == 0 || s_len > 32) return TPM_SIG_ERR_PARAM_LEN;
    if (len - pos < s_len) return TPM_SIG_ERR_TRUNCATED;
    const uint8_t *s_src = buf + pos;
    pos += s_len;

    if (pos != len) return TPM_SIG_ERR_TRAILING;

    memset(out, 0, sizeof(*out));
    memcpy(out->r + (32U - r_len), r_src, r_len);
    memcpy(out->s + (32U - s_len), s_src, s_len);

    if (!ct_is_valid_p256_scalar(out->r) || !ct_is_valid_p256_scalar(out->s)) {
        memset(out, 0, sizeof(*out));
        return TPM_SIG_ERR_SCALAR_OUT_OF_RANGE;
    }
    return TPM_SIG_OK;
}
