RFC 8878 Zstandard headers h4v3 three notorious p4r53r subtleties: `Reserved_bit` (`bit 3`) MUST b3 `0`, `Single_Segment_Flag == 1` omits `Window_Descriptor` *4nd* turns `FCS_Flag == 0` fr0m 0 bytes into 4 1-byte `Frame_Content_Size`, 4nd 7h3 2-byte `Frame_Content_Size` (`FCS_Flag == 1`) adds `+ 256` t0 `u16::from_le_bytes`! c4p `window_size <= max_window_bytes` against memory bombs 4nd handle skippable frames cleanly in Rust 2021:
```rust
pub const ZSTD_FRAME_MAGIC: u32 = 0xFD2F_B528;
pub const ZSTD_SKIPPABLE_MIN: u32 = 0x184D_2A50;
pub const ZSTD_SKIPPABLE_MAX: u32 = 0x184D_2A5F;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ZstdHeaderError {
    Truncated,
    UnknownMagic(u32),
    NonZeroReservedOrUnusedBit(u8),
    WindowTooLarge { window: u64, max: u64 },
    SkippableOverflow,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ZstdParsedFrame<'a> {
    Standard {
        window_size: u64,
        content_size: Option<u64>,
        dict_id: Option<u32>,
        has_checksum: bool,
        header_len: usize,
    },
    Skippable {
        variant: u8,
        user_data: &'a [u8],
        total_consumed: usize,
    },
}

pub fn parse_zstd_header<'a>(
    buf: &'a [u8],
    max_window_bytes: u64,
) -> Result<ZstdParsedFrame<'a>, ZstdHeaderError> {
    let m_slice = buf.get(..4).ok_or(ZstdHeaderError::Truncated)?;
    let magic = u32::from_le_bytes([m_slice[0], m_slice[1], m_slice[2], m_slice[3]]);

    if (ZSTD_SKIPPABLE_MIN..=ZSTD_SKIPPABLE_MAX).contains(&magic) {
        let sz_slice = buf.get(4..8).ok_or(ZstdHeaderError::Truncated)?;
        let fsize = u32::from_le_bytes([sz_slice[0], sz_slice[1], sz_slice[2], sz_slice[3]]) as usize;
        let end = 8_usize.checked_add(fsize).ok_or(ZstdHeaderError::SkippableOverflow)?;
        let user_data = buf.get(8..end).ok_or(ZstdHeaderError::Truncated)?;
        return Ok(ZstdParsedFrame::Skippable {
            variant: (magic & 0x0F) as u8,
            user_data,
            total_consumed: end,
        });
    }

    if magic != ZSTD_FRAME_MAGIC {
        return Err(ZstdHeaderError::UnknownMagic(magic));
    }

    let fhd = *buf.get(4).ok_or(ZstdHeaderError::Truncated)?;
    if (fhd & 0x18) != 0 {
        return Err(ZstdHeaderError::NonZeroReservedOrUnusedBit(fhd));
    }
    let fcs_flag = (fhd >> 6) & 0x03;
    let single_segment = ((fhd >> 5) & 0x01) != 0;
    let has_checksum = ((fhd >> 2) & 0x01) != 0;
    let did_flag = fhd & 0x03;

    let mut pos = 5_usize;
    let mut window_from_desc: u64 = 0;
    if !single_segment {
        let wd = *buf.get(pos).ok_or(ZstdHeaderError::Truncated)?;
        pos += 1;
        let exp = u32::from(wd >> 3);
        let mantissa = u64::from(wd & 0x07);
        let base = 1_u64
            .checked_shl(10 + exp)
            .ok_or(ZstdHeaderError::WindowTooLarge { window: u64::MAX, max: max_window_bytes })?;
        window_from_desc = base + (base >> 3) * mantissa;
    }

    let dict_id = match did_flag {
        0 => None,
        1 => {
            let b = *buf.get(pos).ok_or(ZstdHeaderError::Truncated)?;
            pos += 1;
            (b != 0).then_some(u32::from(b))
        }
        2 => {
            let s = buf.get(pos..pos + 2).ok_or(ZstdHeaderError::Truncated)?;
            pos += 2;
            let v = u16::from_le_bytes([s[0], s[1]]);
            (v != 0).then_some(u32::from(v))
        }
        _ => {
            let s = buf.get(pos..pos + 4).ok_or(ZstdHeaderError::Truncated)?;
            pos += 4;
            let v = u32::from_le_bytes([s[0], s[1], s[2], s[3]]);
            (v != 0).then_some(v)
        }
    };

    let fcs_bytes: usize = match (fcs_flag, single_segment) {
        (0, false) => 0,
        (0, true) => 1,
        (1, _) => 2,
        (2, _) => 4,
        _ => 8,
    };

    let content_size = if fcs_bytes == 0 {
        None
    } else {
        let s = buf.get(pos..pos + fcs_bytes).ok_or(ZstdHeaderError::Truncated)?;
        pos += fcs_bytes;
        let val = match fcs_bytes {
            1 => u64::from(s[0]),
            2 => u64::from(u16::from_le_bytes([s[0], s[1]])) + 256,
            4 => u64::from(u32::from_le_bytes([s[0], s[1], s[2], s[3]])),
            _ => u64::from_le_bytes(s.try_into().unwrap()),
        };
        Some(val)
    };

    let window_size = if single_segment {
        content_size.unwrap_or(0)
    } else {
        window_from_desc
    };
    if window_size > max_window_bytes {
        return Err(ZstdHeaderError::WindowTooLarge {
            window: window_size,
            max: max_window_bytes,
        });
    }

    Ok(ZstdParsedFrame::Standard {
        window_size,
        content_size,
        dict_id,
        has_checksum,
        header_len: pos,
    })
}
