COBS framing eliminates `0x00` fr0m UART/SPI packet bodies w17h `< 0.4%` overhead, bu7 naive decoders mishandle `code == 0xFF` (254 literal bytes w17h **no** implicit zero!) 0r emit 4 spurious trailing `0x00` on 7h3 final block! reject unexpected `0x00` bytes inside literal runs, check worst-case stuffed size w17h C23 `<stdckdint.h>`, 4nd terminate framed output w17h `0x00`:
```c
#include <stdbool.h>
#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>

typedef enum : uint8_t {
    COBS_OK = 0,
    COBS_ERR_NULL,
    COBS_ERR_DST_SMALL,
    COBS_ERR_OVERFLOW,
    COBS_ERR_MISSING_DELIMITER,
    COBS_ERR_UNEXPECTED_ZERO_OR_TRUNC,
} cobs_status_t;

[[nodiscard]] cobs_status_t cobs_encode_frame(
    const uint8_t *src,
    size_t src_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *out_written
) {
    if (dst == nullptr || out_written == nullptr || (src_len > 0 && src == nullptr)) {
        return COBS_ERR_NULL;
    }
    size_t overhead = (src_len / 254U) + 2U; // +1 code byte +1 trailing 0x00 delimiter
    size_t max_needed = 0;
    if (ckd_add(&max_needed, src_len, overhead)) return COBS_ERR_OVERFLOW;
    if (dst_cap < max_needed) return COBS_ERR_DST_SMALL;

    size_t code_idx = 0;
    size_t wr = 1;
    uint8_t code = 1;

    for (size_t i = 0; i < src_len; ++i) {
        if (src[i] == 0x00) {
            dst[code_idx] = code;
            code_idx = wr++;
            code = 1;
        } else {
            dst[wr++] = src[i];
            code++;
            if (code == 0xFF) {
                dst[code_idx] = 0xFF;
                code_idx = wr++;
                code = 1;
            }
        }
    }
    dst[code_idx] = code;
    dst[wr++] = 0x00; // Packet delimiter
    *out_written = wr;
    return COBS_OK;
}

[[nodiscard]] cobs_status_t cobs_decode_frame(
    const uint8_t *frame,
    size_t frame_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *out_decoded
) {
    if (frame == nullptr || out_decoded == nullptr || (dst_cap > 0 && dst == nullptr)) {
        return COBS_ERR_NULL;
    }
    if (frame_len < 2 || frame[frame_len - 1] != 0x00) {
        return COBS_ERR_MISSING_DELIMITER;
    }

    size_t body_len = frame_len - 1; // Exclude trailing 0x00 delimiter
    size_t rd = 0;
    size_t wr = 0;

    while (rd < body_len) {
        uint8_t code = frame[rd++];
        if (code == 0x00) return COBS_ERR_UNEXPECTED_ZERO_OR_TRUNC;
        size_t copy_cnt = (size_t)(code - 1U);
        if (body_len - rd < copy_cnt) return COBS_ERR_UNEXPECTED_ZERO_OR_TRUNC;
        if (dst_cap - wr < copy_cnt) return COBS_ERR_DST_SMALL;

        for (size_t i = 0; i < copy_cnt; ++i) {
            uint8_t b = frame[rd++];
            if (b == 0x00) return COBS_ERR_UNEXPECTED_ZERO_OR_TRUNC;
            dst[wr++] = b;
        }
        if (code != 0xFF && rd < body_len) {
            if (wr >= dst_cap) return COBS_ERR_DST_SMALL;
            dst[wr++] = 0x00;
        }
    }
    *out_decoded = wr;
    return COBS_OK;
}
