#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SqliteRecordError {
    Truncated,
    NonCanonicalVarint,
    InvalidHeaderSize(u64),
    TooManyColumns { max: usize },
    ReservedSerialType(u64),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SqliteSerialKind {
    Null,
    Int8,
    Int16,
    Int24,
    Int32,
    Int48,
    Int64,
    Float64,
    ConstZero,
    ConstOne,
    Blob { byte_len: usize },
    Text { byte_len: usize },
}

pub fn decode_sqlite_varint(buf: &[u8]) -> Result<(u64, usize), SqliteRecordError> {
    let b0 = *buf.first().ok_or(SqliteRecordError::Truncated)?;
    if b0 == 0x80 {
        return Err(SqliteRecordError::NonCanonicalVarint);
    }
    if (b0 & 0x80) == 0 {
        return Ok((u64::from(b0), 1));
    }
    let mut acc = u64::from(b0 & 0x7F);
    for idx in 1..8_usize {
        let b = *buf.get(idx).ok_or(SqliteRecordError::Truncated)?;
        acc = (acc << 7) | u64::from(b & 0x7F);
        if (b & 0x80) == 0 {
            return Ok((acc, idx + 1));
        }
    }
    // Ninth byte (index 8) carries 8 full bits!
    let b8 = *buf.get(8).ok_or(SqliteRecordError::Truncated)?;
    acc = (acc << 8) | u64::from(b8);
    if acc < (1_u64 << 56) {
        return Err(SqliteRecordError::NonCanonicalVarint);
    }
    Ok((acc, 9))
}

pub fn encode_sqlite_varint(val: u64, out: &mut Vec<u8>) {
    if val <= 0x7F {
        out.push(val as u8);
        return;
    }
    if val >= (1_u64 << 56) {
        let mut tmp = [0_u8; 9];
        tmp[8] = (val & 0xFF) as u8;
        let mut hi = val >> 8;
        for slot in (0..8).rev() {
            tmp[slot] = ((hi & 0x7F) as u8) | 0x80;
            hi >>= 7;
        }
        out.extend_from_slice(&tmp);
        return;
    }
    let mut groups = [0_u8; 8];
    let mut n = 0_usize;
    let mut cur = val;
    while cur > 0 {
        groups[n] = (cur & 0x7F) as u8;
        cur >>= 7;
        n += 1;
    }
    for idx in (0..n).rev() {
        let flag = if idx == 0 { 0x00 } else { 0x80 };
        out.push(groups[idx] | flag);
    }
}

pub fn classify_serial_type(st: u64) -> Result<SqliteSerialKind, SqliteRecordError> {
    match st {
        0 => Ok(SqliteSerialKind::Null),
        1 => Ok(SqliteSerialKind::Int8),
        2 => Ok(SqliteSerialKind::Int16),
        3 => Ok(SqliteSerialKind::Int24),
        4 => Ok(SqliteSerialKind::Int32),
        5 => Ok(SqliteSerialKind::Int48),
        6 => Ok(SqliteSerialKind::Int64),
        7 => Ok(SqliteSerialKind::Float64),
        8 => Ok(SqliteSerialKind::ConstZero),
        9 => Ok(SqliteSerialKind::ConstOne),
        10 | 11 => Err(SqliteRecordError::ReservedSerialType(st)),
        n if (n & 1) == 0 => {
            let len = usize::try_from((n - 12) / 2).map_err(|_| SqliteRecordError::InvalidHeaderSize(n))?;
            Ok(SqliteSerialKind::Blob { byte_len: len })
        }
        n => {
            let len = usize::try_from((n - 13) / 2).map_err(|_| SqliteRecordError::InvalidHeaderSize(n))?;
            Ok(SqliteSerialKind::Text { byte_len: len })
        }
    }
}

pub fn parse_sqlite_record_header(
    record: &[u8],
    max_cols: usize,
) -> Result<(Vec<SqliteSerialKind>, usize), SqliteRecordError> {
    let (hdr_sz_u64, mut pos) = decode_sqlite_varint(record)?;
    let hdr_sz = usize::try_from(hdr_sz_u64)
        .map_err(|_| SqliteRecordError::InvalidHeaderSize(hdr_sz_u64))?;
    if hdr_sz < pos {
        return Err(SqliteRecordError::InvalidHeaderSize(hdr_sz_u64));
    }
    let hdr_slice = record.get(..hdr_sz).ok_or(SqliteRecordError::Truncated)?;

    let mut cols = Vec::new();
    while pos < hdr_sz {
        if cols.len() >= max_cols {
            return Err(SqliteRecordError::TooManyColumns { max: max_cols });
        }
        let (st, used) = decode_sqlite_varint(&hdr_slice[pos..])?;
        pos += used;
        cols.push(classify_serial_type(st)?);
    }
    Ok((cols, hdr_sz))
}
