static bool valid_radius_code(uint8_t c) {
    return (c >= 1 && c <= 5) || (c >= 11 && c <= 13);
}

[[nodiscard]] rad_status_t parse_radius_packet(
    const uint8_t *buf,
    size_t len,
    rad_parsed_t *out
) {
