    if (len < 20 || len > 4096) return RAD_ERR_BAD_PACKET_LEN;

    uint8_t code = buf[0];
    if (!valid_radius_code(code)) return RAD_ERR_BAD_CODE;
    uint16_t wire_len = (uint16_t)(((uint16_t)buf[2] << 8) | (uint16_t)buf[3]);
    if ((size_t)wire_len != len) return RAD_ERR_BAD_PACKET_LEN;

    *out = (rad_parsed_t){ .code = code, .identifier = buf[1], .item_count = 0 };
    memcpy(out->authenticator, buf + 4, 16);

    size_t pos = 20;
    while (pos < len) {
        if (len - pos < 2) return RAD_ERR_ATTR_TRUNCATED;
        uint8_t atype = buf[pos];
        uint8_t alen = buf[pos + 1];
        if (alen < 2) return RAD_ERR_ATTR_LEN_UNDERFLOW;
        if (len - pos < alen) return RAD_ERR_ATTR_TRUNCATED;

        const uint8_t *aval = buf + pos + 2;
        uint8_t aval_len = (uint8_t)(alen - 2U);

        if (atype == 26) {
            if (alen < 8 || aval[0] != 0x00) return RAD_ERR_BAD_VSA;
            uint32_t vid = ((uint32_t)aval[1] << 16)
                         | ((uint32_t)aval[2] << 8)
                         | (uint32_t)aval[3];
            if (vid == 0) return RAD_ERR_BAD_VSA;
            size_t vpos = 4;
            while (vpos < aval_len) {
                if ((size_t)aval_len - vpos < 2) return RAD_ERR_BAD_VSA;
                uint8_t vtype = aval[vpos];
                uint8_t vlen = aval[vpos + 1];
                if (vlen < 2 || (size_t)aval_len - vpos < vlen) return RAD_ERR_BAD_VSA;
                if (out->item_count >= 64) return RAD_ERR_TOO_MANY_ATTRS;
                out->items[out->item_count++] = (rad_item_t){
                    .is_vsa = true,
                    .outer_type = 26,
                    .vendor_id = vid,
                    .vsa_type = vtype,
                    .val = aval + vpos + 2,
                    .val_len = (uint8_t)(vlen - 2U),
                };
                vpos += vlen;
            }
        } else {
            if (out->item_count >= 64) return RAD_ERR_TOO_MANY_ATTRS;
            out->items[out->item_count++] = (rad_item_t){
                .is_vsa = false,
                .outer_type = atype,
                .val = aval,
                .val_len = aval_len,
            };
        }
        pos += alen;
    }
    return RAD_OK;
}
