#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SocksProtoError {
    Truncated,
    BadSubnegVersion(u8),
    EmptyOrInvalidCredential,
    BadSocksVersion(u8),
    UnknownReplyCode(u8),
    NonZeroReserved(u8),
    UnsupportedAtyp(u8),
