pub fn parse_socks_userpass_auth(buf: &[u8]) -> Result<SocksUserPassReq<'_>, SocksProtoError> {
    let ver = *buf.first().ok_or(SocksProtoError::Truncated)?;
    if ver != 0x01 {
        return Err(SocksProtoError::BadSubnegVersion(ver));
    }
    let ulen = *buf.get(1).ok_or(SocksProtoError::Truncated)? as usize;
    if ulen == 0 {
        return Err(SocksProtoError::EmptyOrInvalidCredential);
    }
    let u_end = 2 + ulen;
    let uname = buf.get(2..u_end).ok_or(SocksProtoError::Truncated)?;
    let plen = *buf.get(u_end).ok_or(SocksProtoError::Truncated)? as usize;
    if plen == 0 {
        return Err(SocksProtoError::EmptyOrInvalidCredential);
    }
    let p_end = u_end + 1 + plen;
    let passwd = buf.get(u_end + 1..p_end).ok_or(SocksProtoError::Truncated)?;
    if p_end != buf.len() {
        return Err(SocksProtoError::TrailingBytes);
    }
    if uname.contains(&0) || passwd.contains(&0) {
        return Err(SocksProtoError::EmptyOrInvalidCredential);
    }
    Ok(SocksUserPassReq { username: uname, password: passwd })
}

fn valid_socks_domain(raw: &[u8]) -> bool {
    if raw.is_empty() || raw.len() > 253 || raw.starts_with(b".") || raw.contains(&0) {
        return false;
    }
    raw.iter()
        .all(|&b| b.is_ascii_alphanumeric() || b == b'-' || b == b'.')
}

pub fn parse_socks5_reply(buf: &[u8]) -> Result<SocksServerReply, SocksProtoError> {
    let hdr = buf.get(..4).ok_or(SocksProtoError::Truncated)?;
    if hdr[0] != 0x05 {
        return Err(SocksProtoError::BadSocksVersion(hdr[0]));
    }
    if hdr[1] > 0x08 {
        return Err(SocksProtoError::UnknownReplyCode(hdr[1]));
    }
    if hdr[2] != 0x00 {
        return Err(SocksProtoError::NonZeroReserved(hdr[2]));
    }

    let (bound_addr, pos) = match hdr[3] {
        0x01 => {
            let ip = buf.get(4..8).ok_or(SocksProtoError::Truncated)?;
            (SocksBoundAddr::V4([ip[0], ip[1], ip[2], ip[3]]), 8_usize)
        }
        0x03 => {
            let dlen = *buf.get(4).ok_or(SocksProtoError::Truncated)? as usize;
            let dend = 5 + dlen;
            let dom = buf.get(5..dend).ok_or(SocksProtoError::Truncated)?;
            if !valid_socks_domain(dom) {
                return Err(SocksProtoError::InvalidDomainName);
            }
            let s = std::str::from_utf8(dom).unwrap().to_owned();
            (SocksBoundAddr::Domain(s), dend)
        }
        0x04 => {
            let ip: [u8; 16] = buf
                .get(4..20)
                .ok_or(SocksProtoError::Truncated)?
                .try_into()
                .unwrap();
            (SocksBoundAddr::V6(ip), 20_usize)
        }
        bad => return Err(SocksProtoError::UnsupportedAtyp(bad)),
    };

    let port_bytes = buf.get(pos..pos + 2).ok_or(SocksProtoError::Truncated)?;
    if pos + 2 != buf.len() {
        return Err(SocksProtoError::TrailingBytes);
    }
    Ok(SocksServerReply {
        reply_code: hdr[1],
        bound_addr,
        bound_port: u16::from_be_bytes([port_bytes[0], port_bytes[1]]),
    })
}

pub fn serialize_socks5_reply(rep: &SocksServerReply) -> Result<Vec<u8>, SocksProtoError> {
    if rep.reply_code > 0x08 {
        return Err(SocksProtoError::UnknownReplyCode(rep.reply_code));
    }
    let mut out = Vec::with_capacity(22);
    out.extend_from_slice(&[0x05, rep.reply_code, 0x00]);
    match &rep.bound_addr {
        SocksBoundAddr::V4(octets) => {
            out.push(0x01);
            out.extend_from_slice(octets);
        }
        SocksBoundAddr::Domain(dom) => {
            if !valid_socks_domain(dom.as_bytes()) {
                return Err(SocksProtoError::InvalidDomainName);
            }
            out.push(0x03);
            out.push(dom.len() as u8);
            out.extend_from_slice(dom.as_bytes());
        }
        SocksBoundAddr::V6(octets) => {
            out.push(0x04);
            out.extend_from_slice(octets);
        }
    }
    out.extend_from_slice(&rep.bound_port.to_be_bytes());
    Ok(out)
}
