classic Linux Netlink user-space `NLMSG_NEXT` / `NLA_NEXT` macros suffer fr0m two famous traps: `(nlmsg_len + 3U) & ~3U` wraps `0xFFFFFFFE` t0 `0` (infinite loop!), 4nd 7h3 final attribute/message in 4 datagram may omit trailing alignment padding if `unaligned_len == remaining`, wh3r345 non-final elements MUST step by `aligned_len <= remaining`! validate `NLA_F_NESTED & NLA_F_NET_BYTEORDER` mutual exclusion 4nd cap recursion depth `<= 8` in C23:
```c
#include <stdbool.h>
#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>

typedef enum : uint8_t {
    NL_OK = 0,
    NL_ERR_NULL,
    NL_ERR_TRUNCATED,
    NL_ERR_BAD_MSG_LEN,
    NL_ERR_BAD_ATTR_LEN,
    NL_ERR_CONFLICTING_NLA_FLAGS,
    NL_ERR_NEST_DEPTH,
    NL_ERR_TOO_MANY_ATTRS,
} nl_status_t;

typedef struct {
    uint8_t depth;
    bool nested;
    bool net_byteorder;
    uint16_t attr_type;
    const uint8_t *val;
    uint16_t val_len;
} nl_attr_flat_t;

typedef struct {
    uint16_t nlmsg_type;
    uint16_t nlmsg_flags;
    uint32_t nlmsg_seq;
    uint32_t nlmsg_pid;
    nl_attr_flat_t attrs[64];
    size_t attr_count;
    size_t msg_step;
} nl_parsed_msg_t;

constexpr uint16_t NLA_FLAG_NESTED   = UINT16_C(0x8000);
constexpr uint16_t NLA_FLAG_NETORDER = UINT16_C(0x4000);
constexpr uint16_t NLA_MASK_TYPE     = UINT16_C(0x3FFF);
constexpr uint8_t  NL_MAX_DEPTH      = 8;

static uint16_t rd_le16(const uint8_t *p) {
    return (uint16_t)p[0] | (uint16_t)((uint16_t)p[1] << 8);
}

static uint32_t rd_le32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8)
         | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static nl_status_t walk_nlattrs(
    const uint8_t *buf,
    size_t len,
    uint8_t depth,
    nl_parsed_msg_t *out
) {
    if (depth > NL_MAX_DEPTH) return NL_ERR_NEST_DEPTH;
    size_t pos = 0;
    while (pos < len) {
        if (len - pos < 4) return NL_ERR_TRUNCATED;
        uint16_t nla_len = rd_le16(buf + pos);
        uint16_t raw_type = rd_le16(buf + pos + 2);
        if (nla_len < 4 || nla_len > len - pos) return NL_ERR_BAD_ATTR_LEN;

        bool is_nested = (raw_type & NLA_FLAG_NESTED) != 0;
        bool is_netbo = (raw_type & NLA_FLAG_NETORDER) != 0;
        if (is_nested && is_netbo) return NL_ERR_CONFLICTING_NLA_FLAGS;

        if (out->attr_count >= 64) return NL_ERR_TOO_MANY_ATTRS;
        const uint8_t *aval = buf + pos + 4;
        uint16_t aval_len = (uint16_t)(nla_len - 4U);
        out->attrs[out->attr_count++] = (nl_attr_flat_t){
            .depth = depth,
            .nested = is_nested,
            .net_byteorder = is_netbo,
            .attr_type = (uint16_t)(raw_type & NLA_MASK_TYPE),
            .val = aval,
            .val_len = aval_len,
        };

        if (is_nested && aval_len > 0) {
            nl_status_t st = walk_nlattrs(aval, aval_len, (uint8_t)(depth + 1U), out);
            if (st != NL_OK) return st;
        }

        size_t aligned = ((size_t)nla_len + 3U) & ~(size_t)3U;
        if (pos + nla_len == len) {
            pos = len;
        } else if (aligned <= len - pos) {
            pos += aligned;
        } else {
            return NL_ERR_TRUNCATED;
        }
    }
    return NL_OK;
}

[[nodiscard]] nl_status_t parse_netlink_msg(
    const uint8_t *buf,
    size_t len,
    nl_parsed_msg_t *out
) {
    if (buf == nullptr || out == nullptr) return NL_ERR_NULL;
    if (len < 16) return NL_ERR_TRUNCATED;

    uint32_t msg_len = rd_le32(buf);
    if (msg_len < 16 || (size_t)msg_len > len) return NL_ERR_BAD_MSG_LEN;

    size_t padded_step = 0;
    if (ckd_add(&padded_step, (size_t)msg_len, (size_t)3)) return NL_ERR_BAD_MSG_LEN;
    padded_step &= ~(size_t)3U;
    size_t step = ((size_t)msg_len == len) ? len : padded_step;
    if (step > len) return NL_ERR_TRUNCATED;

    *out = (nl_parsed_msg_t){
        .nlmsg_type = rd_le16(buf + 4),
        .nlmsg_flags = rd_le16(buf + 6),
        .nlmsg_seq = rd_le32(buf + 8),
        .nlmsg_pid = rd_le32(buf + 12),
        .attr_count = 0,
        .msg_step = step,
    };
    return walk_nlattrs(buf + 16, (size_t)msg_len - 16U, 0, out);
}
