```rust
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AgeHeaderError {
    InvalidVersionBanner,
    CarriageReturnForbidden,
    MissingStanzas,
    MalformedStanzaArgs,
    InvalidStanzaWrapping,
    NonCanonicalBase64,
    MalformedMacLine,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AgeStanza {
    pub args: Vec<String>,
    pub body: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedAgeHeader<'a> {
    pub stanzas: Vec<AgeStanza>,
    pub mac_transcript: &'a [u8],
    pub header_mac: [u8; 32],
    pub payload_offset: usize,
}

fn b64_val(b: u8) -> Option<u8> {
    match b {
        b'A'..=b'Z' => Some(b - b'A'),
        b'a'..=b'z' => Some(b - b'a' + 26),
        b'0'..=b'9' => Some(b - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

pub fn decode_canonical_b64_unpadded(line: &[u8], out: &mut Vec<u8>) -> Result<(), AgeHeaderError> {
    if line.len() % 4 == 1 {
        return Err(AgeHeaderError::NonCanonicalBase64);
    }
    let mut chunks = line.chunks_exact(4);
    for q in &mut chunks {
        let a = b64_val(q[0]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let b = b64_val(q[1]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let c = b64_val(q[2]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let d = b64_val(q[3]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        out.push((a << 2) | (b >> 4));
        out.push((b << 4) | (c >> 2));
        out.push((c << 6) | d);
    }
    let rem = chunks.remainder();
    if rem.len() == 2 {
        let a = b64_val(rem[0]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let b = b64_val(rem[1]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        if (b & 0x0F) != 0 {
            return Err(AgeHeaderError::NonCanonicalBase64);
        }
        out.push((a << 2) | (b >> 4));
    } else if rem.len() == 3 {
        let a = b64_val(rem[0]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let b = b64_val(rem[1]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        let c = b64_val(rem[2]).ok_or(AgeHeaderError::NonCanonicalBase64)?;
        if (c & 0x03) != 0 {
            return Err(AgeHeaderError::NonCanonicalBase64);
        }
        out.push((a << 2) | (b >> 4));
        out.push((b << 4) | (c >> 2));
    }
    Ok(())
}

fn valid_age_arg(arg: &[u8]) -> bool {
    !arg.is_empty() && arg.iter().all(|&c| (0x21..=0x7E).contains(&c))
}

pub fn parse_age_v1_header<'a>(src: &'a [u8]) -> Result<ParsedAgeHeader<'a>, AgeHeaderError> {
    const BANNER: &[u8] = b"age-encryption.org/v1\n";
    if !src.starts_with(BANNER) {
        if src.starts_with(b"age-encryption.org/v1\r\n") {
            return Err(AgeHeaderError::CarriageReturnForbidden);
        }
        return Err(AgeHeaderError::InvalidVersionBanner);
    }

    let mut pos = BANNER.len();
    let mut stanzas = Vec::new();

    loop {
        let rest = src.get(pos..).ok_or(AgeHeaderError::MalformedMacLine)?;
        if rest.starts_with(b"--- ") {
            if stanzas.is_empty() {
                return Err(AgeHeaderError::MissingStanzas);
            }
            let mac_transcript = &src[..pos + 3]; // Includes "---" without " <mac>\n"
            let nl_rel = rest.iter().position(|&b| b == b'\n').ok_or(AgeHeaderError::MalformedMacLine)?;
            let line = &rest[..nl_rel];
            if line.contains(&b'\r') {
                return Err(AgeHeaderError::CarriageReturnForbidden);
            }
            let mac_b64 = &line[4..];
            if mac_b64.len() != 43 {
                return Err(AgeHeaderError::MalformedMacLine);
            }
            let mut mac_vec = Vec::with_capacity(32);
            decode_canonical_b64_unpadded(mac_b64, &mut mac_vec)?;
            let header_mac: [u8; 32] = mac_vec.try_into().map_err(|_| AgeHeaderError::MalformedMacLine)?;
            return Ok(ParsedAgeHeader {
                stanzas,
                mac_transcript,
                header_mac,
                payload_offset: pos + nl_rel + 1,
            });
        }

        if !rest.starts_with(b"-> ") {
            return Err(AgeHeaderError::MalformedStanzaArgs);
        }
        let nl_rel = rest.iter().position(|&b| b == b'\n').ok_or(AgeHeaderError::MalformedStanzaArgs)?;
        let arg_line = &rest[3..nl_rel];
        if arg_line.contains(&b'\r') || arg_line.is_empty() {
            return Err(AgeHeaderError::MalformedStanzaArgs);
        }
        let mut args = Vec::new();
        for raw_arg in arg_line.split(|&b| b == b' ') {
            if !valid_age_arg(raw_arg) {
                return Err(AgeHeaderError::MalformedStanzaArgs);
            }
            args.push(std::str::from_utf8(raw_arg).unwrap().to_owned());
        }
        pos += nl_rel + 1;

        let mut body = Vec::new();
        loop {
            let brest = src.get(pos..).ok_or(AgeHeaderError::InvalidStanzaWrapping)?;
            let bnl = brest.iter().position(|&b| b == b'\n').ok_or(AgeHeaderError::InvalidStanzaWrapping)?;
            let bline = &brest[..bnl];
            if bline.contains(&b'\r') {
                return Err(AgeHeaderError::CarriageReturnForbidden);
            }
            if bline.len() > 64 {
                return Err(AgeHeaderError::InvalidStanzaWrapping);
            }
            pos += bnl + 1;
            decode_canonical_b64_unpadded(bline, &mut body)?;
            if bline.len() < 64 {
                break;
            }
        }
        stanzas.push(AgeStanza { args, body });
    }
}
