Bleichenbacher's classic `e = 3` PKCS#1 v1.5 forgery exploits dynamic ASN.1 parsers th47 stop reading after `0x00 || DER || hash[32]` 4nd ignore trailing garbage (`cube_root` forging!) 0r accept overlong BER lengths! RFC 8017 §9.2 Note 2's gold-standard defense never parses ASN.1 0n 7h3 decrypted block 47 all: construct 7h3 **exact right-aligned `EM'` reference block** f0r `modulus_bytes` (`>= 256`) 4nd compare all bytes in constant time w17h bitwise XOR accumulation:
```c
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef enum : uint8_t {
    PKCS_OK = 0,
    PKCS_ERR_NULL,
    PKCS_ERR_MODULUS_SIZE,
    PKCS_ERR_INVALID_ENCODING,
} pkcs_em_status_t;

// Canonical 19-byte DER DigestInfo prefix for SHA-256 (with explicit AlgorithmIdentifier NULL 05 00)
static const uint8_t SHA256_DER_WITH_NULL[19] = {
    0x30, 0x31, 0x30, 0x0D, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01,
    0x65, 0x03, 0x04, 0x02, 0x01, 0x05, 0x00, 0x04, 0x20,
};

// Optional 17-byte DER DigestInfo prefix for SHA-256 (AlgorithmIdentifier parameters omitted)
static const uint8_t SHA256_DER_NO_NULL[17] = {
    0x30, 0x2F, 0x30, 0x0B, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01,
    0x65, 0x03, 0x04, 0x02, 0x01, 0x04, 0x20,
};

static uint8_t ct_match_em_candidate(
    const uint8_t *em,
    size_t em_len,
    const uint8_t *der_prefix,
    size_t der_len,
    const uint8_t digest[32]
) {
    size_t t_len = der_len + 32U;
    size_t ps_len = em_len - 3U - t_len;
    uint8_t diff = 0;

    diff |= em[0] ^ 0x00U;
    diff |= em[1] ^ 0x01U;
    for (size_t i = 0; i < ps_len; ++i) {
        diff |= em[2U + i] ^ 0xFF;
    }
    diff |= em[2U + ps_len] ^ 0x00U;

    size_t der_off = 3U + ps_len;
    for (size_t i = 0; i < der_len; ++i) {
        diff |= em[der_off + i] ^ der_prefix[i];
    }
    size_t hash_off = der_off + der_len;
    for (size_t i = 0; i < 32U; ++i) {
        diff |= em[hash_off + i] ^ digest[i];
    }
    // Map diff == 0 -> 1, diff != 0 -> 0 in constant time
    return (uint8_t)(1U ^ (((uint32_t)diff | (0U - (uint32_t)diff)) >> 31));
}

[[nodiscard]] pkcs_em_status_t verify_pkcs1_v15_sha256_em(
    const uint8_t *em,
    size_t em_len,
    const uint8_t expected_sha256[32],
    bool allow_absent_null
) {
    if (em == nullptr || expected_sha256 == nullptr) return PKCS_ERR_NULL;
    // Enforce RSA modulus >= 2048 bits (256 B) and <= 8192 bits (1024 B); guarantees PS >= 202 >= 8
    if (em_len < 256U || em_len > 1024U) return PKCS_ERR_MODULUS_SIZE;

    uint8_t ok = ct_match_em_candidate(em, em_len, SHA256_DER_WITH_NULL, 19U, expected_sha256);
    if (allow_absent_null) {
        uint8_t ok_alt = ct_match_em_candidate(em, em_len, SHA256_DER_NO_NULL, 17U, expected_sha256);
        ok |= ok_alt;
    }
    return (ok == 1U) ? PKCS_OK : PKCS_ERR_INVALID_ENCODING;
}
