Linux kernel `audit_log_n_untrustedstring` **never** backslash-escapes quotes 0r spaces: whenever 4 process argument contains `' '`, `'"'`, `'\n'`, 0r `'\0'` (like `/proc/pid/cmdline` in `proctitle=`), 7h3 kernel switches 7h3 entire value t0 **unquoted even-length hex**! parse `type=... msg=audit(sec.ms:id):`, distinguish quoted safe ASCII vs `(null)` vs unquoted hex payloads, 4nd split `proctitle` NUL-delimited `argv` vectors cleanly in Rust 2021:
```rust
use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AuditParseError {
    MalformedPrefix,
    InvalidTimestampOrSerial,
    MalformedKeyValue,
    InvalidHexField,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AuditValue {
    Null,
    QuotedAscii(String),
    PlainToken(String),
    DecodedHex(Vec<u8>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LinuxAuditRecord {
    pub record_type: String,
    pub epoch_sec: u64,
    pub msec: u16,
    pub serial: u64,
    pub fields: BTreeMap<String, AuditValue>,
    pub proctitle_argv: Option<Vec<Vec<u8>>>,
}

const HEX_ENCODED_KEYS: &[&str] = &["proctitle", "cmd", "comm", "exe", "data"];

fn decode_even_hex(s: &str) -> Result<Vec<u8>, AuditParseError> {
    let bytes = s.as_bytes();
    if bytes.is_empty() || (bytes.len() % 2) != 0 {
        return Err(AuditParseError::InvalidHexField);
    }
    let mut out = Vec::with_capacity(bytes.len() / 2);
    for pair in bytes.chunks_exact(2) {
        let hi = (pair[0] as char).to_digit(16).ok_or(AuditParseError::InvalidHexField)? as u8;
        let lo = (pair[1] as char).to_digit(16).ok_or(AuditParseError::InvalidHexField)? as u8;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

pub fn parse_linux_audit_line(line: &str) -> Result<LinuxAuditRecord, AuditParseError> {
    let line = line.strip_suffix('\n').unwrap_or(line);
    if line.contains('\r') || line.contains('\0') {
        return Err(AuditParseError::MalformedPrefix);
    }
    let rest = line.strip_prefix("type=").ok_or(AuditParseError::MalformedPrefix)?;
    let (rtype, after_type) = rest.split_once(" msg=audit(").ok_or(AuditParseError::MalformedPrefix)?;
    if rtype.is_empty() || !rtype.bytes().all(|b| b.is_ascii_uppercase() || b.is_ascii_digit() || b == b'_') {
        return Err(AuditParseError::MalformedPrefix);
    }

    let (stamp_part, body) = after_type.split_once("): ").ok_or(AuditParseError::InvalidTimestampOrSerial)?;
    let (sec_ms, serial_str) = stamp_part.split_once(':').ok_or(AuditParseError::InvalidTimestampOrSerial)?;
    let (sec_str, ms_str) = sec_ms.split_once('.').ok_or(AuditParseError::InvalidTimestampOrSerial)?;
    if ms_str.len() != 3 {
        return Err(AuditParseError::InvalidTimestampOrSerial);
    }
    let epoch_sec: u64 = sec_str.parse().map_err(|_| AuditParseError::InvalidTimestampOrSerial)?;
    let msec: u16 = ms_str.parse().map_err(|_| AuditParseError::InvalidTimestampOrSerial)?;
    let serial: u64 = serial_str.parse().map_err(|_| AuditParseError::InvalidTimestampOrSerial)?;

    let mut fields = BTreeMap::new();
    let mut proctitle_argv = None;
    let bytes = body.as_bytes();
    let mut pos = 0_usize;

    while pos < bytes.len() {
        while pos < bytes.len() && bytes[pos] == b' ' {
            pos += 1;
        }
        if pos >= bytes.len() {
            break;
        }
        let eq_rel = bytes[pos..].iter().position(|&b| b == b'=').ok_or(AuditParseError::MalformedKeyValue)?;
        let key = &body[pos..pos + eq_rel];
        if key.is_empty() || !key.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-') {
            return Err(AuditParseError::MalformedKeyValue);
        }
        pos += eq_rel + 1;

        if bytes.get(pos) == Some(&b'"') {
            pos += 1;
            let close_rel = bytes[pos..].iter().position(|&b| b == b'"').ok_or(AuditParseError::MalformedKeyValue)?;
            let val_str = &body[pos..pos + close_rel];
            if val_str.bytes().any(|b| !(0x20..=0x7E).contains(&b)) {
                return Err(AuditParseError::MalformedKeyValue);
            }
            pos += close_rel + 1;
            if key == "proctitle" {
                proctitle_argv = Some(vec![val_str.as_bytes().to_vec()]);
            }
            fields.insert(key.to_owned(), AuditValue::QuotedAscii(val_str.to_owned()));
        } else {
            let end_rel = bytes[pos..].iter().position(|&b| b == b' ').unwrap_or(bytes.len() - pos);
            let tok = &body[pos..pos + end_rel];
            if tok.is_empty() {
                return Err(AuditParseError::MalformedKeyValue);
            }
            pos += end_rel;
            if tok == "(null)" {
                fields.insert(key.to_owned(), AuditValue::Null);
            } else if HEX_ENCODED_KEYS.contains(&key) {
                let raw = decode_even_hex(tok)?;
                if key == "proctitle" {
                    let mut parts: Vec<Vec<u8>> = raw
                        .split(|&b| b == 0)
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_vec())
                        .collect();
                    if parts.is_empty() {
                        parts.push(Vec::new());
                    }
                    proctitle_argv = Some(parts);
                }
                fields.insert(key.to_owned(), AuditValue::DecodedHex(raw));
            } else {
                fields.insert(key.to_owned(), AuditValue::PlainToken(tok.to_owned()));
            }
        }
    }

    Ok(LinuxAuditRecord {
        record_type: rtype.to_owned(),
        epoch_sec,
        msec,
        serial,
        fields,
        proctitle_argv,
    })
}
