sFlow v5 uses RFC 4506 XDR big-endian 4-byte alignment throughout, splits `sample_type` into `(enterprise << 12) | format`, 4nd introduced `Expanded Flow Sample` (`format = 3`, 44-byte header) specifically because `Flow Sample` (`format = 1`, 32-byte header) crams interface format bits into 7h3 top 2 bits (`0xC0000000`) 0f `input_if`/`output_if` (breaking ifIndex `>= 2^30`)! normalize both `format = 1` 4nd `format = 3` into unified interface fields w17h strict `% 4 == 0` XDR bounds in C23:
```c
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    SFLOW_OK = 0,
    SFLOW_ERR_NULL,
    SFLOW_ERR_TRUNCATED,
    SFLOW_ERR_BAD_VERSION_OR_ADDR,
    SFLOW_ERR_TOO_MANY_SAMPLES,
    SFLOW_ERR_UNALIGNED_XDR,
    SFLOW_ERR_ZERO_SAMPLING_RATE,
    SFLOW_ERR_TRAILING,
} sflow_status_t;

typedef struct {
    bool expanded;
    uint32_t sample_seq;
    uint32_t src_id_type;
    uint32_t src_id_index;
    uint32_t sampling_rate;
    uint32_t in_if_format;
    uint32_t in_if_value;
    uint32_t out_if_format;
    uint32_t out_if_value;
    uint32_t num_records;
} sflow_norm_sample_t;

typedef struct {
    uint32_t addr_type; // 1 = IPv4, 2 = IPv6
    uint8_t agent_ip[16];
    uint32_t sub_agent_id;
    uint32_t datagram_seq;
    uint32_t uptime_ms;
    sflow_norm_sample_t samples[64];
    size_t sample_count;
} sflow_datagram_t;

static uint32_t rd_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16)
         | ((uint32_t)p[2] << 8)  | (uint32_t)p[3];
}

[[nodiscard]] sflow_status_t parse_sflow_v5_datagram(
    const uint8_t *buf,
    size_t len,
    sflow_datagram_t *out
) {
    if (buf == nullptr || out == nullptr) return SFLOW_ERR_NULL;
    if ((len % 4U) != 0 || len < 28U) return SFLOW_ERR_TRUNCATED;

    if (rd_be32(buf) != 5U) return SFLOW_ERR_BAD_VERSION_OR_ADDR;
    uint32_t atype = rd_be32(buf + 4);
    size_t ip_bytes = (atype == 1U) ? 4U : ((atype == 2U) ? 16U : 0U);
    if (ip_bytes == 0U) return SFLOW_ERR_BAD_VERSION_OR_ADDR;
    if (len < 8U + ip_bytes + 16U) return SFLOW_ERR_TRUNCATED;

    *out = (sflow_datagram_t){ .addr_type = atype, .sample_count = 0 };
    memcpy(out->agent_ip, buf + 8, ip_bytes);

    size_t pos = 8U + ip_bytes;
    out->sub_agent_id = rd_be32(buf + pos);
    out->datagram_seq = rd_be32(buf + pos + 4);
    out->uptime_ms    = rd_be32(buf + pos + 8);
    uint32_t nsamples = rd_be32(buf + pos + 12);
    pos += 16U;

    if (nsamples > 64U) return SFLOW_ERR_TOO_MANY_SAMPLES;

    for (uint32_t i = 0; i < nsamples; ++i) {
        if (len - pos < 8U) return SFLOW_ERR_TRUNCATED;
        uint32_t raw_type = rd_be32(buf + pos);
        uint32_t slen = rd_be32(buf + pos + 4);
        pos += 8U;
        if ((slen % 4U) != 0) return SFLOW_ERR_UNALIGNED_XDR;
        if (len - pos < slen) return SFLOW_ERR_TRUNCATED;

        uint32_t enterprise = raw_type >> 12;
        uint32_t fmt = raw_type & UINT32_C(0xFFF);
        const uint8_t *sp = buf + pos;

        if (enterprise == 0U && fmt == 1U) {
            if (slen < 32U) return SFLOW_ERR_TRUNCATED;
            uint32_t srate = rd_be32(sp + 8);
            if (srate == 0U) return SFLOW_ERR_ZERO_SAMPLING_RATE;
            uint32_t src_id = rd_be32(sp + 4);
            uint32_t in_raw = rd_be32(sp + 20);
            uint32_t out_raw = rd_be32(sp + 24);
            out->samples[out->sample_count++] = (sflow_norm_sample_t){
                .expanded = false,
                .sample_seq = rd_be32(sp),
                .src_id_type = src_id >> 24,
                .src_id_index = src_id & UINT32_C(0x00FFFFFF),
                .sampling_rate = srate,
                .in_if_format = in_raw >> 30,
                .in_if_value = in_raw & UINT32_C(0x3FFFFFFF),
                .out_if_format = out_raw >> 30,
                .out_if_value = out_raw & UINT32_C(0x3FFFFFFF),
                .num_records = rd_be32(sp + 28),
            };
        } else if (enterprise == 0U && fmt == 3U) {
            if (slen < 44U) return SFLOW_ERR_TRUNCATED;
            uint32_t srate = rd_be32(sp + 12);
            if (srate == 0U) return SFLOW_ERR_ZERO_SAMPLING_RATE;
            out->samples[out->sample_count++] = (sflow_norm_sample_t){
                .expanded = true,
                .sample_seq = rd_be32(sp),
                .src_id_type = rd_be32(sp + 4),
                .src_id_index = rd_be32(sp + 8),
                .sampling_rate = srate,
                .in_if_format = rd_be32(sp + 24),
                .in_if_value = rd_be32(sp + 28),
                .out_if_format = rd_be32(sp + 32),
                .out_if_value = rd_be32(sp + 36),
                .num_records = rd_be32(sp + 40),
            };
        }
        pos += slen;
    }

    if (pos != len) return SFLOW_ERR_TRAILING;
    return SFLOW_OK;
}
