LZ4 Frame Format v1.6.4 guards its variable-length descriptor (`FLG`, `BD`, optional `ContentSize`, optional `DictID`) w17h `(xxh32(desc, 0) >> 8) & 0xFF` *b3f0r3* reading any data block, forbids `BlockMaxSize` codes `0..=3`, 4nd uses bit 31 (`0x8000_0000`) 0f each block size f0r uncompressed blocks! implement clean XXH32 + zero-panic block framing in Rust 2021:
```rust
pub const LZ4_FRAME_MAGIC: u32 = 0x184D_2204;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LzFrameError {
    Truncated,
    InvalidMagic(u32),
    UnsupportedVersion(u8),
    NonZeroReservedBits,
    InvalidBlockMaxCode(u8),
    HeaderChecksumMismatch { expected: u8, got: u8 },
    BlockExceedsMax { len: usize, max: usize },
    TrailingBytes,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LzDataBlock<'a> {
    pub uncompressed: bool,
    pub payload: &'a [u8],
    pub block_checksum: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedLzFrame<'a> {
    pub block_indep: bool,
    pub block_max_bytes: usize,
    pub content_size: Option<u64>,
    pub dict_id: Option<u32>,
    pub blocks: Vec<LzDataBlock<'a>>,
    pub content_checksum: Option<u32>,
}

pub fn xxh_32_zero_seed(data: &[u8]) -> u32 {
    const P1: u32 = 0x9E37_79B1;
    const P2: u32 = 0x85EB_CA77;
    const P3: u32 = 0xC2B2_AE3D;
    const P4: u32 = 0x27D4_EB2F;
    const P5: u32 = 0x1656_67B1;

    let mut pos = 0_usize;
    let mut h32: u32 = if data.len() >= 16 {
        let mut v1 = P1.wrapping_add(P2);
        let mut v2 = P2;
        let mut v3 = 0_u32;
        let mut v4 = 0_u32.wrapping_sub(P1);
        while pos + 16 <= data.len() {
            let r = |off: usize| {
                u32::from_le_bytes([
                    data[pos + off],
                    data[pos + off + 1],
                    data[pos + off + 2],
                    data[pos + off + 3],
                ])
            };
            v1 = v1.wrapping_add(r(0).wrapping_mul(P2)).rotate_left(13).wrapping_mul(P1);
            v2 = v2.wrapping_add(r(4).wrapping_mul(P2)).rotate_left(13).wrapping_mul(P1);
            v3 = v3.wrapping_add(r(8).wrapping_mul(P2)).rotate_left(13).wrapping_mul(P1);
            v4 = v4.wrapping_add(r(12).wrapping_mul(P2)).rotate_left(13).wrapping_mul(P1);
            pos += 16;
        }
        v1.rotate_left(1)
            .wrapping_add(v2.rotate_left(7))
            .wrapping_add(v3.rotate_left(12))
            .wrapping_add(v4.rotate_left(18))
    } else {
        P5
    };

    h32 = h32.wrapping_add(data.len() as u32);
    while pos + 4 <= data.len() {
        let k = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]);
        h32 = h32.wrapping_add(k.wrapping_mul(P3)).rotate_left(17).wrapping_mul(P4);
        pos += 4;
    }
    while pos < data.len() {
        h32 = h32.wrapping_add(u32::from(data[pos]).wrapping_mul(P5)).rotate_left(11).wrapping_mul(P1);
        pos += 1;
    }
    h32 ^= h32 >> 15;
    h32 = h32.wrapping_mul(P2);
    h32 ^= h32 >> 13;
    h32 = h32.wrapping_mul(P3);
    h32 ^ (h32 >> 16)
}

pub fn parse_lz4_frame(buf: &[u8]) -> Result<ParsedLzFrame<'_>, LzFrameError> {
    let m = buf.get(..4).ok_or(LzFrameError::Truncated)?;
    let magic = u32::from_le_bytes([m[0], m[1], m[2], m[3]]);
    if magic != LZ4_FRAME_MAGIC {
        return Err(LzFrameError::InvalidMagic(magic));
    }

    let flg = *buf.get(4).ok_or(LzFrameError::Truncated)?;
    let bd = *buf.get(5).ok_or(LzFrameError::Truncated)?;
    let ver = (flg >> 6) & 0x03;
    if ver != 0x01 {
        return Err(LzFrameError::UnsupportedVersion(ver));
    }
    if (flg & 0x02) != 0 || (bd & 0x8F) != 0 {
        return Err(LzFrameError::NonZeroReservedBits);
    }

    let bmax_code = (bd >> 4) & 0x07;
    let block_max_bytes: usize = match bmax_code {
        4 => 64 * 1024,
        5 => 256 * 1024,
        6 => 1024 * 1024,
        7 => 4 * 1024 * 1024,
        bad => return Err(LzFrameError::InvalidBlockMaxCode(bad)),
    };

    let block_indep = (flg & 0x20) != 0;
    let has_bcheck = (flg & 0x10) != 0;
    let has_csize = (flg & 0x08) != 0;
    let has_ccheck = (flg & 0x04) != 0;
    let has_dict = (flg & 0x01) != 0;

    let mut pos = 6_usize;
    let content_size = if has_csize {
        let s = buf.get(pos..pos + 8).ok_or(LzFrameError::Truncated)?;
        pos += 8;
        Some(u64::from_le_bytes(s.try_into().unwrap()))
    } else {
        None
    };
    let dict_id = if has_dict {
        let s = buf.get(pos..pos + 4).ok_or(LzFrameError::Truncated)?;
        pos += 4;
        Some(u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
    } else {
        None
    };

    let hc = *buf.get(pos).ok_or(LzFrameError::Truncated)?;
    let expected_hc = ((xxh_32_zero_seed(&buf[4..pos]) >> 8) & 0xFF) as u8;
    if hc != expected_hc {
        return Err(LzFrameError::HeaderChecksumMismatch { expected: expected_hc, got: hc });
    }
    pos += 1;

    let mut blocks = Vec::new();
    loop {
        let bh = buf.get(pos..pos + 4).ok_or(LzFrameError::Truncated)?;
        pos += 4;
        let raw_sz = u32::from_le_bytes([bh[0], bh[1], bh[2], bh[3]]);
        if raw_sz == 0 {
            break; // EndMark
        }
        let uncompressed = (raw_sz & 0x8000_0000) != 0;
        let blen = (raw_sz & 0x7FFF_FFFF) as usize;
        if blen == 0 || blen > block_max_bytes {
            return Err(LzFrameError::BlockExceedsMax { len: blen, max: block_max_bytes });
        }
        let end = pos.checked_add(blen).ok_or(LzFrameError::Truncated)?;
        let payload = buf.get(pos..end).ok_or(LzFrameError::Truncated)?;
        pos = end;
        let block_checksum = if has_bcheck {
            let cs = buf.get(pos..pos + 4).ok_or(LzFrameError::Truncated)?;
            pos += 4;
