    WASM_ERR_NULL,
    WASM_ERR_TRUNCATED,
    WASM_ERR_BAD_PREAMBLE,
    WASM_ERR_UNKNOWN_SECTION_ID,
    WASM_ERR_ULEB_OVERFLOW,
    WASM_ERR_SECTION_ORDER_OR_DUP,
    WASM_ERR_BAD_CUSTOM_NAME,
    WASM_ERR_TOO_MANY_SECTIONS,
