// Monotonic order rank per Wasm 2.0 §5.5.2: DataCount (12) precedes Code (10) and Data (11)!
static int wasm_section_rank(uint8_t id) {
    switch (id) {
        case 1:  return 1;  // Type
        case 2:  return 2;  // Import
        case 3:  return 3;  // Function
        case 4:  return 4;  // Table
        case 5:  return 5;  // Memory
        case 6:  return 6;  // Global
        case 7:  return 7;  // Export
        case 8:  return 8;  // Start
        case 9:  return 9;  // Element
        case 12: return 10; // DataCount (BEFORE Code!)
        case 10: return 11; // Code
        case 11: return 12; // Data
        default: return -1;
    }
}

static wasm_status_t read_wasm_u32(
    const uint8_t *buf,
    size_t len,
    bool strict_canonical,
    uint32_t *out_val,
    size_t *out_used
