        if ((b & 0x80) == 0) {
            if (strict_canonical && i > 0U && b == 0x00) {
                return WASM_ERR_ULEB_OVERFLOW;
            }
            *out_val = acc;
            *out_used = i + 1U;
            return WASM_OK;
        }
    }
    return WASM_ERR_ULEB_OVERFLOW;
