    if (len < 8U) return WASM_ERR_TRUNCATED;
    if (buf[0] != 0x00 || buf[1] != 0x61 || buf[2] != 0x73 || buf[3] != 0x6D ||
        buf[4] != 0x01 || buf[5] != 0x00 || buf[6] != 0x00 || buf[7] != 0x00) {
        return WASM_ERR_BAD_PREAMBLE;
    }

    *out = (wasm_module_view_t){ .count = 0 };
    int last_known_rank = 0;
    size_t pos = 8U;

    while (pos < len) {
        uint8_t sid = buf[pos++];
        if (sid > 12U) return WASM_ERR_UNKNOWN_SECTION_ID;

        uint32_t sec_sz = 0;
        size_t sz_used = 0;
        wasm_status_t st = read_wasm_u32(buf + pos, len - pos, strict_canonical, &sec_sz, &sz_used);
