        pos += sz_used;

        if (len - pos < (size_t)sec_sz) return WASM_ERR_TRUNCATED;
        const uint8_t *sec_ptr = buf + pos;
        pos += sec_sz;

        if (out->count >= 64U) return WASM_ERR_TOO_MANY_SECTIONS;

        if (sid == 0U) {
            uint32_t name_len = 0;
            size_t n_used = 0;
