            if ((size_t)sec_sz - n_used < (size_t)name_len) return WASM_ERR_BAD_CUSTOM_NAME;
            out->sections[out->count++] = (wasm_section_view_t){
                .id = 0,
                .custom_name = sec_ptr + n_used,
                .custom_name_len = name_len,
                .payload = sec_ptr + n_used + name_len,
                .payload_len = (uint32_t)((size_t)sec_sz - n_used - (size_t)name_len),
            };
        } else {
            int rank = wasm_section_rank(sid);
            if (rank <= last_known_rank) return WASM_ERR_SECTION_ORDER_OR_DUP;
            last_known_rank = rank;
            out->sections[out->count++] = (wasm_section_view_t){
                .id = sid,
                .custom_name = nullptr,
                .custom_name_len = 0,
                .payload = sec_ptr,
                .payload_len = sec_sz,
            };
        }
    }
    return WASM_OK;
}
