pub enum QpackPrefixError {
    Truncated,
    VarintOverflow,
    DynamicTableDisabled,
    EncodedInsertCountOutOfRange,
    InvalidRequiredInsertCount,
    NegativeBase,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct QpackSectionPrefix {
    pub required_insert_count: u64,
    pub base: u64,
    pub bytes_consumed: usize,
}

fn read_qpack_int(buf: &[u8], prefix_bits: u8) -> Result<(u64, usize), QpackPrefixError> {
    let first = *buf.first().ok_or(QpackPrefixError::Truncated)?;
    let mask: u8 = if prefix_bits == 8 { 0xFF } else { (1_u8 << prefix_bits) - 1 };
    let mut val = u64::from(first & mask);
    if (first & mask) < mask {
        return Ok((val, 1));
    }
    let mut shift: u32 = 0;
    let mut pos = 1_usize;
    loop {
        let b = *buf.get(pos).ok_or(QpackPrefixError::Truncated)?;
        pos += 1;
        let factor = 1_u64.checked_shl(shift).ok_or(QpackPrefixError::VarintOverflow)?;
        let add = u64::from(b & 0x7F)
            .checked_mul(factor)
            .ok_or(QpackPrefixError::VarintOverflow)?;
        val = val.checked_add(add).ok_or(QpackPrefixError::VarintOverflow)?;
        if (b & 0x80) == 0 {
            return Ok((val, pos));
        }
        shift += 7;
        if shift > 62 {
            return Err(QpackPrefixError::VarintOverflow);
        }
    }
}

fn write_qpack_int(mut val: u64, prefix_bits: u8, high_bits: u8, out: &mut Vec<u8>) {
    let mask: u8 = if prefix_bits == 8 { 0xFF } else { (1_u8 << prefix_bits) - 1 };
    let top = high_bits & !mask;
    let max_p = u64::from(mask);
    if val < max_p {
        out.push(top | (val as u8));
        return;
    }
    out.push(top | mask);
    val -= max_p;
    while val >= 128 {
        out.push(((val & 0x7F) as u8) | 0x80);
        val >>= 7;
    }
    out.push(val as u8);
}

pub fn decode_qpack_prefix(
    buf: &[u8],
    max_table_capacity: u64,
    total_num_inserts: u64,
) -> Result<QpackSectionPrefix, QpackPrefixError> {
    let (enc_ic, ic_len) = read_qpack_int(buf, 8)?;
    let rest = buf.get(ic_len..).ok_or(QpackPrefixError::Truncated)?;
    let sign_neg = (*rest.first().ok_or(QpackPrefixError::Truncated)? & 0x80) != 0;
    let (delta_base, db_len) = read_qpack_int(rest, 7)?;

    let max_entries = max_table_capacity / 32;
    let ric = if enc_ic == 0 {
        0
    } else {
        if max_entries == 0 {
            return Err(QpackPrefixError::DynamicTableDisabled);
        }
        let full_range = max_entries.checked_mul(2).ok_or(QpackPrefixError::VarintOverflow)?;
        if enc_ic > full_range {
            return Err(QpackPrefixError::EncodedInsertCountOutOfRange);
        }
        let max_value = total_num_inserts
            .checked_add(max_entries)
            .ok_or(QpackPrefixError::VarintOverflow)?;
        let max_wrapped = (max_value / full_range) * full_range;
        let mut recovered = max_wrapped
            .checked_add(enc_ic - 1)
            .ok_or(QpackPrefixError::VarintOverflow)?;
        if recovered > max_value {
            if recovered <= full_range {
                return Err(QpackPrefixError::InvalidRequiredInsertCount);
            }
            recovered -= full_range;
        }
        if recovered == 0 {
            return Err(QpackPrefixError::InvalidRequiredInsertCount);
        }
        recovered
    };

    let base = if !sign_neg {
        ric.checked_add(delta_base).ok_or(QpackPrefixError::VarintOverflow)?
    } else {
        let sub = delta_base.checked_add(1).ok_or(QpackPrefixError::VarintOverflow)?;
        ric.checked_sub(sub).ok_or(QpackPrefixError::NegativeBase)?
    };

    Ok(QpackSectionPrefix {
        required_insert_count: ric,
        base,
        bytes_consumed: ic_len + db_len,
    })
}

pub fn encode_qpack_prefix(
    ric: u64,
    base: u64,
    max_table_capacity: u64,
) -> Result<Vec<u8>, QpackPrefixError> {
    let max_entries = max_table_capacity / 32;
    let enc_ic = if ric == 0 {
        0
    } else {
        if max_entries == 0 {
            return Err(QpackPrefixError::DynamicTableDisabled);
        }
        (ric % (2 * max_entries)) + 1
    };
    let mut out = Vec::with_capacity(4);
    write_qpack_int(enc_ic, 8, 0x00, &mut out);
    if base >= ric {
        write_qpack_int(base - ric, 7, 0x00, &mut out);
    } else {
        write_qpack_int(ric - base - 1, 7, 0x80, &mut out);
    }
    Ok(out)
}
