        .receive_ts = rd_be64(buf + 32),
        .transmit_ts = rd_be64(buf + 40),
        .ext_count = 0,
    };

    if (out->transmit_ts == 0U || (mode == 4U && out->origin_ts == 0U)) {
        return NTP_ERR_ZERO_TIMESTAMP;
    }

    if (stratum == 0U) {
        for (int i = 0; i < 4; ++i) {
            uint8_t c = buf[12 + i];
            if (c < 'A' || c > 'Z') return NTP_ERR_BAD_STRATUM_OR_KOD;
            out->kiss_code[i] = (char)c;
        }
        out->kiss_code[4] = '\0';
    }

    size_t pos = 48U;
    while (pos < len) {
        if (len - pos < 16U) return NTP_ERR_BAD_EXT_FIELD;
        uint16_t ftype = rd_be16(buf + pos);
        uint16_t flen = rd_be16(buf + pos + 2);
        if (flen < 16U || (flen % 4U) != 0U || (size_t)flen > len - pos) {
            return NTP_ERR_BAD_EXT_FIELD;
        }
        // RFC 7822 §3.1: final EF without legacy MAC MUST be >= 28 octets
        if (pos + flen == len && flen < 28U) {
            return NTP_ERR_BAD_EXT_FIELD;
        }
        if (out->ext_count >= 16U) return NTP_ERR_TOO_MANY_EXTS;
        out->exts[out->ext_count++] = (ntp_ext_view_t){
            .field_type = ftype,
            .total_len = flen,
            .val = buf + pos + 4U,
        };
        pos += flen;
    }
    return NTP_OK;
}
