#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NoisePhase {
    HandshakeInitiatorMsg1,
    HandshakeResponderMsg2,
    Transport,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NoiseFrameError {
    Truncated,
    MessageTooShort { got: usize, min: usize },
    LowOrderEphemeralPoint,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NoiseSplitPacket<'a> {
    Msg1 {
        ephemeral_pk: [u8; 32],
        encrypted_static: [u8; 48],
        encrypted_payload: &'a [u8],
        frame_consumed: usize,
    },
    Msg2 {
        ephemeral_pk: [u8; 32],
        encrypted_payload: &'a [u8],
        frame_consumed: usize,
    },
    Transport {
        ciphertext: &'a [u8],
        frame_consumed: usize,
    },
}

fn ct_eq_32(a: &[u8; 32], b: &[u8; 32]) -> u8 {
    let mut d = 0_u8;
    for i in 0..32 {
        d |= a[i] ^ b[i];
    }
    (1_u16.wrapping_sub((u16::from(d).wrapping_add(0xFF)) >> 8)) as u8 ^ 1
}

pub fn is_low_order_x25519(pk: &[u8; 32]) -> bool {
    let mut masked = *pk;
    masked[31] &= 0x7F; // RFC 7748 clears MSB before decoding u-coordinate
    let mut hit = 0_u8;
    for bad in &X25519_LOW_ORDER_CANONICAL {
        hit |= ct_eq_32(&masked, bad);
    }
    hit != 0
}

pub fn parse_noise_ik_tcp_frame(
    stream: &[u8],
    phase: NoisePhase,
) -> Result<NoiseSplitPacket<'_>, NoiseFrameError> {
    let len_hdr = stream.get(..2).ok_or(NoiseFrameError::Truncated)?;
    let msg_len = u16::from_be_bytes([len_hdr[0], len_hdr[1]]) as usize;
    let total = 2 + msg_len;
    let body = stream.get(2..total).ok_or(NoiseFrameError::Truncated)?;

    match phase {
        NoisePhase::HandshakeInitiatorMsg1 => {
            if body.len() < 96 {
                return Err(NoiseFrameError::MessageTooShort { got: body.len(), min: 96 });
            }
            let e_pk: [u8; 32] = body[0..32].try_into().unwrap();
            if is_low_order_x25519(&e_pk) {
                return Err(NoiseFrameError::LowOrderEphemeralPoint);
            }
            let enc_s: [u8; 48] = body[32..80].try_into().unwrap();
            Ok(NoiseSplitPacket::Msg1 {
                ephemeral_pk: e_pk,
                encrypted_static: enc_s,
                encrypted_payload: &body[80..],
                frame_consumed: total,
            })
        }
        NoisePhase::HandshakeResponderMsg2 => {
            if body.len() < 48 {
                return Err(NoiseFrameError::MessageTooShort { got: body.len(), min: 48 });
            }
            let e_pk: [u8; 32] = body[0..32].try_into().unwrap();
            if is_low_order_x25519(&e_pk) {
                return Err(NoiseFrameError::LowOrderEphemeralPoint);
            }
            Ok(NoiseSplitPacket::Msg2 {
                ephemeral_pk: e_pk,
                encrypted_payload: &body[32..],
                frame_consumed: total,
            })
        }
        NoisePhase::Transport => {
            if body.len() < 16 {
                return Err(NoiseFrameError::MessageTooShort { got: body.len(), min: 16 });
            }
            Ok(NoiseSplitPacket::Transport {
                ciphertext: body,
                frame_consumed: total,
            })
        }
    }
}
