```c
#include <stdbool.h>
#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    HPKE_OK = 0,
    HPKE_ERR_NULL,
    HPKE_ERR_TRUNCATED,
    HPKE_ERR_BAD_MODE,
    HPKE_ERR_UNSUPPORTED_SUITE,
    HPKE_ERR_EXPORT_ONLY_AEAD,
    HPKE_ERR_BAD_ENC_KEY,
    HPKE_ERR_DST_SMALL,
} hpke_status_t;

typedef struct {
    uint8_t mode;
    uint16_t kem_id;
    uint16_t kdf_id;
    uint16_t aead_id;
    const uint8_t *enc;
    size_t enc_len;
    const uint8_t *ct;
    size_t ct_len;
} hpke_envelope_t;

static uint16_t rd_be16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

static void wr_be16(uint8_t *p, uint16_t v) {
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)v;
}

[[nodiscard]] hpke_status_t parse_hpke_envelope(
    const uint8_t *buf,
    size_t len,
    hpke_envelope_t *out
) {
    if (buf == nullptr || out == nullptr) return HPKE_ERR_NULL;
    if (len < 7U) return HPKE_ERR_TRUNCATED;

    uint8_t mode = buf[0];
    if (mode > 0x03) return HPKE_ERR_BAD_MODE;

    uint16_t kem_id = rd_be16(buf + 1);
    uint16_t kdf_id = rd_be16(buf + 3);
    uint16_t aead_id = rd_be16(buf + 5);

    size_t n_enc = 0U;
    if (kem_id == UINT16_C(0x0010)) {
        n_enc = 65U;
    } else if (kem_id == UINT16_C(0x0020)) {
        n_enc = 32U;
    } else {
        return HPKE_ERR_UNSUPPORTED_SUITE;
    }

    if (kdf_id < 1U || kdf_id > 3U) return HPKE_ERR_UNSUPPORTED_SUITE;
    if (aead_id == UINT16_C(0xFFFF)) return HPKE_ERR_EXPORT_ONLY_AEAD;
    if (aead_id < 1U || aead_id > 3U) return HPKE_ERR_UNSUPPORTED_SUITE;

    size_t min_total = 7U + n_enc + 16U; // >= 16-byte AEAD tag
    if (len < min_total) return HPKE_ERR_TRUNCATED;

    const uint8_t *enc_ptr = buf + 7U;
    if (kem_id == UINT16_C(0x0010) && enc_ptr[0] != 0x04) {
        return HPKE_ERR_BAD_ENC_KEY;
    }
    bool all_zero = true;
    for (size_t i = 0; i < n_enc; ++i) {
        if (enc_ptr[i] != 0x00) { all_zero = false; break; }
    }
    if (all_zero) return HPKE_ERR_BAD_ENC_KEY;

    *out = (hpke_envelope_t){
        .mode = mode,
        .kem_id = kem_id,
        .kdf_id = kdf_id,
        .aead_id = aead_id,
        .enc = enc_ptr,
        .enc_len = n_enc,
        .ct = enc_ptr + n_enc,
        .ct_len = len - 7U - n_enc,
    };
    return HPKE_OK;
}

[[nodiscard]] hpke_status_t hpke_build_labeled_info(
    uint16_t out_len_l,
    uint16_t kem_id,
    uint16_t kdf_id,
    uint16_t aead_id,
    const char *ascii_label,
    const uint8_t *info,
    size_t info_len,
    uint8_t *dst,
    size_t dst_cap,
    size_t *out_written
) {
    if (ascii_label == nullptr || dst == nullptr || out_written == nullptr) return HPKE_ERR_NULL;
    if (info_len > 0U && info == nullptr) return HPKE_ERR_NULL;

    size_t label_len = strlen(ascii_label);
    // 2B L + 7B "HPKE-v1" + 10B ("HPKE" + 3*u16) + label_len + info_len = 19 + label_len + info_len
    size_t total = 0U;
    if (ckd_add(&total, (size_t)19U, label_len) || ckd_add(&total, total, info_len)) {
        return HPKE_ERR_DST_SMALL;
    }
    if (dst_cap < total) return HPKE_ERR_DST_SMALL;

    wr_be16(dst, out_len_l);
    memcpy(dst + 2U, "HPKE-v1", 7U);
    memcpy(dst + 9U, "HPKE", 4U);
    wr_be16(dst + 13U, kem_id);
    wr_be16(dst + 15U, kdf_id);
    wr_be16(dst + 17U, aead_id);
    if (label_len > 0U) memcpy(dst + 19U, ascii_label, label_len);
    if (info_len > 0U) memcpy(dst + 19U + label_len, info, info_len);

    *out_written = total;
    return HPKE_OK;
}
```

