```rust
pub const PLOG_MAGIC: [u8; 4] = *b"PLOG";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PlogError {
    Truncated,
    BadMagicOrVersion,
    ReservedBitmapBits(u8),
    CrcMismatch { expected: u16, got: u16 },
    InvalidStatusOrTimestamp,
    AllZeroTraceOrSpanId,
    InvalidStringField,
    TrailingBytes,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProxyLogEntry {
    pub status_code: u16,
    pub timestamp_ns: u64,
    pub duration_us: u32,
    pub trace_ctx: Option<([u8; 16], [u8; 8])>,
    pub tls_sni: Option<String>,
    pub upstream_cluster: Option<String>,
}

pub fn crc_ccitt_false(data: &[u8]) -> u16 {
    let mut crc: u16 = 0xFFFF;
    for &b in data {
        crc ^= u16::from(b) << 8;
        for _ in 0..8 {
            if (crc & 0x8000) != 0 {
                crc = (crc << 1) ^ 0x1021;
            } else {
                crc <<= 1;
            }
        }
    }
    crc
}

fn valid_sni(s: &str) -> bool {
    let b = s.as_bytes();
    !b.is_empty()
        && b.len() <= 253
        && !b.starts_with(b".")
        && b.iter().all(|&c| c.is_ascii_alphanumeric() || c == b'-' || c == b'.')
}

fn valid_cluster(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 128
        && s.bytes().all(|b| b > 0x20 && b != 0x7F)
}

pub fn encode_plog_entry(entry: &ProxyLogEntry) -> Result<Vec<u8>, PlogError> {
    if !(100..=599).contains(&entry.status_code) || entry.timestamp_ns == 0 {
        return Err(PlogError::InvalidStatusOrTimestamp);
    }
    let mut bitmap = 0_u8;
    if let Some((tid, sid)) = &entry.trace_ctx {
        if tid == &[0; 16] || sid == &[0; 8] {
            return Err(PlogError::AllZeroTraceOrSpanId);
        }
        bitmap |= 0x01;
    }
    if let Some(sni) = &entry.tls_sni {
        if !valid_sni(sni) {
            return Err(PlogError::InvalidStringField);
        }
        bitmap |= 0x02;
    }
    if let Some(cl) = &entry.upstream_cluster {
        if !valid_cluster(cl) {
            return Err(PlogError::InvalidStringField);
        }
        bitmap |= 0x04;
    }

    let mut out = Vec::with_capacity(64);
    out.extend_from_slice(&PLOG_MAGIC);
    out.push(0x01);
    out.push(bitmap);
    out.extend_from_slice(&entry.status_code.to_be_bytes());
    out.extend_from_slice(&entry.timestamp_ns.to_be_bytes());
    out.extend_from_slice(&entry.duration_us.to_be_bytes());

    if let Some((tid, sid)) = &entry.trace_ctx {
        out.extend_from_slice(tid);
        out.extend_from_slice(sid);
    }
    if let Some(sni) = &entry.tls_sni {
        out.push(sni.len() as u8);
        out.extend_from_slice(sni.as_bytes());
    }
    if let Some(cl) = &entry.upstream_cluster {
        out.push(cl.len() as u8);
        out.extend_from_slice(cl.as_bytes());
    }
    let crc = crc_ccitt_false(&out);
    out.extend_from_slice(&crc.to_be_bytes());
    Ok(out)
}

pub fn decode_plog_entry(buf: &[u8]) -> Result<ProxyLogEntry, PlogError> {
    if buf.len() < 22 {
        return Err(PlogError::Truncated);
    }
    if buf[0..4] != PLOG_MAGIC || buf[4] != 0x01 {
        return Err(PlogError::BadMagicOrVersion);
    }
    let bitmap = buf[5];
    if (bitmap & 0xF8) != 0 {
        return Err(PlogError::ReservedBitmapBits(bitmap));
    }

    let body_end = buf.len() - 2;
    let got_crc = u16::from_be_bytes([buf[body_end], buf[body_end + 1]]);
    let expected_crc = crc_ccitt_false(&buf[..body_end]);
    if got_crc != expected_crc {
        return Err(PlogError::CrcMismatch { expected: expected_crc, got: got_crc });
    }

    let status_code = u16::from_be_bytes([buf[6], buf[7]]);
    let timestamp_ns = u64::from_be_bytes(buf[8..16].try_into().unwrap());
    let duration_us = u32::from_be_bytes(buf[16..20].try_into().unwrap());
    if !(100..=599).contains(&status_code) || timestamp_ns == 0 {
        return Err(PlogError::InvalidStatusOrTimestamp);
    }

    let mut pos = 20_usize;
    let trace_ctx = if (bitmap & 0x01) != 0 {
        let tc = buf.get(pos..pos + 24).ok_or(PlogError::Truncated)?;
        pos += 24;
        let tid: [u8; 16] = tc[0..16].try_into().unwrap();
        let sid: [u8; 8] = tc[16..24].try_into().unwrap();
        if tid == [0; 16] || sid == [0; 8] {
            return Err(PlogError::AllZeroTraceOrSpanId);
        }
        Some((tid, sid))
    } else {
        None
    };

    let tls_sni = if (bitmap & 0x02) != 0 {
        let slen = *buf.get(pos).ok_or(PlogError::Truncated)? as usize;
        pos += 1;
        let raw = buf.get(pos..pos + slen).ok_or(PlogError::Truncated)?;
        pos += slen;
        let s = std::str::from_utf8(raw).map_err(|_| PlogError::InvalidStringField)?;
        if !valid_sni(s) {
            return Err(PlogError::InvalidStringField);
        }
        Some(s.to_owned())
    } else {
        None
    };

    let upstream_cluster = if (bitmap & 0x04) != 0 {
        let clen = *buf.get(pos).ok_or(PlogError::Truncated)? as usize;
        pos += 1;
        let raw = buf.get(pos..pos + clen).ok_or(PlogError::Truncated)?;
        pos += clen;
        let s = std::str::from_utf8(raw).map_err(|_| PlogError::InvalidStringField)?;
        if !valid_cluster(s) {
            return Err(PlogError::InvalidStringField);
        }
        Some(s.to_owned())
    } else {
        None
    };

    if pos != body_end {
        return Err(PlogError::TrailingBytes);
    }

    Ok(ProxyLogEntry {
        status_code,
        timestamp_ns,
        duration_us,
        trace_ctx,
        tls_sni,
        upstream_cluster,
    })
}
