#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef enum : uint8_t {
    SYSLOG_OK = 0,
    SYSLOG_ERR_NULL,
    SYSLOG_ERR_BAD_PRI_OR_VER,
    SYSLOG_ERR_BAD_HEADER_TOKEN,
    SYSLOG_ERR_BAD_SD_SYNTAX,
    SYSLOG_ERR_UNESCAPED_SD_CHAR,
    SYSLOG_ERR_TOO_MANY_PARAMS,
} syslog_status_t;

typedef struct {
    char sd_id[33];
    char key[33];
    char value[128];
} syslog_sd_param_t;

typedef struct {
    uint8_t priority;
    uint8_t facility;
    uint8_t severity;
    const uint8_t *hostname; size_t hostname_len;
    const uint8_t *app_name; size_t app_name_len;
    syslog_sd_param_t params[16];
    size_t param_count;
    const uint8_t *msg;
    size_t msg_len;
    bool msg_had_utf8_bom;
} syslog_parsed_t;

static bool is_print_usascii(uint8_t c) {
    return c >= 0x21 && c <= 0x7E;
}

static bool is_sd_name_char(uint8_t c) {
    return is_print_usascii(c) && c != '=' && c != ' ' && c != ']' && c != '"';
}

static bool read_sp_token(
    const uint8_t *buf,
    size_t len,
    size_t *pos,
    size_t max_tok,
    const uint8_t **out_ptr,
    size_t *out_len
) {
    size_t start = *pos;
    while (*pos < len && buf[*pos] != ' ') {
        if (!is_print_usascii(buf[*pos])) return false;
        (*pos)++;
    }
    size_t tlen = *pos - start;
    if (tlen == 0U || tlen > max_tok || *pos >= len || buf[*pos] != ' ') return false;
    (*pos)++; // consume SP
    if (out_ptr != nullptr) *out_ptr = buf + start;
    if (out_len != nullptr) *out_len = tlen;
    return true;
}

[[nodiscard]] syslog_status_t parse_rfc5424_syslog(
    const uint8_t *buf,
    size_t len,
    syslog_parsed_t *out
) {
    if (buf == nullptr || out == nullptr) return SYSLOG_ERR_NULL;
    if (len < 16U || buf[0] != '<') return SYSLOG_ERR_BAD_PRI_OR_VER;

    size_t pos = 1U;
    uint32_t pri = 0U;
    size_t digits = 0U;
    while (pos < len && buf[pos] >= '0' && buf[pos] <= '9' && digits < 4U) {
        pri = pri * 10U + (uint32_t)(buf[pos] - '0');
        pos++;
        digits++;
    }
    if (digits == 0U || digits > 3U || (digits > 1U && buf[1] == '0') || pri > 191U) {
        return SYSLOG_ERR_BAD_PRI_OR_VER;
    }
    if (pos + 2U >= len || buf[pos] != '>' || buf[pos + 1U] != '1' || buf[pos + 2U] != ' ') {
        return SYSLOG_ERR_BAD_PRI_OR_VER;
    }
    pos += 3U;

    *out = (syslog_parsed_t){
        .priority = (uint8_t)pri,
        .facility = (uint8_t)(pri >> 3),
        .severity = (uint8_t)(pri & 7U),
    };

    if (!read_sp_token(buf, len, &pos, 64U, nullptr, nullptr)) return SYSLOG_ERR_BAD_HEADER_TOKEN; // TIMESTAMP
    if (!read_sp_token(buf, len, &pos, 255U, &out->hostname, &out->hostname_len)) return SYSLOG_ERR_BAD_HEADER_TOKEN;
    if (!read_sp_token(buf, len, &pos, 48U, &out->app_name, &out->app_name_len)) return SYSLOG_ERR_BAD_HEADER_TOKEN;
    if (!read_sp_token(buf, len, &pos, 128U, nullptr, nullptr)) return SYSLOG_ERR_BAD_HEADER_TOKEN; // PROCID
    if (!read_sp_token(buf, len, &pos, 32U, nullptr, nullptr)) return SYSLOG_ERR_BAD_HEADER_TOKEN;  // MSGID

    if (pos >= len) return SYSLOG_ERR_BAD_SD_SYNTAX;
    if (buf[pos] == '-') {
        pos++;
    } else if (buf[pos] == '[') {
        while (pos < len && buf[pos] == '[') {
            pos++; // '['
            size_t id_start = pos;
            while (pos < len && is_sd_name_char(buf[pos])) pos++;
            size_t id_len = pos - id_start;
            if (id_len == 0U || id_len > 32U || pos >= len) return SYSLOG_ERR_BAD_SD_SYNTAX;

            while (pos < len && buf[pos] == ' ') {
                pos++;
                size_t k_start = pos;
                while (pos < len && is_sd_name_char(buf[pos])) pos++;
                size_t k_len = pos - k_start;
                if (k_len == 0U || k_len > 32U || pos + 1U >= len || buf[pos] != '=' || buf[pos + 1U] != '"') {
                    return SYSLOG_ERR_BAD_SD_SYNTAX;
                }
                pos += 2U; // '="'

                if (out->param_count >= 16U) return SYSLOG_ERR_TOO_MANY_PARAMS;
                syslog_sd_param_t *slot = &out->params[out->param_count];
                memcpy(slot->sd_id, buf + id_start, id_len);
                slot->sd_id[id_len] = '\0';
                memcpy(slot->key, buf + k_start, k_len);
                slot->key[k_len] = '\0';

                size_t vw = 0U;
                bool closed_quote = false;
                while (pos < len) {
                    uint8_t c = buf[pos++];
                    if (c == '"') {
                        closed_quote = true;
                        break;
                    }
                    if (c == ']' || c == 0x00) {
                        return SYSLOG_ERR_UNESCAPED_SD_CHAR; // RFC 5424 §6.3.3: ']' MUST be escaped!
                    }
                    if (c == '\\') {
                        if (pos >= len) return SYSLOG_ERR_BAD_SD_SYNTAX;
                        c = buf[pos++];
                    }
                    if (vw + 1U >= sizeof(slot->value)) return SYSLOG_ERR_BAD_SD_SYNTAX;
                    slot->value[vw++] = (char)c;
                }
                if (!closed_quote) return SYSLOG_ERR_BAD_SD_SYNTAX;
                slot->value[vw] = '\0';
                out->param_count++;
            }
            if (pos >= len || buf[pos] != ']') return SYSLOG_ERR_BAD_SD_SYNTAX;
            pos++; // ']'
        }
    } else {
        return SYSLOG_ERR_BAD_SD_SYNTAX;
    }

    if (pos < len) {
        if (buf[pos] != ' ') return SYSLOG_ERR_BAD_SD_SYNTAX;
        pos++;
        if (len - pos >= 3U && buf[pos] == 0xEF && buf[pos + 1U] == 0xBB && buf[pos + 2U] == 0xBF) {
            out->msg_had_utf8_bom = true;
            pos += 3U;
        }
        out->msg = buf + pos;
        out->msg_len = len - pos;
    }
    return SYSLOG_OK;
}
